window.ATLAS_PRIORITY_DETAILS=window.ATLAS_PRIORITY_DETAILS||{};window.ATLAS_PRIORITY_DETAILS["evidence-000"]={"LRRC42":{"coreEvidence":[{"partner":"PARP2","hgnc":"HGNC:272","core":true,"core_annotation":{"hgnc":"HGNC:272","symbol_at_source":"PARP2","accession":"Q9UGN5","function":"Chromatin remodeling cofactor","target":"#","pmids":["20092359"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":556,"hub_weight":0.28724249481071307,"quality":0.4,"programmes":["pubmed:40057523"],"pmids":["40057523"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Poly-ADP-ribosyltransferase that mediates poly-ADP-ribosylation of proteins and plays a key role in DNA repair (PubMed:10364231, PubMed:25043379, PubMed:27471034, PubMed:30104678, PubMed:32028527, PubMed:32939087, PubMed:34108479, PubMed:34486521, PubMed:34874266). Mediates glutamate, aspartate or serine ADP-ribosylation of proteins: the ADP-D-ribosyl group of NAD(+) is transferred to the acceptor carboxyl group of target residues and further ADP-ribosyl groups are transferred to the 2'-position of the terminal adenosine moiety, building up a polymer with an average chain length of 20-30 units (PubMed:25043379, PubMed:30104678, PubMed:30321391). Serine ADP-ribosylation of proteins constitutes the primary form of ADP-ribosylation of proteins in response to DNA damage (PubMed:32939087). Mediates glutamate and aspartate ADP-ribosylation of target proteins in absence of HPF1 (PubMed:25043379). Following interaction with HPF1, catalyzes serine ADP-ribosylation of target proteins; HPF1 conferring serine specificity by completing the PARP2 active site (PubMed:28190768, PubMed:32028527, PubMed:34108479, PubMed:34486521, PubMed:34874266). PARP2 initiates the repair of double-strand DNA breaks: recognizes and binds DNA breaks within chromatin and recruits HPF1, licensing serine ADP-ribosylation of target proteins, such as histones, thereby promoting decompaction of chromatin and the recruitment of repair factors leading to the reparation of DNA strand breaks (PubMed:10364231, PubMed:32939087, PubMed:34108479). HPF1 initiates serine ADP-ribosylation but restricts the polymerase activity of PARP2 in order to limit the length of poly-ADP-ribose chains (PubMed:34732825, PubMed:34795260). Specifically mediates formation of branched poly-ADP-ribosylation (PubMed:30104678). Branched poly-ADP-ribose chains are specifically recognized by some factors, such as APLF (PubMed:30104678). In addition to proteins, also able to ADP-ribosylate DNA: preferentially acts on 5'-terminal phosphates at DNA strand breaks termini in nicked duplex (PubMed:27471034, PubMed:29361132)","source":"project UniProt records20261017/18"},{"partner":"CUL3","hgnc":"HGNC:2553","core":true,"core_annotation":{"hgnc":"HGNC:2553","symbol_at_source":"CUL3","accession":"Q13618","function":"Histone modification write","target":"histone","pmids":["15897469"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":2139,"hub_weight":0.15113398071880554,"quality":0.65,"programmes":["BioPlex","pubmed:21145461"],"pmids":["21145461","28514442","33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus; Golgi apparatus; Cell projection, cilium, flagellum; Cytoplasm, cytoskeleton, spindle; Cytoplasm; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Cytoplasm, cytoskeleton, spindle pole","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Core component of multiple cullin-RING-based BCR (BTB-CUL3-RBX1) E3 ubiquitin-protein ligase complexes which mediate the ubiquitination and subsequent proteasomal degradation of target proteins (PubMed:29695787). BCR complexes and ARIH1 collaborate in tandem to mediate ubiquitination of target proteins (PubMed:27565346). As a scaffold protein may contribute to catalysis through positioning of the substrate and the ubiquitin-conjugating enzyme. The E3 ubiquitin-protein ligase activity of the complex is dependent on the neddylation of the cullin subunit and is inhibited by the association of the deneddylated cullin subunit with TIP120A/CAND1. The functional specificity of the BCR complex depends on the BTB domain-containing protein as the substrate recognition component. BCR(KLHL42) is involved in ubiquitination of KATNA1. BCR(SPOP) is involved in ubiquitination of BMI1/PCGF4, BRMS1, MACROH2A1 and DAXX, GLI2 and GLI3. Can also form a cullin-RING-based BCR (BTB-CUL3-RBX1) E3 ubiquitin-protein ligase complex containing homodimeric SPOPL or the heterodimer formed by SPOP and SPOPL; these complexes have lower ubiquitin ligase activity. BCR(KLHL9-KLHL13) controls the dynamic behavior of AURKB on mitotic chromosomes and thereby coordinates faithful mitotic progression and completion of cytokinesis. BCR(KLHL12) is involved in ER-Golgi transport by regulating the size of COPII coats, thereby playing a key role in collagen export, which is required for embryonic stem (ES) cells division: BCR(KLHL12) acts by mediating monoubiquitination of SEC31 (SEC31A or SEC31B) (PubMed:22358839, PubMed:27716508). BCR(KLHL3) acts as a regulator of ion transport in the distal nephron; by mediating ubiquitination of WNK4 (PubMed:23387299, PubMed:23453970, PubMed:23576762). The BCR(KLHL20) E3 ubiquitin ligase complex is involved in interferon response and anterograde Golgi to endosome transport: it mediates both ubiquitination leading to degradation and 'Lys-33'-linked ubiquitination (PubMed:20389280, PubMed:21670212, PubMed:21840486, PubMed:24768539). The BCR(KLHL21) E3 ubiquitin ligase complex regulates localization of the chromosomal passenger complex (CPC) from chromosomes to the spindle midzone in anaphase and mediates the ubiquitination of AURKB (PubMed:19995937). The BCR(KLHL22) ubiquitin ligase complex mediates monoubiquitination of PLK1, leading to PLK1 dissociation from phosphoreceptor proteins and subsequent removal from kinetochores, allowing silencing of the spindle assembly checkpoint (SAC) and chromosome segregation (PubMed:23455478). The BCR(KLHL22) ubiquitin ligase complex is also responsible for the amino acid-stimulated 'Lys-48' polyubiquitination and proteasomal degradation of DEPDC5. Through the degradation of DEPDC5, releases the GATOR1 complex-mediated inhibition of the TORC1 pathway (PubMed:29769719). The BCR(KLHL25) ubiquitin ligase complex is involved in translational homeostasis by mediating ubiquitination and subsequent degradation of hypophosphorylated EIF4EBP1 (4E-BP1) (PubMed:22578813). The BCR(KLHL25) ubiquitin ligase complex is also involved in lipid synthesis by mediating ubiquitination and degradation of ACLY (PubMed:27664236). The BCR(KBTBD8) complex acts by mediating monoubiquitination of NOLC1 and TCOF1, leading to remodel the translational program of differentiating cells in favor of neural crest specification (PubMed:26399832). Involved in ubiquitination of cyclin E and of cyclin D1 (in vitro) thus involved in regulation of G1/S transition. Involved in the ubiquitination of KEAP1, ENC1 and KLHL41 (PubMed:15983046). In concert with ATF2 and RBX1, promotes degradation of KAT5 thereby attenuating its ability to acetylate and activate ATM. The BCR(KCTD17) E3 ubiquitin ligase complex mediates ubiquitination and degradation of TCHP, a down-regulator of cilium assembly, thereby inducing ciliogenesis (PubMed:25270598). The BCR(KLHL24) E3 ubiquitin ligase complex mediates ubiquitination of KRT14, controls KRT14 levels during keratinocytes differentiation, and is essential for skin integrity (PubMed:27798626). The BCR(KLHL18) E3 ubiquitin ligase complex mediates the ubiquitination of AURKA leading to its activation at the centrosome which is required for initiating mitotic entry (PubMed:23213400). The BCR(KEAP1) E3 ubiquitin ligase complex acts as a key sensor of oxidative and electrophilic stress by mediating ubiquitination and degradation of NFE2L2/NRF2, a transcription factor regulating expression of many cytoprotective genes (PubMed:15601839, PubMed:16006525). As part of the CUL3(KBTBD6/7) E3 ubiquitin ligase complex functions mediates 'Lys-48' ubiquitination and proteasomal degradation of TIAM1 (PubMed:25684205). By controlling the ubiquitination of that RAC1 guanine exchange factors (GEF), regulates RAC1 signal transduction and downstream biological processes including the organization of the cytoskeleton, cell migration and cell proliferation (PubMed:25684205). The BCR(KBTBD4) E3 ubiquitin ligase complex targets CoREST corepressor complex components RCOR1, KDM1A/LSD1 and HDAC2 for proteasomal degradation with RCOR1 likely to be the primary target while degradation of KDM1A and HDAC2 is likely due to their association with RCOR1 (PubMed:33417871). It also targets RCOR3, MIER2 and MIER3 for proteasomal degradation as well as associated proteins ZNF217 and RREB1 with degradation being dependent on the presence of an ELM2 domain in the target proteins (PubMed:36997086). The BCR(ARMC5) complex mediates premature transcription termination of transcripts that are unfavorably configured for transcriptional elongation by mediating ubiquitination of Pol II subunit POLR2A (PubMed:35687106, PubMed:38225631, PubMed:39504960, PubMed:39667934). Required for 'Lys-63'-linked ubiquitination of large ribosomal subunit protein MRPL12 (PubMed:37526061). Protects against human enterovirus D68 infection by mediating the ubiquitination and subsequent degradation of viral protein VP1 (PubMed:40396757)","source":"project UniProt records20261017/18"},{"partner":"EYA4","hgnc":"HGNC:3522","core":true,"core_annotation":{"hgnc":"HGNC:3522","symbol_at_source":"EYA4","accession":"O95677","function":"Histone modification erase","target":"histone","pmids":[],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":212,"hub_weight":0.436852028330519,"quality":0.4,"programmes":["pubmed:38360978"],"pmids":["38360978"],"assays":["proximity_label"],"contexts":[],"partner_location":"Cytoplasm; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Tyrosine phosphatase that specifically dephosphorylates 'Tyr-142' of histone H2AX (H2AXY142ph). 'Tyr-142' phosphorylation of histone H2AX plays a central role in DNA repair and acts as a mark that distinguishes between apoptotic and repair responses to genotoxic stress. Promotes efficient DNA repair by dephosphorylating H2AX, promoting the recruitment of DNA repair complexes containing MDC1. Its function as histone phosphatase probably explains its role in transcription regulation during organogenesis. May be involved in development of the eye (By similarity)","source":"project UniProt records20261017/18"},{"partner":"KAT5","hgnc":"HGNC:5275","core":true,"core_annotation":{"hgnc":"HGNC:5275","symbol_at_source":"KAT5","accession":"Q92993","function":"Histone modification write","target":"histone","pmids":["10096020"],"complexes":"SWR, NuA4, Piccolo_NuA4","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":337,"hub_weight":0.3594425773447947,"quality":0.65,"programmes":["BioPlex"],"pmids":["26186194","28514442","33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus; Chromosome; Cytoplasm; Chromosome, centromere, kinetochore; Cytoplasm, cytoskeleton, spindle pole; Nucleus, nucleolus; Cytoplasm, perinuclear region; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Catalytic subunit of the NuA4 histone acetyltransferase complex, a multiprotein complex involved in transcriptional activation of select genes principally by acetylation of nucleosomal histones H2A and H4 (PubMed:12776177, PubMed:14966270, PubMed:15042092, PubMed:15121871, PubMed:15310756, PubMed:16387653, PubMed:19909775, PubMed:25865756, PubMed:27153538, PubMed:29174981, PubMed:29335245, PubMed:32822602, PubMed:33076429). Histone acetylation alters nucleosome-DNA interactions and promotes interaction of the modified histones with other proteins which positively regulate transcription (PubMed:12776177, PubMed:14966270, PubMed:15042092, PubMed:15121871, PubMed:15310756). The NuA4 histone acetyltransferase complex is required for the activation of transcriptional programs associated with proto-oncogene mediated growth induction, tumor suppressor mediated growth arrest and replicative senescence, apoptosis, and DNA repair (PubMed:17709392, PubMed:19783983, PubMed:32832608). The NuA4 complex plays a direct role in repair of DNA double-strand breaks (DSBs) by promoting homologous recombination (HR): the complex inhibits TP53BP1 binding to chromatin via MBTD1, which recognizes and binds histone H4 trimethylated at 'Lys-20' (H4K20me), and KAT5 that catalyzes acetylation of 'Lys-15' of histone H2A (H2AK15ac), thereby blocking the ubiquitination mark required for TP53BP1 localization at DNA breaks (PubMed:27153538, PubMed:32832608). Also involved in DSB repair by mediating acetylation of 'Lys-5' of histone H2AX (H2AXK5ac), promoting NBN/NBS1 assembly at the sites of DNA damage (PubMed:17709392, PubMed:26438602). The NuA4 complex plays a key role in hematopoietic stem cell maintenance and is required to maintain acetylated H2A.Z/H2AZ1 at MYC target genes (By similarity). The NuA4 complex is also required for spermatid development by promoting acetylation of histones: histone hyperacetylation is required for histone replacement during the transition from round to elongating spermatids (By similarity). Component of a SWR1-like complex that specifically mediates the removal of histone H2A.Z/H2AZ1 from the nucleosome (PubMed:24463511). Also acetylates non-histone proteins, such as BMAL1, ATM, AURKB, CHKA, CGAS, ERCC4/XPF, LPIN1, TP53/p53, NDC80/HEC1, NR1D2, RAN, SOX4, FOXP3, SQSTM1, ULK1 and RUBCNL/Pacer (PubMed:16141325, PubMed:17189187, PubMed:17360565, PubMed:17996965, PubMed:24835996, PubMed:26829474, PubMed:29040603, PubMed:30409912, PubMed:30704899, PubMed:31857589, PubMed:32034146, PubMed:32817552, PubMed:34077757). Directly acetylates and activates ATM (PubMed:16141325). Promotes nucleotide excision repair (NER) by mediating acetylation of ERCC4/XPF, thereby promoting formation of the ERCC4-ERCC1 complex (PubMed:32034146). Relieves NR1D2-mediated inhibition of APOC3 expression by acetylating NR1D2 (PubMed:17996965). Acts as a regulator of regulatory T-cells (Treg) by catalyzing FOXP3 acetylation, thereby promoting FOXP3 transcriptional repressor activity (PubMed:17360565, PubMed:24835996). Involved in skeletal myoblast differentiation by mediating acetylation of SOX4 (PubMed:26291311). Catalyzes acetylation of APBB1/FE65, increasing its transcription activator activity (PubMed:33938178). Promotes transcription elongation during the activation phase of the circadian cycle by catalyzing acetylation of BMAL1, promoting elongation of circadian transcripts (By similarity). Together with GSK3 (GSK3A or GSK3B), acts as a regulator of autophagy: phosphorylated at Ser-86 by GSK3 under starvation conditions, leading to activate acetyltransferase activity and promote acetylation of key autophagy regulators, such as ULK1 and RUBCNL/Pacer (PubMed:30704899). Acts as a regulator of the cGAS-STING innate antiviral response by catalyzing acetylation the N-terminus of CGAS, thereby promoting CGAS DNA-binding and activation (PubMed:32817552). Also regulates lipid metabolism by mediating acetylation of CHKA or LPIN1 (PubMed:34077757). Promotes lipolysis of lipid droplets following glucose deprivation by mediating acetylation of isoform 1 of CHKA, thereby promoting monomerization of CHKA and its conversion into a tyrosine-protein kinase (PubMed:34077757). Acts as a regulator of fatty-acid-induced triacylglycerol synthesis by catalyzing acetylation of LPIN1, thereby promoting the synthesis of diacylglycerol (PubMed:29765047). In addition to protein acetyltransferase, can use different acyl-CoA substrates, such as (2E)-butenoyl-CoA (crotonyl-CoA), S-lactoyl-CoA (lactyl-CoA) and 2-hydroxyisobutanoyl-CoA (2-hydroxyisobutyryl-CoA), and is able to mediate protein crotonylation, lactylation and 2-hydroxyisobutyrylation, respectively (PubMed:29192674, PubMed:34608293, PubMed:38961290). Acts as a key regulator of chromosome segregation and kinetochore-microtubule attachment during mitosis by mediating acetylation or crotonylation of target proteins (PubMed:26829474, PubMed:29040603, PubMed:30409912, PubMed:34608293). Catalyzes acetylation of AURKB at kinetochores, increasing AURKB activity and promoting accurate chromosome segregation in mitosis (PubMed:26829474). Acetylates RAN during mitosis, promoting microtubule assembly at mitotic chromosomes (PubMed:29040603). Acetylates NDC80/HEC1 during mitosis, promoting robust kinetochore-microtubule attachment (PubMed:30409912). Catalyzes crotonylation of MAPRE1/EB1, thereby ensuring accurate spindle positioning in mitosis (PubMed:34608293). Catalyzes lactylation of NBN/NBS1 in response to DNA damage, thereby promoting DNA double-strand breaks (DSBs) via homologous recombination (HR) (PubMed:38961290)\n(Microbial infection) Catalyzes the acetylation of flavivirus NS3 protein to modulate their RNA-binding and -unwinding activities leading to facilitate viral replication","source":"project UniProt records20261017/18"},{"partner":"RAG2","hgnc":"HGNC:9832","core":true,"core_annotation":{"hgnc":"HGNC:9832","symbol_at_source":"RAG2","accession":"P55895","function":"Histone modification read","target":"histone","pmids":["21423274"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":121,"hub_weight":0.5407380704358751,"quality":0.4,"programmes":["pubmed:41601259"],"pmids":["41601259"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Core component of the RAG complex, a multiprotein complex that mediates the DNA cleavage phase during V(D)J recombination. V(D)J recombination assembles a diverse repertoire of immunoglobulin and T-cell receptor genes in developing B and T-lymphocytes through rearrangement of different V (variable), in some cases D (diversity), and J (joining) gene segments. DNA cleavage by the RAG complex occurs in 2 steps: a first nick is introduced in the top strand immediately upstream of the heptamer, generating a 3'-hydroxyl group that can attack the phosphodiester bond on the opposite strand in a direct transesterification reaction, thereby creating 4 DNA ends: 2 hairpin coding ends and 2 blunt, 5'-phosphorylated ends. The chromatin structure plays an essential role in the V(D)J recombination reactions and the presence of histone H3 trimethylated at 'Lys-4' (H3K4me3) stimulates both the nicking and haipinning steps. The RAG complex also plays a role in pre-B cell allelic exclusion, a process leading to expression of a single immunoglobulin heavy chain allele to enforce clonality and monospecific recognition by the B-cell antigen receptor (BCR) expressed on individual B-lymphocytes. The introduction of DNA breaks by the RAG complex on one immunoglobulin allele induces ATM-dependent repositioning of the other allele to pericentromeric heterochromatin, preventing accessibility to the RAG complex and recombination of the second allele. In the RAG complex, RAG2 is not the catalytic component but is required for all known catalytic activities mediated by RAG1. It probably acts as a sensor of chromatin state that recruits the RAG complex to H3K4me3 (By similarity)","source":"project UniProt records20261017/18"},{"partner":"USP7","hgnc":"HGNC:12630","core":true,"core_annotation":{"hgnc":"HGNC:12630","symbol_at_source":"USP7","accession":"Q93009","function":"Histone modification erase, DNA modification cofactor","target":"histone, DNA","pmids":["15749019"],"complexes":"BCOR","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":684,"hub_weight":0.2609978754859403,"quality":0.65,"programmes":["pubmed:39393471"],"pmids":["39393471"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus; Cytoplasm; Nucleus, PML body; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Hydrolase that deubiquitinates target proteins such as ARMC5, FOXO4, DEPTOR, KAT5, p53/TP53, MDM2, ERCC6, DNMT1, UHRF1, PTEN, KMT2E/MLL5 and DAXX (PubMed:11923872, PubMed:15053880, PubMed:16964248, PubMed:18716620, PubMed:25283148, PubMed:25865756, PubMed:26678539, PubMed:28655758, PubMed:33544460, PubMed:35216969). Together with DAXX, prevents MDM2 self-ubiquitination and enhances the E3 ligase activity of MDM2 towards p53/TP53, thereby promoting p53/TP53 ubiquitination and proteasomal degradation (PubMed:15053880, PubMed:16845383, PubMed:18566590, PubMed:20153724). Deubiquitinates p53/TP53, preventing degradation of p53/TP53, and enhances p53/TP53-dependent transcription regulation, cell growth repression and apoptosis (PubMed:25283148). Deubiquitinates p53/TP53 and MDM2 and strongly stabilizes p53/TP53 even in the presence of excess MDM2, and also induces p53/TP53-dependent cell growth repression and apoptosis (PubMed:11923872, PubMed:26786098). Deubiquitination of FOXO4 in presence of hydrogen peroxide is not dependent on p53/TP53 and inhibits FOXO4-induced transcriptional activity (PubMed:16964248). In association with DAXX, is involved in the deubiquitination and translocation of PTEN from the nucleus to the cytoplasm, both processes that are counteracted by PML (PubMed:18716620). Deubiquitinates KMT2E/MLL5 preventing KMT2E/MLL5 proteasomal-mediated degradation (PubMed:26678539). Involved in cell proliferation during early embryonic development. Involved in transcription-coupled nucleotide excision repair (TC-NER) in response to UV damage: recruited to DNA damage sites following interaction with KIAA1530/UVSSA and promotes deubiquitination of ERCC6, preventing UV-induced degradation of ERCC6 (PubMed:22466611, PubMed:22466612). Involved in maintenance of DNA methylation via its interaction with UHRF1 and DNMT1: acts by mediating deubiquitination of UHRF1 and DNMT1, preventing their degradation and promoting DNA methylation by DNMT1 (PubMed:21745816, PubMed:22411829). Deubiquitinates alkylation repair enzyme ALKBH3. OTUD4 recruits USP7 and USP9X to stabilize ALKBH3, thereby promoting the repair of alkylated DNA lesions (PubMed:25944111). Acts as a chromatin regulator via its association with the Polycomb group (PcG) multiprotein PRC1-like complex; may act by deubiquitinating components of the PRC1-like complex (PubMed:20601937). Able to mediate deubiquitination of histone H2B; it is however unsure whether this activity takes place in vivo (PubMed:20601937). Exhibits a preference towards 'Lys-48'-linked ubiquitin chains (PubMed:22689415). Increases regulatory T-cells (Treg) suppressive capacity by deubiquitinating and stabilizing the transcription factor FOXP3 which is crucial for Treg cell function (PubMed:23973222). Plays a role in the maintenance of the circadian clock periodicity via deubiquitination and stabilization of the CRY1 and CRY2 proteins (PubMed:27123980). Deubiquitinates REST, thereby stabilizing REST and promoting the maintenance of neural progenitor cells (PubMed:21258371). Deubiquitinates SIRT7, inhibiting SIRT7 histone deacetylase activity and regulating gluconeogenesis (PubMed:28655758). Involved in the regulation of WASH-dependent actin polymerization at the surface of endosomes and the regulation of endosomal protein recycling (PubMed:26365382). It maintains optimal WASH complex activity and precise F-actin levels via deubiquitination of TRIM27 and WASHC1 (PubMed:26365382). Mediates the deubiquitination of phosphorylated DEPTOR, promoting its stability and leading to decreased mTORC1 signaling (PubMed:35216969). Deubiquitinates H2AB1, H2BC4 and H2BC22 (By similarity)\n(Microbial infection) Contributes to the overall stabilization and trans-activation capability of the herpesvirus 1 trans-acting transcriptional protein ICP0/VMW110 during HSV-1 infection\n(Microbial infection) Upon infection with Epstein-Barr virus, the interaction with viral EBNA1 increases the association of USP7 with PML proteins, which is required for the polyubiquitylation and degradation of PML","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"CRYBG2":{"coreEvidence":[{"partner":"PARP1","hgnc":"HGNC:270","core":true,"core_annotation":{"hgnc":"HGNC:270","symbol_at_source":"PARP1","accession":"P09874","function":"Chromatin remodeling","target":"histone","pmids":["20926656","17177976","17396150"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":1585,"hub_weight":0.17487435419566724,"quality":0.4,"programmes":["pubmed:40057523"],"pmids":["40057523"],"assays":["proximity_label"],"contexts":[],"partner_location":"Chromosome; Nucleus; Nucleus, nucleolus; Cytoplasm, cytosol; Chromosome; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Poly-ADP-ribosyltransferase that mediates poly-ADP-ribosylation of proteins and plays a key role in DNA repair (PubMed:17177976, PubMed:18055453, PubMed:18172500, PubMed:19344625, PubMed:19661379, PubMed:20388712, PubMed:21680843, PubMed:22582261, PubMed:23230272, PubMed:25043379, PubMed:26344098, PubMed:26626479, PubMed:26626480, PubMed:30104678, PubMed:31796734, PubMed:32028527, PubMed:32241924, PubMed:32358582, PubMed:33186521, PubMed:34465625, PubMed:34737271). Mediates glutamate, aspartate, serine, histidine or tyrosine ADP-ribosylation of proteins: the ADP-D-ribosyl group of NAD(+) is transferred to the acceptor carboxyl group of target residues and further ADP-ribosyl groups are transferred to the 2'-position of the terminal adenosine moiety, building up a polymer with an average chain length of 20-30 units (PubMed:19764761, PubMed:25043379, PubMed:28190768, PubMed:29954836, PubMed:35393539, PubMed:7852410, PubMed:9315851). Serine ADP-ribosylation of proteins constitutes the primary form of ADP-ribosylation of proteins in response to DNA damage (PubMed:33186521, PubMed:34874266, PubMed:41062835). Specificity for the different amino acids is conferred by interacting factors, such as HPF1 and NMNAT1 (PubMed:28190768, PubMed:29954836, PubMed:32028527, PubMed:33186521, PubMed:33589610, PubMed:34625544, PubMed:34874266). Following interaction with HPF1, catalyzes serine ADP-ribosylation of target proteins; HPF1 confers serine specificity by completing the PARP1 active site (PubMed:28190768, PubMed:29954836, PubMed:32028527, PubMed:33186521, PubMed:33589610, PubMed:34625544, PubMed:34874266). Also catalyzes tyrosine ADP-ribosylation of target proteins following interaction with HPF1 (PubMed:29954836, PubMed:30257210). Following interaction with NMNAT1, catalyzes glutamate and aspartate ADP-ribosylation of target proteins; NMNAT1 confers glutamate and aspartate specificity (By similarity). PARP1 initiates the repair of DNA breaks: recognizes and binds DNA breaks within chromatin and recruits HPF1, licensing serine ADP-ribosylation of target proteins, such as histones (H2BS6ADPr and H3S10ADPr), thereby promoting decompaction of chromatin and the recruitment of repair factors leading to the reparation of DNA strand breaks (PubMed:17177976, PubMed:18172500, PubMed:19344625, PubMed:19661379, PubMed:23230272, PubMed:27067600, PubMed:34465625, PubMed:34874266). HPF1 initiates serine ADP-ribosylation but restricts the polymerase activity of PARP1 in order to limit the length of poly-ADP-ribose chains (PubMed:33683197, PubMed:34732825, PubMed:34795260). In addition to base excision repair (BER) pathway, also involved in double-strand breaks (DSBs) repair: together with TIMELESS, accumulates at DNA damage sites and promotes homologous recombination repair by mediating poly-ADP-ribosylation (PubMed:26344098, PubMed:30356214). Mediates the poly-ADP-ribosylation of a number of proteins, including itself, APLF, CHFR, RPA1 and NFAT5 (PubMed:17396150, PubMed:19764761, PubMed:24906880, PubMed:34049076). In addition to proteins, also able to ADP-ribosylate DNA: catalyzes ADP-ribosylation of DNA strand break termini containing terminal phosphates and a 2'-OH group in single- and double-stranded DNA, respectively (PubMed:27471034). Required for PARP9 and DTX3L recruitment to DNA damage sites (PubMed:23230272). PARP1-dependent PARP9-DTX3L-mediated ubiquitination promotes the rapid and specific recruitment of 53BP1/TP53BP1, UIMC1/RAP80, and BRCA1 to DNA damage sites (PubMed:23230272). PARP1-mediated DNA repair in neurons plays a role in sleep: senses DNA damage in neurons and promotes sleep, facilitating efficient DNA repair (By similarity). In addition to DNA repair, also involved in other processes, such as transcription regulation, programmed cell death, membrane repair, adipogenesis and innate immunity (PubMed:15607977, PubMed:17177976, PubMed:19344625, PubMed:27256882, PubMed:32315358, PubMed:32844745, PubMed:35124853, PubMed:35393539, PubMed:35460603). Acts as a repressor of transcription: binds to nucleosomes and modulates chromatin structure in a manner similar to histone H1, thereby altering RNA polymerase II (PubMed:15607977, PubMed:22464733). Acts both as a positive and negative regulator of transcription elongation, depending on the context (PubMed:27256882, PubMed:35393539). Acts as a positive regulator of transcription elongation by mediating poly-ADP-ribosylation of NELFE, preventing RNA-binding activity of NELFE and relieving transcription pausing (PubMed:27256882). Acts as a negative regulator of transcription elongation in response to DNA damage by catalyzing poly-ADP-ribosylation of CCNT1, disrupting the phase separation activity of CCNT1 and subsequent activation of CDK9 (PubMed:35393539). Involved in replication fork progression following interaction with CARM1: mediates poly-ADP-ribosylation at replication forks, slowing fork progression (PubMed:33412112). Poly-ADP-ribose chains generated by PARP1 also play a role in poly-ADP-ribose-dependent cell death, a process named parthanatos (By similarity). Also acts as a negative regulator of the cGAS-STING pathway (PubMed:32315358, PubMed:32844745, PubMed:35460603). Acts by mediating poly-ADP-ribosylation of CGAS: PARP1 translocates into the cytosol following phosphorylation by PRKDC and catalyzes poly-ADP-ribosylation and inactivation of CGAS (PubMed:35460603). Acts as a negative regulator of adipogenesis: catalyzes poly-ADP-ribosylation of histone H2B on 'Glu-35' (H2BE35ADPr) following interaction with NMNAT1, inhibiting phosphorylation of H2B at 'Ser-36' (H2BS36ph), thereby blocking expression of pro-adipogenetic genes (By similarity). Involved in the synthesis of ATP in the nucleus, together with NMNAT1, PARG and NUDT5 (PubMed:27257257). Nuclear ATP generation is required for extensive chromatin remodeling events that are energy-consuming (PubMed:27257257). Plays a role in sister chromatid cohesion by mediating ADP-ribosylation of RSMC during S phase which promotes the interaction between RSMC and CDCA5/sororin, leading to enhanced interaction of CDCA5/sororin with the cohesin complex and promotion of sister chromatid cohesion (PubMed:41261216)\nPromotes AIFM1-mediated apoptosis (PubMed:33168626). This form, which translocates into the cytoplasm following cleavage by caspase-3 (CASP3) and caspase-7 (CASP7) in response to apoptosis, is auto-poly-ADP-ribosylated and serves as a poly-ADP-ribose carrier to induce AIFM1-mediated apoptosis (PubMed:33168626)\nThis cleavage form irreversibly binds to DNA breaks and interferes with DNA repair, promoting DNA damage-induced apoptosis","source":"project UniProt records20261017/18"},{"partner":"PARP2","hgnc":"HGNC:272","core":true,"core_annotation":{"hgnc":"HGNC:272","symbol_at_source":"PARP2","accession":"Q9UGN5","function":"Chromatin remodeling cofactor","target":"#","pmids":["20092359"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":556,"hub_weight":0.28724249481071307,"quality":0.4,"programmes":["pubmed:40057523"],"pmids":["40057523"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Poly-ADP-ribosyltransferase that mediates poly-ADP-ribosylation of proteins and plays a key role in DNA repair (PubMed:10364231, PubMed:25043379, PubMed:27471034, PubMed:30104678, PubMed:32028527, PubMed:32939087, PubMed:34108479, PubMed:34486521, PubMed:34874266). Mediates glutamate, aspartate or serine ADP-ribosylation of proteins: the ADP-D-ribosyl group of NAD(+) is transferred to the acceptor carboxyl group of target residues and further ADP-ribosyl groups are transferred to the 2'-position of the terminal adenosine moiety, building up a polymer with an average chain length of 20-30 units (PubMed:25043379, PubMed:30104678, PubMed:30321391). Serine ADP-ribosylation of proteins constitutes the primary form of ADP-ribosylation of proteins in response to DNA damage (PubMed:32939087). Mediates glutamate and aspartate ADP-ribosylation of target proteins in absence of HPF1 (PubMed:25043379). Following interaction with HPF1, catalyzes serine ADP-ribosylation of target proteins; HPF1 conferring serine specificity by completing the PARP2 active site (PubMed:28190768, PubMed:32028527, PubMed:34108479, PubMed:34486521, PubMed:34874266). PARP2 initiates the repair of double-strand DNA breaks: recognizes and binds DNA breaks within chromatin and recruits HPF1, licensing serine ADP-ribosylation of target proteins, such as histones, thereby promoting decompaction of chromatin and the recruitment of repair factors leading to the reparation of DNA strand breaks (PubMed:10364231, PubMed:32939087, PubMed:34108479). HPF1 initiates serine ADP-ribosylation but restricts the polymerase activity of PARP2 in order to limit the length of poly-ADP-ribose chains (PubMed:34732825, PubMed:34795260). Specifically mediates formation of branched poly-ADP-ribosylation (PubMed:30104678). Branched poly-ADP-ribose chains are specifically recognized by some factors, such as APLF (PubMed:30104678). In addition to proteins, also able to ADP-ribosylate DNA: preferentially acts on 5'-terminal phosphates at DNA strand breaks termini in nicked duplex (PubMed:27471034, PubMed:29361132)","source":"project UniProt records20261017/18"},{"partner":"EZH2","hgnc":"HGNC:3527","core":true,"core_annotation":{"hgnc":"HGNC:3527","symbol_at_source":"EZH2","accession":"Q15910","function":"Histone modification write, Polycomb group (PcG) protein","target":"histone","pmids":["19026781"],"complexes":"PRC2","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":1062,"hub_weight":0.21204723241999274,"quality":0.65,"programmes":["pubmed:27634302"],"pmids":["27634302"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Catalytic subunit of the PRC2/EED-EZH2 complex, a Polycomb group (PcG) complex that methylates 'Lys-9' (H3K9me) and 'Lys-27' (H3K27me) of histone H3, leading to transcriptional repression of the affected target gene (PubMed:14532106, PubMed:15225548, PubMed:15385962, PubMed:16618801, PubMed:16936726, PubMed:17344414, PubMed:22323599, PubMed:24474760, PubMed:26581166, PubMed:30026490, PubMed:30923826). Able to mono-, di- and trimethylate 'Lys-27' of histone H3 to form H3K27me1, H3K27me2 and H3K27me3, respectively (PubMed:15231737, PubMed:17210787, PubMed:18285464, PubMed:22323599, PubMed:30923826). Displays a preference for substrates with less methylation, loses activity when progressively more methyl groups are incorporated into H3K27, H3K27me0 > H3K27me1 > H3K27me2 (PubMed:22323599, PubMed:30923826). Compared to EZH1-containing complexes, it is more abundant in embryonic stem cells and plays a major role in forming H3K27me3, which is required for embryonic stem cell identity and proper differentiation (PubMed:19026781). The PRC2/EED-EZH2 complex may also serve as a recruiting platform for DNA methyltransferases, thereby linking two epigenetic repression systems (PubMed:16357870, PubMed:17200670). Genes repressed by the PRC2/EED-EZH2 complex include HOXC8, HOXA9, MYT1, CDKN2A and retinoic acid target genes (PubMed:16179254, PubMed:18086877, PubMed:20935635). EZH2 can also methylate non-histone proteins such as the transcription factor GATA4 and the nuclear receptor RORA (PubMed:23063525). Regulates the circadian clock via histone methylation at the promoter of the circadian genes (PubMed:16717091). Essential for the CRY1/2-mediated repression of the transcriptional activation of PER1/2 by the CLOCK-BMAL1 heterodimer; involved in the di and trimethylation of 'Lys-27' of histone H3 on PER1/2 promoters which is necessary for the CRY1/2 proteins to inhibit transcription (By similarity)","source":"project UniProt records20261017/18"},{"partner":"MGA","hgnc":"HGNC:14010","core":true,"core_annotation":{"hgnc":"HGNC:14010","symbol_at_source":"MGA","accession":"Q8IWI9","function":"Histone modification write cofactor, TF","target":"DNA","pmids":[],"complexes":"RING2-L3MBTL2, CHD8, MLL2/3, MLL4/WBP7","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":205,"hub_weight":0.44280744277004763,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Functions as a dual-specificity transcription factor, regulating the expression of both MAX-network and T-box family target genes. Functions as a repressor or an activator. Binds to 5'-AATTTCACACCTAGGTGTGAAATT-3' core sequence and seems to regulate MYC-MAX target genes. Suppresses transcriptional activation by MYC and inhibits MYC-dependent cell transformation. Function activated by heterodimerization with MAX. This heterodimerization serves the dual function of both generating an E-box-binding heterodimer and simultaneously blocking interaction of a corepressor (By similarity)","source":"project UniProt records20261017/18"},{"partner":"KAT14","hgnc":"HGNC:15904","core":true,"core_annotation":{"hgnc":"HGNC:15904","symbol_at_source":"CSRP2BP","accession":"Q9H8E8","function":"Histone modification write","target":"histone","pmids":["19103755"],"complexes":"ATAC","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":101,"hub_weight":0.575435337648436,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Component of the ATAC complex, a complex with histone acetyltransferase activity on histones H3 and H4. May function as a scaffold for the ATAC complex to promote ATAC complex stability. Has also weak histone acetyltransferase activity toward histone H4. Required for the normal progression through G1 and G2/M phases of the cell cycle","source":"project UniProt records20261017/18"},{"partner":"L3MBTL2","hgnc":"HGNC:18594","core":true,"core_annotation":{"hgnc":"HGNC:18594","symbol_at_source":"L3MBTL2","accession":"Q969R5","function":"Histone modification read","target":"histone","pmids":["19233876"],"complexes":"RING2-L3MBTL2","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":176,"hub_weight":0.4703604341917987,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Putative Polycomb group (PcG) protein. PcG proteins maintain the transcriptionally repressive state of genes, probably via a modification of chromatin, rendering it heritably changed in its expressibility. Its association with a chromatin-remodeling complex suggests that it may contribute to prevent expression of genes that trigger the cell into mitosis. Binds to monomethylated and dimethylated 'Lys-20' on histone H4. Binds histone H3 peptides that are monomethylated or dimethylated on 'Lys-4', 'Lys-9' or 'Lys-27'","source":"project UniProt records20261017/18"},{"partner":"MBIP","hgnc":"HGNC:20427","core":true,"core_annotation":{"hgnc":"HGNC:20427","symbol_at_source":"MBIP","accession":"Q9NS73","function":"Histone modification write cofactor","target":"histone","pmids":["19103755"],"complexes":"ATAC","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":150,"hub_weight":0.5,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Functions as part of the ATAC complex, a complex with histone acetyltransferase activity on histones H3 and H4 (PubMed:19103755). Inhibits the MAP3K12 activity to induce the activation of the JNK/SAPK pathway (PubMed:10801814). Together with MOCS2B, inhibits the activity of stress kinase EIF2AK2/PKR; this may lead to effects such as suppression of JNK activation and subsequent stress-responsive transcription, or suppression of eIF2a phosphorylation to favor translation (PubMed:26705305)","source":"project UniProt records20261017/18"},{"partner":"PCGF6","hgnc":"HGNC:21156","core":true,"core_annotation":{"hgnc":"HGNC:21156","symbol_at_source":"PCGF6","accession":"Q9BYE7","function":"Polycomb group (PcG) protein","target":"#","pmids":["21282530"],"complexes":"PRC1, RING2-L3MBTL2","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":159,"hub_weight":0.4891159880445185,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Transcriptional repressor (PubMed:12167161). May modulate the levels of histone H3K4Me3 by activating KDM5D histone demethylase (PubMed:17320162). Component of a Polycomb group (PcG) multiprotein PRC1-like complex, a complex class required to maintain the transcriptionally repressive state of many genes, including Hox genes, throughout development. PcG PRC1 complex acts via chromatin remodeling and modification of histones; it mediates monoubiquitination of histone H2A 'Lys-119', rendering chromatin heritably changed in its expressibility (PubMed:12167161). Within the PRC1-like complex, regulates RNF2 ubiquitin ligase activity (PubMed:26151332)","source":"project UniProt records20261017/18"},{"partner":"SATB2","hgnc":"HGNC:21637","core":true,"core_annotation":{"hgnc":"HGNC:21637","symbol_at_source":"SATB2","accession":"Q9UPW6","function":"Chromatin remodeling cofactor","target":"chromatin","pmids":["18255031"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":160,"hub_weight":0.4879500364742666,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus matrix","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Binds to DNA, at nuclear matrix- or scaffold-associated regions. Thought to recognize the sugar-phosphate structure of double-stranded DNA. Transcription factor controlling nuclear gene expression, by binding to matrix attachment regions (MARs) of DNA and inducing a local chromatin-loop remodeling. Acts as a docking site for several chromatin remodeling enzymes and also by recruiting corepressors (HDACs) or coactivators (HATs) directly to promoters and enhancers. Required for the initiation of the upper-layer neurons (UL1) specific genetic program and for the inactivation of deep-layer neurons (DL) and UL2 specific genes, probably by modulating BCL11B expression. Repressor of Ctip2 and regulatory determinant of corticocortical connections in the developing cerebral cortex. May play an important role in palate formation. Acts as a molecular node in a transcriptional network regulating skeletal development and osteoblast differentiation","source":"project UniProt records20261017/18"},{"partner":"ZZZ3","hgnc":"HGNC:24523","core":true,"core_annotation":{"hgnc":"HGNC:24523","symbol_at_source":"ZZZ3","accession":"Q8IYH5","function":"Histone modification read","target":"histone","pmids":["19103755"],"complexes":"ATAC","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":129,"hub_weight":0.52851642258169,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone H3 reader that is required for the ATAC complex-mediated maintenance of histone acetylation and gene activation (PubMed:30217978). Component of the ATAC complex, a complex with histone acetyltransferase activity on histones H3 and H4 (PubMed:19103755)","source":"project UniProt records20261017/18"},{"partner":"YEATS2","hgnc":"HGNC:25489","core":true,"core_annotation":{"hgnc":"HGNC:25489","symbol_at_source":"YEATS2","accession":"Q9ULM3","function":"Histone chaperone","target":"histone","pmids":["18838386","29057918"],"complexes":"ATAC","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":155,"hub_weight":0.4938647983247948,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Chromatin reader component of the ATAC complex, a complex with histone acetyltransferase activity on histones H3 and H4 (PubMed:18838386, PubMed:19103755, PubMed:27103431). YEATS2 specifically recognizes and binds histone H3 crotonylated at 'Lys-27' (H3K27cr) (PubMed:27103431). Crotonylation marks active promoters and enhancers and confers resistance to transcriptional repressors (PubMed:27103431)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"PNMA8A":{"coreEvidence":[{"partner":"EED","hgnc":"HGNC:3188","core":true,"core_annotation":{"hgnc":"HGNC:3188","symbol_at_source":"EED","accession":"O75530","function":"Polycomb group (PcG) protein","target":"#","pmids":["9584199"],"complexes":"PRC2","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":587,"hub_weight":0.2801659073402629,"quality":0.4,"programmes":["pubmed:41932313"],"pmids":["41932313"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Polycomb group (PcG) protein. Component of the PRC2/EED-EZH2 complex, which methylates 'Lys-9' and 'Lys-27' of histone H3, leading to transcriptional repression of the affected target gene. Also recognizes 'Lys-26' trimethylated histone H1 with the effect of inhibiting PRC2 complex methyltransferase activity on nucleosomal histone H3 'Lys-27', whereas H3 'Lys-27' recognition has the opposite effect, enabling the propagation of this repressive mark. The PRC2/EED-EZH2 complex may also serve as a recruiting platform for DNA methyltransferases, thereby linking two epigenetic repression systems. Genes repressed by the PRC2/EED-EZH2 complex include HOXC8, HOXA9, MYT1 and CDKN2A","source":"project UniProt records20261017/18"},{"partner":"H1-4","hgnc":"HGNC:4718","core":true,"core_annotation":{"hgnc":"HGNC:4718","symbol_at_source":"HIST1H1E","accession":"P10412","function":"Histone/protamine","target":"chromatin","pmids":[],"version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":559,"hub_weight":0.2865341275306264,"quality":0.65,"programmes":["pubmed:37071682"],"pmids":["37071682"],"assays":["crosslink"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone H1 protein binds to linker DNA between nucleosomes forming the macromolecular structure known as the chromatin fiber (PubMed:35581345, PubMed:40240600). Histones H1 are necessary for the condensation of nucleosome chains into higher-order structured fibers and promote formation of the H3K27me3 mark by the PRC2/EED-EZH2 complex (PubMed:35581345, PubMed:40240600, PubMed:40516528). Ability to associate with nucleosomes and compact chromatin depends on linker DNA length and trajectory (PubMed:35581345). Also acts as a regulator of individual gene transcription through chromatin remodeling, nucleosome spacing and DNA methylation (PubMed:40240600)","source":"project UniProt records20261017/18"},{"partner":"H1-6","hgnc":"HGNC:4720","core":true,"core_annotation":{"hgnc":"HGNC:4720","symbol_at_source":"HIST1H1T","accession":"P22492","function":"Histone/protamine","target":"chromatin","pmids":[],"version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":223,"hub_weight":0.4279604925109129,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Testis-specific histone H1 that forms less compacted chromatin compared to other H1 histone subtypes (PubMed:26757249). Formation of more relaxed chromatin may be required to promote chromatin architecture required for proper chromosome regulation during meiosis, such as homologous recombination (PubMed:26757249). Histones H1 act as linkers that bind to nucleosomes and compact polynucleosomes into a higher-order chromatin configuration (Probable)","source":"project UniProt records20261017/18"},{"partner":"NUCLEOLIN","hgnc":"HGNC:7667","core":true,"core_annotation":{"hgnc":"HGNC:7667","symbol_at_source":"NCL","accession":"P19338","function":"Histone chaperone","target":"histone, DNA, RNA","pmids":["16601700"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":695,"hub_weight":0.2590638800754199,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus, nucleolus; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Nucleolin is the major nucleolar protein of growing eukaryotic cells. It is found associated with intranucleolar chromatin and pre-ribosomal particles. It induces chromatin decondensation by binding to histone H1. It is thought to play a role in pre-rRNA transcription and ribosome assembly. May play a role in the process of transcriptional elongation. Binds RNA oligonucleotides with 5'-UUAGGG-3' repeats more tightly than the telomeric single-stranded DNA 5'-TTAGGG-3' repeats","source":"project UniProt records20261017/18"},{"partner":"OGT","hgnc":"HGNC:8127","core":true,"core_annotation":{"hgnc":"HGNC:8127","symbol_at_source":"OGT","accession":"O15294","function":"Histone modification write","target":"histone","pmids":["22121020"],"complexes":"NSL","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":741,"hub_weight":0.2514182275771345,"quality":1,"programmes":["pubmed:32994395"],"pmids":["32994395"],"assays":["reconstituted"],"contexts":[],"partner_location":"Nucleus; Cytoplasm; Mitochondrion; Membrane; Cytoplasm; Nucleus; Cell membrane; Mitochondrion membrane; Cell projection; Cytoplasm; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Catalyzes the transfer of a single N-acetylglucosamine from UDP-GlcNAc to a serine or threonine residue in cytoplasmic and nuclear proteins resulting in their modification with a beta-linked N-acetylglucosamine (O-GlcNAc) (PubMed:12150998, PubMed:15361863, PubMed:19451179, PubMed:20018868, PubMed:21240259, PubMed:21285374, PubMed:23103939, PubMed:26237509, PubMed:26369908, PubMed:26678539, PubMed:27713473, PubMed:37541260, PubMed:37962578). Glycosylates a large and diverse number of proteins including histone H2B, AKT1, AMPK, ATG4B, CAPRIN1, EZH2, FNIP1, GSDMD, KRT7, LMNA, LMNB1, LMNB2, RPTOR, HOXA1, PFKL, KMT2E/MLL5, MAPT/TAU, TET2, RBL2, RET, NOD2 and HCFC1 (PubMed:19451179, PubMed:20200153, PubMed:21285374, PubMed:22923583, PubMed:23353889, PubMed:24474760, PubMed:26237509, PubMed:26369908, PubMed:26678539, PubMed:27527864, PubMed:30699359, PubMed:34074792, PubMed:34667079, PubMed:37541260, PubMed:37962578). Can regulate their cellular processes via cross-talk between glycosylation and phosphorylation or by affecting proteolytic processing (PubMed:21285374). Involved in insulin resistance in muscle and adipocyte cells via glycosylating insulin signaling components and inhibiting the 'Thr-308' phosphorylation of AKT1, enhancing IRS1 phosphorylation and attenuating insulin signaling (By similarity). Involved in glycolysis regulation by mediating glycosylation of 6-phosphofructokinase PFKL, inhibiting its activity (PubMed:22923583). Plays a key role in chromatin structure by mediating O-GlcNAcylation of 'Ser-112' of histone H2B: recruited to CpG-rich transcription start sites of active genes via its interaction with TET proteins (TET1, TET2 or TET3) (PubMed:22121020, PubMed:23353889). As part of the NSL complex indirectly involved in acetylation of nucleosomal histone H4 on several lysine residues (PubMed:20018852). O-GlcNAcylation of 'Ser-75' of EZH2 increases its stability, and facilitating the formation of H3K27me3 by the PRC2/EED-EZH2 complex (PubMed:24474760). Stabilizes KMT2E/MLL5 by mediating its glycosylation, thereby preventing KMT2E/MLL5 ubiquitination (PubMed:26678539). Regulates circadian oscillation of the clock genes and glucose homeostasis in the liver (By similarity). Stabilizes clock proteins BMAL1 and CLOCK through O-glycosylation, which prevents their ubiquitination and subsequent degradation (By similarity). Promotes the CLOCK-BMAL1-mediated transcription of genes in the negative loop of the circadian clock such as PER1/2 and CRY1/2. O-glycosylates HCFC1 and regulates its proteolytic processing and transcriptional activity (PubMed:21285374, PubMed:28302723, PubMed:28584052). Component of a THAP1/THAP3-HCFC1-OGT complex that is required for the regulation of the transcriptional activity of RRM1 (PubMed:20200153). Regulates mitochondrial motility in neurons by mediating glycosylation of TRAK1 (By similarity). Promotes autophagy by mediating O-glycosylation of ATG4B (PubMed:27527864). Acts as a regulator of mTORC1 signaling by mediating O-glycosylation of RPTOR and FNIP1: O-GlcNAcylation of RPTOR in response to glucose sufficiency promotes activation of the mTORC1 complex (PubMed:30699359, PubMed:37541260)\nThe mitochondrial isoform (mOGT) is cytotoxic and triggers apoptosis in several cell types including INS1, an insulinoma cell line\nHas N-acetylglucosaminyltransferase activity: glycosylates proteins, such as HNRNPU, NEUROD1, NUP62 and PDCD6IP (PubMed:31527085). Displays specific substrate selectivity compared to other isoforms (PubMed:31527085)","source":"project UniProt records20261017/18"},{"partner":"NSD2","hgnc":"HGNC:12766","core":true,"core_annotation":{"hgnc":"HGNC:12766","symbol_at_source":"WHSC1","accession":"O96028","function":"Histone modification write","target":"histone","pmids":["18172012"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":231,"hub_weight":0.4218245406095978,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus; Chromosome; Nucleus; Chromosome; Nucleus; Cytoplasm; Nucleus, nucleolus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone methyltransferase which specifically dimethylates nucleosomal histone H3 at 'Lys-36' (H3K36me2) (PubMed:19808676, PubMed:22099308, PubMed:27571355, PubMed:29728617, PubMed:33941880). Also monomethylates nucleosomal histone H3 at 'Lys-36' (H3K36me) in vitro (PubMed:22099308). Does not trimethylate nucleosomal histone H3 at 'Lys-36' (H3K36me3) (PubMed:22099308). However, specifically trimethylates histone H3 at 'Lys-36' (H3K36me3) at euchromatic regions in embryonic stem (ES) cells (By similarity). By methylating histone H3 at 'Lys-36', involved in the regulation of gene transcription during various biological processes (PubMed:16115125, PubMed:22099308, PubMed:29728617). In ES cells, associates with developmental transcription factors such as SALL1 and represses inappropriate gene transcription mediated by histone deacetylation (By similarity). During heart development, associates with transcription factor NKX2-5 to repress transcription of NKX2-5 target genes (By similarity). Plays an essential role in adipogenesis, by regulating expression of genes involved in pre-adipocyte differentiation (PubMed:29728617). During T-cell receptor (TCR) and CD28-mediated T-cell activation, promotes the transcription of transcription factor BCL6 which is required for follicular helper T (Tfh) cell differentiation (By similarity). During B-cell development, required for the generation of the B1 lineage (By similarity). During B2 cell activation, may contribute to the control of isotype class switch recombination (CRS), splenic germinal center formation, and the humoral immune response (By similarity). Plays a role in class switch recombination of the immunoglobulin heavy chain (IgH) locus during B-cell activation (By similarity). By regulating the methylation of histone H3 at 'Lys-36' and histone H4 at 'Lys-20' at the IgH locus, involved in TP53BP1 recruitment to the IgH switch region and promotes the transcription of IgA (By similarity)\nHistone methyltransferase which specifically dimethylates nucleosomal histone H3 at 'Lys-36' (H3K36me2)\nHistone methyltransferase which specifically dimethylates nucleosomal histone H3 at 'Lys-36' (H3K36me2) (PubMed:22099308). Methylation of histone H3 at 'Lys-27' is controversial (PubMed:18172012, PubMed:22099308). Mono-, di- or tri-methylates histone H3 at 'Lys-27' (H3K27me, H3K27me2 and H3K27me3) (PubMed:18172012). Does not methylate histone H3 at 'Lys-27' (PubMed:22099308). May act as a transcription regulator that binds DNA and suppresses IL5 transcription through HDAC recruitment (PubMed:11152655, PubMed:18172012)","source":"project UniProt records20261017/18"},{"partner":"KAT6A","hgnc":"HGNC:13013","core":true,"core_annotation":{"hgnc":"HGNC:13013","symbol_at_source":"KAT6A","accession":"Q92794","function":"Histone modification write","target":"histone","pmids":["11313971"],"complexes":"MOZ/MORF","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":415,"hub_weight":0.32791291789197646,"quality":0.65,"programmes":["pubmed:36537216"],"pmids":["36537216"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus; Nucleus, nucleolus; Nucleus, nucleoplasm; Nucleus, PML body","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone acetyltransferase that acetylates lysine residues in histone H3 and histone H4 (in vitro) (PubMed:11742995, PubMed:11965546). Component of the MOZ/MORF complex which has a histone H3 acetyltransferase activity (PubMed:11965546). May act as a transcriptional coactivator for RUNX1 and RUNX2 (PubMed:12771199). Acetylates p53/TP53 at 'Lys-120' and 'Lys-382' and controls its transcriptional activity via association with PML (PubMed:23431171). May play a role in leukemogenic gene transcription (PubMed:39794553)","source":"project UniProt records20261017/18"},{"partner":"POLE3","hgnc":"HGNC:13546","core":true,"core_annotation":{"hgnc":"HGNC:13546","symbol_at_source":"POLE3","accession":"Q9NRF9","function":"Histone chaperone","target":"histone","pmids":["10880450"],"complexes":"CHRAC","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":72,"hub_weight":0.6401843996644799,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Accessory component of the DNA polymerase epsilon complex (PubMed:10801849). Participates in DNA repair and in chromosomal DNA replication (By similarity). Forms a complex with CHRAC1 and binds naked DNA, which is then incorporated into chromatin, aided by the nucleosome-remodeling activity of ISWI/SNF2H and ACF1 (PubMed:10801849). Does not enhance nucleosome sliding activity of the ACF-5 ISWI chromatin remodeling complex (PubMed:14759371)","source":"project UniProt records20261017/18"},{"partner":"H2AJ","hgnc":"HGNC:14456","core":true,"core_annotation":{"hgnc":"HGNC:14456","symbol_at_source":"H2AFJ","accession":"Q9BTM1","function":"Histone/protamine","target":"chromatin","pmids":[],"version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":136,"hub_weight":0.5184758473652126,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Core component of nucleosome. Nucleosomes wrap and compact DNA into chromatin, limiting DNA accessibility to the cellular machineries which require DNA as a template. Histones thereby play a central role in transcription regulation, DNA repair, DNA replication and chromosomal stability. DNA accessibility is regulated via a complex set of post-translational modifications of histones, also called histone code, and nucleosome remodeling","source":"project UniProt records20261017/18"},{"partner":"ASH1L","hgnc":"HGNC:19088","core":true,"core_annotation":{"hgnc":"HGNC:19088","symbol_at_source":"ASH1L","accession":"Q9NR48","function":"Histone modification write","target":"histone","pmids":["21239497"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":45,"hub_weight":0.7254762501100116,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus; Cell junction, tight junction; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone methyltransferase specifically trimethylating 'Lys-36' of histone H3 forming H3K36me3 (PubMed:21239497). Also monomethylates 'Lys-9' of histone H3 (H3K9me1) in vitro (By similarity). The physiological significance of the H3K9me1 activity is unclear (By similarity)","source":"project UniProt records20261017/18"},{"partner":"USP36","hgnc":"HGNC:20062","core":true,"core_annotation":{"hgnc":"HGNC:20062","symbol_at_source":"USP36","accession":"Q9P275","function":"Histone modification write cofactor","target":"histone","pmids":["22622177"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":492,"hub_weight":0.3037283696153935,"quality":0.65,"programmes":["pubmed:36912080"],"pmids":["36912080"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus, nucleolus; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Deubiquitinase essential for the regulation of nucleolar structure and function (PubMed:19208757, PubMed:22902402, PubMed:29273634). Required for cell and organism viability (PubMed:19208757, PubMed:22902402, PubMed:29273634). Plays an important role in ribosomal RNA processing and protein synthesis, which is mediated, at least in part, through deubiquitination of DHX33, NPM1 and FBL, regulating their protein stability (PubMed:19208757, PubMed:22902402, PubMed:29273634, PubMed:36912080). Functions as a transcriptional repressor by deubiquiting histone H2B at the promoters of genes critical for cellular differentiation, such as CDKN1A, thereby preventing histone H3 'Lys-4' trimethylation (H3K4) (PubMed:29274341). Specifically deubiquitinates MYC in the nucleolus, leading to prevent MYC degradation by the proteasome: acts by specifically interacting with isoform 3 of FBXW7 (FBW7gamma) in the nucleolus and counteracting ubiquitination of MYC by the SCF(FBW7) complex (PubMed:25775507). In contrast, it does not interact with isoform 1 of FBXW7 (FBW7alpha) in the nucleoplasm (PubMed:25775507). Interacts to and regulates the actions of E3 ubiquitin-protein ligase NEDD4L over substrates such as NTRK1, KCNQ2 and KCNQ3, affecting their expression an functions (PubMed:27445338). Deubiquitinates SOD2, regulates SOD2 protein stability (PubMed:21268071). Deubiquitinase activity is required to control selective autophagy activation by ubiquitinated proteins (PubMed:22622177). Promotes CEP63 stabilization through 'Lys-48'-linked deubiquitination leading to increased stability (PubMed:35989368). Acts as a SUMO ligase to promote EXOSC10 sumoylation critical for the nucleolar RNA exosome function in rRNA processing (PubMed:36912080). Binds to pre-rRNAs (PubMed:36912080)","source":"project UniProt records20261017/18"},{"partner":"GLYR1","hgnc":"HGNC:24434","core":true,"core_annotation":{"hgnc":"HGNC:24434","symbol_at_source":"GLYR1","accession":"Q49A26","function":"Histone modification read","target":"histone","pmids":["20850016"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":232,"hub_weight":0.42107596053325946,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Cytokine-like nuclear factor with chromatin gene reader activity involved in chromatin modification and regulation of gene expression (PubMed:23260659, PubMed:30970244). Acts as a nucleosome-destabilizing factor that is recruited to genes during transcriptional activation (PubMed:29759984, PubMed:30970244). Recognizes and binds histone H3 without a preference for specific epigenetic markers and also binds DNA (PubMed:20850016, PubMed:30970244). Interacts with KDM1B and promotes its histone demethylase activity by facilitating the capture of H3 tails, they form a multifunctional enzyme complex that modifies transcribed chromatin and facilitates Pol II transcription through nucleosomes (PubMed:23260659, PubMed:29759984, PubMed:30970244). Stimulates the acetylation of 'Lys-56' of nucleosomal histone H3 (H3K56ac) by EP300 (PubMed:29759984). With GATA4, co-binds a defined set of heart development genes and coregulates their expression during cardiomyocyte differentiation (PubMed:35182466). Regulates p38 MAP kinase activity by mediating stress activation of MAPK14/p38alpha and specifically regulating MAPK14 signaling (PubMed:16352664). Indirectly promotes phosphorylation of MAPK14 and activation of ATF2 (PubMed:16352664). The phosphorylation of MAPK14 requires upstream activity of MAP2K4 and MAP2K6 (PubMed:16352664)","source":"project UniProt records20261017/18"},{"partner":"HP1BP3","hgnc":"HGNC:24973","core":true,"core_annotation":{"hgnc":"HGNC:24973","symbol_at_source":"HP1BP3","accession":"Q5SSJ5","function":"Chromatin remodeling","target":"chromatin","pmids":["25100860"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":310,"hub_weight":0.37267799624996495,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Component of heterochromatin that maintains heterochromatin integrity during G1/S progression and regulates the duration of G1 phase to critically influence cell proliferative capacity (PubMed:24830416). Mediates chromatin condensation during hypoxia, leading to increased tumor cell viability, radio-resistance, chemo-resistance and self-renewal (PubMed:25100860)","source":"project UniProt records20261017/18"},{"partner":"RRP8","hgnc":"HGNC:29030","core":true,"core_annotation":{"hgnc":"HGNC:29030","symbol_at_source":"RRP8","accession":"O43159","function":"Histone modification cofactor","target":"histone","pmids":["18485871"],"complexes":"eNoSc","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":272,"hub_weight":0.3940552031195503,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus, nucleolus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Essential component of the eNoSC (energy-dependent nucleolar silencing) complex, a complex that mediates silencing of rDNA in response to intracellular energy status and acts by recruiting histone-modifying enzymes. The eNoSC complex is able to sense the energy status of cell: upon glucose starvation, elevation of NAD(+)/NADP(+) ratio activates SIRT1, leading to histone H3 deacetylation followed by dimethylation of H3 at 'Lys-9' (H3K9me2) by SUV39H1 and the formation of silent chromatin in the rDNA locus. In the complex, RRP8 binds to H3K9me2 and probably acts as a methyltransferase. Its substrates are however unknown","source":"project UniProt records20261017/18"},{"partner":"NAT10","hgnc":"HGNC:29830","core":true,"core_annotation":{"hgnc":"HGNC:29830","symbol_at_source":"NAT10","accession":"Q9H0A0","function":"Histone modification write","target":"histone","pmids":["14592445"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":313,"hub_weight":0.37113480951260275,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus, nucleolus; Midbody","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"RNA cytidine acetyltransferase that catalyzes the formation of N(4)-acetylcytidine (ac4C) modification on mRNAs, 18S rRNA and tRNAs (PubMed:25411247, PubMed:25653167, PubMed:30449621, PubMed:35679869). Catalyzes ac4C modification of a broad range of mRNAs, enhancing mRNA stability and translation (PubMed:30449621, PubMed:35679869). mRNA ac4C modification is frequently present within wobble cytidine sites and promotes translation efficiency (PubMed:30449621). Mediates the formation of ac4C at position 1842 in 18S rRNA (PubMed:25411247). May also catalyze the formation of ac4C at position 1337 in 18S rRNA (By similarity). Required for early nucleolar cleavages of precursor rRNA at sites A0, A1 and A2 during 18S rRNA synthesis (PubMed:25411247, PubMed:25653167). Catalyzes the formation of ac4C in serine and leucine tRNAs (By similarity). Requires the tRNA-binding adapter protein THUMPD1 for full tRNA acetyltransferase activity but not for 18S rRNA acetylation (PubMed:25653167). In addition to RNA acetyltransferase activity, also able to acetylate lysine residues of proteins, such as histones, microtubules, p53/TP53 and MDM2, in vitro (PubMed:14592445, PubMed:17631499, PubMed:19303003, PubMed:26882543, PubMed:27993683, PubMed:30165671). The relevance of the protein lysine acetyltransferase activity is however unsure in vivo (PubMed:30449621). Activates telomerase activity by stimulating the transcription of TERT, and may also regulate telomerase function by affecting the balance of telomerase subunit assembly, disassembly, and localization (PubMed:14592445, PubMed:18082603). Involved in the regulation of centrosome duplication by acetylating CENATAC during mitosis, promoting SASS6 proteasome degradation (PubMed:31722219). Part of the small subunit (SSU) processome, first precursor of the small eukaryotic ribosomal subunit. During the assembly of the SSU processome in the nucleolus, many ribosome biogenesis factors, an RNA chaperone and ribosomal proteins associate with the nascent pre-rRNA and work in concert to generate RNA folding, modifications, rearrangements and cleavage as well as targeted degradation of pre-ribosomal RNA by the RNA exosome (PubMed:34516797)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"PHLDB3":{"coreEvidence":[{"partner":"BMAL1","hgnc":"HGNC:701","core":true,"core_annotation":{"hgnc":"HGNC:701","symbol_at_source":"ARNTL","accession":"O00327","function":"Histone modification write cofactor, TF","target":"histone","pmids":["14645221","24395244"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":87,"hub_weight":0.604122093330177,"quality":0.65,"programmes":["pubmed:27173435"],"pmids":["27173435"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus; Cytoplasm; Nucleus, PML body","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Transcriptional activator which forms a core component of the circadian clock. The circadian clock, an internal time-keeping system, regulates various physiological processes through the generation of approximately 24 hour circadian rhythms in gene expression, which are translated into rhythms in metabolism and behavior. It is derived from the Latin roots 'circa' (about) and 'diem' (day) and acts as an important regulator of a wide array of physiological functions including metabolism, sleep, body temperature, blood pressure, endocrine, immune, cardiovascular, and renal function. Consists of two major components: the central clock, residing in the suprachiasmatic nucleus (SCN) of the brain, and the peripheral clocks that are present in nearly every tissue and organ system. Both the central and peripheral clocks can be reset by environmental cues, also known as Zeitgebers (German for 'timegivers'). The predominant Zeitgeber for the central clock is light, which is sensed by retina and signals directly to the SCN. The central clock entrains the peripheral clocks through neuronal and hormonal signals, body temperature and feeding-related cues, aligning all clocks with the external light/dark cycle. Circadian rhythms allow an organism to achieve temporal homeostasis with its environment at the molecular level by regulating gene expression to create a peak of protein expression once every 24 hours to control when a particular physiological process is most active with respect to the solar day. Transcription and translation of core clock components (CLOCK, NPAS2, BMAL1, BMAL2, PER1, PER2, PER3, CRY1 and CRY2) plays a critical role in rhythm generation, whereas delays imposed by post-translational modifications (PTMs) are important for determining the period (tau) of the rhythms (tau refers to the period of a rhythm and is the length, in time, of one complete cycle). A diurnal rhythm is synchronized with the day/night cycle, while the ultradian and infradian rhythms have a period shorter and longer than 24 hours, respectively. Disruptions in the circadian rhythms contribute to the pathology of cardiovascular diseases, cancer, metabolic syndromes and aging. A transcription/translation feedback loop (TTFL) forms the core of the molecular circadian clock mechanism. Transcription factors, CLOCK or NPAS2 and BMAL1 or BMAL2, form the positive limb of the feedback loop, act in the form of a heterodimer and activate the transcription of core clock genes and clock-controlled genes (involved in key metabolic processes), harboring E-box elements (5'-CACGTG-3') within their promoters. The core clock genes: PER1/2/3 and CRY1/2 which are transcriptional repressors form the negative limb of the feedback loop and interact with the CLOCK|NPAS2-BMAL1|BMAL2 heterodimer inhibiting its activity and thereby negatively regulating their own expression. This heterodimer also activates nuclear receptors NR1D1/2 and RORA/B/G, which form a second feedback loop and which activate and repress BMAL1 transcription, respectively. BMAL1 positively regulates myogenesis and negatively regulates adipogenesis via the transcriptional control of the genes of the canonical Wnt signaling pathway. Plays a role in normal pancreatic beta-cell function; regulates glucose-stimulated insulin secretion via the regulation of antioxidant genes NFE2L2/NRF2 and its targets SESN2, PRDX3, CCLC and CCLM. Negatively regulates the mTORC1 signaling pathway; regulates the expression of MTOR and DEPTOR. Controls diurnal oscillations of Ly6C inflammatory monocytes; rhythmic recruitment of the PRC2 complex imparts diurnal variation to chemokine expression that is necessary to sustain Ly6C monocyte rhythms. Regulates the expression of HSD3B2, STAR, PTGS2, CYP11A1, CYP19A1 and LHCGR in the ovary and also the genes involved in hair growth. Plays an important role in adult hippocampal neurogenesis by regulating the timely entry of neural stem/progenitor cells (NSPCs) into the cell cycle and the number of cell divisions that take place prior to cell-cycle exit. Regulates the circadian expression of CIART and KLF11. The CLOCK-BMAL1 heterodimer regulates the circadian expression of SERPINE1/PAI1, VWF, B3, CCRN4L/NOC, NAMPT, DBP, MYOD1, PPARGC1A, PPARGC1B, SIRT1, GYS2, F7, NGFR, GNRHR, BHLHE40/DEC1, ATF4, MTA1, KLF10 and also genes implicated in glucose and lipid metabolism. Promotes rhythmic chromatin opening, regulating the DNA accessibility of other transcription factors. The NPAS2-BMAL1 heterodimer positively regulates the expression of MAOA, F7 and LDHA and modulates the circadian rhythm of daytime contrast sensitivity by regulating the rhythmic expression of adenylate cyclase type 1 (ADCY1) in the retina. The preferred binding motif for the CLOCK-BMAL1 heterodimer is 5'-CACGTGA-3', which contains a flanking adenine nucleotide at the 3-prime end of the canonical 6-nucleotide E-box sequence (PubMed:23229515). CLOCK specifically binds to the half-site 5'-CAC-3', while BMAL1 binds to the half-site 5'-GTGA-3' (PubMed:23229515). The CLOCK-BMAL1 heterodimer also recognizes the non-canonical E-box motifs 5'-AACGTGA-3' and 5'-CATGTGA-3' (PubMed:23229515). Essential for the rhythmic interaction of CLOCK with ASS1 and plays a critical role in positively regulating CLOCK-mediated acetylation of ASS1 (PubMed:28985504). Plays a role in protecting against lethal sepsis by limiting the expression of immune checkpoint protein CD274 in macrophages in a PKM2-dependent manner (By similarity). Regulates the diurnal rhythms of skeletal muscle metabolism via transcriptional activation of genes promoting triglyceride synthesis (DGAT2) and metabolic efficiency (COQ10B) (By similarity)\n(Microbial infection) Regulates SARS coronavirus-2/SARS-CoV-2 entry and replication in lung epithelial cells probably through the post-transcriptional regulation of ACE2 and interferon-stimulated gene expression","source":"project UniProt records20261017/18"},{"partner":"CLOCK","hgnc":"HGNC:2082","core":true,"core_annotation":{"hgnc":"HGNC:2082","symbol_at_source":"CLOCK","accession":"O15516","function":"Histone modification write","target":"histone","pmids":[],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":72,"hub_weight":0.6401843996644799,"quality":0.65,"programmes":["pubmed:27173435"],"pmids":["27173435"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus; Cytoplasm; Cytoplasm, cytosol","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Transcriptional activator which forms a core component of the circadian clock. The circadian clock, an internal time-keeping system, regulates various physiological processes through the generation of approximately 24 hour circadian rhythms in gene expression, which are translated into rhythms in metabolism and behavior. It is derived from the Latin roots 'circa' (about) and 'diem' (day) and acts as an important regulator of a wide array of physiological functions including metabolism, sleep, body temperature, blood pressure, endocrine, immune, cardiovascular, and renal function. Consists of two major components: the central clock, residing in the suprachiasmatic nucleus (SCN) of the brain, and the peripheral clocks that are present in nearly every tissue and organ system. Both the central and peripheral clocks can be reset by environmental cues, also known as Zeitgebers (German for 'timegivers'). The predominant Zeitgeber for the central clock is light, which is sensed by retina and signals directly to the SCN. The central clock entrains the peripheral clocks through neuronal and hormonal signals, body temperature and feeding-related cues, aligning all clocks with the external light/dark cycle. Circadian rhythms allow an organism to achieve temporal homeostasis with its environment at the molecular level by regulating gene expression to create a peak of protein expression once every 24 hours to control when a particular physiological process is most active with respect to the solar day. Transcription and translation of core clock components (CLOCK, NPAS2, BMAL1, BMAL2, PER1, PER2, PER3, CRY1 and CRY2) plays a critical role in rhythm generation, whereas delays imposed by post-translational modifications (PTMs) are important for determining the period (tau) of the rhythms (tau refers to the period of a rhythm and is the length, in time, of one complete cycle). A diurnal rhythm is synchronized with the day/night cycle, while the ultradian and infradian rhythms have a period shorter and longer than 24 hours, respectively. Disruptions in the circadian rhythms contribute to the pathology of cardiovascular diseases, cancer, metabolic syndromes and aging. A transcription/translation feedback loop (TTFL) forms the core of the molecular circadian clock mechanism. Transcription factors, CLOCK or NPAS2 and BMAL1 or BMAL2, form the positive limb of the feedback loop, act in the form of a heterodimer and activate the transcription of core clock genes and clock-controlled genes (involved in key metabolic processes), harboring E-box elements (5'-CACGTG-3') within their promoters. The core clock genes: PER1/2/3 and CRY1/2 which are transcriptional repressors form the negative limb of the feedback loop and interact with the CLOCK|NPAS2-BMAL1|BMAL2 heterodimer inhibiting its activity and thereby negatively regulating their own expression. This heterodimer also activates nuclear receptors NR1D1/2 and RORA/B/G, which form a second feedback loop and which activate and repress BMAL1 transcription, respectively. Regulates the circadian expression of ICAM1, VCAM1, CCL2, THPO and MPL and also acts as an enhancer of the transactivation potential of NF-kappaB. Plays an important role in the homeostatic regulation of sleep. The CLOCK-BMAL1 heterodimer regulates the circadian expression of SERPINE1/PAI1, VWF, B3, CCRN4L/NOC, NAMPT, DBP, MYOD1, PPARGC1A, PPARGC1B, SIRT1, GYS2, F7, NGFR, GNRHR, BHLHE40/DEC1, ATF4, MTA1, KLF10 and also genes implicated in glucose and lipid metabolism. Promotes rhythmic chromatin opening, regulating the DNA accessibility of other transcription factors. The CLOCK-BMAL2 heterodimer activates the transcription of SERPINE1/PAI1 and BHLHE40/DEC1. The preferred binding motif for the CLOCK-BMAL1 heterodimer is 5'-CACGTGA-3', which contains a flanking adenine nucleotide at the 3-prime end of the canonical 6-nucleotide E-box sequence (PubMed:23229515). CLOCK specifically binds to the half-site 5'-CAC-3', while BMAL1 binds to the half-site 5'-GTGA-3' (PubMed:23229515). The CLOCK-BMAL1 heterodimer also recognizes the non-canonical E-box motifs 5'-AACGTGA-3' and 5'-CATGTGA-3' (PubMed:23229515). CLOCK has an intrinsic acetyltransferase activity, which enables circadian chromatin remodeling by acetylating histones and nonhistone proteins, including its own partner BMAL1. Represses glucocorticoid receptor NR3C1/GR-induced transcriptional activity by reducing the association of NR3C1/GR to glucocorticoid response elements (GREs) via the acetylation of multiple lysine residues located in its hinge region (PubMed:21980503). The acetyltransferase activity of CLOCK is as important as its transcription activity in circadian control. Acetylates metabolic enzymes IMPDH2 and NDUFA9 in a circadian manner. Facilitated by BMAL1, rhythmically interacts and acetylates argininosuccinate synthase 1 (ASS1) leading to enzymatic inhibition of ASS1 as well as the circadian oscillation of arginine biosynthesis and subsequent ureagenesis (PubMed:28985504). Drives the circadian rhythm of blood pressure through transcriptional activation of ATP1B1 (By similarity)","source":"project UniProt records20261017/18"},{"partner":"HMG20A","hgnc":"HGNC:5001","core":true,"core_annotation":{"hgnc":"HGNC:5001","symbol_at_source":"HMG20A","accession":"Q9NP66","function":"Chromatin remodeling cofactor","target":"histone","pmids":["24227653"],"complexes":"LSD-CoREST","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":201,"hub_weight":0.4463218426774518,"quality":0.65,"programmes":["pubmed:27173435"],"pmids":["27173435"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Plays a role in neuronal differentiation as chromatin-associated protein. Acts as inhibitor of HMG20B. Overcomes the repressive effects of the neuronal silencer REST and induces the activation of neuronal-specific genes. Involved in the recruitment of the histone methyltransferase KMT2A/MLL1 and consequent increased methylation of histone H3 lysine 4 (By similarity)","source":"project UniProt records20261017/18"},{"partner":"MAX","hgnc":"HGNC:6913","core":true,"core_annotation":{"hgnc":"HGNC:6913","symbol_at_source":"MAX","accession":"P61244","function":"Histone modification write cofactor, TF","target":"DNA","pmids":["18271930","12004135"],"complexes":"CHD8, MLL2/3, MLL4/WBP7","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":200,"hub_weight":0.4472135954999579,"quality":0.65,"programmes":["pubmed:27173435"],"pmids":["27173435"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus; Cell projection, dendrite","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Transcription regulator. Forms a sequence-specific DNA-binding protein complex with MYC or MAD which recognizes the core sequence 5'-CAC[GA]TG-3'. The MYC:MAX complex is a transcriptional activator, whereas the MAD:MAX complex is a repressor. May repress transcription via the recruitment of a chromatin remodeling complex containing H3 'Lys-9' histone methyltransferase activity. Represses MYC transcriptional activity from E-box elements","source":"project UniProt records20261017/18"},{"partner":"TFPT","hgnc":"HGNC:13630","core":true,"core_annotation":{"hgnc":"HGNC:13630","symbol_at_source":"TFPT","accession":"P0C1Z6","function":"Chromatin remodeling cofactor, DNA modification","target":"chromatin","pmids":["16230350"],"complexes":"Ino80","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":132,"hub_weight":0.5241424183609592,"quality":0.65,"programmes":["pubmed:27173435"],"pmids":["27173435"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Appears to promote apoptosis in a p53/TP53-independent manner\nPutative regulatory component of the chromatin remodeling INO80 complex which is involved in transcriptional regulation, DNA replication and probably DNA repair","source":"project UniProt records20261017/18"},{"partner":"SIRT1","hgnc":"HGNC:14929","core":true,"core_annotation":{"hgnc":"HGNC:14929","symbol_at_source":"SIRT1","accession":"Q96EB6","function":"Histone modification erase, Histone modification write cofactor","target":"histone","pmids":["15469825"],"complexes":"eNoSc","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":398,"hub_weight":0.33407655239053047,"quality":0.65,"programmes":["pubmed:23382074"],"pmids":["23382074"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus, PML body; Cytoplasm; Nucleus; Nucleus, nucleoplasm; Cytoplasm; Mitochondrion","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"NAD-dependent protein deacetylase that links transcriptional regulation directly to intracellular energetics and participates in the coordination of several separated cellular functions such as cell cycle, response to DNA damage, metabolism, apoptosis and autophagy (PubMed:11672523, PubMed:12006491, PubMed:14976264, PubMed:14980222, PubMed:15126506, PubMed:15152190, PubMed:15205477, PubMed:15469825, PubMed:15692560, PubMed:16079181, PubMed:16166628, PubMed:16892051, PubMed:16998810, PubMed:17283066, PubMed:17290224, PubMed:17334224, PubMed:17505061, PubMed:17612497, PubMed:17620057, PubMed:17936707, PubMed:18203716, PubMed:18296641, PubMed:18662546, PubMed:18687677, PubMed:19188449, PubMed:19220062, PubMed:19364925, PubMed:19690166, PubMed:19934257, PubMed:20097625, PubMed:20100829, PubMed:20203304, PubMed:20375098, PubMed:20620956, PubMed:20670893, PubMed:20817729, PubMed:20955178, PubMed:21149730, PubMed:21245319, PubMed:21471201, PubMed:21504832, PubMed:21555002, PubMed:21698133, PubMed:21701047, PubMed:21775285, PubMed:21807113, PubMed:21841822, PubMed:21890893, PubMed:21947282, PubMed:22274616, PubMed:22918831, PubMed:24415752, PubMed:24824780, PubMed:29681526, PubMed:29765047, PubMed:30409912). Can modulate chromatin function through deacetylation of histones and can promote alterations in the methylation of histones and DNA, leading to transcriptional repression (PubMed:15469825). Deacetylates a broad range of transcription factors and coregulators, thereby regulating target gene expression positively and negatively (PubMed:14976264, PubMed:14980222, PubMed:15152190). Serves as a sensor of the cytosolic ratio of NAD(+)/NADH which is altered by glucose deprivation and metabolic changes associated with caloric restriction (PubMed:15205477). Is essential in skeletal muscle cell differentiation and in response to low nutrients mediates the inhibitory effect on skeletal myoblast differentiation which also involves 5'-AMP-activated protein kinase (AMPK) and nicotinamide phosphoribosyltransferase (NAMPT) (By similarity). Component of the eNoSC (energy-dependent nucleolar silencing) complex, a complex that mediates silencing of rDNA in response to intracellular energy status and acts by recruiting histone-modifying enzymes (PubMed:18485871). The eNoSC complex is able to sense the energy status of cell: upon glucose starvation, elevation of NAD(+)/NADP(+) ratio activates SIRT1, leading to histone H3 deacetylation followed by dimethylation of H3 at 'Lys-9' (H3K9me2) by SUV39H1 and the formation of silent chromatin in the rDNA locus (PubMed:18485871, PubMed:21504832). Deacetylates 'Lys-266' of SUV39H1, leading to its activation (PubMed:21504832). Inhibits skeletal muscle differentiation by deacetylating PCAF and MYOD1 (PubMed:19188449). Deacetylates H2A and 'Lys-26' of H1-4 (PubMed:15469825). Deacetylates 'Lys-16' of histone H4 (in vitro). Involved in NR0B2/SHP corepression function through chromatin remodeling: Recruited to LRH1 target gene promoters by NR0B2/SHP thereby stimulating histone H3 and H4 deacetylation leading to transcriptional repression (PubMed:20375098). Proposed to contribute to genomic integrity via positive regulation of telomere length; however, reports on localization to pericentromeric heterochromatin are conflicting (By similarity). Proposed to play a role in constitutive heterochromatin (CH) formation and/or maintenance through regulation of the available pool of nuclear SUV39H1 (PubMed:15469825, PubMed:18004385). Upon oxidative/metabolic stress decreases SUV39H1 degradation by inhibiting SUV39H1 polyubiquitination by MDM2 (PubMed:18004385, PubMed:21504832). This increase in SUV39H1 levels enhances SUV39H1 turnover in CH, which in turn seems to accelerate renewal of the heterochromatin which correlates with greater genomic integrity during stress response (PubMed:18004385, PubMed:21504832). Deacetylates 'Lys-382' of p53/TP53 and impairs its ability to induce transcription-dependent proapoptotic program and modulate cell senescence (PubMed:11672523, PubMed:12006491, PubMed:22542455). Deacetylates TAF1B and thereby represses rDNA transcription by the RNA polymerase I (By similarity). Deacetylates MYC, promotes the association of MYC with MAX and decreases MYC stability leading to compromised transformational capability (PubMed:19364925, PubMed:21807113). Deacetylates FOXO3 in response to oxidative stress thereby increasing its ability to induce cell cycle arrest and resistance to oxidative stress but inhibiting FOXO3-mediated induction of apoptosis transcriptional activity; also leading to FOXO3 ubiquitination and protesomal degradation (PubMed:14976264, PubMed:14980222, PubMed:21841822). Appears to have a similar effect on MLLT7/FOXO4 in regulation of transcriptional activity and apoptosis (PubMed:15126506). Deacetylates DNMT1; thereby impairs DNMT1 methyltransferase-independent transcription repressor activity, modulates DNMT1 cell cycle regulatory function and DNMT1-mediated gene silencing (PubMed:21947282). Deacetylates RELA/NF-kappa-B p65 thereby inhibiting its transactivating potential and augments apoptosis in response to TNF (PubMed:15152190). Deacetylates HIF1A, KAT5/TIP60, RB1 and HIC1 (PubMed:17283066, PubMed:17620057, PubMed:20100829, PubMed:20620956). Deacetylates FOXO1 resulting in its nuclear retention and enhancement of its transcriptional activity leading to increased gluconeogenesis in liver (PubMed:15692560). Inhibits E2F1 transcriptional activity and apoptotic function, possibly by deacetylation (PubMed:16892051). Involved in HES1- and HEY2-mediated transcriptional repression (PubMed:12535671). In cooperation with MYCN seems to be involved in transcriptional repression of DUSP6/MAPK3 leading to MYCN stabilization by phosphorylation at 'Ser-62' (PubMed:21698133). Deacetylates MEF2D (PubMed:16166628). Required for antagonist-mediated transcription suppression of AR-dependent genes which may be linked to local deacetylation of histone H3 (PubMed:17505061). Represses HNF1A-mediated transcription (By similarity). Required for the repression of ESRRG by CREBZF (PubMed:19690166). Deacetylates NR1H3 and NR1H2 and deacetylation of NR1H3 at 'Lys-434' positively regulates transcription of NR1H3:RXR target genes, promotes NR1H3 proteasomal degradation and results in cholesterol efflux; a promoter clearing mechanism after reach round of transcription is proposed (PubMed:17936707). Involved in lipid metabolism: deacetylates LPIN1, thereby inhibiting diacylglycerol synthesis (PubMed:20817729, PubMed:29765047). Implicated in regulation of adipogenesis and fat mobilization in white adipocytes by repression of PPARG which probably involves association with NCOR1 and SMRT/NCOR2 (By similarity). Deacetylates p300/EP300 and PRMT1 (By similarity). Deacetylates ACSS2 leading to its activation, and HMGCS1 deacetylation (PubMed:21701047). Involved in liver and muscle metabolism. Through deacetylation and activation of PPARGC1A is required to activate fatty acid oxidation in skeletal muscle under low-glucose conditions and is involved in glucose homeostasis (PubMed:23142079). Involved in regulation of PPARA and fatty acid beta-oxidation in liver. Involved in positive regulation of insulin secretion in pancreatic beta cells in response to glucose; the function seems to imply transcriptional repression of UCP2. Proposed to deacetylate IRS2 thereby facilitating its insulin-induced tyrosine phosphorylation. Deacetylates SREBF1 isoform SREBP-1C thereby decreasing its stability and transactivation in lipogenic gene expression (PubMed:17290224, PubMed:20817729). Involved in DNA damage response by repressing genes which are involved in DNA repair, such as XPC and TP73, deacetylating XRCC6/Ku70, and facilitating recruitment of additional factors to sites of damaged DNA, such as SIRT1-deacetylated NBN can recruit ATM to initiate DNA repair and SIRT1-deacetylated XPA interacts with RPA2 (PubMed:15205477, PubMed:16998810, PubMed:17334224, PubMed:17612497, PubMed:20670893, PubMed:21149730). Also involved in DNA repair of DNA double-strand breaks by homologous recombination and specifically single-strand annealing independently of XRCC6/Ku70 and NBN (PubMed:15205477, PubMed:17334224, PubMed:20097625). Promotes DNA double-strand breaks by mediating deacetylation of SIRT6 (PubMed:32538779). Transcriptional suppression of XPC probably involves an E2F4:RBL2 suppressor complex and protein kinase B (AKT) signaling. Transcriptional suppression of TP73 probably involves E2F4 and PCAF. Deacetylates WRN thereby regulating its helicase and exonuclease activities and regulates WRN nuclear translocation in response to DNA damage (PubMed:18203716). Deacetylates APEX1 at 'Lys-6' and 'Lys-7' and stimulates cellular AP endonuclease activity by promoting the association of APEX1 to XRCC1 (PubMed:19934257). Catalyzes deacetylation of ERCC4/XPF, thereby impairing interaction with ERCC1 and nucleotide excision repair (NER) (PubMed:32034146). Increases p53/TP53-mediated transcription-independent apoptosis by blocking nuclear translocation of cytoplasmic p53/TP53 and probably redirecting it to mitochondria. Deacetylates XRCC6/Ku70 at 'Lys-539' and 'Lys-542' causing it to sequester BAX away from mitochondria thereby inhibiting stress-induced apoptosis. Is involved in autophagy, presumably by deacetylating ATG5, ATG7 and MAP1LC3B/ATG8 (PubMed:18296641). Deacetylates AKT1 which leads to enhanced binding of AKT1 and PDK1 to PIP3 and promotes their activation (PubMed:21775285). Acts as a regulator of AMPK activity in response to calorie restriction: deacetylates the ATP6V1E1 subunit of the V-ATPase complex following activation by TULP3, leading to (1) V-ATPase complex inhibition on lysosomes and (2) AMPK activation via the AXIN1-STK11/LKB1 axis (By similarity). Proposed to play role in regulation of STK11/LBK1-dependent AMPK signaling pathways implicated in cellular senescence which seems to involve the regulation of the acetylation status of STK11/LBK1. Can deacetylate STK11/LBK1 and thereby increase its activity, cytoplasmic localization and association with STRAD; however, the relevance of such activity in normal cells is unclear (PubMed:18687677, PubMed:20203304). In endothelial cells is shown to inhibit STK11/LBK1 activity and to promote its degradation. Deacetylates SMAD7 at 'Lys-64' and 'Lys-70' thereby promoting its degradation. Deacetylates CIITA and augments its MHC class II transactivation and contributes to its stability (PubMed:21890893). Deacetylates MECOM/EVI1 (PubMed:21555002). Deacetylates PML at 'Lys-487' and this deacetylation promotes PML control of PER2 nuclear localization (PubMed:22274616). During the neurogenic transition, represses selective NOTCH1-target genes through histone deacetylation in a BCL6-dependent manner and leading to neuronal differentiation. Regulates the circadian expression of several core clock genes, including BMAL1, RORC, PER2 and CRY1 and plays a critical role in maintaining a controlled rhythmicity in histone acetylation, thereby contributing to circadian chromatin remodeling (PubMed:18662546). Deacetylates BMAL1 and histones at the circadian gene promoters in order to facilitate repression by inhibitory components of the circadian oscillator (By similarity). Deacetylates PER2, facilitating its ubiquitination and degradation by the proteasome (By similarity). Protects cardiomyocytes against palmitate-induced apoptosis (By similarity). Deacetylates XBP1 isoform 2; deacetylation decreases protein stability of XBP1 isoform 2 and inhibits its transcriptional activity (PubMed:20955178). Deacetylates PCK1 and directs its activity toward phosphoenolpyruvate production promoting gluconeogenesis (PubMed:30193097). Involved in the CCAR2-mediated regulation of PCK1 and NR1D1 (PubMed:24415752). Deacetylates CTNB1 at 'Lys-49' (PubMed:24824780). In POMC (pro-opiomelanocortin) neurons, required for leptin-induced activation of PI3K signaling (By similarity). Deacetylates SOX9; promoting SOX9 nuclear localization and transactivation activity (By similarity). Involved in the regulation of centrosome duplication: deacetylates CENATAC in G1 phase, allowing for SASS6 accumulation on the centrosome and subsequent procentriole assembly (PubMed:31722219). Deacetylates NDC80/HEC1 (PubMed:30409912). In addition to protein deacetylase activity, also acts as a protein-lysine deacylase by mediating protein delactylation, depropionylation and decrotonylation (PubMed:28497810, PubMed:38512451). Mediates depropionylation of Osterix (SP7) (By similarity). Catalyzes decrotonylation of histones; it however does not represent a major histone decrotonylase (PubMed:28497810). Mediates protein delactylation of TEAD1 and YAP1 (PubMed:38512451)\nDeacetylates 'Lys-382' of p53/TP53, however with lower activity than isoform 1. In combination, the two isoforms exert an additive effect. Isoform 2 regulates p53/TP53 expression and cellular stress response and is in turn repressed by p53/TP53 presenting a SIRT1 isoform-dependent auto-regulatory loop\nCatalytically inactive 75SirT1 may be involved in regulation of apoptosis. May be involved in protecting chondrocytes from apoptotic death by associating with cytochrome C and interfering with apoptosome assembly\n(Microbial infection) In case of HIV-1 infection, interacts with and deacetylates the viral Tat protein. The viral Tat protein inhibits SIRT1 deacetylation activity toward RELA/NF-kappa-B p65, thereby potentiates its transcriptional activity and SIRT1 is proposed to contribute to T-cell hyperactivation during infection","source":"project UniProt records20261017/18"},{"partner":"RCOR1","hgnc":"HGNC:17441","core":true,"core_annotation":{"hgnc":"HGNC:17441","symbol_at_source":"RCOR1","accession":"Q9UKL0","function":"Histone modification erase cofactor, Histone modification erase cofactor","target":"histone","pmids":["10449787"],"complexes":"BHC, SCL, LSD-CoREST","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":415,"hub_weight":0.32791291789197646,"quality":0.65,"programmes":["pubmed:27173435"],"pmids":["27173435"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Essential component of the BHC complex, a corepressor complex that represses transcription of neuron-specific genes in non-neuronal cells. The BHC complex is recruited at RE1/NRSE sites by REST and acts by deacetylating and demethylating specific sites on histones, thereby acting as a chromatin modifier. In the BHC complex, it serves as a molecular beacon for the recruitment of molecular machinery, including MeCP2 and SUV39H1, that imposes silencing across a chromosomal interval. Plays a central role in demethylation of Lys-4 of histone H3 by promoting demethylase activity of KDM1A on core histones and nucleosomal substrates. It also protects KDM1A from the proteasome. Component of a RCOR/GFI/KDM1A/HDAC complex that suppresses, via histone deacetylase (HDAC) recruitment, a number of genes implicated in multilineage blood cell development and controls hematopoietic differentiation","source":"project UniProt records20261017/18"},{"partner":"OIP5","hgnc":"HGNC:20300","core":true,"core_annotation":{"hgnc":"HGNC:20300","symbol_at_source":"OIP5","accession":"O43482","function":"Chromatin remodeling","target":"histone","pmids":["17199038"],"complexes":"Mis18","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":152,"hub_weight":0.4975185951049946,"quality":0.65,"programmes":["pubmed:27173435"],"pmids":["27173435"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus; Chromosome; Chromosome, centromere","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Required for recruitment of CENPA to centromeres and normal chromosome segregation during mitosis","source":"project UniProt records20261017/18"},{"partner":"MBIP","hgnc":"HGNC:20427","core":true,"core_annotation":{"hgnc":"HGNC:20427","symbol_at_source":"MBIP","accession":"Q9NS73","function":"Histone modification write cofactor","target":"histone","pmids":["19103755"],"complexes":"ATAC","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":150,"hub_weight":0.5,"quality":0.65,"programmes":["BioPlex"],"pmids":["26186194","28514442","33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Functions as part of the ATAC complex, a complex with histone acetyltransferase activity on histones H3 and H4 (PubMed:19103755). Inhibits the MAP3K12 activity to induce the activation of the JNK/SAPK pathway (PubMed:10801814). Together with MOCS2B, inhibits the activity of stress kinase EIF2AK2/PKR; this may lead to effects such as suppression of JNK activation and subsequent stress-responsive transcription, or suppression of eIF2a phosphorylation to favor translation (PubMed:26705305)","source":"project UniProt records20261017/18"},{"partner":"PHF21A","hgnc":"HGNC:24156","core":true,"core_annotation":{"hgnc":"HGNC:24156","symbol_at_source":"PHF21A","accession":"Q96BD5","function":"Histone modification erase cofactor","target":"histone","pmids":["16140033"],"complexes":"BHC, LSD-CoREST","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":273,"hub_weight":0.39344473768231686,"quality":0.65,"programmes":["pubmed:27173435"],"pmids":["27173435"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Component of the BHC complex, a corepressor complex that represses transcription of neuron-specific genes in non-neuronal cells. The BHC complex is recruited at RE1/NRSE sites by REST and acts by deacetylating and demethylating specific sites on histones, thereby acting as a chromatin modifier. In the BHC complex, it may act as a scaffold. Inhibits KDM1A-mediated demethylation of 'Lys-4' of histone H3 in vitro, suggesting a role in demethylation regulation","source":"project UniProt records20261017/18"},{"partner":"YEATS4","hgnc":"HGNC:24859","core":true,"core_annotation":{"hgnc":"HGNC:24859","symbol_at_source":"YEATS4","accession":"O95619","function":"Histone modification write cofactor","target":"histone","pmids":["14966270"],"complexes":"NuA4, NuA4-related complex, SRCAP","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":160,"hub_weight":0.4879500364742666,"quality":0.65,"programmes":["pubmed:27173435"],"pmids":["27173435"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Chromatin reader component of the NuA4 histone acetyltransferase (HAT) complex, a complex involved in transcriptional activation of select genes principally by acetylation of nucleosomal histones H4 and H2A (PubMed:12963728, PubMed:14966270). Specifically recognizes and binds acylated histone H3, with a preference for histone H3 diacetylated at 'Lys-18' and 'Lys-27' (H3K18ac and H3K27ac) or histone H3 diacetylated at 'Lys-14' and 'Lys-27' (H3K14ac and H3K27ac) (PubMed:29437725, PubMed:29900004, PubMed:30071723). Also able to recognize and bind crotonylated histone H3 (PubMed:30071723). May also recognize and bind histone H3 succinylated at 'Lys-122' (H3K122succ); additional evidence is however required to confirm this result in vivo (PubMed:29463709). Plays a key role in histone variant H2AZ1/H2A.Z deposition into specific chromatin regions: recognizes and binds H3K14ac and H3K27ac on the promoters of actively transcribed genes and recruits NuA4-related complex to deposit H2AZ1/H2A.Z (PubMed:29437725). H2AZ1/H2A.Z deposition is required for maintenance of embryonic stem cell (By similarity)","source":"project UniProt records20261017/18"},{"partner":"KDM1A","hgnc":"HGNC:29079","core":true,"core_annotation":{"hgnc":"HGNC:29079","symbol_at_source":"KDM1A","accession":"O60341","function":"Histone modification erase","target":"histone","pmids":["16223729"],"complexes":"NuRD, BHC, SCL","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":641,"hub_weight":0.26899609689495085,"quality":0.65,"programmes":["pubmed:27173435"],"pmids":["27173435"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone demethylase that can demethylate both 'Lys-4' (H3K4me) and 'Lys-9' (H3K9me) of histone H3, thereby acting as a coactivator or a corepressor, depending on the context (PubMed:15620353, PubMed:15811342, PubMed:16079794, PubMed:16079795, PubMed:16140033, PubMed:16223729, PubMed:27292636). Acts by oxidizing the substrate by FAD to generate the corresponding imine that is subsequently hydrolyzed (PubMed:15620353, PubMed:15811342, PubMed:16079794, PubMed:21300290, PubMed:26214369). Acts as a corepressor by mediating demethylation of H3K4me, a specific tag for epigenetic transcriptional activation. Demethylates both mono- (H3K4me1) and di-methylated (H3K4me2) (PubMed:15620353, PubMed:20389281, PubMed:21300290, PubMed:23721412). May play a role in the repression of neuronal genes. Alone, it is unable to demethylate H3K4me on nucleosomes and requires the presence of RCOR1/CoREST to achieve such activity (PubMed:16079794, PubMed:16140033, PubMed:16885027, PubMed:21300290, PubMed:23721412). Also acts as a coactivator of androgen receptor (AR)-dependent transcription, by being recruited to AR target genes and mediating demethylation of H3K9me, a specific tag for epigenetic transcriptional repression. The presence of PRKCB in AR-containing complexes, which mediates phosphorylation of 'Thr-6' of histone H3 (H3T6ph), a specific tag that prevents demethylation H3K4me, prevents H3K4me demethylase activity of KDM1A (PubMed:16079795). Demethylates di-methylated 'Lys-370' of p53/TP53 which prevents interaction of p53/TP53 with TP53BP1 and represses p53/TP53-mediated transcriptional activation. Demethylates and stabilizes the DNA methylase DNMT1 (PubMed:29691401). Demethylates methylated 'Lys-42' and methylated 'Lys-117' of SOX2 (PubMed:29358331). Required for gastrulation during embryogenesis. Component of a RCOR/GFI/KDM1A/HDAC complex that suppresses, via histone deacetylase (HDAC) recruitment, a number of genes implicated in multilineage blood cell development (PubMed:16079794, PubMed:16140033). Facilitates epithelial-to-mesenchymal transition by acting as an effector of SNAI1-mediated transcription repression of epithelial markers E-cadherin/CDH1, CDN7 and KRT8 (PubMed:20562920, PubMed:27292636). Required for the maintenance of the silenced state of the SNAI1 target genes E-cadherin/CDH1 and CDN7 (PubMed:20389281). Required for the repression of GIPR expression (PubMed:34655521, PubMed:34906447)\nNeuron-specific histone demethylase that demethylates mono- and dimethylated 'Lys-20' of histone H4 (H4K20me1 and H4K20me2), a chromatin repressive mark (PubMed:26214369). This demethylation is crucial for the initiation and elongation of neuronal activity-regulated genes, required for spatial learning and memory (By similarity). Mediates H3K9me2 demethylation through cooperation with the supervillin protein (SVIL), and this H3K9 demethylase activity is essential for regulating gene expression during neuronal differentiation (PubMed:25684206)\nNeuron-specific histone demethylase that demethylates mono- and dimethylated 'Lys-20' of histone H4 (H4K20me1 and H4K20me2), a chromatin repressive mark (PubMed:26214369). This demethylation is crucial for the initiation and elongation of neuronal activity-regulated genes, required for spatial learning and memory (By similarity). Mediates H3K9me2 demethylation through cooperation with the supervillin protein (SVIL), and this H3K9 demethylase activity is essential for regulating gene expression during neuronal differentiation (PubMed:25684206)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"EFCAB5":{"coreEvidence":[{"partner":"PARP1","hgnc":"HGNC:270","core":true,"core_annotation":{"hgnc":"HGNC:270","symbol_at_source":"PARP1","accession":"P09874","function":"Chromatin remodeling","target":"histone","pmids":["20926656","17177976","17396150"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":1585,"hub_weight":0.17487435419566724,"quality":0.4,"programmes":["pubmed:40057523"],"pmids":["40057523"],"assays":["proximity_label"],"contexts":[],"partner_location":"Chromosome; Nucleus; Nucleus, nucleolus; Cytoplasm, cytosol; Chromosome; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Poly-ADP-ribosyltransferase that mediates poly-ADP-ribosylation of proteins and plays a key role in DNA repair (PubMed:17177976, PubMed:18055453, PubMed:18172500, PubMed:19344625, PubMed:19661379, PubMed:20388712, PubMed:21680843, PubMed:22582261, PubMed:23230272, PubMed:25043379, PubMed:26344098, PubMed:26626479, PubMed:26626480, PubMed:30104678, PubMed:31796734, PubMed:32028527, PubMed:32241924, PubMed:32358582, PubMed:33186521, PubMed:34465625, PubMed:34737271). Mediates glutamate, aspartate, serine, histidine or tyrosine ADP-ribosylation of proteins: the ADP-D-ribosyl group of NAD(+) is transferred to the acceptor carboxyl group of target residues and further ADP-ribosyl groups are transferred to the 2'-position of the terminal adenosine moiety, building up a polymer with an average chain length of 20-30 units (PubMed:19764761, PubMed:25043379, PubMed:28190768, PubMed:29954836, PubMed:35393539, PubMed:7852410, PubMed:9315851). Serine ADP-ribosylation of proteins constitutes the primary form of ADP-ribosylation of proteins in response to DNA damage (PubMed:33186521, PubMed:34874266, PubMed:41062835). Specificity for the different amino acids is conferred by interacting factors, such as HPF1 and NMNAT1 (PubMed:28190768, PubMed:29954836, PubMed:32028527, PubMed:33186521, PubMed:33589610, PubMed:34625544, PubMed:34874266). Following interaction with HPF1, catalyzes serine ADP-ribosylation of target proteins; HPF1 confers serine specificity by completing the PARP1 active site (PubMed:28190768, PubMed:29954836, PubMed:32028527, PubMed:33186521, PubMed:33589610, PubMed:34625544, PubMed:34874266). Also catalyzes tyrosine ADP-ribosylation of target proteins following interaction with HPF1 (PubMed:29954836, PubMed:30257210). Following interaction with NMNAT1, catalyzes glutamate and aspartate ADP-ribosylation of target proteins; NMNAT1 confers glutamate and aspartate specificity (By similarity). PARP1 initiates the repair of DNA breaks: recognizes and binds DNA breaks within chromatin and recruits HPF1, licensing serine ADP-ribosylation of target proteins, such as histones (H2BS6ADPr and H3S10ADPr), thereby promoting decompaction of chromatin and the recruitment of repair factors leading to the reparation of DNA strand breaks (PubMed:17177976, PubMed:18172500, PubMed:19344625, PubMed:19661379, PubMed:23230272, PubMed:27067600, PubMed:34465625, PubMed:34874266). HPF1 initiates serine ADP-ribosylation but restricts the polymerase activity of PARP1 in order to limit the length of poly-ADP-ribose chains (PubMed:33683197, PubMed:34732825, PubMed:34795260). In addition to base excision repair (BER) pathway, also involved in double-strand breaks (DSBs) repair: together with TIMELESS, accumulates at DNA damage sites and promotes homologous recombination repair by mediating poly-ADP-ribosylation (PubMed:26344098, PubMed:30356214). Mediates the poly-ADP-ribosylation of a number of proteins, including itself, APLF, CHFR, RPA1 and NFAT5 (PubMed:17396150, PubMed:19764761, PubMed:24906880, PubMed:34049076). In addition to proteins, also able to ADP-ribosylate DNA: catalyzes ADP-ribosylation of DNA strand break termini containing terminal phosphates and a 2'-OH group in single- and double-stranded DNA, respectively (PubMed:27471034). Required for PARP9 and DTX3L recruitment to DNA damage sites (PubMed:23230272). PARP1-dependent PARP9-DTX3L-mediated ubiquitination promotes the rapid and specific recruitment of 53BP1/TP53BP1, UIMC1/RAP80, and BRCA1 to DNA damage sites (PubMed:23230272). PARP1-mediated DNA repair in neurons plays a role in sleep: senses DNA damage in neurons and promotes sleep, facilitating efficient DNA repair (By similarity). In addition to DNA repair, also involved in other processes, such as transcription regulation, programmed cell death, membrane repair, adipogenesis and innate immunity (PubMed:15607977, PubMed:17177976, PubMed:19344625, PubMed:27256882, PubMed:32315358, PubMed:32844745, PubMed:35124853, PubMed:35393539, PubMed:35460603). Acts as a repressor of transcription: binds to nucleosomes and modulates chromatin structure in a manner similar to histone H1, thereby altering RNA polymerase II (PubMed:15607977, PubMed:22464733). Acts both as a positive and negative regulator of transcription elongation, depending on the context (PubMed:27256882, PubMed:35393539). Acts as a positive regulator of transcription elongation by mediating poly-ADP-ribosylation of NELFE, preventing RNA-binding activity of NELFE and relieving transcription pausing (PubMed:27256882). Acts as a negative regulator of transcription elongation in response to DNA damage by catalyzing poly-ADP-ribosylation of CCNT1, disrupting the phase separation activity of CCNT1 and subsequent activation of CDK9 (PubMed:35393539). Involved in replication fork progression following interaction with CARM1: mediates poly-ADP-ribosylation at replication forks, slowing fork progression (PubMed:33412112). Poly-ADP-ribose chains generated by PARP1 also play a role in poly-ADP-ribose-dependent cell death, a process named parthanatos (By similarity). Also acts as a negative regulator of the cGAS-STING pathway (PubMed:32315358, PubMed:32844745, PubMed:35460603). Acts by mediating poly-ADP-ribosylation of CGAS: PARP1 translocates into the cytosol following phosphorylation by PRKDC and catalyzes poly-ADP-ribosylation and inactivation of CGAS (PubMed:35460603). Acts as a negative regulator of adipogenesis: catalyzes poly-ADP-ribosylation of histone H2B on 'Glu-35' (H2BE35ADPr) following interaction with NMNAT1, inhibiting phosphorylation of H2B at 'Ser-36' (H2BS36ph), thereby blocking expression of pro-adipogenetic genes (By similarity). Involved in the synthesis of ATP in the nucleus, together with NMNAT1, PARG and NUDT5 (PubMed:27257257). Nuclear ATP generation is required for extensive chromatin remodeling events that are energy-consuming (PubMed:27257257). Plays a role in sister chromatid cohesion by mediating ADP-ribosylation of RSMC during S phase which promotes the interaction between RSMC and CDCA5/sororin, leading to enhanced interaction of CDCA5/sororin with the cohesin complex and promotion of sister chromatid cohesion (PubMed:41261216)\nPromotes AIFM1-mediated apoptosis (PubMed:33168626). This form, which translocates into the cytoplasm following cleavage by caspase-3 (CASP3) and caspase-7 (CASP7) in response to apoptosis, is auto-poly-ADP-ribosylated and serves as a poly-ADP-ribose carrier to induce AIFM1-mediated apoptosis (PubMed:33168626)\nThis cleavage form irreversibly binds to DNA breaks and interferes with DNA repair, promoting DNA damage-induced apoptosis","source":"project UniProt records20261017/18"},{"partner":"PARP3","hgnc":"HGNC:273","core":true,"core_annotation":{"hgnc":"HGNC:273","symbol_at_source":"PARP3","accession":"Q9Y6F1","function":"Polycomb group (PcG) protein","target":"#","pmids":["16924674"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":209,"hub_weight":0.4393747751637468,"quality":0.4,"programmes":["pubmed:40057523"],"pmids":["40057523"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome, centriole","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Mono-ADP-ribosyltransferase that mediates mono-ADP-ribosylation of target proteins and plays a key role in the response to DNA damage (PubMed:16924674, PubMed:19354255, PubMed:20064938, PubMed:21211721, PubMed:21270334, PubMed:23742272, PubMed:24598253, PubMed:25043379, PubMed:28447610). Mediates mono-ADP-ribosylation of glutamate, aspartate or lysine residues on target proteins (PubMed:20064938, PubMed:25043379). In contrast to PARP1 and PARP2, it is not able to mediate poly-ADP-ribosylation (PubMed:25043379). Involved in DNA repair by mediating mono-ADP-ribosylation of a limited number of acceptor proteins involved in chromatin architecture and in DNA metabolism, such as histone H2B, XRCC5 and XRCC6 (PubMed:16924674, PubMed:24598253). ADP-ribosylation follows DNA damage and appears as an obligatory step in a detection/signaling pathway leading to the reparation of DNA strand breaks (PubMed:16924674, PubMed:21211721, PubMed:21270334). Involved in single-strand break repair by catalyzing mono-ADP-ribosylation of histone H2B on 'Glu-2' (H2BE2ADPr) of nucleosomes containing nicked DNA (PubMed:27530147). Cooperates with the XRCC5-XRCC6 (Ku80-Ku70) heterodimer to limit end-resection thereby promoting accurate NHEJ (PubMed:24598253). Suppresses G-quadruplex (G4) structures in response to DNA damage (PubMed:28447610). Associates with a number of DNA repair factors and is involved in the response to exogenous and endogenous DNA strand breaks (PubMed:16924674, PubMed:21211721, PubMed:21270334). Together with APLF, promotes the retention of the LIG4-XRCC4 complex on chromatin and accelerate DNA ligation during non-homologous end-joining (NHEJ) (PubMed:21211721). May link the DNA damage surveillance network to the mitotic fidelity checkpoint (PubMed:16924674). Acts as a negative regulator of immunoglobulin class switch recombination, probably by controlling the level of AICDA /AID on the chromatin (By similarity). In addition to proteins, also able to ADP-ribosylate DNA: mediates DNA mono-ADP-ribosylation of DNA strand break termini via covalent addition of a single ADP-ribose moiety to a 5'- or 3'-terminal phosphate residues in DNA containing multiple strand breaks (PubMed:29361132, PubMed:29520010)","source":"project UniProt records20261017/18"},{"partner":"H1-5","hgnc":"HGNC:4719","core":true,"core_annotation":{"hgnc":"HGNC:4719","symbol_at_source":"HIST1H1B","accession":"P16401","function":"Histone/protamine","target":"chromatin","pmids":[],"version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":330,"hub_weight":0.3627381250550058,"quality":0.65,"programmes":["pubmed:30021884"],"pmids":["30021884"],"assays":["crosslink"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone H1 protein binds to linker DNA between nucleosomes forming the macromolecular structure known as the chromatin fiber (By similarity). Histones H1 are necessary for the condensation of nucleosome chains into higher-order structured fibers and promote formation of the H3K27me3 mark by the PRC2/EED-EZH2 complex (PubMed:40516528). Also acts as a regulator of individual gene transcription through chromatin remodeling, nucleosome spacing and DNA methylation (By similarity)","source":"project UniProt records20261017/18"},{"partner":"USP7","hgnc":"HGNC:12630","core":true,"core_annotation":{"hgnc":"HGNC:12630","symbol_at_source":"USP7","accession":"Q93009","function":"Histone modification erase, DNA modification cofactor","target":"histone, DNA","pmids":["15749019"],"complexes":"BCOR","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":684,"hub_weight":0.2609978754859403,"quality":1,"programmes":["pubmed:36243803"],"pmids":["36243803"],"assays":["reconstituted"],"contexts":[],"partner_location":"Nucleus; Cytoplasm; Nucleus, PML body; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Hydrolase that deubiquitinates target proteins such as ARMC5, FOXO4, DEPTOR, KAT5, p53/TP53, MDM2, ERCC6, DNMT1, UHRF1, PTEN, KMT2E/MLL5 and DAXX (PubMed:11923872, PubMed:15053880, PubMed:16964248, PubMed:18716620, PubMed:25283148, PubMed:25865756, PubMed:26678539, PubMed:28655758, PubMed:33544460, PubMed:35216969). Together with DAXX, prevents MDM2 self-ubiquitination and enhances the E3 ligase activity of MDM2 towards p53/TP53, thereby promoting p53/TP53 ubiquitination and proteasomal degradation (PubMed:15053880, PubMed:16845383, PubMed:18566590, PubMed:20153724). Deubiquitinates p53/TP53, preventing degradation of p53/TP53, and enhances p53/TP53-dependent transcription regulation, cell growth repression and apoptosis (PubMed:25283148). Deubiquitinates p53/TP53 and MDM2 and strongly stabilizes p53/TP53 even in the presence of excess MDM2, and also induces p53/TP53-dependent cell growth repression and apoptosis (PubMed:11923872, PubMed:26786098). Deubiquitination of FOXO4 in presence of hydrogen peroxide is not dependent on p53/TP53 and inhibits FOXO4-induced transcriptional activity (PubMed:16964248). In association with DAXX, is involved in the deubiquitination and translocation of PTEN from the nucleus to the cytoplasm, both processes that are counteracted by PML (PubMed:18716620). Deubiquitinates KMT2E/MLL5 preventing KMT2E/MLL5 proteasomal-mediated degradation (PubMed:26678539). Involved in cell proliferation during early embryonic development. Involved in transcription-coupled nucleotide excision repair (TC-NER) in response to UV damage: recruited to DNA damage sites following interaction with KIAA1530/UVSSA and promotes deubiquitination of ERCC6, preventing UV-induced degradation of ERCC6 (PubMed:22466611, PubMed:22466612). Involved in maintenance of DNA methylation via its interaction with UHRF1 and DNMT1: acts by mediating deubiquitination of UHRF1 and DNMT1, preventing their degradation and promoting DNA methylation by DNMT1 (PubMed:21745816, PubMed:22411829). Deubiquitinates alkylation repair enzyme ALKBH3. OTUD4 recruits USP7 and USP9X to stabilize ALKBH3, thereby promoting the repair of alkylated DNA lesions (PubMed:25944111). Acts as a chromatin regulator via its association with the Polycomb group (PcG) multiprotein PRC1-like complex; may act by deubiquitinating components of the PRC1-like complex (PubMed:20601937). Able to mediate deubiquitination of histone H2B; it is however unsure whether this activity takes place in vivo (PubMed:20601937). Exhibits a preference towards 'Lys-48'-linked ubiquitin chains (PubMed:22689415). Increases regulatory T-cells (Treg) suppressive capacity by deubiquitinating and stabilizing the transcription factor FOXP3 which is crucial for Treg cell function (PubMed:23973222). Plays a role in the maintenance of the circadian clock periodicity via deubiquitination and stabilization of the CRY1 and CRY2 proteins (PubMed:27123980). Deubiquitinates REST, thereby stabilizing REST and promoting the maintenance of neural progenitor cells (PubMed:21258371). Deubiquitinates SIRT7, inhibiting SIRT7 histone deacetylase activity and regulating gluconeogenesis (PubMed:28655758). Involved in the regulation of WASH-dependent actin polymerization at the surface of endosomes and the regulation of endosomal protein recycling (PubMed:26365382). It maintains optimal WASH complex activity and precise F-actin levels via deubiquitination of TRIM27 and WASHC1 (PubMed:26365382). Mediates the deubiquitination of phosphorylated DEPTOR, promoting its stability and leading to decreased mTORC1 signaling (PubMed:35216969). Deubiquitinates H2AB1, H2BC4 and H2BC22 (By similarity)\n(Microbial infection) Contributes to the overall stabilization and trans-activation capability of the herpesvirus 1 trans-acting transcriptional protein ICP0/VMW110 during HSV-1 infection\n(Microbial infection) Upon infection with Epstein-Barr virus, the interaction with viral EBNA1 increases the association of USP7 with PML proteins, which is required for the polyubiquitylation and degradation of PML","source":"project UniProt records20261017/18"},{"partner":"WDR5","hgnc":"HGNC:12757","core":true,"core_annotation":{"hgnc":"HGNC:12757","symbol_at_source":"WDR5","accession":"P61964","function":"Histone modification read","target":"histone","pmids":["16946699"],"complexes":"ATAC, NSL, RING2-L3MBTL2, COMPASS, Menin-associated_HMT, MLL-HCF, CHD8, MLL2/3, COMPASS-like MLL1,2, MLL4/WBP7, COMPASS-like MLL3,4","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":1007,"hub_weight":0.21749411414517786,"quality":0.4,"programmes":["pubmed:41932313"],"pmids":["41932313"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Contributes to histone modification (PubMed:16600877, PubMed:16829960, PubMed:19103755, PubMed:19131338, PubMed:19556245, PubMed:20018852). May position the N-terminus of histone H3 for efficient trimethylation at 'Lys-4' (PubMed:16829960). As part of the MLL1/MLL complex it is involved in methylation and dimethylation at 'Lys-4' of histone H3 (PubMed:19556245). H3 'Lys-4' methylation represents a specific tag for epigenetic transcriptional activation (PubMed:18840606). As part of the NSL complex it may be involved in acetylation of nucleosomal histone H4 on several lysine residues (PubMed:19103755, PubMed:20018852). May regulate osteoblasts differentiation (By similarity). In association with RBBP5 and ASH2L, stimulates the histone methyltransferase activities of KMT2A, KMT2B, KMT2C, KMT2D, SETD1A and SETD1B (PubMed:21220120, PubMed:22266653)","source":"project UniProt records20261017/18"},{"partner":"SETD3","hgnc":"HGNC:20493","core":true,"core_annotation":{"hgnc":"HGNC:20493","symbol_at_source":"SETD3","accession":"Q86TU7","function":"Histone modification write","target":"histone","pmids":[],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":1463,"hub_weight":0.1817881366751496,"quality":0.65,"programmes":["pubmed:38272222"],"pmids":["38272222"],"assays":["capture_association"],"contexts":[],"partner_location":"Cytoplasm; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Protein-histidine N-methyltransferase that specifically mediates 3-methylhistidine (tele-methylhistidine) methylation of actin at 'His-73' (PubMed:30526847, PubMed:30626964, PubMed:30785395, PubMed:31388018, PubMed:31993215). Histidine methylation of actin is required for smooth muscle contraction of the laboring uterus during delivery (PubMed:30626964). Does not have protein-lysine N-methyltransferase activity and probably only catalyzes histidine methylation of actin (PubMed:30626964, PubMed:30785395, PubMed:31388018)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"ZDBF2":{"coreEvidence":[{"partner":"CTBP1","hgnc":"HGNC:2494","core":true,"core_annotation":{"hgnc":"HGNC:2494","symbol_at_source":"CTBP1","accession":"Q13363","function":"Chromatin remodeling","target":"chromatin","pmids":["21102443"],"complexes":"LSD-CoREST","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":575,"hub_weight":0.282842712474619,"quality":0.65,"programmes":["pubmed:31041561"],"pmids":["31041561"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens U-373 MG glioblastoma astrocytoma cell\", \"human-u373_mg\"]"],"partner_location":"Cytoplasm; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Corepressor targeting diverse transcription regulators such as GLIS2 or BCL6. Has dehydrogenase activity. Involved in controlling the equilibrium between tubular and stacked structures in the Golgi complex. Functions in brown adipose tissue (BAT) differentiation","source":"project UniProt records20261017/18"},{"partner":"H1-5","hgnc":"HGNC:4719","core":true,"core_annotation":{"hgnc":"HGNC:4719","symbol_at_source":"HIST1H1B","accession":"P16401","function":"Histone/protamine","target":"chromatin","pmids":[],"version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":330,"hub_weight":0.3627381250550058,"quality":0.65,"programmes":["pubmed:30021884"],"pmids":["30021884"],"assays":["crosslink"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone H1 protein binds to linker DNA between nucleosomes forming the macromolecular structure known as the chromatin fiber (By similarity). Histones H1 are necessary for the condensation of nucleosome chains into higher-order structured fibers and promote formation of the H3K27me3 mark by the PRC2/EED-EZH2 complex (PubMed:40516528). Also acts as a regulator of individual gene transcription through chromatin remodeling, nucleosome spacing and DNA methylation (By similarity)","source":"project UniProt records20261017/18"},{"partner":"HDAC1","hgnc":"HGNC:4852","core":true,"core_annotation":{"hgnc":"HGNC:4852","symbol_at_source":"HDAC1","accession":"Q13547","function":"Histone modification erase","target":"histone","pmids":["10220385"],"complexes":"SWI/SNF_Brm, NuRD, BHC, MeCP1, mSin3A, core HDAC, mSin3A-like complex, RING2-L3MBTL2, CREST-BRG1, LSD-CoREST","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":937,"hub_weight":0.22507456830317185,"quality":0.4,"programmes":["pubmed:34709266"],"pmids":["34709266"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone deacetylase that catalyzes the deacetylation of lysine residues on the N-terminal part of the core histones (H2A, H2B, H3 and H4) (PubMed:16762839, PubMed:17704056, PubMed:28497810). Histone deacetylation gives a tag for epigenetic repression and plays an important role in transcriptional regulation, cell cycle progression and developmental events (PubMed:16762839, PubMed:17704056). Histone deacetylases act via the formation of large multiprotein complexes (PubMed:16762839, PubMed:17704056). Acts as a component of the histone deacetylase NuRD complex which participates in the remodeling of chromatin (PubMed:16428440, PubMed:28977666). As part of the SIN3B complex is recruited downstream of the constitutively active genes transcriptional start sites through interaction with histones and mitigates histone acetylation and RNA polymerase II progression within transcribed regions contributing to the regulation of transcription (PubMed:21041482). Also functions as a deacetylase for non-histone targets, such as NR1D2, RELA, SP1, SP3, STAT3, ZNF76 and TSHZ3 (PubMed:12837748, PubMed:16285960, PubMed:16337145, PubMed:16478997, PubMed:17996965, PubMed:19343227). Deacetylates SP proteins, SP1 and SP3, and regulates their function (PubMed:12837748, PubMed:16478997). Component of the BRG1-RB1-HDAC1 complex, which negatively regulates the CREST-mediated transcription in resting neurons (PubMed:19081374). Upon calcium stimulation, HDAC1 is released from the complex and CREBBP is recruited, which facilitates transcriptional activation (PubMed:19081374). Deacetylates TSHZ3 and regulates its transcriptional repressor activity (PubMed:19343227). Deacetylates 'Lys-310' in RELA and thereby inhibits the transcriptional activity of NF-kappa-B (PubMed:17000776). Deacetylates NR1D2 and abrogates the effect of KAT5-mediated relieving of NR1D2 transcription repression activity (PubMed:17996965). Component of a RCOR/GFI/KDM1A/HDAC complex that suppresses, via histone deacetylase (HDAC) recruitment, a number of genes implicated in multilineage blood cell development (By similarity). Involved in CIART-mediated transcriptional repression of the circadian transcriptional activator: CLOCK-BMAL1 heterodimer (By similarity). Required for the transcriptional repression of circadian target genes, such as PER1, mediated by the large PER complex or CRY1 through histone deacetylation (By similarity). In addition to protein deacetylase activity, also has protein-lysine deacylase activity: acts as a protein decrotonylase and delactylase by mediating decrotonylation ((2E)-butenoyl) and delactylation (lactoyl) of histones, respectively (PubMed:28497810, PubMed:35044827)","source":"project UniProt records20261017/18"},{"partner":"MSH6","hgnc":"HGNC:7329","core":true,"core_annotation":{"hgnc":"HGNC:7329","symbol_at_source":"MSH6","accession":"P52701","function":"Histone modification read","target":"histone","pmids":["21423274"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":250,"hub_weight":0.408248290463863,"quality":0.65,"programmes":["pubmed:35271311"],"pmids":["35271311"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]"],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Component of the post-replicative DNA mismatch repair system (MMR). Heterodimerizes with MSH2 to form MutS alpha, which binds to DNA mismatches thereby initiating DNA repair. When bound, MutS alpha bends the DNA helix and shields approximately 20 base pairs, and recognizes single base mismatches and dinucleotide insertion-deletion loops (IDL) in the DNA. After mismatch binding, forms a ternary complex with the MutL alpha heterodimer, which is thought to be responsible for directing the downstream MMR events, including strand discrimination, excision, and resynthesis. ATP binding and hydrolysis play a pivotal role in mismatch repair functions. The ATPase activity associated with MutS alpha regulates binding similar to a molecular switch: mismatched DNA provokes ADP-->ATP exchange, resulting in a discernible conformational transition that converts MutS alpha into a sliding clamp capable of hydrolysis-independent diffusion along the DNA backbone. This transition is crucial for mismatch repair. MutS alpha may also play a role in DNA homologous recombination repair. Recruited on chromatin in G1 and early S phase via its PWWP domain that specifically binds trimethylated 'Lys-36' of histone H3 (H3K36me3): early recruitment to chromatin to be replicated allowing a quick identification of mismatch repair to initiate the DNA mismatch repair reaction","source":"project UniProt records20261017/18"},{"partner":"SET","hgnc":"HGNC:10760","core":true,"core_annotation":{"hgnc":"HGNC:10760","symbol_at_source":"SET","accession":"Q01105","function":"Histone modification","target":"histone","pmids":["17320507"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":277,"hub_weight":0.39103094350288753,"quality":0.65,"programmes":["BioPlex"],"pmids":["28514442","33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Cytoplasm, cytosol; Endoplasmic reticulum; Nucleus, nucleoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Multitasking protein, involved in apoptosis, transcription, nucleosome assembly and histone chaperoning. Isoform 2 anti-apoptotic activity is mediated by inhibition of the GZMA-activated DNase, NME1. In the course of cytotoxic T-lymphocyte (CTL)-induced apoptosis, GZMA cleaves SET, disrupting its binding to NME1 and releasing NME1 inhibition. Isoform 1 and isoform 2 are potent inhibitors of protein phosphatase 2A. Isoform 1 and isoform 2 inhibit EP300/CREBBP and PCAF-mediated acetylation of histones (HAT) and nucleosomes, most probably by masking the accessibility of lysines of histones to the acetylases. The predominant target for inhibition is histone H4. HAT inhibition leads to silencing of HAT-dependent transcription and prevents active demethylation of DNA. Both isoforms stimulate DNA replication of the adenovirus genome complexed with viral core proteins; however, isoform 2 specific activity is higher","source":"project UniProt records20261017/18"},{"partner":"AURKA","hgnc":"HGNC:11393","core":true,"core_annotation":{"hgnc":"HGNC:11393","symbol_at_source":"AURKA","accession":"O14965","function":"Histone modification write","target":"histone","pmids":["12576638"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":603,"hub_weight":0.27671226645624275,"quality":0.65,"programmes":["pubmed:41475341"],"pmids":["41475341"],"assays":["crosslink"],"contexts":[],"partner_location":"Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Cytoplasm, cytoskeleton, spindle pole; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome, centriole; Cell projection, neuron projection; Cell projection, cilium; Cytoplasm, cytoskeleton, cilium basal body; Basolateral cell membrane","partner_has_nuclear_annotation":false,"partner_location_assessed":true,"function":"Mitotic serine/threonine kinase that contributes to the regulation of cell cycle progression (PubMed:11039908, PubMed:12390251, PubMed:17125279, PubMed:17360485, PubMed:18615013, PubMed:26246606). Associates with the centrosome and the spindle microtubules during mitosis and plays a critical role in various mitotic events including the establishment of mitotic spindle, centrosome duplication, centrosome separation as well as maturation, chromosomal alignment, spindle assembly checkpoint, and cytokinesis (PubMed:14523000, PubMed:26246606). Required for normal spindle positioning during mitosis and for the localization of NUMA1 and DCTN1 to the cell cortex during metaphase (PubMed:27335426). Required for initial activation of CDK1 at centrosomes (PubMed:13678582, PubMed:15128871). Phosphorylates numerous target proteins, including ARHGEF2, BORA, BRCA1, CDC25B, DLGP5, HDAC6, KIF2A, LATS2, NDEL1, PARD3, PPP1R2, PLK1, RASSF1, TACC3, p53/TP53 and TPX2 (PubMed:11551964, PubMed:14702041, PubMed:15128871, PubMed:15147269, PubMed:15987997, PubMed:17604723, PubMed:18056443, PubMed:18615013). Phosphorylates MCRS1 which is required for MCRS1-mediated kinetochore fiber assembly and mitotic progression (PubMed:27192185). Regulates KIF2A tubulin depolymerase activity (PubMed:19351716). Important for microtubule formation and/or stabilization (PubMed:18056443). Required for normal axon formation (PubMed:19812038). Plays a role in microtubule remodeling during neurite extension (PubMed:19668197). Also acts as a key regulatory component of the p53/TP53 pathway, and particularly the checkpoint-response pathways critical for oncogenic transformation of cells, by phosphorylating and destabilizing p53/TP53 (PubMed:14702041). Phosphorylates its own inhibitors, the protein phosphatase type 1 (PP1) isoforms, to inhibit their activity (PubMed:11551964). Inhibits cilia outgrowth (By similarity). Required for cilia disassembly via phosphorylation of HDAC6 and subsequent deacetylation of alpha-tubulin (PubMed:17604723, PubMed:20643351). Regulates protein levels of the anti-apoptosis protein BIRC5 by suppressing the expression of the SCF(FBXL7) E3 ubiquitin-protein ligase substrate adapter FBXL7 through the phosphorylation of the transcription factor FOXP1 (PubMed:28218735)","source":"project UniProt records20261017/18"},{"partner":"TAF12","hgnc":"HGNC:11545","core":true,"core_annotation":{"hgnc":"HGNC:11545","symbol_at_source":"TAF12","accession":"Q16514","function":"Histone chaperone, Histone modification write","target":"histone","pmids":["10594036"],"complexes":"PCAF, STAGA","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":91,"hub_weight":0.5954913341754137,"quality":0.65,"programmes":["pubmed:35271311"],"pmids":["35271311"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]"],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"The TFIID basal transcription factor complex plays a major role in the initiation of RNA polymerase II (Pol II)-dependent transcription (PubMed:33795473). TFIID recognizes and binds promoters with or without a TATA box via its subunit TBP, a TATA-box-binding protein, and promotes assembly of the pre-initiation complex (PIC) (PubMed:33795473). The TFIID complex consists of TBP and TBP-associated factors (TAFs), including TAF1, TAF2, TAF3, TAF4, TAF5, TAF6, TAF7, TAF8, TAF9, TAF10, TAF11, TAF12 and TAF13 (PubMed:33795473). Component of the TATA-binding protein-free TAF complex (TFTC), the PCAF histone acetylase complex and the STAGA transcription coactivator-HAT complex (PubMed:10373431, PubMed:7729427, PubMed:8598932, PubMed:8663456, PubMed:9674425, PubMed:9885574)","source":"project UniProt records20261017/18"},{"partner":"TP53","hgnc":"HGNC:11998","core":true,"core_annotation":{"hgnc":"HGNC:11998","symbol_at_source":"TP53","accession":"P04637","function":"Histone modification write cofactor, TF","target":"histone","pmids":["23870121"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":1691,"hub_weight":0.16946718543287687,"quality":0.4,"programmes":["pubmed:38580884"],"pmids":["38580884"],"assays":["proximity_label"],"contexts":[],"partner_location":"Cytoplasm; Nucleus; Nucleus, PML body; Endoplasmic reticulum; Mitochondrion matrix; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Nucleus; Cytoplasm; Nucleus; Cytoplasm; Nucleus; Cytoplasm; Nucleus; Cytoplasm; Nucleus; Cytoplasm; Nucleus; Cytoplasm; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Multifunctional transcription factor that induces cell cycle arrest, DNA repair or apoptosis upon binding to its target DNA sequence (PubMed:11025664, PubMed:12524540, PubMed:12810724, PubMed:15186775, PubMed:15340061, PubMed:17317671, PubMed:17349958, PubMed:19556538, PubMed:20673990, PubMed:20959462, PubMed:22726440, PubMed:24051492, PubMed:24652652, PubMed:35618207, PubMed:36634798, PubMed:38653238, PubMed:9840937). Acts as a tumor suppressor in many tumor types; induces growth arrest or apoptosis depending on the physiological circumstances and cell type (PubMed:11025664, PubMed:12524540, PubMed:12810724, PubMed:15186775, PubMed:15340061, PubMed:17189187, PubMed:17317671, PubMed:17349958, PubMed:19556538, PubMed:20673990, PubMed:20959462, PubMed:22726440, PubMed:24051492, PubMed:24652652, PubMed:38653238, PubMed:9840937). Negatively regulates cell division by controlling expression of a set of genes required for this process (PubMed:11025664, PubMed:12524540, PubMed:12810724, PubMed:15186775, PubMed:15340061, PubMed:17317671, PubMed:17349958, PubMed:19556538, PubMed:20673990, PubMed:20959462, PubMed:22726440, PubMed:24051492, PubMed:24652652, PubMed:9840937). One of the activated genes is an inhibitor of cyclin-dependent kinases. Apoptosis induction seems to be mediated either by stimulation of BAX and FAS antigen expression, or by repression of Bcl-2 expression (PubMed:12524540, PubMed:17189187). Its pro-apoptotic activity is activated via its interaction with PPP1R13B/ASPP1 or TP53BP2/ASPP2 (PubMed:12524540). However, this activity is inhibited when the interaction with PPP1R13B/ASPP1 or TP53BP2/ASPP2 is displaced by PPP1R13L/iASPP (PubMed:12524540). In cooperation with mitochondrial PPIF is involved in activating oxidative stress-induced necrosis; the function is largely independent of transcription. Induces the transcription of long intergenic non-coding RNA p21 (lincRNA-p21) and lincRNA-Mkln1. LincRNA-p21 participates in TP53-dependent transcriptional repression leading to apoptosis and seems to have an effect on cell-cycle regulation. Implicated in Notch signaling cross-over. Prevents CDK7 kinase activity when associated to CAK complex in response to DNA damage, thus stopping cell cycle progression. Isoform 2 enhances the transactivation activity of isoform 1 from some but not all TP53-inducible promoters. Isoform 4 suppresses transactivation activity and impairs growth suppression mediated by isoform 1. Isoform 7 inhibits isoform 1-mediated apoptosis. Regulates the circadian clock by repressing CLOCK-BMAL1-mediated transcriptional activation of PER2 (PubMed:24051492)","source":"project UniProt records20261017/18"},{"partner":"UBE2H","hgnc":"HGNC:12484","core":true,"core_annotation":{"hgnc":"HGNC:12484","symbol_at_source":"UBE2H","accession":"P62256","function":"Histone modification write","target":"histone","pmids":["8132613"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":1345,"hub_weight":0.18932061141568826,"quality":0.65,"programmes":["pubmed:38113892"],"pmids":["38113892"],"assays":["capture_association"],"contexts":[],"partner_location":"","partner_has_nuclear_annotation":false,"partner_location_assessed":false,"function":"Accepts ubiquitin from the E1 complex and catalyzes its covalent attachment to other proteins (PubMed:17588522, PubMed:20061386, PubMed:8132613). E2 ubiquitin conjugating enzyme that transfers ubiquitin to MAEA, a core component of the CTLH E3 ubiquitin-protein ligase complex (PubMed:29911972). In vitro catalyzes 'Lys-11'- and 'Lys-48'-linked polyubiquitination (PubMed:20061386). Capable, in vitro, to ubiquitinate histone H2A (PubMed:8132613)","source":"project UniProt records20261017/18"},{"partner":"SIRT6","hgnc":"HGNC:14934","core":true,"core_annotation":{"hgnc":"HGNC:14934","symbol_at_source":"SIRT6","accession":"Q8N6T7","function":"Histone modification erase","target":"histone","pmids":["18337721"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":552,"hub_weight":0.28819520885211747,"quality":0.65,"programmes":["BioPlex"],"pmids":["28514442"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]"],"partner_location":"Nucleus; Chromosome; Chromosome, telomere; Endoplasmic reticulum","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"NAD-dependent protein deacetylase, deacylase and mono-ADP-ribosyltransferase that plays an essential role in DNA damage repair, telomere maintenance, metabolic homeostasis, inflammation, tumorigenesis and aging (PubMed:18337721, PubMed:19135889, PubMed:19625767, PubMed:21362626, PubMed:21680843, PubMed:23217706, PubMed:23552949, PubMed:23653361, PubMed:24052263, PubMed:27180906, PubMed:27322069, PubMed:29555651, PubMed:30374165). Displays protein-lysine deacetylase or defatty-acylase (demyristoylase and depalmitoylase) activity, depending on the context (PubMed:23552949, PubMed:24052263, PubMed:27322069). Acts as a key histone deacetylase by catalyzing deacetylation of histone H3 at 'Lys-9', 'Lys-18' and 'Lys-56' (H3K9ac, H3K18ac and H3K56ac, respectively), suppressing target gene expression of several transcription factors, including NF-kappa-B (PubMed:19625767, PubMed:21362626, PubMed:23892288, PubMed:23911928, PubMed:24012758, PubMed:26456828, PubMed:26898756, PubMed:27043296, PubMed:27180906, PubMed:30374165, PubMed:33067423). Acts as an inhibitor of transcription elongation by mediating deacetylation of H3K9ac and H3K56ac, preventing release of NELFE from chromatin and causing transcriptional pausing (By similarity). Involved in DNA repair by promoting double-strand break (DSB) repair: acts as a DSB sensor by recognizing and binding DSB sites, leading to (1) recruitment of DNA repair proteins, such as SMARCA5/SNF2H, and (2) deacetylation of histone H3K9ac and H3K56ac (PubMed:23911928, PubMed:31995034, PubMed:32538779). SIRT6 participation to DSB repair is probably involved in extension of life span (By similarity). Also promotes DNA repair by deacetylating non-histone proteins, such as DDB2 and p53/TP53 (PubMed:29474172, PubMed:32789493). Specifically deacetylates H3K18ac at pericentric heterochromatin, thereby maintaining pericentric heterochromatin silencing at centromeres and protecting against genomic instability and cellular senescence (PubMed:27043296). Involved in telomere maintenance by catalyzing deacetylation of histone H3 in telomeric chromatin, regulating telomere position effect and telomere movement in response to DNA damage (PubMed:18337721, PubMed:19625767, PubMed:21847107). Required for embryonic stem cell differentiation by mediating histone deacetylation of H3K9ac (PubMed:25915124, PubMed:29555651). Plays a major role in metabolism by regulating processes such as glycolysis, gluconeogenesis, insulin secretion and lipid metabolism (PubMed:24012758, PubMed:26787900). Inhibits glycolysis via histone deacetylase activity and by acting as a corepressor of the transcription factor HIF1A, thereby controlling the expression of multiple glycolytic genes (By similarity). Has tumor suppressor activity by repressing glycolysis, thereby inhibiting the Warburg effect (PubMed:23217706). Also regulates glycolysis and tumorigenesis by mediating deacetylation and nuclear export of non-histone proteins, such as isoform M2 of PKM (PKM2) (PubMed:26787900). Acts as a negative regulator of gluconeogenesis by mediating deacetylation of non-histone proteins, such as FOXO1 and KAT2A/GCN5 (PubMed:23142079, PubMed:25009184). Promotes beta-oxidation of fatty acids during fasting by catalyzing deacetylation of NCOA2, inducing coactivation of PPARA (By similarity). Acts as a regulator of lipid catabolism in brown adipocytes, both by catalyzing deacetylation of histones and non-histone proteins, such as FOXO1 (By similarity). Also acts as a regulator of circadian rhythms, both by regulating expression of clock-controlled genes involved in lipid and carbohydrate metabolism, and by catalyzing deacetylation of PER2 (By similarity). The defatty-acylase activity is specifically involved in regulation of protein secretion (PubMed:23552949, PubMed:24052263, PubMed:27322069, PubMed:28406396). Has high activity toward long-chain fatty acyl groups and mediates protein-lysine demyristoylation and depalmitoylation of target proteins, such as RRAS2 and TNF, thereby regulating their secretion (PubMed:23552949, PubMed:28406396). Also acts as a mono-ADP-ribosyltransferase by mediating mono-ADP-ribosylation of PARP1, TRIM28/KAP1 or SMARCC2/BAF170 (PubMed:21680843, PubMed:22753495, PubMed:27322069, PubMed:27568560). Mono-ADP-ribosyltransferase activity is involved in DNA repair, cellular senescence, repression of LINE-1 retrotransposon elements and regulation of transcription (PubMed:21680843, PubMed:22753495, PubMed:27568560)","source":"project UniProt records20261017/18"},{"partner":"RCOR1","hgnc":"HGNC:17441","core":true,"core_annotation":{"hgnc":"HGNC:17441","symbol_at_source":"RCOR1","accession":"Q9UKL0","function":"Histone modification erase cofactor, Histone modification erase cofactor","target":"histone","pmids":["10449787"],"complexes":"BHC, SCL, LSD-CoREST","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":415,"hub_weight":0.32791291789197646,"quality":0.4,"programmes":["pubmed:34709266"],"pmids":["34709266"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Essential component of the BHC complex, a corepressor complex that represses transcription of neuron-specific genes in non-neuronal cells. The BHC complex is recruited at RE1/NRSE sites by REST and acts by deacetylating and demethylating specific sites on histones, thereby acting as a chromatin modifier. In the BHC complex, it serves as a molecular beacon for the recruitment of molecular machinery, including MeCP2 and SUV39H1, that imposes silencing across a chromosomal interval. Plays a central role in demethylation of Lys-4 of histone H3 by promoting demethylase activity of KDM1A on core histones and nucleosomal substrates. It also protects KDM1A from the proteasome. Component of a RCOR/GFI/KDM1A/HDAC complex that suppresses, via histone deacetylase (HDAC) recruitment, a number of genes implicated in multilineage blood cell development and controls hematopoietic differentiation","source":"project UniProt records20261017/18"},{"partner":"SETD3","hgnc":"HGNC:20493","core":true,"core_annotation":{"hgnc":"HGNC:20493","symbol_at_source":"SETD3","accession":"Q86TU7","function":"Histone modification write","target":"histone","pmids":[],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":1463,"hub_weight":0.1817881366751496,"quality":0.65,"programmes":["pubmed:38272222"],"pmids":["38272222"],"assays":["capture_association"],"contexts":[],"partner_location":"Cytoplasm; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Protein-histidine N-methyltransferase that specifically mediates 3-methylhistidine (tele-methylhistidine) methylation of actin at 'His-73' (PubMed:30526847, PubMed:30626964, PubMed:30785395, PubMed:31388018, PubMed:31993215). Histidine methylation of actin is required for smooth muscle contraction of the laboring uterus during delivery (PubMed:30626964). Does not have protein-lysine N-methyltransferase activity and probably only catalyzes histidine methylation of actin (PubMed:30626964, PubMed:30785395, PubMed:31388018)","source":"project UniProt records20261017/18"},{"partner":"PHF21A","hgnc":"HGNC:24156","core":true,"core_annotation":{"hgnc":"HGNC:24156","symbol_at_source":"PHF21A","accession":"Q96BD5","function":"Histone modification erase cofactor","target":"histone","pmids":["16140033"],"complexes":"BHC, LSD-CoREST","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":273,"hub_weight":0.39344473768231686,"quality":0.4,"programmes":["pubmed:34709266"],"pmids":["34709266"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Component of the BHC complex, a corepressor complex that represses transcription of neuron-specific genes in non-neuronal cells. The BHC complex is recruited at RE1/NRSE sites by REST and acts by deacetylating and demethylating specific sites on histones, thereby acting as a chromatin modifier. In the BHC complex, it may act as a scaffold. Inhibits KDM1A-mediated demethylation of 'Lys-4' of histone H3 in vitro, suggesting a role in demethylation regulation","source":"project UniProt records20261017/18"},{"partner":"NIPBL","hgnc":"HGNC:28862","core":true,"core_annotation":{"hgnc":"HGNC:28862","symbol_at_source":"NIPBL","accession":"Q6KC79","function":"Histone modification erase cofactor","target":"#","pmids":["25255084","18854353"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":174,"hub_weight":0.472455591261534,"quality":0.65,"programmes":["pubmed:31010829"],"pmids":["31010829"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Plays an important role in the loading of the cohesin complex on to DNA. Forms a heterodimeric complex (also known as cohesin loading complex) with MAU2/SCC4 which mediates the loading of the cohesin complex onto chromatin (PubMed:22628566, PubMed:28914604). Plays a role in cohesin loading at sites of DNA damage. Its recruitment to double-strand breaks (DSBs) sites occurs in a CBX3-, RNF8- and RNF168-dependent manner whereas its recruitment to UV irradiation-induced DNA damage sites occurs in a ATM-, ATR-, RNF8- and RNF168-dependent manner (PubMed:28167679). Along with ZNF609, promotes cortical neuron migration during brain development by regulating the transcription of crucial genes in this process. Preferentially binds promoters containing paused RNA polymerase II. Up-regulates the expression of SEMA3A, NRP1, PLXND1 and GABBR2 genes, among others (By similarity)","source":"project UniProt records20261017/18"},{"partner":"KDM1A","hgnc":"HGNC:29079","core":true,"core_annotation":{"hgnc":"HGNC:29079","symbol_at_source":"KDM1A","accession":"O60341","function":"Histone modification erase","target":"histone","pmids":["16223729"],"complexes":"NuRD, BHC, SCL","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":641,"hub_weight":0.26899609689495085,"quality":0.4,"programmes":["pubmed:34709266"],"pmids":["34709266"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone demethylase that can demethylate both 'Lys-4' (H3K4me) and 'Lys-9' (H3K9me) of histone H3, thereby acting as a coactivator or a corepressor, depending on the context (PubMed:15620353, PubMed:15811342, PubMed:16079794, PubMed:16079795, PubMed:16140033, PubMed:16223729, PubMed:27292636). Acts by oxidizing the substrate by FAD to generate the corresponding imine that is subsequently hydrolyzed (PubMed:15620353, PubMed:15811342, PubMed:16079794, PubMed:21300290, PubMed:26214369). Acts as a corepressor by mediating demethylation of H3K4me, a specific tag for epigenetic transcriptional activation. Demethylates both mono- (H3K4me1) and di-methylated (H3K4me2) (PubMed:15620353, PubMed:20389281, PubMed:21300290, PubMed:23721412). May play a role in the repression of neuronal genes. Alone, it is unable to demethylate H3K4me on nucleosomes and requires the presence of RCOR1/CoREST to achieve such activity (PubMed:16079794, PubMed:16140033, PubMed:16885027, PubMed:21300290, PubMed:23721412). Also acts as a coactivator of androgen receptor (AR)-dependent transcription, by being recruited to AR target genes and mediating demethylation of H3K9me, a specific tag for epigenetic transcriptional repression. The presence of PRKCB in AR-containing complexes, which mediates phosphorylation of 'Thr-6' of histone H3 (H3T6ph), a specific tag that prevents demethylation H3K4me, prevents H3K4me demethylase activity of KDM1A (PubMed:16079795). Demethylates di-methylated 'Lys-370' of p53/TP53 which prevents interaction of p53/TP53 with TP53BP1 and represses p53/TP53-mediated transcriptional activation. Demethylates and stabilizes the DNA methylase DNMT1 (PubMed:29691401). Demethylates methylated 'Lys-42' and methylated 'Lys-117' of SOX2 (PubMed:29358331). Required for gastrulation during embryogenesis. Component of a RCOR/GFI/KDM1A/HDAC complex that suppresses, via histone deacetylase (HDAC) recruitment, a number of genes implicated in multilineage blood cell development (PubMed:16079794, PubMed:16140033). Facilitates epithelial-to-mesenchymal transition by acting as an effector of SNAI1-mediated transcription repression of epithelial markers E-cadherin/CDH1, CDN7 and KRT8 (PubMed:20562920, PubMed:27292636). Required for the maintenance of the silenced state of the SNAI1 target genes E-cadherin/CDH1 and CDN7 (PubMed:20389281). Required for the repression of GIPR expression (PubMed:34655521, PubMed:34906447)\nNeuron-specific histone demethylase that demethylates mono- and dimethylated 'Lys-20' of histone H4 (H4K20me1 and H4K20me2), a chromatin repressive mark (PubMed:26214369). This demethylation is crucial for the initiation and elongation of neuronal activity-regulated genes, required for spatial learning and memory (By similarity). Mediates H3K9me2 demethylation through cooperation with the supervillin protein (SVIL), and this H3K9 demethylase activity is essential for regulating gene expression during neuronal differentiation (PubMed:25684206)\nNeuron-specific histone demethylase that demethylates mono- and dimethylated 'Lys-20' of histone H4 (H4K20me1 and H4K20me2), a chromatin repressive mark (PubMed:26214369). This demethylation is crucial for the initiation and elongation of neuronal activity-regulated genes, required for spatial learning and memory (By similarity). Mediates H3K9me2 demethylation through cooperation with the supervillin protein (SVIL), and this H3K9 demethylase activity is essential for regulating gene expression during neuronal differentiation (PubMed:25684206)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"NOAZFP":{"coreEvidence":[{"partner":"PARP1","hgnc":"HGNC:270","core":true,"core_annotation":{"hgnc":"HGNC:270","symbol_at_source":"PARP1","accession":"P09874","function":"Chromatin remodeling","target":"histone","pmids":["20926656","17177976","17396150"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":1585,"hub_weight":0.17487435419566724,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Chromosome; Nucleus; Nucleus, nucleolus; Cytoplasm, cytosol; Chromosome; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Poly-ADP-ribosyltransferase that mediates poly-ADP-ribosylation of proteins and plays a key role in DNA repair (PubMed:17177976, PubMed:18055453, PubMed:18172500, PubMed:19344625, PubMed:19661379, PubMed:20388712, PubMed:21680843, PubMed:22582261, PubMed:23230272, PubMed:25043379, PubMed:26344098, PubMed:26626479, PubMed:26626480, PubMed:30104678, PubMed:31796734, PubMed:32028527, PubMed:32241924, PubMed:32358582, PubMed:33186521, PubMed:34465625, PubMed:34737271). Mediates glutamate, aspartate, serine, histidine or tyrosine ADP-ribosylation of proteins: the ADP-D-ribosyl group of NAD(+) is transferred to the acceptor carboxyl group of target residues and further ADP-ribosyl groups are transferred to the 2'-position of the terminal adenosine moiety, building up a polymer with an average chain length of 20-30 units (PubMed:19764761, PubMed:25043379, PubMed:28190768, PubMed:29954836, PubMed:35393539, PubMed:7852410, PubMed:9315851). Serine ADP-ribosylation of proteins constitutes the primary form of ADP-ribosylation of proteins in response to DNA damage (PubMed:33186521, PubMed:34874266, PubMed:41062835). Specificity for the different amino acids is conferred by interacting factors, such as HPF1 and NMNAT1 (PubMed:28190768, PubMed:29954836, PubMed:32028527, PubMed:33186521, PubMed:33589610, PubMed:34625544, PubMed:34874266). Following interaction with HPF1, catalyzes serine ADP-ribosylation of target proteins; HPF1 confers serine specificity by completing the PARP1 active site (PubMed:28190768, PubMed:29954836, PubMed:32028527, PubMed:33186521, PubMed:33589610, PubMed:34625544, PubMed:34874266). Also catalyzes tyrosine ADP-ribosylation of target proteins following interaction with HPF1 (PubMed:29954836, PubMed:30257210). Following interaction with NMNAT1, catalyzes glutamate and aspartate ADP-ribosylation of target proteins; NMNAT1 confers glutamate and aspartate specificity (By similarity). PARP1 initiates the repair of DNA breaks: recognizes and binds DNA breaks within chromatin and recruits HPF1, licensing serine ADP-ribosylation of target proteins, such as histones (H2BS6ADPr and H3S10ADPr), thereby promoting decompaction of chromatin and the recruitment of repair factors leading to the reparation of DNA strand breaks (PubMed:17177976, PubMed:18172500, PubMed:19344625, PubMed:19661379, PubMed:23230272, PubMed:27067600, PubMed:34465625, PubMed:34874266). HPF1 initiates serine ADP-ribosylation but restricts the polymerase activity of PARP1 in order to limit the length of poly-ADP-ribose chains (PubMed:33683197, PubMed:34732825, PubMed:34795260). In addition to base excision repair (BER) pathway, also involved in double-strand breaks (DSBs) repair: together with TIMELESS, accumulates at DNA damage sites and promotes homologous recombination repair by mediating poly-ADP-ribosylation (PubMed:26344098, PubMed:30356214). Mediates the poly-ADP-ribosylation of a number of proteins, including itself, APLF, CHFR, RPA1 and NFAT5 (PubMed:17396150, PubMed:19764761, PubMed:24906880, PubMed:34049076). In addition to proteins, also able to ADP-ribosylate DNA: catalyzes ADP-ribosylation of DNA strand break termini containing terminal phosphates and a 2'-OH group in single- and double-stranded DNA, respectively (PubMed:27471034). Required for PARP9 and DTX3L recruitment to DNA damage sites (PubMed:23230272). PARP1-dependent PARP9-DTX3L-mediated ubiquitination promotes the rapid and specific recruitment of 53BP1/TP53BP1, UIMC1/RAP80, and BRCA1 to DNA damage sites (PubMed:23230272). PARP1-mediated DNA repair in neurons plays a role in sleep: senses DNA damage in neurons and promotes sleep, facilitating efficient DNA repair (By similarity). In addition to DNA repair, also involved in other processes, such as transcription regulation, programmed cell death, membrane repair, adipogenesis and innate immunity (PubMed:15607977, PubMed:17177976, PubMed:19344625, PubMed:27256882, PubMed:32315358, PubMed:32844745, PubMed:35124853, PubMed:35393539, PubMed:35460603). Acts as a repressor of transcription: binds to nucleosomes and modulates chromatin structure in a manner similar to histone H1, thereby altering RNA polymerase II (PubMed:15607977, PubMed:22464733). Acts both as a positive and negative regulator of transcription elongation, depending on the context (PubMed:27256882, PubMed:35393539). Acts as a positive regulator of transcription elongation by mediating poly-ADP-ribosylation of NELFE, preventing RNA-binding activity of NELFE and relieving transcription pausing (PubMed:27256882). Acts as a negative regulator of transcription elongation in response to DNA damage by catalyzing poly-ADP-ribosylation of CCNT1, disrupting the phase separation activity of CCNT1 and subsequent activation of CDK9 (PubMed:35393539). Involved in replication fork progression following interaction with CARM1: mediates poly-ADP-ribosylation at replication forks, slowing fork progression (PubMed:33412112). Poly-ADP-ribose chains generated by PARP1 also play a role in poly-ADP-ribose-dependent cell death, a process named parthanatos (By similarity). Also acts as a negative regulator of the cGAS-STING pathway (PubMed:32315358, PubMed:32844745, PubMed:35460603). Acts by mediating poly-ADP-ribosylation of CGAS: PARP1 translocates into the cytosol following phosphorylation by PRKDC and catalyzes poly-ADP-ribosylation and inactivation of CGAS (PubMed:35460603). Acts as a negative regulator of adipogenesis: catalyzes poly-ADP-ribosylation of histone H2B on 'Glu-35' (H2BE35ADPr) following interaction with NMNAT1, inhibiting phosphorylation of H2B at 'Ser-36' (H2BS36ph), thereby blocking expression of pro-adipogenetic genes (By similarity). Involved in the synthesis of ATP in the nucleus, together with NMNAT1, PARG and NUDT5 (PubMed:27257257). Nuclear ATP generation is required for extensive chromatin remodeling events that are energy-consuming (PubMed:27257257). Plays a role in sister chromatid cohesion by mediating ADP-ribosylation of RSMC during S phase which promotes the interaction between RSMC and CDCA5/sororin, leading to enhanced interaction of CDCA5/sororin with the cohesin complex and promotion of sister chromatid cohesion (PubMed:41261216)\nPromotes AIFM1-mediated apoptosis (PubMed:33168626). This form, which translocates into the cytoplasm following cleavage by caspase-3 (CASP3) and caspase-7 (CASP7) in response to apoptosis, is auto-poly-ADP-ribosylated and serves as a poly-ADP-ribose carrier to induce AIFM1-mediated apoptosis (PubMed:33168626)\nThis cleavage form irreversibly binds to DNA breaks and interferes with DNA repair, promoting DNA damage-induced apoptosis","source":"project UniProt records20261017/18"},{"partner":"BAZ1A","hgnc":"HGNC:960","core":true,"core_annotation":{"hgnc":"HGNC:960","symbol_at_source":"BAZ1A","accession":"Q9NRL2","function":"Histone chaperone","target":"histone","pmids":["14759371"],"complexes":"ACF, CHRAC","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":155,"hub_weight":0.4938647983247948,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Regulatory subunit of the ATP-dependent ACF-1 and ACF-5 ISWI chromatin remodeling complexes, which form ordered nucleosome arrays on chromatin and slide edge- and center-positioned histone octamers away from their original location on the DNA template to facilitate access to DNA during DNA-templated processes such as DNA replication, transcription, and repair (PubMed:17099699, PubMed:28801535). Both complexes regulate the spacing of nucleosomes along the chromatin and have the ability to slide mononucleosomes to the center of a DNA template in an ATP-dependent manner (PubMed:14759371, PubMed:17099699, PubMed:28801535). The ACF-1 ISWI chromatin remodeling complex has a lower ATP hydrolysis rate than the ACF-5 ISWI chromatin remodeling complex (PubMed:28801535). Has a role in sensing the length of DNA which flank nucleosomes, which modulates the nucleosome spacing activity of the ACF-5 ISWI chromatin remodeling complex (PubMed:17099699). Involved in DNA replication and together with SMARCA5/SNF2H is required for replication of pericentric heterochromatin in S-phase (PubMed:12434153). May have a role in nuclear receptor-mediated transcription repression (PubMed:17519354)","source":"project UniProt records20261017/18"},{"partner":"BAZ1B","hgnc":"HGNC:961","core":true,"core_annotation":{"hgnc":"HGNC:961","symbol_at_source":"BAZ1B","accession":"Q9UIG0","function":"Histone modification write","target":"histone","pmids":["19092802"],"complexes":"B-WICH, WINAC","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":203,"hub_weight":0.444554224474387,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Atypical tyrosine-protein kinase that plays a central role in chromatin remodeling and acts as a transcription regulator (PubMed:19092802). Involved in DNA damage response by phosphorylating 'Tyr-142' of histone H2AX (H2AXY142ph) (PubMed:19092802, PubMed:19234442). H2AXY142ph plays a central role in DNA repair and acts as a mark that distinguishes between apoptotic and repair responses to genotoxic stress (PubMed:19092802, PubMed:19234442). Regulatory subunit of the ATP-dependent WICH-1 and WICH-5 ISWI chromatin remodeling complexes, which form ordered nucleosome arrays on chromatin and facilitate access to DNA during DNA-templated processes such as DNA replication, transcription, and repair (PubMed:11980720, PubMed:28801535). Both complexes regulate the spacing of nucleosomes along the chromatin and have the ability to slide mononucleosomes to the center of a DNA template (PubMed:28801535). The WICH-1 ISWI chromatin remodeling complex has a lower ATP hydrolysis rate than the WICH-5 ISWI chromatin remodeling complex (PubMed:28801535). The WICH-5 ISWI chromatin-remodeling complex regulates the transcription of various genes, has a role in RNA polymerase I transcription (By similarity). Within the B-WICH complex has a role in RNA polymerase III transcription (PubMed:16603771). Mediates the recruitment of the WICH-5 ISWI chromatin remodeling complex to replication foci during DNA replication (PubMed:15543136)","source":"project UniProt records20261017/18"},{"partner":"BRD1","hgnc":"HGNC:1102","core":true,"core_annotation":{"hgnc":"HGNC:1102","symbol_at_source":"BRD1","accession":"O95696","function":"Histone modification read","target":"histone","pmids":["21720545"],"complexes":"MOZ/MORF","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":267,"hub_weight":0.3971507353947688,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Scaffold subunit of various histone acetyltransferase (HAT) complexes, such as the MOZ/MORF and HBO1 complexes, that acts as a regulator of hematopoiesis (PubMed:16387653, PubMed:21753189, PubMed:21880731). Plays a key role in HBO1 complex by directing KAT7/HBO1 specificity towards histone H3 'Lys-14' acetylation (H3K14ac), thereby promoting erythroid differentiation (PubMed:21753189)","source":"project UniProt records20261017/18"},{"partner":"BRD2","hgnc":"HGNC:1103","core":true,"core_annotation":{"hgnc":"HGNC:1103","symbol_at_source":"BRD2","accession":"P25440","function":"Histone modification read","target":"histone","pmids":["18406326","20495584"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":358,"hub_weight":0.35007002100700246,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Chromatin reader protein that specifically recognizes and binds histone H4 acetylated at 'Lys-5' and 'Lys-12' (H4K5ac and H4K12ac, respectively), thereby controlling gene expression and remodeling chromatin structures (PubMed:17148447, PubMed:17848202, PubMed:18406326, PubMed:20048151, PubMed:20709061, PubMed:20871596). Recruits transcription factors and coactivators to target gene sites, and activates RNA polymerase II machinery for transcriptional elongation (PubMed:28262505). Plays a key role in genome compartmentalization via its association with CTCF and cohesin: recruited to chromatin by CTCF and promotes formation of topologically associating domains (TADs) via its ability to bind acetylated histones, contributing to CTCF boundary formation and enhancer insulation (PubMed:35410381). Also recognizes and binds acetylated non-histone proteins, such as STAT3 (PubMed:28262505). Involved in inflammatory response by regulating differentiation of naive CD4(+) T-cells into T-helper Th17: recognizes and binds STAT3 acetylated at 'Lys-87', promoting STAT3 recruitment to chromatin (PubMed:28262505). In addition to acetylated lysines, also recognizes and binds lysine residues on histones that are both methylated and acetylated on the same side chain to form N6-acetyl-N6-methyllysine (Kacme), an epigenetic mark of active chromatin associated with increased transcriptional initiation (PubMed:37731000). Specifically binds histone H4 acetyl-methylated at 'Lys-5' and 'Lys-12' (H4K5acme and H4K12acme, respectively) (PubMed:37731000)","source":"project UniProt records20261017/18"},{"partner":"BRD3","hgnc":"HGNC:1104","core":true,"core_annotation":{"hgnc":"HGNC:1104","symbol_at_source":"BRD3","accession":"Q15059","function":"Histone modification read","target":"histone","pmids":["18406326"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":446,"hub_weight":0.31750031750047625,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Chromatin reader that recognizes and binds acetylated histones, thereby controlling gene expression and remodeling chromatin structures (PubMed:18406326, PubMed:22464331, PubMed:27105114, PubMed:32895492). Recruits transcription factors and coactivators to target gene sites, and activates RNA polymerase II machinery for transcriptional elongation (PubMed:29567837, PubMed:32895492). In vitro, binds acetylated lysine residues on the N-terminus of histone H2A, H2B, H3 and H4 (PubMed:18406326). Involved in endoderm differentiation via its association with long non-coding RNA (lncRNA) DIGIT: BRD3 undergoes liquid-liquid phase separation upon binding to lncRNA DIGIT, promoting binding to histone H3 acetylated at 'Lys-18' (H3K18ac) to induce endoderm gene expression (PubMed:32895492). Also binds non-histones acetylated proteins, such as GATA1 and GATA2: regulates transcription by promoting the binding of the transcription factor GATA1 to its targets (By similarity)","source":"project UniProt records20261017/18"},{"partner":"CBX2","hgnc":"HGNC:1552","core":true,"core_annotation":{"hgnc":"HGNC:1552","symbol_at_source":"CBX2","accession":"Q14781","function":"Histone modification read","target":"histone","pmids":["21047797"],"complexes":"PRC1","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":121,"hub_weight":0.5407380704358751,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Component of a Polycomb group (PcG) multiprotein PRC1-like complex, a complex class required to maintain the transcriptionally repressive state of many genes, including Hox genes, throughout development (PubMed:21282530). PcG PRC1 complex acts via chromatin remodeling and modification of histones; it mediates monoubiquitination of histone H2A 'Lys-119', rendering chromatin heritably changed in its expressibility (PubMed:21282530). Binds to histone H3 trimethylated at 'Lys-9' (H3K9me3) or at 'Lys-27' (H3K27me3) (By similarity). Plays a role in the lineage differentiation of the germ layers in embryonic development (By similarity). Involved in sexual development, acting as activator of NR5A1 expression (PubMed:19361780)","source":"project UniProt records20261017/18"},{"partner":"CBX3","hgnc":"HGNC:1553","core":true,"core_annotation":{"hgnc":"HGNC:1553","symbol_at_source":"CBX3","accession":"Q13185","function":"Histone modification read","target":"histone","pmids":["21047797"],"complexes":"RING2-L3MBTL2, L3MBTL1","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":629,"hub_weight":0.2713626770646286,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Component of heterochromatin, which recognizes and binds histone H3 tails methylated at 'Lys-9', leading to epigenetic repression (PubMed:11242053). Also recognizes and binds histone H1.4 methylated at 'Lys-26' (H1.4K26me) (PubMed:16127177). Excluded from chromatin when histone H1.4 is Simultaneously methylated at Lys-26 (H1.4K26me) and phosphorylated at Ser-27 (H1.4S27Ph) (PubMed:16127177). Involved in the formation of functional kinetochore through interaction with MIS12 complex proteins (PubMed:15502821). Contributes to the conversion of local chromatin to a heterochromatin-like repressive state through H3 'Lys-9' trimethylation, mediates the recruitment of the methyltransferases SUV39H1 and/or SUV39H2 by the PER complex to the E-box elements of the circadian target genes such as PER2 itself or PER1 (By similarity). Mediates the recruitment of NIPBL to sites of DNA damage at double-strand breaks (DSBs) (PubMed:28167679)","source":"project UniProt records20261017/18"},{"partner":"CBX5","hgnc":"HGNC:1555","core":true,"core_annotation":{"hgnc":"HGNC:1555","symbol_at_source":"CBX5","accession":"P45973","function":"Histone modification read","target":"histone","pmids":["21047797"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":338,"hub_weight":0.358979079308869,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome; Chromosome, centromere","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Component of heterochromatin that recognizes and binds histone H3 tails methylated at 'Lys-9' (H3K9me), leading to epigenetic repression (PubMed:40440427). In contrast, it is excluded from chromatin when 'Tyr-41' of histone H3 is phosphorylated (H3Y41ph) (PubMed:19783980). Also recognizes and binds histone H1.4 methylated at 'Lys-26' (H1.4K26me) (PubMed:16127177). Excluded from chromatin when histone H1.4 is Simultaneously methylated at Lys-26 (H1.4K26me) and phosphorylated at Ser-27 (H1.4S27Ph) (PubMed:16127177). May contribute to the association of heterochromatin with the inner nuclear membrane by interactions with the lamin-B receptor (LBR) (PubMed:19783980). Involved in the formation of kinetochore through interaction with the MIS12 complex subunit NSL1 (PubMed:19783980, PubMed:20231385). Required for the formation of the inner centromere (PubMed:20231385)","source":"project UniProt records20261017/18"},{"partner":"CDK9","hgnc":"HGNC:1780","core":true,"core_annotation":{"hgnc":"HGNC:1780","symbol_at_source":"CDK9","accession":"P50750","function":"Histone modification cofactor","target":"histone","pmids":["19844166"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":530,"hub_weight":0.29361010975735174,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Cytoplasm; Nucleus, PML body","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Protein kinase involved in the regulation of transcription (PubMed:10574912, PubMed:10757782, PubMed:11145967, PubMed:11575923, PubMed:11809800, PubMed:11884399, PubMed:14701750, PubMed:16109376, PubMed:16109377, PubMed:20930849, PubMed:28426094, PubMed:29335245). Member of the cyclin-dependent kinase pair (CDK9/cyclin-T) complex, also called positive transcription elongation factor b (P-TEFb), which facilitates the transition from abortive to productive elongation by phosphorylating the CTD (C-terminal domain) of the large subunit of RNA polymerase II (RNAP II) POLR2A, SUPT5H and RDBP (PubMed:10574912, PubMed:10757782, PubMed:11145967, PubMed:11575923, PubMed:11809800, PubMed:11884399, PubMed:14701750, PubMed:16109376, PubMed:16109377, PubMed:16427012, PubMed:20930849, PubMed:28426094, PubMed:30134174). This complex is inactive when in the 7SK snRNP complex form (PubMed:10574912, PubMed:10757782, PubMed:11145967, PubMed:11575923, PubMed:11809800, PubMed:11884399, PubMed:14701750, PubMed:16109376, PubMed:16109377, PubMed:20930849, PubMed:28426094). Phosphorylates EP300, MYOD1, RPB1/POLR2A and AR and the negative elongation factors DSIF and NELFE (PubMed:10912001, PubMed:11112772, PubMed:12037670, PubMed:16427012, PubMed:20081228, PubMed:20980437, PubMed:21127351, PubMed:9857195). Regulates cytokine inducible transcription networks by facilitating promoter recognition of target transcription factors (e.g. TNF-inducible RELA/p65 activation and IL-6-inducible STAT3 signaling) (PubMed:17956865, PubMed:18362169). Promotes RNA synthesis in genetic programs for cell growth, differentiation and viral pathogenesis (PubMed:10393184, PubMed:11112772). P-TEFb is also involved in cotranscriptional histone modification, mRNA processing and mRNA export (PubMed:15564463, PubMed:19575011, PubMed:19844166, PubMed:28539972). Modulates a complex network of chromatin modifications including histone H2B monoubiquitination (H2Bub1), H3 lysine 4 trimethylation (H3K4me3) and H3K36me3; integrates phosphorylation during transcription with chromatin modifications to control co-transcriptional histone mRNA processing (PubMed:15564463, PubMed:19575011, PubMed:19844166). Also catalyzes phosphorylation of histone H1.4 (H1-4) at 'Ser-187' (H1.4S187Ph), a modification associated with transcription activation (PubMed:28539972). The CDK9/cyclin-K complex has also a kinase activity towards CTD of RNAP II and can substitute for CDK9/cyclin-T P-TEFb in vitro (PubMed:21127351). Replication stress response protein; the CDK9/cyclin-K complex is required for genome integrity maintenance, by promoting cell cycle recovery from replication arrest and limiting single-stranded DNA amount in response to replication stress, thus reducing the breakdown of stalled replication forks and avoiding DNA damage (PubMed:20493174). In addition, probable function in DNA repair of isoform 2 via interaction with KU70/XRCC6 (PubMed:20493174). Promotes cardiac myocyte enlargement (PubMed:20081228). RPB1/POLR2A phosphorylation on 'Ser-2' in CTD activates transcription (PubMed:21127351). AR phosphorylation modulates AR transcription factor promoter selectivity and cell growth. DSIF and NELF phosphorylation promotes transcription by inhibiting their negative effect (PubMed:10912001, PubMed:11112772, PubMed:9857195). The phosphorylation of MYOD1 enhances its transcriptional activity and thus promotes muscle differentiation (PubMed:12037670). Catalyzes phosphorylation of KAT5, promoting KAT5 recruitment to chromatin and histone acetyltransferase activity (PubMed:29335245)","source":"project UniProt records20261017/18"},{"partner":"CENPC","hgnc":"HGNC:1854","core":true,"core_annotation":{"hgnc":"HGNC:1854","symbol_at_source":"CENPC","accession":"Q03188","function":"DNA modification","target":"DNA","pmids":["19482874"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":109,"hub_weight":0.5607721540920443,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome, centromere, kinetochore; Chromosome, centromere","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Component of the CENPA-NAC (nucleosome-associated) complex, a complex that plays a central role in assembly of kinetochore proteins, mitotic progression and chromosome segregation. The CENPA-NAC complex recruits the CENPA-CAD (nucleosome distal) complex and may be involved in incorporation of newly synthesized CENPA into centromeres. CENPC recruits DNA methylation and DNMT3B to both centromeric and pericentromeric satellite repeats and regulates the histone code in these regions","source":"project UniProt records20261017/18"},{"partner":"CHAF1A","hgnc":"HGNC:1910","core":true,"core_annotation":{"hgnc":"HGNC:1910","symbol_at_source":"CHAF1A","accession":"Q13111","function":"Chromatin remodeling","target":"histone","pmids":["7600578"],"complexes":"CAF-1","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":190,"hub_weight":0.45643546458763845,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Acts as a component of the histone chaperone complex chromatin assembly factor 1 (CAF-1), which assembles histone octamers onto DNA during replication and repair. CAF-1 performs the first step of the nucleosome assembly process, bringing newly synthesized histones H3 and H4 to replicating DNA; histones H2A/H2B can bind to this chromatin precursor subsequent to DNA replication to complete the histone octamer. It may play a role in heterochromatin maintenance in proliferating cells by bringing newly synthesized cbx proteins to heterochromatic DNA replication foci","source":"project UniProt records20261017/18"},{"partner":"CHAF1B","hgnc":"HGNC:1911","core":true,"core_annotation":{"hgnc":"HGNC:1911","symbol_at_source":"CHAF1B","accession":"Q13112","function":"Chromatin remodeling","target":"histone","pmids":["7600578"],"complexes":"WINAC, CAF-1","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":149,"hub_weight":0.5012547071170855,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Acts as a component of the histone chaperone complex chromatin assembly factor 1 (CAF-1), which assembles histone octamers onto DNA during replication and repair. CAF-1 performs the first step of the nucleosome assembly process, bringing newly synthesized histones H3 and H4 to replicating DNA; histones H2A/H2B can bind to this chromatin precursor subsequent to DNA replication to complete the histone octamer","source":"project UniProt records20261017/18"},{"partner":"CHD1","hgnc":"HGNC:1915","core":true,"core_annotation":{"hgnc":"HGNC:1915","symbol_at_source":"CHD1","accession":"O14646","function":"Chromatin remodeling","target":"DNA","pmids":["12592387"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":126,"hub_weight":0.5330017908890261,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"ATP-dependent chromatin-remodeling factor which functions as substrate recognition component of the transcription regulatory histone acetylation (HAT) complex SAGA. Regulates polymerase II transcription. Also required for efficient transcription by RNA polymerase I, and more specifically the polymerase I transcription termination step. Regulates negatively DNA replication. Not only involved in transcription-related chromatin-remodeling, but also required to maintain a specific chromatin configuration across the genome. Is also associated with histone deacetylase (HDAC) activity (By similarity). Required for the bridging of SNF2, the FACT complex, the PAF complex as well as the U2 snRNP complex to H3K4me3. Functions to modulate the efficiency of pre-mRNA splicing in part through physical bridging of spliceosomal components to H3K4me3 (PubMed:18042460, PubMed:28866611). Required for maintaining open chromatin and pluripotency in embryonic stem cells (By similarity)","source":"project UniProt records20261017/18"},{"partner":"CHD3","hgnc":"HGNC:1918","core":true,"core_annotation":{"hgnc":"HGNC:1918","symbol_at_source":"CHD3","accession":"Q12873","function":"Chromatin remodeling","target":"DNA","pmids":["12592387"],"complexes":"NuRD","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":671,"hub_weight":0.26334032657486167,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus, PML body; Nucleus; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"ATP-dependent chromatin-remodeling factor that binds and distorts nucleosomal DNA (PubMed:28977666). Acts as a component of the histone deacetylase NuRD complex which participates in the remodeling of chromatin (PubMed:16428440, PubMed:28977666, PubMed:30397230, PubMed:9804427). Involved in transcriptional repression as part of the NuRD complex (PubMed:27068747). Required for anchoring centrosomal pericentrin in both interphase and mitosis, for spindle organization and centrosome integrity (PubMed:17626165)","source":"project UniProt records20261017/18"},{"partner":"CUL3","hgnc":"HGNC:2553","core":true,"core_annotation":{"hgnc":"HGNC:2553","symbol_at_source":"CUL3","accession":"Q13618","function":"Histone modification write","target":"histone","pmids":["15897469"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":2139,"hub_weight":0.15113398071880554,"quality":0.65,"programmes":["pubmed:35563538"],"pmids":["35563538"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus; Golgi apparatus; Cell projection, cilium, flagellum; Cytoplasm, cytoskeleton, spindle; Cytoplasm; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Cytoplasm, cytoskeleton, spindle pole","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Core component of multiple cullin-RING-based BCR (BTB-CUL3-RBX1) E3 ubiquitin-protein ligase complexes which mediate the ubiquitination and subsequent proteasomal degradation of target proteins (PubMed:29695787). BCR complexes and ARIH1 collaborate in tandem to mediate ubiquitination of target proteins (PubMed:27565346). As a scaffold protein may contribute to catalysis through positioning of the substrate and the ubiquitin-conjugating enzyme. The E3 ubiquitin-protein ligase activity of the complex is dependent on the neddylation of the cullin subunit and is inhibited by the association of the deneddylated cullin subunit with TIP120A/CAND1. The functional specificity of the BCR complex depends on the BTB domain-containing protein as the substrate recognition component. BCR(KLHL42) is involved in ubiquitination of KATNA1. BCR(SPOP) is involved in ubiquitination of BMI1/PCGF4, BRMS1, MACROH2A1 and DAXX, GLI2 and GLI3. Can also form a cullin-RING-based BCR (BTB-CUL3-RBX1) E3 ubiquitin-protein ligase complex containing homodimeric SPOPL or the heterodimer formed by SPOP and SPOPL; these complexes have lower ubiquitin ligase activity. BCR(KLHL9-KLHL13) controls the dynamic behavior of AURKB on mitotic chromosomes and thereby coordinates faithful mitotic progression and completion of cytokinesis. BCR(KLHL12) is involved in ER-Golgi transport by regulating the size of COPII coats, thereby playing a key role in collagen export, which is required for embryonic stem (ES) cells division: BCR(KLHL12) acts by mediating monoubiquitination of SEC31 (SEC31A or SEC31B) (PubMed:22358839, PubMed:27716508). BCR(KLHL3) acts as a regulator of ion transport in the distal nephron; by mediating ubiquitination of WNK4 (PubMed:23387299, PubMed:23453970, PubMed:23576762). The BCR(KLHL20) E3 ubiquitin ligase complex is involved in interferon response and anterograde Golgi to endosome transport: it mediates both ubiquitination leading to degradation and 'Lys-33'-linked ubiquitination (PubMed:20389280, PubMed:21670212, PubMed:21840486, PubMed:24768539). The BCR(KLHL21) E3 ubiquitin ligase complex regulates localization of the chromosomal passenger complex (CPC) from chromosomes to the spindle midzone in anaphase and mediates the ubiquitination of AURKB (PubMed:19995937). The BCR(KLHL22) ubiquitin ligase complex mediates monoubiquitination of PLK1, leading to PLK1 dissociation from phosphoreceptor proteins and subsequent removal from kinetochores, allowing silencing of the spindle assembly checkpoint (SAC) and chromosome segregation (PubMed:23455478). The BCR(KLHL22) ubiquitin ligase complex is also responsible for the amino acid-stimulated 'Lys-48' polyubiquitination and proteasomal degradation of DEPDC5. Through the degradation of DEPDC5, releases the GATOR1 complex-mediated inhibition of the TORC1 pathway (PubMed:29769719). The BCR(KLHL25) ubiquitin ligase complex is involved in translational homeostasis by mediating ubiquitination and subsequent degradation of hypophosphorylated EIF4EBP1 (4E-BP1) (PubMed:22578813). The BCR(KLHL25) ubiquitin ligase complex is also involved in lipid synthesis by mediating ubiquitination and degradation of ACLY (PubMed:27664236). The BCR(KBTBD8) complex acts by mediating monoubiquitination of NOLC1 and TCOF1, leading to remodel the translational program of differentiating cells in favor of neural crest specification (PubMed:26399832). Involved in ubiquitination of cyclin E and of cyclin D1 (in vitro) thus involved in regulation of G1/S transition. Involved in the ubiquitination of KEAP1, ENC1 and KLHL41 (PubMed:15983046). In concert with ATF2 and RBX1, promotes degradation of KAT5 thereby attenuating its ability to acetylate and activate ATM. The BCR(KCTD17) E3 ubiquitin ligase complex mediates ubiquitination and degradation of TCHP, a down-regulator of cilium assembly, thereby inducing ciliogenesis (PubMed:25270598). The BCR(KLHL24) E3 ubiquitin ligase complex mediates ubiquitination of KRT14, controls KRT14 levels during keratinocytes differentiation, and is essential for skin integrity (PubMed:27798626). The BCR(KLHL18) E3 ubiquitin ligase complex mediates the ubiquitination of AURKA leading to its activation at the centrosome which is required for initiating mitotic entry (PubMed:23213400). The BCR(KEAP1) E3 ubiquitin ligase complex acts as a key sensor of oxidative and electrophilic stress by mediating ubiquitination and degradation of NFE2L2/NRF2, a transcription factor regulating expression of many cytoprotective genes (PubMed:15601839, PubMed:16006525). As part of the CUL3(KBTBD6/7) E3 ubiquitin ligase complex functions mediates 'Lys-48' ubiquitination and proteasomal degradation of TIAM1 (PubMed:25684205). By controlling the ubiquitination of that RAC1 guanine exchange factors (GEF), regulates RAC1 signal transduction and downstream biological processes including the organization of the cytoskeleton, cell migration and cell proliferation (PubMed:25684205). The BCR(KBTBD4) E3 ubiquitin ligase complex targets CoREST corepressor complex components RCOR1, KDM1A/LSD1 and HDAC2 for proteasomal degradation with RCOR1 likely to be the primary target while degradation of KDM1A and HDAC2 is likely due to their association with RCOR1 (PubMed:33417871). It also targets RCOR3, MIER2 and MIER3 for proteasomal degradation as well as associated proteins ZNF217 and RREB1 with degradation being dependent on the presence of an ELM2 domain in the target proteins (PubMed:36997086). The BCR(ARMC5) complex mediates premature transcription termination of transcripts that are unfavorably configured for transcriptional elongation by mediating ubiquitination of Pol II subunit POLR2A (PubMed:35687106, PubMed:38225631, PubMed:39504960, PubMed:39667934). Required for 'Lys-63'-linked ubiquitination of large ribosomal subunit protein MRPL12 (PubMed:37526061). Protects against human enterovirus D68 infection by mediating the ubiquitination and subsequent degradation of viral protein VP1 (PubMed:40396757)","source":"project UniProt records20261017/18"},{"partner":"DEK","hgnc":"HGNC:2768","core":true,"core_annotation":{"hgnc":"HGNC:2768","symbol_at_source":"DEK","accession":"P35659","function":"Chromatin remodeling","target":"histone","pmids":["17524367"],"complexes":"B-WICH","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":195,"hub_weight":0.45175395145262565,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Involved in chromatin organization","source":"project UniProt records20261017/18"},{"partner":"DNMT1","hgnc":"HGNC:2976","core":true,"core_annotation":{"hgnc":"HGNC:2976","symbol_at_source":"DNMT1","accession":"P26358","function":"DNA modification","target":"DNA","pmids":["18754681"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":501,"hub_weight":0.30123761656438897,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"DNA methyltransferase that methylates CpG residues (PubMed:17200670, PubMed:18754681, PubMed:21745816, PubMed:26070743). Preferentially methylates hemimethylated DNA (PubMed:21745816, PubMed:26070743). Associates with DNA replication sites in S phase maintaining the methylation pattern in the newly synthesized strand, that is essential for epigenetic inheritance (PubMed:17200670, PubMed:21745816). Associates with chromatin during G2 and M phases to maintain DNA methylation independently of replication (PubMed:21745816). It is responsible for maintaining methylation patterns established in development (PubMed:21745816). DNA methylation is coordinated with methylation of histones (PubMed:16357870). Mediates transcriptional repression by direct binding to HDAC2 (PubMed:10888872). In association with DNMT3B and via the recruitment of CTCFL/BORIS, involved in activation of BAG1 gene expression by modulating dimethylation of promoter histone H3 at H3K4 and H3K9 (PubMed:18413740). Probably forms a corepressor complex required for activated KRAS-mediated promoter hypermethylation and transcriptional silencing of tumor suppressor genes (TSGs) or other tumor-related genes in colorectal cancer (CRC) cells (PubMed:24623306). Also required to maintain a transcriptionally repressive state of genes in undifferentiated embryonic stem cells (ESCs) (PubMed:24623306). Associates at promoter regions of tumor suppressor genes (TSGs) leading to their gene silencing (PubMed:24623306)","source":"project UniProt records20261017/18"},{"partner":"DNMT3A","hgnc":"HGNC:2978","core":true,"core_annotation":{"hgnc":"HGNC:2978","symbol_at_source":"DNMT3A","accession":"Q9Y6K1","function":"DNA modification","target":"DNA","pmids":["12138111"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":98,"hub_weight":0.5812381937190964,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Required for genome-wide de novo methylation and is essential for the establishment of DNA methylation patterns during development (PubMed:12138111, PubMed:16357870, PubMed:30478443). DNA methylation is coordinated with methylation of histones (PubMed:12138111, PubMed:16357870, PubMed:30478443). It modifies DNA in a non-processive manner and also methylates non-CpG sites (PubMed:12138111, PubMed:16357870, PubMed:30478443). May preferentially methylate DNA linker between 2 nucleosomal cores and is inhibited by histone H1 (By similarity). Plays a role in paternal and maternal imprinting (By similarity). Required for methylation of most imprinted loci in germ cells (By similarity). Acts as a transcriptional corepressor for ZBTB18 (By similarity). Recruited to trimethylated 'Lys-36' of histone H3 (H3K36me3) sites (By similarity). Can actively repress transcription through the recruitment of HDAC activity (By similarity). Also has weak auto-methylation activity on Cys-710 in absence of DNA (By similarity)","source":"project UniProt records20261017/18"},{"partner":"H1-10","hgnc":"HGNC:4722","core":true,"core_annotation":{"hgnc":"HGNC:4722","symbol_at_source":"H1FX","accession":"Q92522","function":"Histone/protamine","target":"chromatin","pmids":[],"version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":266,"hub_weight":0.397778642087865,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Nucleus, nucleolus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone H1 protein binds to linker DNA between nucleosomes forming the macromolecular structure known as the chromatin fiber (PubMed:33238161). Histones H1 are necessary for the condensation of nucleosome chains into higher-order structured fibers and promote formation of the H3K27me3 mark by the PRC2/EED-EZH2 complex (PubMed:33238161, PubMed:40516528)","source":"project UniProt records20261017/18"},{"partner":"MACROH2A1","hgnc":"HGNC:4740","core":true,"core_annotation":{"hgnc":"HGNC:4740","symbol_at_source":"H2AFY","accession":"O75367","function":"Histone/protamine","target":"chromatin","pmids":[],"version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":412,"hub_weight":0.3289758474798845,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Variant histone H2A which replaces conventional H2A in a subset of nucleosomes where it represses transcription (PubMed:12718888, PubMed:15621527, PubMed:16428466). Nucleosomes wrap and compact DNA into chromatin, limiting DNA accessibility to the cellular machineries which require DNA as a template (PubMed:15897469). Histones thereby play a central role in transcription regulation, DNA repair, DNA replication and chromosomal stability (PubMed:15897469). DNA accessibility is regulated via a complex set of post-translational modifications of histones, also called histone code, and nucleosome remodeling. Involved in stable X chromosome inactivation (PubMed:15897469). Inhibits the binding of transcription factors, including NF-kappa-B, and interferes with the activity of remodeling SWI/SNF complexes (PubMed:12718888, PubMed:16428466). Inhibits histone acetylation by EP300 and recruits class I HDACs, which induces a hypoacetylated state of chromatin (PubMed:16107708, PubMed:16428466)\nIsoform that specifically binds poly-ADP-ribose and O-acetyl-ADP-ribose and plays a key role in NAD(+) metabolism (PubMed:15902274). Able to bind to the ends of poly-ADP-ribose chains created by PARP1 and cap them (By similarity). This prevents PARP1 from further addition of ADP-ribose and thus limits the consumption of nuclear NAD(+), allowing the cell to maintain proper NAD(+) levels in both the nucleus and the mitochondria to promote proper mitochondrial respiration (By similarity). Increases the expression of genes involved in redox metabolism, including SOD3 (PubMed:23022728)\nIn contrast to isoform 1, does not bind poly-ADP-ribose (PubMed:15902274). Represses SOD3 gene expression (PubMed:23022728)","source":"project UniProt records20261017/18"},{"partner":"H2AZ1","hgnc":"HGNC:4741","core":true,"core_annotation":{"hgnc":"HGNC:4741","symbol_at_source":"H2AFZ","accession":"P0C0S5","function":"Histone/protamine","target":"chromatin","pmids":[],"version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":351,"hub_weight":0.35311227577322435,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Variant histone H2A which replaces conventional H2A in a subset of nucleosomes. Nucleosomes wrap and compact DNA into chromatin, limiting DNA accessibility to the cellular machineries which require DNA as a template. Histones thereby play a central role in transcription regulation, DNA repair, DNA replication and chromosomal stability. DNA accessibility is regulated via a complex set of post-translational modifications of histones, also called histone code, and nucleosome remodeling. May be involved in the formation of constitutive heterochromatin. May be required for chromosome segregation during cell division","source":"project UniProt records20261017/18"},{"partner":"H2BC17","hgnc":"HGNC:4758","core":true,"core_annotation":{"hgnc":"HGNC:4758","symbol_at_source":"HIST1H2BO","accession":"P23527","function":"Histone/protamine","target":"chromatin","pmids":[],"version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":241,"hub_weight":0.41451333614483915,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Core component of nucleosome. Nucleosomes wrap and compact DNA into chromatin, limiting DNA accessibility to the cellular machineries which require DNA as a template. Histones thereby play a central role in transcription regulation, DNA repair, DNA replication and chromosomal stability. DNA accessibility is regulated via a complex set of post-translational modifications of histones, also called histone code, and nucleosome remodeling","source":"project UniProt records20261017/18"},{"partner":"HELLS","hgnc":"HGNC:4861","core":true,"core_annotation":{"hgnc":"HGNC:4861","symbol_at_source":"HELLS","accession":"Q9NRZ9","function":"Chromatin remodeling","target":"chromatin","pmids":["14612388"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":157,"hub_weight":0.49147318718299043,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"ATP-dependent chromatin remodeler that regulates chromatin accessibility, DNA methylation, and histone modifications. It facilitates de novo DNA methylation at repetitive sequences and promotes transcriptional silencing via recruitment of DNA methyltransferases (DNMTs) and histone deacetylases (HDACs), contributing to heterochromatin formation and repression of transposable elements (PubMed:30307408). Also involved in DNA repair by recruiting DNA damage response mediators to double-strand breaks in heterochromatin, promoting homologous recombination via RBBP8/CtIP-dependent end resection (PubMed:22946062, PubMed:31802118). During meiosis, it is recruited by PRDM9 to recombination hotspots, aiding chromatin opening (PubMed:32001511). Through these diverse roles, is crucial for processes such as development, differentiation, and genomic stability (PubMed:22946062, PubMed:31802118). Involved in regulation of the expansion or survival of lymphoid cells (By similarity)","source":"project UniProt records20261017/18"},{"partner":"HMGB1","hgnc":"HGNC:4983","core":true,"core_annotation":{"hgnc":"HGNC:4983","symbol_at_source":"HMGB1","accession":"P09429","function":"Chromatin remodeling","target":"chromatin","pmids":["19158276"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":487,"hub_weight":0.3051390988486767,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome; Cytoplasm; Secreted; Cell membrane; Endosome; Endoplasmic reticulum-Golgi intermediate compartment; Endoplasmic reticulum","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Multifunctional redox sensitive protein with various roles in different cellular compartments. In the nucleus is one of the major chromatin-associated non-histone proteins and acts as a DNA chaperone involved in replication, transcription, chromatin remodeling, V(D)J recombination, DNA repair and genome stability (PubMed:33147444). Proposed to be an universal biosensor for nucleic acids. Promotes host inflammatory response to sterile and infectious signals and is involved in the coordination and integration of innate and adaptive immune responses. In the cytoplasm functions as a sensor and/or chaperone for immunogenic nucleic acids implicating the activation of TLR9-mediated immune responses, and mediates autophagy. Acts as a danger-associated molecular pattern (DAMP) molecule that amplifies immune responses during tissue injury (PubMed:27362237). Released to the extracellular environment can bind DNA, nucleosomes, IL-1 beta, CXCL12, AGER isoform 2/sRAGE, lipopolysaccharide (LPS) and lipoteichoic acid (LTA), and activates cells through engagement of multiple surface receptors (PubMed:34743181). In the extracellular compartment fully reduced HMGB1 (released by necrosis) acts as a chemokine, disulfide HMGB1 (actively secreted) as a cytokine, and sulfonyl HMGB1 (released from apoptotic cells) promotes immunological tolerance (PubMed:23446148, PubMed:23519706, PubMed:23994764, PubMed:25048472). Has proangiogdenic activity (By similarity). May be involved in platelet activation (By similarity). Binds to phosphatidylserine and phosphatidylethanolamide (By similarity). Bound to RAGE mediates signaling for neuronal outgrowth (By similarity). May play a role in accumulation of expanded polyglutamine (polyQ) proteins such as huntingtin (HTT) or TBP (PubMed:23303669, PubMed:25549101)\nNuclear functions are attributed to fully reduced HGMB1. Associates with chromatin and binds DNA with a preference to non-canonical DNA structures such as single-stranded DNA, DNA-containing cruciforms or bent structures, supercoiled DNA and ZDNA. Can bent DNA and enhance DNA flexibility by looping thus providing a mechanism to promote activities on various gene promoters by enhancing transcription factor binding and/or bringing distant regulatory sequences into close proximity (PubMed:20123072). May have an enhancing role in nucleotide excision repair (NER) (By similarity). However, effects in NER using in vitro systems have been reported conflictingly (PubMed:19360789, PubMed:19446504). May be involved in mismatch repair (MMR) and base excision repair (BER) pathways (PubMed:15014079, PubMed:16143102, PubMed:17803946). May be involved in double strand break repair such as non-homologous end joining (NHEJ) (By similarity). Involved in V(D)J recombination by acting as a cofactor of the RAG complex: acts by stimulating cleavage and RAG protein binding at the 23 bp spacer of conserved recombination signal sequences (RSS) (By similarity). In vitro can displace histone H1 from highly bent DNA (By similarity). Can restructure the canonical nucleosome leading to relaxation of structural constraints for transcription factor-binding (By similarity). Enhances binding of sterol regulatory element-binding proteins (SREBPs) such as SREBF1 to their cognate DNA sequences and increases their transcriptional activities (By similarity). Facilitates binding of TP53 to DNA (PubMed:23063560). Proposed to be involved in mitochondrial quality control and autophagy in a transcription-dependent fashion implicating HSPB1; however, this function has been questioned (By similarity). Can modulate the activity of the telomerase complex and may be involved in telomere maintenance (By similarity)\nIn the cytoplasm proposed to dissociate the BECN1:BCL2 complex via competitive interaction with BECN1 leading to autophagy activation (PubMed:20819940). Involved in oxidative stress-mediated autophagy (PubMed:21395369). Can protect BECN1 and ATG5 from calpain-mediated cleavage and thus proposed to control their proautophagic and proapoptotic functions and to regulate the extent and severity of inflammation-associated cellular injury (By similarity). In myeloid cells has a protective role against endotoxemia and bacterial infection by promoting autophagy (By similarity). Involved in endosomal translocation and activation of TLR9 in response to CpG-DNA in macrophages (By similarity)\nIn the extracellular compartment (following either active secretion or passive release) involved in regulation of the inflammatory response. Fully reduced HGMB1 (which subsequently gets oxidized after release) in association with CXCL12 mediates the recruitment of inflammatory cells during the initial phase of tissue injury; the CXCL12:HMGB1 complex triggers CXCR4 homodimerization (PubMed:22370717). Induces the migration of monocyte-derived immature dendritic cells and seems to regulate adhesive and migratory functions of neutrophils implicating AGER/RAGE and ITGAM (By similarity). Can bind to various types of DNA and RNA including microbial unmethylated CpG-DNA to enhance the innate immune response to nucleic acids. Proposed to act in promiscuous DNA/RNA sensing which cooperates with subsequent discriminative sensing by specific pattern recognition receptors (By similarity). Promotes extracellular DNA-induced AIM2 inflammasome activation implicating AGER/RAGE (PubMed:24971542). Disulfide HMGB1 binds to transmembrane receptors, such as AGER/RAGE, TLR2, TLR4 and probably TREM1, thus activating their signal transduction pathways. Mediates the release of cytokines/chemokines such as TNF, IL-1, IL-6, IL-8, CCL2, CCL3, CCL4 and CXCL10 (PubMed:12765338, PubMed:18354232, PubMed:19264983, PubMed:20547845, PubMed:24474694). Promotes secretion of interferon-gamma by macrophage-stimulated natural killer (NK) cells in concert with other cytokines like IL-2 or IL-12 (PubMed:15607795). TLR4 is proposed to be the primary receptor promoting macrophage activation and signaling through TLR4 seems to implicate LY96/MD-2 (PubMed:20547845). In bacterial LPS- or LTA-mediated inflammatory responses binds to the endotoxins and transfers them to CD14 for signaling to the respective TLR4:LY96 and TLR2 complexes (PubMed:18354232, PubMed:21660935, PubMed:25660311). Contributes to tumor proliferation by association with ACER/RAGE (By similarity). Can bind to IL1-beta and signals through the IL1R1:IL1RAP receptor complex (PubMed:18250463). Binding to class A CpG activates cytokine production in plasmacytoid dendritic cells implicating TLR9, MYD88 and AGER/RAGE and can activate autoreactive B cells. Via HMGB1-containing chromatin immune complexes may also promote B cell responses to endogenous TLR9 ligands through a B-cell receptor (BCR)-dependent and ACER/RAGE-independent mechanism (By similarity). Inhibits phagocytosis of apoptotic cells by macrophages; the function is dependent on poly-ADP-ribosylation and involves binding to phosphatidylserine on the cell surface of apoptotic cells (By similarity). In adaptive immunity may be involved in enhancing immunity through activation of effector T cells and suppression of regulatory T (TReg) cells (PubMed:15944249, PubMed:22473704). In contrast, without implicating effector or regulatory T-cells, required for tumor infiltration and activation of T-cells expressing the lymphotoxin LTA:LTB heterotrimer thus promoting tumor malignant progression (By similarity). Also reported to limit proliferation of T-cells (By similarity). Released HMGB1:nucleosome complexes formed during apoptosis can signal through TLR2 to induce cytokine production (PubMed:19064698). Involved in induction of immunological tolerance by apoptotic cells; its pro-inflammatory activities when released by apoptotic cells are neutralized by reactive oxygen species (ROS)-dependent oxidation specifically on Cys-106 (PubMed:18631454). During macrophage activation by activated lymphocyte-derived self apoptotic DNA (ALD-DNA) promotes recruitment of ALD-DNA to endosomes (By similarity)\n(Microbial infection) Critical for entry of human coronaviruses SARS-CoV and SARS-CoV-2, as well as human coronavirus NL63/HCoV-NL63 (PubMed:33147444). Regulates the expression of the pro-viral genes ACE2 and CTSL through chromatin modulation (PubMed:33147444). Required for SARS-CoV-2 ORF3A-induced reticulophagy which induces endoplasmic reticulum stress and inflammatory responses and facilitates viral infection (PubMed:35239449)\n(Microbial infection) Associates with the influenza A viral protein NP in the nucleus of infected cells, promoting viral growth and enhancing the activity of the viral polymerase\n(Microbial infection) Promotes Epstein-Barr virus (EBV) latent-to-lytic switch by sustaining the expression of the viral transcription factor BZLF1 that acts as a molecular switch to induce the transition from the latent to the lytic or productive phase of the virus cycle. Mechanistically, participates in EBV reactivation through the NLRP3 inflammasome\n(Microbial infection) Facilitates dengue virus propagation via interaction with the untranslated regions of viral genome. In turn, this interaction with viral RNA may regulate secondary structure of dengue RNA thus facilitating its recognition by the replication complex","source":"project UniProt records20261017/18"},{"partner":"HMG20A","hgnc":"HGNC:5001","core":true,"core_annotation":{"hgnc":"HGNC:5001","symbol_at_source":"HMG20A","accession":"Q9NP66","function":"Chromatin remodeling cofactor","target":"histone","pmids":["24227653"],"complexes":"LSD-CoREST","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":201,"hub_weight":0.4463218426774518,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Plays a role in neuronal differentiation as chromatin-associated protein. Acts as inhibitor of HMG20B. Overcomes the repressive effects of the neuronal silencer REST and induces the activation of neuronal-specific genes. Involved in the recruitment of the histone methyltransferase KMT2A/MLL1 and consequent increased methylation of histone H3 lysine 4 (By similarity)","source":"project UniProt records20261017/18"},{"partner":"HSPA1A","hgnc":"HGNC:5232","core":true,"core_annotation":{"hgnc":"HGNC:5232","symbol_at_source":"HSPA1A","accession":"P0DMV8","function":"Histone modification write cofactor","target":"Protein","pmids":["16809764","2123078"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":1105,"hub_weight":0.20806259464411975,"quality":0.65,"programmes":["pubmed:32687490"],"pmids":["32687490"],"assays":["capture_association"],"contexts":[],"partner_location":"Cytoplasm; Nucleus; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Secreted","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Molecular chaperone implicated in a wide variety of cellular processes, including protection of the proteome from stress, folding and transport of newly synthesized polypeptides, activation of proteolysis of misfolded proteins and the formation and dissociation of protein complexes. Plays a pivotal role in the protein quality control system, ensuring the correct folding of proteins, the re-folding of misfolded proteins and controlling the targeting of proteins for subsequent degradation. This is achieved through cycles of ATP binding, ATP hydrolysis and ADP release, mediated by co-chaperones. The co-chaperones have been shown to not only regulate different steps of the ATPase cycle, but they also have an individual specificity such that one co-chaperone may promote folding of a substrate while another may promote degradation. The affinity for polypeptides is regulated by its nucleotide bound state. In the ATP-bound form, it has a low affinity for substrate proteins. However, upon hydrolysis of the ATP to ADP, it undergoes a conformational change that increases its affinity for substrate proteins. It goes through repeated cycles of ATP hydrolysis and nucleotide exchange, which permits cycles of substrate binding and release. The co-chaperones are of three types: J-domain co-chaperones such as HSP40s (stimulate ATPase hydrolysis by HSP70), the nucleotide exchange factors (NEF) such as BAG1/2/3 (facilitate conversion of HSP70 from the ADP-bound to the ATP-bound state thereby promoting substrate release), and the TPR domain chaperones such as HOPX and STUB1 (PubMed:24012426, PubMed:24318877, PubMed:26865365). Maintains protein homeostasis during cellular stress through two opposing mechanisms: protein refolding and degradation. Its acetylation/deacetylation state determines whether it functions in protein refolding or protein degradation by controlling the competitive binding of co-chaperones HOPX and STUB1. During the early stress response, the acetylated form binds to HOPX which assists in chaperone-mediated protein refolding, thereafter, it is deacetylated and binds to ubiquitin ligase STUB1 that promotes ubiquitin-mediated protein degradation (PubMed:27708256). Regulates centrosome integrity during mitosis, and is required for the maintenance of a functional mitotic centrosome that supports the assembly of a bipolar mitotic spindle (PubMed:27137183). Enhances STUB1-mediated SMAD3 ubiquitination and degradation and facilitates STUB1-mediated inhibition of TGF-beta signaling (PubMed:24613385). Essential for STUB1-mediated ubiquitination and degradation of FOXP3 in regulatory T-cells (Treg) during inflammation (PubMed:23973223). Required as a co-chaperone for optimal STUB1/CHIP ubiquitination of NFATC3 (By similarity). Negatively regulates heat shock-induced HSF1 transcriptional activity during the attenuation and recovery phase period of the heat shock response (PubMed:9499401). Involved in the clearance of misfolded PRDM1/Blimp-1 proteins. Sequesters them in the cytoplasm and promotes their association with SYNV1/HRD1, leading to proteasomal degradation (PubMed:28842558)\n(Microbial infection) In case of rotavirus A infection, serves as a post-attachment receptor for the virus to facilitate entry into the cell","source":"project UniProt records20261017/18"},{"partner":"MAZ","hgnc":"HGNC:6914","core":true,"core_annotation":{"hgnc":"HGNC:6914","symbol_at_source":"MAZ","accession":"P56270","function":"Chromatin remodeling","target":"chromatin","pmids":["21920360"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":87,"hub_weight":0.604122093330177,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Transcriptional regulator, potentially with dual roles in transcription initiation and termination\nBinds DNA and functions as a transcriptional activator (PubMed:12270922). Binds to two G/A-rich sites, ME1a1 and ME1a2, within the MYC promoter having greater affinity for the former (PubMed:1502157). Also binds to multiple G/C-rich sites within the promoter of the Sp1 family of transcription factors (PubMed:1502157)\nBinds DNA and functions as a transcriptional activator (PubMed:12270922). Inhibits MAZ isoform 1-mediated transcription (PubMed:12270922)\nBinds DNA and functions as a transcriptional activator","source":"project UniProt records20261017/18"},{"partner":"MECP2","hgnc":"HGNC:6990","core":true,"core_annotation":{"hgnc":"HGNC:6990","symbol_at_source":"MECP2","accession":"P51608","function":"Histone modification write cofactor, Histone modification write cofactor, TF","target":"DNA","pmids":["10773092"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":1032,"hub_weight":0.2149667901961739,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Chromosomal protein that binds to methylated DNA. It can bind specifically to a single methyl-CpG pair. It is not influenced by sequences flanking the methyl-CpGs. Mediates transcriptional repression through interaction with histone deacetylase and the corepressor SIN3A. Binds both 5-methylcytosine (5mC) and 5-hydroxymethylcytosine (5hmC)-containing DNA, with a preference for 5-methylcytosine (5mC)","source":"project UniProt records20261017/18"},{"partner":"KMT2A","hgnc":"HGNC:7132","core":true,"core_annotation":{"hgnc":"HGNC:7132","symbol_at_source":"KMT2A","accession":"Q03164","function":"Histone modification write","target":"histone","pmids":["19187761"],"complexes":"MLL-HCF, CHD8, COMPASS-like MLL1,2","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":266,"hub_weight":0.397778642087865,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Nucleus; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone methyltransferase that plays an essential role in early development and hematopoiesis (PubMed:12453419, PubMed:15960975, PubMed:19187761, PubMed:19556245, PubMed:20677832, PubMed:21220120, PubMed:26886794). Catalytic subunit of the MLL1/MLL complex, a multiprotein complex that mediates both methylation of 'Lys-4' of histone H3 (H3K4me) complex and acetylation of 'Lys-16' of histone H4 (H4K16ac) (PubMed:12453419, PubMed:15960975, PubMed:19187761, PubMed:19556245, PubMed:20677832, PubMed:21220120, PubMed:24235145, PubMed:26886794). Catalyzes methyl group transfer from S-adenosyl-L-methionine to the epsilon-amino group of 'Lys-4' of histone H3 (H3K4) via a non-processive mechanism. Part of chromatin remodeling machinery predominantly forms H3K4me1 and H3K4me2 methylation marks at active chromatin sites where transcription and DNA repair take place (PubMed:12453419, PubMed:15960975, PubMed:19187761, PubMed:19556245, PubMed:20677832, PubMed:21220120, PubMed:25561738, PubMed:26886794). Has weak methyltransferase activity by itself, and requires other component of the MLL1/MLL complex to obtain full methyltransferase activity (PubMed:19187761, PubMed:26886794). Has no activity toward histone H3 phosphorylated on 'Thr-3', less activity toward H3 dimethylated on 'Arg-8' or 'Lys-9', while it has higher activity toward H3 acetylated on 'Lys-9' (PubMed:19187761). Binds to unmethylated CpG elements in the promoter of target genes and helps maintain them in the nonmethylated state (PubMed:20010842). Required for transcriptional activation of HOXA9 (PubMed:12453419, PubMed:20010842, PubMed:20677832). Promotes PPP1R15A-induced apoptosis (PubMed:10490642). Plays a critical role in the control of circadian gene expression and is essential for the transcriptional activation mediated by the CLOCK-BMAL1 heterodimer (By similarity). Establishes a permissive chromatin state for circadian transcription by mediating a rhythmic methylation of 'Lys-4' of histone H3 (H3K4me) and this histone modification directs the circadian acetylation at H3K9 and H3K14 allowing the recruitment of CLOCK-BMAL1 to chromatin (By similarity). Also has auto-methylation activity on Cys-3882 in absence of histone H3 substrate (PubMed:24235145)","source":"project UniProt records20261017/18"},{"partner":"MLLT1","hgnc":"HGNC:7134","core":true,"core_annotation":{"hgnc":"HGNC:7134","symbol_at_source":"MLLT1","accession":"Q03111","function":"Chromatin remodeling cofactor","target":"chromatin","pmids":["23623499"],"complexes":"SWI/SNF-like_EPAFa, SWI/SNF-like EPAFB","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":109,"hub_weight":0.5607721540920443,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Chromatin reader component of the super elongation complex (SEC), a complex required to increase the catalytic rate of RNA polymerase II transcription by suppressing transient pausing by the polymerase at multiple sites along the DNA (PubMed:20159561, PubMed:20471948). Specifically recognizes and binds acetylated and crotonylated histones, with a preference for histones that are crotonylated (PubMed:27105114). Has a slightly higher affinity for binding histone H3 crotonylated at 'Lys-27' (H3K27cr) than 'Lys-20' (H3K9cr20) (PubMed:27105114). May play a role in leukemogenic gene transcription (PubMed:39794553)\nActs as a key chromatin reader in acute myeloid leukemia by recognizing and binding to acetylated histones via its YEATS domain, thereby regulating oncogenic gene transcription","source":"project UniProt records20261017/18"},{"partner":"MLLT6","hgnc":"HGNC:7138","core":true,"core_annotation":{"hgnc":"HGNC:7138","symbol_at_source":"MLLT6","accession":"P55198","function":"Histone modification write cofactor","target":"histone","pmids":["20203130"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":79,"hub_weight":0.6225728063646904,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Involved in the stimulation of renal sodium reabsorption mediated by the epithelial sodium channel (ENaC) (By similarity). Up-regulates ENaC expression in renal collecting duct cells by promoting DOT1L export from the nucleus to the cytoplasm, thus limiting DOT1L-mediated H3K79 methylation and transcriptional repression at the SCNN1A promoter (PubMed:19864429, PubMed:22087315)","source":"project UniProt records20261017/18"},{"partner":"MSH6","hgnc":"HGNC:7329","core":true,"core_annotation":{"hgnc":"HGNC:7329","symbol_at_source":"MSH6","accession":"P52701","function":"Histone modification read","target":"histone","pmids":["21423274"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":250,"hub_weight":0.408248290463863,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Component of the post-replicative DNA mismatch repair system (MMR). Heterodimerizes with MSH2 to form MutS alpha, which binds to DNA mismatches thereby initiating DNA repair. When bound, MutS alpha bends the DNA helix and shields approximately 20 base pairs, and recognizes single base mismatches and dinucleotide insertion-deletion loops (IDL) in the DNA. After mismatch binding, forms a ternary complex with the MutL alpha heterodimer, which is thought to be responsible for directing the downstream MMR events, including strand discrimination, excision, and resynthesis. ATP binding and hydrolysis play a pivotal role in mismatch repair functions. The ATPase activity associated with MutS alpha regulates binding similar to a molecular switch: mismatched DNA provokes ADP-->ATP exchange, resulting in a discernible conformational transition that converts MutS alpha into a sliding clamp capable of hydrolysis-independent diffusion along the DNA backbone. This transition is crucial for mismatch repair. MutS alpha may also play a role in DNA homologous recombination repair. Recruited on chromatin in G1 and early S phase via its PWWP domain that specifically binds trimethylated 'Lys-36' of histone H3 (H3K36me3): early recruitment to chromatin to be replicated allowing a quick identification of mismatch repair to initiate the DNA mismatch repair reaction","source":"project UniProt records20261017/18"},{"partner":"MYBBP1A","hgnc":"HGNC:7546","core":true,"core_annotation":{"hgnc":"HGNC:7546","symbol_at_source":"MYBBP1A","accession":"Q9BQG0","function":"Chromatin remodeling cofactor","target":"chromatin","pmids":["16603771"],"complexes":"B-WICH","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":425,"hub_weight":0.3244428422615251,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Cytoplasm; Nucleus; Nucleus, nucleolus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"May activate or repress transcription via interactions with sequence specific DNA-binding proteins (By similarity). Repression may be mediated at least in part by histone deacetylase activity (HDAC activity) (By similarity). Acts as a corepressor and in concert with CRY1, represses the transcription of the core circadian clock component PER2 (By similarity). Preferentially binds to dimethylated histone H3 'Lys-9' (H3K9me2) on the PER2 promoter (By similarity). Has a role in rRNA biogenesis together with PWP1 (PubMed:29065309)","source":"project UniProt records20261017/18"},{"partner":"NAP1L1","hgnc":"HGNC:7637","core":true,"core_annotation":{"hgnc":"HGNC:7637","symbol_at_source":"NAP1L1","accession":"P55209","function":"Histone chaperone","target":"histone","pmids":["18226242"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":308,"hub_weight":0.37371754637596794,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome; Melanosome; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone chaperone that plays a role in the nuclear import of H2A-H2B and nucleosome assembly (PubMed:20002496, PubMed:21211722, PubMed:26841755). Also participates in several important DNA repair mechanisms: greatly enhances ERCC6-mediated chromatin remodeling which is essential for transcription-coupled nucleotide excision DNA repair (PubMed:28369616). Also stimulates homologous recombination (HR) by RAD51 and RAD54 which is essential in mitotic DNA double strand break (DSB) repair (PubMed:24798879). Plays a key role in the regulation of embryonic neurogenesis (By similarity). Promotes the proliferation of neural progenitors and inhibits neuronal differentiation during cortical development (By similarity). Regulates neurogenesis via the modulation of RASSF10; regulates RASSF10 expression by promoting SETD1A-mediated H3K4 methylation at the RASSF10 promoter (By similarity)\n(Microbial infection) Positively regulates Epstein-Barr virus reactivation in epithelial cells through the induction of viral BZLF1 expression\n(Microbial infection) Together with human herpesvirus 8 protein LANA1, assists the proper assembly of the nucleosome on the replicated viral DNA","source":"project UniProt records20261017/18"},{"partner":"NAP1L4","hgnc":"HGNC:7640","core":true,"core_annotation":{"hgnc":"HGNC:7640","symbol_at_source":"NAP1L4","accession":"Q99733","function":"Histone modification cofactor","target":"histone","pmids":["21333655"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":186,"hub_weight":0.4602873089491617,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Acts as a histone chaperone in nucleosome assembly","source":"project UniProt records20261017/18"},{"partner":"NUCLEOLIN","hgnc":"HGNC:7667","core":true,"core_annotation":{"hgnc":"HGNC:7667","symbol_at_source":"NCL","accession":"P19338","function":"Histone chaperone","target":"histone, DNA, RNA","pmids":["16601700"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":695,"hub_weight":0.2590638800754199,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus, nucleolus; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Nucleolin is the major nucleolar protein of growing eukaryotic cells. It is found associated with intranucleolar chromatin and pre-ribosomal particles. It induces chromatin decondensation by binding to histone H1. It is thought to play a role in pre-rRNA transcription and ribosome assembly. May play a role in the process of transcriptional elongation. Binds RNA oligonucleotides with 5'-UUAGGG-3' repeats more tightly than the telomeric single-stranded DNA 5'-TTAGGG-3' repeats","source":"project UniProt records20261017/18"},{"partner":"NPM1","hgnc":"HGNC:7910","core":true,"core_annotation":{"hgnc":"HGNC:7910","symbol_at_source":"NPM1","accession":"P06748","function":"Histone chaperone","target":"histone","pmids":["25349213"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":1053,"hub_weight":0.21291058142914557,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus, nucleolus; Nucleus, nucleoplasm; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Involved in diverse cellular processes such as ribosome biogenesis, centrosome duplication, protein chaperoning, histone assembly, cell proliferation, and regulation of tumor suppressors p53/TP53 and ARF. Binds ribosome presumably to drive ribosome nuclear export. Associated with nucleolar ribonucleoprotein structures and bind single-stranded nucleic acids. Acts as a chaperonin for the core histones H3, H2B and H4. Stimulates APEX1 endonuclease activity on apurinic/apyrimidinic (AP) double-stranded DNA but inhibits APEX1 endonuclease activity on AP single-stranded RNA. May exert a control of APEX1 endonuclease activity within nucleoli devoted to repair AP on rDNA and the removal of oxidized rRNA molecules. In concert with BRCA2, regulates centrosome duplication. Regulates centriole duplication: phosphorylation by PLK2 is able to trigger centriole replication. Negatively regulates the activation of EIF2AK2/PKR and suppresses apoptosis through inhibition of EIF2AK2/PKR autophosphorylation. Antagonizes the inhibitory effect of ATF5 on cell proliferation and relieves ATF5-induced G2/M blockade (PubMed:22528486). In complex with MYC enhances the transcription of MYC target genes (PubMed:25956029). May act as chaperonin or cotransporter in the nucleolar localization of transcription termination factor TTF1 (By similarity)","source":"project UniProt records20261017/18"},{"partner":"PHF2","hgnc":"HGNC:8920","core":true,"core_annotation":{"hgnc":"HGNC:8920","symbol_at_source":"PHF2","accession":"O75151","function":"Histone modification erase","target":"histone","pmids":["21532585"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":119,"hub_weight":0.5439282932204211,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus, nucleolus; Chromosome, centromere, kinetochore","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Lysine demethylase that demethylates both histones and non-histone proteins (PubMed:20129925, PubMed:21167174, PubMed:21532585). Enzymatically inactive by itself, and becomes active following phosphorylation by PKA: forms a complex with ARID5B and mediates demethylation of methylated ARID5B (PubMed:21532585). Demethylation of ARID5B leads to target the PHF2-ARID5B complex to target promoters, where PHF2 mediates demethylation of dimethylated 'Lys-9' of histone H3 (H3K9me2), followed by transcription activation of target genes (PubMed:21532585). The PHF2-ARID5B complex acts as a coactivator of HNF4A in liver. PHF2 is recruited to trimethylated 'Lys-4' of histone H3 (H3K4me3) at rDNA promoters and promotes expression of rDNA (PubMed:21532585). Involved in the activation of toll-like receptor 4 (TLR4)-target inflammatory genes in macrophages by catalyzing the demethylation of trimethylated histone H4 lysine 20 (H4K20me3) at the gene promoters (By similarity)","source":"project UniProt records20261017/18"},{"partner":"PPM1G","hgnc":"HGNC:9278","core":true,"core_annotation":{"hgnc":"HGNC:9278","symbol_at_source":"PPM1G","accession":"O15355","function":"Chromatin remodeling","target":"chromatin","pmids":["23723158"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":283,"hub_weight":0.3874921291460643,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Cytoplasm; Membrane","partner_has_nuclear_annotation":false,"partner_location_assessed":true,"function":"","source":"project UniProt records20261017/18"},{"partner":"ZMYND8","hgnc":"HGNC:9397","core":true,"core_annotation":{"hgnc":"HGNC:9397","symbol_at_source":"ZMYND8","accession":"Q9ULU4","function":"Histone modification erase cofactor","target":"histone","pmids":["25123934"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":186,"hub_weight":0.4602873089491617,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Chromatin reader that recognizes dual histone modifications such as histone H3.1 dimethylated at 'Lys-36' and histone H4 acetylated at 'Lys-16' (H3.1K36me2-H4K16ac) and histone H3 methylated at 'Lys-4' and histone H4 acetylated at 'Lys-14' (H3K4me1-H3K14ac) (PubMed:26655721, PubMed:27477906, PubMed:31965980, PubMed:36064715). May act as a transcriptional corepressor for KDM5D by recognizing the dual histone signature H3K4me1-H3K14ac (PubMed:27477906). May also act as a transcriptional corepressor for KDM5C and EZH2 (PubMed:33323928). Recognizes acetylated histone H4 and recruits the NuRD chromatin remodeling complex to damaged chromatin for transcriptional repression and double-strand break repair by homologous recombination (PubMed:25593309, PubMed:27732854, PubMed:30134174). Also activates transcription elongation by RNA polymerase II through recruiting the P-TEFb complex to target promoters (PubMed:26655721, PubMed:30134174). Localizes to H3.1K36me2-H4K16ac marks at all-trans-retinoic acid (ATRA)-responsive genes and positively regulates their expression (PubMed:26655721). Promotes neuronal differentiation by associating with regulatory regions within the MAPT gene, to enhance transcription of a protein-coding MAPT isoform and suppress the non-coding MAPT213 isoform (PubMed:30134174, PubMed:35916866, PubMed:36064715). Suppresses breast cancer, and prostate cancer cell invasion and metastasis (PubMed:27477906, PubMed:31965980, PubMed:33323928)","source":"project UniProt records20261017/18"},{"partner":"PSIP1","hgnc":"HGNC:9527","core":true,"core_annotation":{"hgnc":"HGNC:9527","symbol_at_source":"PSIP1","accession":"O75475","function":"Chromatin remodeling","target":"chromatin","pmids":["217205545"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":185,"hub_weight":0.46126560401444255,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Transcriptional coactivator involved in neuroepithelial stem cell differentiation and neurogenesis. Involved in particular in lens epithelial cell gene regulation and stress responses. May play an important role in lens epithelial to fiber cell terminal differentiation. May play a protective role during stress-induced apoptosis. Isoform 2 is a more general and stronger transcriptional coactivator. Isoform 2 may also act as an adapter to coordinate pre-mRNA splicing. Cellular cofactor for lentiviral integration","source":"project UniProt records20261017/18"},{"partner":"RAI1","hgnc":"HGNC:9834","core":true,"core_annotation":{"hgnc":"HGNC:9834","symbol_at_source":"RAI1","accession":"Q7Z5J4","function":"Chromatin remodeling","target":"chromatin","pmids":["22498752"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":106,"hub_weight":0.5661385170722979,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Cytoplasm; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Transcriptional regulator of the circadian clock components: CLOCK, BMAL1, BMAL2, PER1/3, CRY1/2, NR1D1/2 and RORA/C. Positively regulates the transcriptional activity of CLOCK a core component of the circadian clock. Regulates transcription through chromatin remodeling by interacting with other proteins in chromatin as well as proteins in the basic transcriptional machinery. May be important for embryonic and postnatal development. May be involved in neuronal differentiation","source":"project UniProt records20261017/18"},{"partner":"RNF2","hgnc":"HGNC:10061","core":true,"core_annotation":{"hgnc":"HGNC:10061","symbol_at_source":"RNF2","accession":"Q99496","function":"Histone modification write","target":"histone","pmids":["16943429"],"complexes":"PRC1, BCOR, RING2-L3MBTL2, RING2-FBRS, CHD8, MLL2/3, MLL4/WBP7","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":661,"hub_weight":0.26518576139191,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Cytoplasm; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"E3 ubiquitin-protein ligase that mediates monoubiquitination of 'Lys-119' of histone H2A (H2AK119Ub), thereby playing a central role in histone code and gene regulation (PubMed:15386022, PubMed:16359901, PubMed:21772249, PubMed:25355358, PubMed:25519132, PubMed:26151332, PubMed:33864376). H2AK119Ub gives a specific tag for epigenetic transcriptional repression and participates in X chromosome inactivation of female mammals. May be involved in the initiation of both imprinted and random X inactivation (By similarity). Essential component of a Polycomb group (PcG) multiprotein PRC1-like complex, a complex class required to maintain the transcriptionally repressive state of many genes, including Hox genes, throughout development (PubMed:16359901, PubMed:26151332). PcG PRC1 complex acts via chromatin remodeling and modification of histones, rendering chromatin heritably changed in its expressibility (PubMed:26151332). E3 ubiquitin-protein ligase activity is enhanced by BMI1/PCGF4 (PubMed:21772249). Acts as the main E3 ubiquitin ligase on histone H2A of the PRC1 complex, while RING1 may rather act as a modulator of RNF2/RING2 activity (Probable). Association with the chromosomal DNA is cell-cycle dependent. In resting B- and T-lymphocytes, interaction with AURKB leads to block its activity, thereby maintaining transcription in resting lymphocytes (By similarity). Also acts as a negative regulator of autophagy by mediating ubiquitination of AMBRA1, leading to its subsequent degradation (By similarity)","source":"project UniProt records20261017/18"},{"partner":"SET","hgnc":"HGNC:10760","core":true,"core_annotation":{"hgnc":"HGNC:10760","symbol_at_source":"SET","accession":"Q01105","function":"Histone modification","target":"histone","pmids":["17320507"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":277,"hub_weight":0.39103094350288753,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Cytoplasm, cytosol; Endoplasmic reticulum; Nucleus, nucleoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Multitasking protein, involved in apoptosis, transcription, nucleosome assembly and histone chaperoning. Isoform 2 anti-apoptotic activity is mediated by inhibition of the GZMA-activated DNase, NME1. In the course of cytotoxic T-lymphocyte (CTL)-induced apoptosis, GZMA cleaves SET, disrupting its binding to NME1 and releasing NME1 inhibition. Isoform 1 and isoform 2 are potent inhibitors of protein phosphatase 2A. Isoform 1 and isoform 2 inhibit EP300/CREBBP and PCAF-mediated acetylation of histones (HAT) and nucleosomes, most probably by masking the accessibility of lysines of histones to the acetylases. The predominant target for inhibition is histone H4. HAT inhibition leads to silencing of HAT-dependent transcription and prevents active demethylation of DNA. Both isoforms stimulate DNA replication of the adenovirus genome complexed with viral core proteins; however, isoform 2 specific activity is higher","source":"project UniProt records20261017/18"},{"partner":"SMARCA1","hgnc":"HGNC:11097","core":true,"core_annotation":{"hgnc":"HGNC:11097","symbol_at_source":"SMARCA1","accession":"P28370","function":"Chromatin remodeling, Histone modification erase","target":"chromatin","pmids":["15310751"],"complexes":"NuRF, CERF, CERF","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":187,"hub_weight":0.45931521217462534,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"ATPase that possesses intrinsic ATP-dependent chromatin-remodeling activity (PubMed:14609955, PubMed:15310751, PubMed:15640247, PubMed:28801535). ATPase activity is substrate-dependent, and is increased when nucleosomes are the substrate, but is also catalytically active when DNA alone is the substrate (PubMed:14609955, PubMed:15310751, PubMed:15640247). Catalytic subunit of ISWI chromatin-remodeling complexes, which form ordered nucleosome arrays on chromatin and facilitate access to DNA during DNA-templated processes such as DNA replication, transcription, and repair (PubMed:14609955, PubMed:15310751, PubMed:15640247, PubMed:28801535). Within the ISWI chromatin-remodeling complexes, slides edge- and center-positioned histone octamers away from their original location on the DNA template (PubMed:28801535). Catalytic activity and histone octamer sliding propensity is regulated and determined by components of the ISWI chromatin-remodeling complexes (PubMed:28801535). The BAZ1A-, BAZ1B-, BAZ2A- and BAZ2B-containing ISWI chromatin-remodeling complexes regulate the spacing of nucleosomes along the chromatin and have the ability to slide mononucleosomes to the center of a DNA template (PubMed:28801535). The CECR2- and RSF1-containing ISWI chromatin-remodeling complexes do not have the ability to slide mononucleosomes to the center of a DNA template (PubMed:28801535). Within the NURF-1 and CERF-1 ISWI chromatin remodeling complexes, nucleosomes are the preferred substrate for its ATPase activity (PubMed:14609955, PubMed:15640247). Within the NURF-1 ISWI chromatin-remodeling complex, binds to the promoters of En1 and En2 to positively regulate their expression and promote brain development (PubMed:14609955). May promote neurite outgrowth (PubMed:14609955). May be involved in the development of luteal cells (PubMed:16740656). Facilitates nucleosome assembly during DNA replication, ensuring replication fork progression and genomic stability by preventing replication stress and nascent DNA gaps (PubMed:39413208)\nCatalytically inactive when either DNA or nucleosomes are the substrate and does not possess chromatin-remodeling activity (PubMed:15310751, PubMed:28801535). Acts as a negative regulator of chromatin remodelers by generating inactive complexes (PubMed:15310751)","source":"project UniProt records20261017/18"},{"partner":"HLTF","hgnc":"HGNC:11099","core":true,"core_annotation":{"hgnc":"HGNC:11099","symbol_at_source":"HLTF","accession":"Q14527","function":"Chromatin remodeling cofactor","target":"chromatin","pmids":["18719106"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":139,"hub_weight":0.5143444998736397,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Functions as a DNA-dependent ATPase and E3 ubiquitin-protein ligase involved in chromatin regulation and DNA damage tolerance (DDT) (PubMed:18316726, PubMed:18719106, PubMed:26051180, PubMed:31960921, PubMed:39142279, PubMed:40680746). Catalyzes 'Lys-63'-linked polyubiquitination of monoubiquitinated PCNA at 'Lys-164' in response to genotoxic stress, promoting error-free postreplication repair via template switching (PubMed:18316726, PubMed:18719106). Acts as an epigenetic regulator by promoting recruitment of DNMT1, thereby ensuring DNA methylation inheritance: specifically binds histone H3 trimethylated at 'Lys-9' (H3K9me3) and mediates histone H3 'Lys-23' polyubiquitination (H3K23ub), a docking site for DNMT1, leading to DNMT1 recruitment and replication-coupled DNA methylation maintenance (PubMed:40680746). Catalyzes formation of H3K23ub in two steps: first mediates monoubiquitination together with UBE2E1 and UBE2D2, and then extends ubiquitin chains via 'Lys-63'-linked ubiquitination together with UBE2N and UBE2V2 (PubMed:40680746). Also acts as a chromatin redodeling factor, thereby regulating transcription (PubMed:10391891, PubMed:1994885, PubMed:9126292). Exhibits ATP-dependent double-stranded DNA (dsDNA) translocase activity but lacks classical helicase activity; mediates replication fork reversal by concertedly unwinding and annealing nascent and parental strands, thereby suppressing DNA synthesis and maintaining genomic stability (PubMed:1994885). Resolves G-quadruplex (G4) DNA structures in cooperation with MSH2, limiting replication stress and G4 accumulation across the cell cycle (PubMed:39142279). Contributes to nucleotide excision repair by evicting lesion-containing oligonucleotides using its HIRAN and ATPase domains (PubMed:26051180). Can displace single-stranded DNA from triplex structures through ATP-dependent dsDNA translocation (PubMed:26051180, PubMed:31960921). Also has protein clearing activity at the stalled replication fork, facilitating restart of DNA replication (PubMed:21795603)","source":"project UniProt records20261017/18"},{"partner":"SMARCA4","hgnc":"HGNC:11100","core":true,"core_annotation":{"hgnc":"HGNC:11100","symbol_at_source":"SMARCA4","accession":"P51532","function":"Histone modification read, TF","target":"histone","pmids":["17582821"],"complexes":"BAF, nBAF, npBAF, PBAF, SWI/SNF_Brg1(I), SWI/SNF_Brg1(II), SWI/SNF_Brm, SWI/SNF-like_EPAFa, WINAC, SWI/SNF-like EPAFB, bBAF, SWI/SNF BRM-BRG1, CREST-BRG1","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":753,"hub_weight":0.24953256425297482,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"ATPase involved in transcriptional activation and repression of select genes by chromatin remodeling (alteration of DNA-nucleosome topology). Component of SWI/SNF chromatin remodeling complexes that carry out key enzymatic activities, changing chromatin structure by altering DNA-histone contacts within a nucleosome in an ATP-dependent manner (PubMed:15075294, PubMed:29374058, PubMed:30339381, PubMed:32459350). Component of the CREST-BRG1 complex, a multiprotein complex that regulates promoter activation by orchestrating the calcium-dependent release of a repressor complex and the recruitment of an activator complex. In resting neurons, transcription of the c-FOS promoter is inhibited by SMARCA4-dependent recruitment of a phospho-RB1-HDAC repressor complex. Upon calcium influx, RB1 is dephosphorylated by calcineurin, which leads to release of the repressor complex. At the same time, there is increased recruitment of CREBBP to the promoter by a CREST-dependent mechanism, which leads to transcriptional activation. The CREST-BRG1 complex also binds to the NR2B promoter, and activity-dependent induction of NR2B expression involves the release of HDAC1 and recruitment of CREBBP (By similarity). Belongs to the neural progenitors-specific chromatin remodeling complex (npBAF complex) and the neuron-specific chromatin remodeling complex (nBAF complex). During neural development, a switch from a stem/progenitor to a postmitotic chromatin remodeling mechanism occurs as neurons exit the cell cycle and become committed to their adult state. The transition from proliferating neural stem/progenitor cells to postmitotic neurons requires a switch in subunit composition of the npBAF and nBAF complexes. As neural progenitors exit mitosis and differentiate into neurons, npBAF complexes which contain ACTL6A/BAF53A and PHF10/BAF45A, are exchanged for homologous alternative ACTL6B/BAF53B and DPF1/BAF45B or DPF3/BAF45C subunits in neuron-specific complexes (nBAF). The npBAF complex is essential for the self-renewal/proliferative capacity of the multipotent neural stem cells. The nBAF complex along with CREST plays a role regulating the activity of genes essential for dendrite growth. SMARCA4/BAF190A may promote neural stem cell self-renewal/proliferation by enhancing Notch-dependent proliferative signals, while concurrently making the neural stem cell insensitive to SHH-dependent differentiating cues (By similarity). Acts as a corepressor of ZEB1 to regulate E-cadherin transcription and is required for induction of epithelial-mesenchymal transition (EMT) by ZEB1 (PubMed:20418909). Binds via DLX1 to enhancers located in the intergenic region between DLX5 and DLX6 and this binding is stabilized by the long non-coding RNA (lncRNA) Evf2 (By similarity). Binds to RNA in a promiscuous manner (By similarity). In brown adipose tissue, involved in the regulation of thermogenic genes expression (By similarity)","source":"project UniProt records20261017/18"},{"partner":"SMARCA5","hgnc":"HGNC:11101","core":true,"core_annotation":{"hgnc":"HGNC:11101","symbol_at_source":"SMARCA5","accession":"O60264","function":"Chromatin remodeling","target":"chromatin","pmids":["10880450"],"complexes":"ACF, B-WICH, RSF, CHRAC, NoRC","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":384,"hub_weight":0.3394221166510653,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"ATPase that possesses intrinsic ATP-dependent nucleosome-remodeling activity (PubMed:12972596, PubMed:28801535). Catalytic subunit of ISWI chromatin-remodeling complexes, which form ordered nucleosome arrays on chromatin and facilitate access to DNA during DNA-templated processes such as DNA replication, transcription, and repair; this may require intact histone H4 tails (PubMed:10880450, PubMed:12198550, PubMed:12434153, PubMed:12972596, PubMed:23911928, PubMed:28801535). Within the ISWI chromatin-remodeling complexes, slides edge- and center-positioned histone octamers away from their original location on the DNA template (PubMed:28801535). Catalytic activity and histone octamer sliding propensity is regulated and determined by components of the ISWI chromatin-remodeling complexes (PubMed:28801535). The BAZ1A/ACF1-, BAZ1B/WSTF-, BAZ2A/TIP5- and BAZ2B-containing ISWI chromatin-remodeling complexes regulate the spacing of nucleosomes along the chromatin and have the ability to slide mononucleosomes to the center of a DNA template in an ATP-dependent manner (PubMed:14759371, PubMed:15543136, PubMed:28801535). The CECR2- and RSF1-containing ISWI chromatin-remodeling complexes do not have the ability to slide mononucleosomes to the center of a DNA template (PubMed:28801535). Binds to core histones together with RSF1, and is required for the assembly of regular nucleosome arrays by the RSF-5 ISWI chromatin-remodeling complex (PubMed:12972596). Involved in DNA replication and together with BAZ1A/ACF1 is required for replication of pericentric heterochromatin in S-phase (PubMed:12434153). Probably plays a role in repression of RNA polymerase I dependent transcription of the rDNA locus, through the recruitment of the SIN3/HDAC1 corepressor complex to the rDNA promoter (By similarity). Essential component of the WICH-5 ISWI chromatin-remodeling complex (also called the WICH complex), a chromatin-remodeling complex that mobilizes nucleosomes and reconfigures irregular chromatin to a regular nucleosomal array structure (PubMed:11980720, PubMed:15543136). The WICH-5 ISWI chromatin-remodeling complex regulates the transcription of various genes, has a role in RNA polymerase I transcription (By similarity). Within the B-WICH complex has a role in RNA polymerase III transcription (PubMed:16603771). Mediates the histone H2AX phosphorylation at 'Tyr-142', and is involved in the maintenance of chromatin structures during DNA replication processes (By similarity). Essential component of NoRC-5 ISWI chromatin-remodeling complex, a complex that mediates silencing of a fraction of rDNA by recruiting histone-modifying enzymes and DNA methyltransferases, leading to heterochromatin formation and transcriptional silencing (By similarity)","source":"project UniProt records20261017/18"},{"partner":"SMARCC1","hgnc":"HGNC:11104","core":true,"core_annotation":{"hgnc":"HGNC:11104","symbol_at_source":"SMARCC1","accession":"Q92922","function":"Chromatin remodeling cofactor","target":"chromatin","pmids":["10078207"],"complexes":"BAF, nBAF, npBAF, PBAF, SWI/SNF_Brg1(I), SWI/SNF_Brg1(II), SWI/SNF_Brm, SWI/SNF-like_EPAFa, WINAC, SWI/SNF-like EPAFB, bBAF, SWI/SNF BRM-BRG1","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":341,"hub_weight":0.35759926992607577,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Involved in transcriptional activation and repression of select genes by chromatin remodeling (alteration of DNA-nucleosome topology). Component of SWI/SNF chromatin remodeling complexes that carry out key enzymatic activities, changing chromatin structure by altering DNA-histone contacts within a nucleosome in an ATP-dependent manner. May stimulate the ATPase activity of the catalytic subunit of the complex (PubMed:10078207, PubMed:29374058). Belongs to the neural progenitors-specific chromatin remodeling complex (npBAF complex) and the neuron-specific chromatin remodeling complex (nBAF complex). During neural development a switch from a stem/progenitor to a postmitotic chromatin remodeling mechanism occurs as neurons exit the cell cycle and become committed to their adult state. The transition from proliferating neural stem/progenitor cells to postmitotic neurons requires a switch in subunit composition of the npBAF and nBAF complexes. As neural progenitors exit mitosis and differentiate into neurons, npBAF complexes which contain ACTL6A/BAF53A and PHF10/BAF45A, are exchanged for homologous alternative ACTL6B/BAF53B and DPF1/BAF45B or DPF3/BAF45C subunits in neuron-specific complexes (nBAF). The npBAF complex is essential for the self-renewal/proliferative capacity of the multipotent neural stem cells. The nBAF complex along with CREST plays a role regulating the activity of genes essential for dendrite growth (By similarity)","source":"project UniProt records20261017/18"},{"partner":"SMARCC2","hgnc":"HGNC:11105","core":true,"core_annotation":{"hgnc":"HGNC:11105","symbol_at_source":"SMARCC2","accession":"Q8TAQ2","function":"Chromatin remodeling cofactor","target":"chromatin","pmids":["10078207"],"complexes":"BAF, nBAF, npBAF, PBAF, SWI/SNF_Brg1(I), SWI/SNF_Brg1(II), SWI/SNF_Brm, SWI/SNF-like_EPAFa, WINAC, SWI/SNF-like EPAFB, bBAF, SWI/SNF BRM-BRG1","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":334,"hub_weight":0.36084391824351614,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Involved in transcriptional activation and repression of select genes by chromatin remodeling (alteration of DNA-nucleosome topology). Component of SWI/SNF chromatin remodeling complexes that carry out key enzymatic activities, changing chromatin structure by altering DNA-histone contacts within a nucleosome in an ATP-dependent manner (PubMed:11018012). Can stimulate the ATPase activity of the catalytic subunit of these complexes (PubMed:10078207). May be required for CoREST dependent repression of neuronal specific gene promoters in non-neuronal cells (PubMed:12192000). Belongs to the neural progenitors-specific chromatin remodeling complex (npBAF complex) and the neuron-specific chromatin remodeling complex (nBAF complex). During neural development a switch from a stem/progenitor to a postmitotic chromatin remodeling mechanism occurs as neurons exit the cell cycle and become committed to their adult state. The transition from proliferating neural stem/progenitor cells to postmitotic neurons requires a switch in subunit composition of the npBAF and nBAF complexes. As neural progenitors exit mitosis and differentiate into neurons, npBAF complexes which contain ACTL6A/BAF53A and PHF10/BAF45A, are exchanged for homologous alternative ACTL6B/BAF53B and DPF1/BAF45B or DPF3/BAF45C subunits in neuron-specific complexes (nBAF). The npBAF complex is essential for the self-renewal/proliferative capacity of the multipotent neural stem cells. The nBAF complex along with CREST plays a role regulating the activity of genes essential for dendrite growth (By similarity). Critical regulator of myeloid differentiation, controlling granulocytopoiesis and the expression of genes involved in neutrophil granule formation (By similarity)","source":"project UniProt records20261017/18"},{"partner":"SSRP1","hgnc":"HGNC:11327","core":true,"core_annotation":{"hgnc":"HGNC:11327","symbol_at_source":"SSRP1","accession":"Q08945","function":"Chromatin remodeling","target":"histone","pmids":["12934006"],"complexes":"FACT","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":653,"hub_weight":0.2666903735313325,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Nucleus, nucleolus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Component of the FACT complex, a general chromatin factor that acts to reorganize nucleosomes. The FACT complex is involved in multiple processes that require DNA as a template such as mRNA elongation, DNA replication and DNA repair. During transcription elongation the FACT complex acts as a histone chaperone that both destabilizes and restores nucleosomal structure. It facilitates the passage of RNA polymerase II and transcription by promoting the dissociation of one histone H2A-H2B dimer from the nucleosome, then subsequently promotes the reestablishment of the nucleosome following the passage of RNA polymerase II. The FACT complex is probably also involved in phosphorylation of 'Ser-392' of p53/TP53 via its association with CK2 (casein kinase II). Binds specifically to double-stranded DNA and at low levels to DNA modified by the antitumor agent cisplatin. May potentiate cisplatin-induced cell death by blocking replication and repair of modified DNA. Also acts as a transcriptional coactivator for p63/TP63","source":"project UniProt records20261017/18"},{"partner":"SUPT16H","hgnc":"HGNC:11465","core":true,"core_annotation":{"hgnc":"HGNC:11465","symbol_at_source":"SUPT16H","accession":"Q9Y5B9","function":"Histone modification read","target":"histone","pmids":["12934006"],"complexes":"WINAC, FACT","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":416,"hub_weight":0.3275608910402092,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Component of the FACT complex, a general chromatin factor that acts to reorganize nucleosomes. The FACT complex is involved in multiple processes that require DNA as a template such as mRNA elongation, DNA replication and DNA repair. During transcription elongation the FACT complex acts as a histone chaperone that both destabilizes and restores nucleosomal structure. It facilitates the passage of RNA polymerase II and transcription by promoting the dissociation of one histone H2A-H2B dimer from the nucleosome, then subsequently promotes the reestablishment of the nucleosome following the passage of RNA polymerase II. The FACT complex is probably also involved in phosphorylation of 'Ser-392' of p53/TP53 via its association with CK2 (casein kinase II)","source":"project UniProt records20261017/18"},{"partner":"SUPT6H","hgnc":"HGNC:11470","core":true,"core_annotation":{"hgnc":"HGNC:11470","symbol_at_source":"SUPT6H","accession":"Q7KZ85","function":"Histone modification erase cofactor","target":"histone","pmids":["23503590"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":188,"hub_weight":0.45834924851410563,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone H3-H4 chaperone that plays a key role in the regulation of transcription elongation and mRNA processing. Enhances the transcription elongation by RNA polymerase II (RNAPII) and is also required for the efficient activation of transcriptional elongation by the HIV-1 nuclear transcriptional activator, Tat. Besides chaperoning histones in transcription, acts to transport and splice mRNA by forming a complex with IWS1 and the C-terminal domain (CTD) of the RNAPII subunit RPB1 (POLR2A). The SUPT6H:IWS1:CTD complex recruits mRNA export factors (ALYREF/THOC4, EXOSC10) as well as histone modifying enzymes (such as SETD2), to ensure proper mRNA splicing, efficient mRNA export and elongation-coupled H3K36 methylation, a signature chromatin mark of active transcription. SUPT6H via its association with SETD1A, regulates both class-switch recombination and somatic hypermutation through formation of H3K4me3 epigenetic marks on activation-induced cytidine deaminase (AICDA) target loci. Promotes the activation of the myogenic gene program by entailing erasure of the repressive H3K27me3 epigenetic mark through stabilization of the chromatin interaction of the H3K27 demethylase KDM6A","source":"project UniProt records20261017/18"},{"partner":"TAF1","hgnc":"HGNC:11535","core":true,"core_annotation":{"hgnc":"HGNC:11535","symbol_at_source":"TAF1","accession":"P21675","function":"Histone modification write","target":"histone","pmids":["11295558"],"complexes":"CHD8, MLL2/3, MLL4/WBP7","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":186,"hub_weight":0.4602873089491617,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"The TFIID basal transcription factor complex plays a major role in the initiation of RNA polymerase II (Pol II)-dependent transcription (PubMed:33795473). TFIID recognizes and binds promoters with or without a TATA box via its subunit TBP, a TATA-box-binding protein, and promotes assembly of the pre-initiation complex (PIC) (PubMed:33795473). The TFIID complex consists of TBP and TBP-associated factors (TAFs), including TAF1, TAF2, TAF3, TAF4, TAF5, TAF6, TAF7, TAF8, TAF9, TAF10, TAF11, TAF12 and TAF13 (PubMed:33795473). TAF1 is the largest component and core scaffold of the TFIID complex, involved in nucleating complex assembly (PubMed:25412659, PubMed:27007846, PubMed:33795473). TAF1 forms a promoter DNA binding subcomplex of TFIID, together with TAF7 and TAF2 (PubMed:33795473). Contains novel N- and C-terminal Ser/Thr kinase domains which can autophosphorylate or transphosphorylate other transcription factors (PubMed:25412659, PubMed:8625415). Phosphorylates TP53 on 'Thr-55' which leads to MDM2-mediated degradation of TP53 (PubMed:25412659). Phosphorylates GTF2A1 and GTF2F1 on Ser residues (PubMed:25412659). Possesses DNA-binding activity (PubMed:25412659). Essential for progression of the G1 phase of the cell cycle (PubMed:11278496, PubMed:15053879, PubMed:2038334, PubMed:8450888, PubMed:8625415, PubMed:9660973, PubMed:9858607). Exhibits histone acetyltransferase activity towards histones H3 and H4 (PubMed:15870300)","source":"project UniProt records20261017/18"},{"partner":"TRIM24","hgnc":"HGNC:11812","core":true,"core_annotation":{"hgnc":"HGNC:11812","symbol_at_source":"TRIM24","accession":"O15164","function":"Histone modification read","target":"histone","pmids":["22464331"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":342,"hub_weight":0.35714285714285715,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Cytoplasm; Mitochondrion","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Transcriptional coactivator that interacts with numerous nuclear receptors and coactivators and modulates the transcription of target genes. Interacts with chromatin depending on histone H3 modifications, having the highest affinity for histone H3 that is both unmodified at 'Lys-4' (H3K4me0) and acetylated at 'Lys-23' (H3K23ac). Has E3 protein-ubiquitin ligase activity. During the DNA damage response, participates in an autoregulatory feedback loop with TP53. Early in response to DNA damage, ATM kinase phosphorylates TRIM24 leading to its ubiquitination and degradation. After sufficient DNA repair has occurred, TP53 activates TRIM24 transcription, ultimately leading to TRIM24-mediated TP53 ubiquitination and degradation (PubMed:24820418). Plays a role in the regulation of cell proliferation and apoptosis, at least in part via its effects on p53/TP53 levels. Up-regulates ligand-dependent transcription activation by AR, GCR/NR3C1, thyroid hormone receptor (TR) and ESR1. Modulates transcription activation by retinoic acid (RA) receptors, including RARA. Plays a role in regulating retinoic acid-dependent proliferation of hepatocytes (By similarity). Also participates in innate immunity by mediating the specific 'Lys-63'-linked ubiquitination of TRAF3 leading to activation of downstream signal transduction of the type I IFN pathway (PubMed:32324863). Additionally, negatively regulates NLRP3/CASP1/IL-1beta-mediated pyroptosis and cell migration probably by ubiquitinating NLRP3 (PubMed:33724611)","source":"project UniProt records20261017/18"},{"partner":"TOP2A","hgnc":"HGNC:11989","core":true,"core_annotation":{"hgnc":"HGNC:11989","symbol_at_source":"TOP2A","accession":"P11388","function":"Chromatin remodeling","target":"DNA","pmids":["11062478"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":461,"hub_weight":0.3128056235449272,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Cytoplasm; Nucleus, nucleoplasm; Nucleus; Nucleus, nucleolus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Key decatenating enzyme that alters DNA topology by binding to two double-stranded DNA molecules, generating a double-stranded break in one of the strands, passing the intact strand through the broken strand, and religating the broken strand (PubMed:17567603, PubMed:18790802, PubMed:22013166, PubMed:22323612, PubMed:27754753). May play a role in regulating the period length of BMAL1 transcriptional oscillation (By similarity)","source":"project UniProt records20261017/18"},{"partner":"TOP2B","hgnc":"HGNC:11990","core":true,"core_annotation":{"hgnc":"HGNC:11990","symbol_at_source":"TOP2B","accession":"Q02880","function":"Chromatin remodeling","target":"chromatin","pmids":["11062478"],"complexes":"WINAC","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":250,"hub_weight":0.408248290463863,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus, nucleolus; Nucleus, nucleoplasm; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Key decatenating enzyme that alters DNA topology by binding to two double-stranded DNA molecules, generating a double-stranded break in one of the strands, passing the intact strand through the broken strand, and religating the broken strand. Plays a role in B-cell differentiation","source":"project UniProt records20261017/18"},{"partner":"UHRF1","hgnc":"HGNC:12556","core":true,"core_annotation":{"hgnc":"HGNC:12556","symbol_at_source":"UHRF1","accession":"Q96T88","function":"Histone modification read, Histone modification write cofactor","target":"histone, DNA","pmids":["17967883"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":194,"hub_weight":0.45267873021259264,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"E3 ubiquitin-protein ligase that acts as a key epigenetic regulator by bridging DNA methylation and chromatin modification (PubMed:10646863, PubMed:15009091, PubMed:19056828, PubMed:23022729, PubMed:24013172, PubMed:27595565, PubMed:30104358, PubMed:30392929, PubMed:30392931, PubMed:39607687). Plays a key role in DNA methylation inheritance by promoting recruitment of DNMT1 to hemimethylated DNA and ensure faithful propagation of the DNA methylation patterns through DNA replication (PubMed:23022729, PubMed:24013172, PubMed:27595565, PubMed:30104358, PubMed:30392929, PubMed:30392931, PubMed:39607687). Acts both as a histone reader and writer: specifically recognizes and binds (1) hemimethylated DNA at replication forks and (2) histone H3 trimethylated at 'Lys-9' and unmethylated at 'Arg-2' (H3K9me3 and H3R2me0, respectively), thereby activating its E3 ubiquitin-protein ligase activity (PubMed:15361834, PubMed:17673620, PubMed:17967883, PubMed:18772889, PubMed:21745816, PubMed:21777816, PubMed:22100450, PubMed:22837395, PubMed:23022729, PubMed:27595565, PubMed:30104358). UHRF1 then mediates histone H3 'Lys-18' monoubiquitination (H3K18ub), a docking site for DNMT1, leading to DNMT1 recruitment and replication-coupled DNA methylation maintenance (PubMed:27595565). Also mediates histone H3 'Lys-14' and 'Lys-23' ubiquitination (H3K14ub and H3K23ub) at lower level (PubMed:24013172, PubMed:27595565). Histone ubiquitin ligase activity also stimulates the methyltransferase activity of SUV39H1 and/or SUV39H2, promoting accumulation of H3K9me3 histone mark to reinformce heterochromatin state (PubMed:39631394). Enriched in pericentric heterochromatin where it recruits different chromatin modifiers required for this chromatin replication. Also localizes to euchromatic regions where it negatively regulates transcription possibly by impacting DNA methylation and histone modifications (PubMed:21777816). Plays a role in DNA repair by cooperating with UHRF2 to ensure recruitment of FANCD2 to interstrand cross-links (ICLs) leading to FANCD2 activation (PubMed:30335751). Also ubiquitinates non-histone proteins, such as histone H3, KIF11 and PML (PubMed:22945642, PubMed:37728657). Acts as a critical player of proper spindle architecture by catalyzing the 'Lys-63'-linked ubiquitination of KIF11, thereby controlling KIF11 localization on the spindle (PubMed:37728657)","source":"project UniProt records20261017/18"},{"partner":"VRK1","hgnc":"HGNC:12718","core":true,"core_annotation":{"hgnc":"HGNC:12718","symbol_at_source":"VRK1","accession":"Q99986","function":"Histone modification write","target":"histone","pmids":["22194607"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":240,"hub_weight":0.41522739926869984,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Cytoplasm; Nucleus, Cajal body","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Serine/threonine kinase involved in the regulation of key cellular processes including the cell cycle, nuclear condensation, transcription regulation, and DNA damage response (PubMed:14645249, PubMed:18617507, PubMed:19103756, PubMed:33076429). Controls chromatin organization and remodeling by mediating phosphorylation of histone H3 on 'Thr-4' and histone H2AX (H2aXT4ph) (PubMed:31527692, PubMed:37179361). It also phosphorylates KAT5 in response to DNA damage, promoting KAT5 association with chromatin and histone acetyltransferase activity (PubMed:33076429). Is involved in the regulation of cell cycle progression of neural progenitors, and is required for proper cortical neuronal migration (By similarity). Is involved in neurite elongation and branching in motor neurons, and has an essential role in Cajal bodies assembly, acting through COIL phosphorylation and the control of coilin degradation (PubMed:21920476, PubMed:31090908, PubMed:31527692). Involved in Golgi disassembly during the cell cycle: following phosphorylation by PLK3 during mitosis, it is required to induce Golgi fragmentation (PubMed:19103756). Phosphorylates BANF1: disrupts its ability to bind DNA, reduces its binding to LEM domain-containing proteins and causes its relocalization from the nucleus to the cytoplasm (PubMed:16495336). Phosphorylates TP53BP1 and p53/TP53 on 'Thr-18', preventing the interaction between p53/TP53 and MDM2 (PubMed:10951572, PubMed:31527692). Phosphorylates ATF2 which activates its transcriptional activity (PubMed:15105425). Phosphorylates JUN (PubMed:31527692)","source":"project UniProt records20261017/18"},{"partner":"NSD2","hgnc":"HGNC:12766","core":true,"core_annotation":{"hgnc":"HGNC:12766","symbol_at_source":"WHSC1","accession":"O96028","function":"Histone modification write","target":"histone","pmids":["18172012"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":231,"hub_weight":0.4218245406095978,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome; Nucleus; Chromosome; Nucleus; Cytoplasm; Nucleus, nucleolus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone methyltransferase which specifically dimethylates nucleosomal histone H3 at 'Lys-36' (H3K36me2) (PubMed:19808676, PubMed:22099308, PubMed:27571355, PubMed:29728617, PubMed:33941880). Also monomethylates nucleosomal histone H3 at 'Lys-36' (H3K36me) in vitro (PubMed:22099308). Does not trimethylate nucleosomal histone H3 at 'Lys-36' (H3K36me3) (PubMed:22099308). However, specifically trimethylates histone H3 at 'Lys-36' (H3K36me3) at euchromatic regions in embryonic stem (ES) cells (By similarity). By methylating histone H3 at 'Lys-36', involved in the regulation of gene transcription during various biological processes (PubMed:16115125, PubMed:22099308, PubMed:29728617). In ES cells, associates with developmental transcription factors such as SALL1 and represses inappropriate gene transcription mediated by histone deacetylation (By similarity). During heart development, associates with transcription factor NKX2-5 to repress transcription of NKX2-5 target genes (By similarity). Plays an essential role in adipogenesis, by regulating expression of genes involved in pre-adipocyte differentiation (PubMed:29728617). During T-cell receptor (TCR) and CD28-mediated T-cell activation, promotes the transcription of transcription factor BCL6 which is required for follicular helper T (Tfh) cell differentiation (By similarity). During B-cell development, required for the generation of the B1 lineage (By similarity). During B2 cell activation, may contribute to the control of isotype class switch recombination (CRS), splenic germinal center formation, and the humoral immune response (By similarity). Plays a role in class switch recombination of the immunoglobulin heavy chain (IgH) locus during B-cell activation (By similarity). By regulating the methylation of histone H3 at 'Lys-36' and histone H4 at 'Lys-20' at the IgH locus, involved in TP53BP1 recruitment to the IgH switch region and promotes the transcription of IgA (By similarity)\nHistone methyltransferase which specifically dimethylates nucleosomal histone H3 at 'Lys-36' (H3K36me2)\nHistone methyltransferase which specifically dimethylates nucleosomal histone H3 at 'Lys-36' (H3K36me2) (PubMed:22099308). Methylation of histone H3 at 'Lys-27' is controversial (PubMed:18172012, PubMed:22099308). Mono-, di- or tri-methylates histone H3 at 'Lys-27' (H3K27me, H3K27me2 and H3K27me3) (PubMed:18172012). Does not methylate histone H3 at 'Lys-27' (PubMed:22099308). May act as a transcription regulator that binds DNA and suppresses IL5 transcription through HDAC recruitment (PubMed:11152655, PubMed:18172012)","source":"project UniProt records20261017/18"},{"partner":"NSD3","hgnc":"HGNC:12767","core":true,"core_annotation":{"hgnc":"HGNC:12767","symbol_at_source":"WHSC1L1","accession":"Q9BZ95","function":"Chromatin remodeling cofactor, TF","target":"histone","pmids":["16682010"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":106,"hub_weight":0.5661385170722979,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone methyltransferase. Preferentially dimethylates 'Lys-4' and 'Lys-27' of histone H3 forming H3K4me2 and H3K27me2. H3 'Lys-4' methylation represents a specific tag for epigenetic transcriptional activation, while 'Lys-27' is a mark for transcriptional repression","source":"project UniProt records20261017/18"},{"partner":"YY1","hgnc":"HGNC:12856","core":true,"core_annotation":{"hgnc":"HGNC:12856","symbol_at_source":"YY1","accession":"P25490","function":"Chromatin remodeling cofactor, TF","target":"DNA","pmids":["11445535"],"complexes":"Ino80","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":409,"hub_weight":0.3300491809922248,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus matrix","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Multifunctional transcription factor that exhibits positive and negative control on a large number of cellular and viral genes by binding to sites overlapping the transcription start site (PubMed:15329343, PubMed:17721549, PubMed:24326773, PubMed:25787250). Binds to the consensus sequence 5'-CCGCCATNTT-3'; some genes have been shown to contain a longer binding motif allowing enhanced binding; the initial CG dinucleotide can be methylated greatly reducing the binding affinity (PubMed:15329343, PubMed:17721549, PubMed:24326773, PubMed:25787250). The effect on transcription regulation is depending upon the context in which it binds and diverse mechanisms of action include direct activation or repression, indirect activation or repression via cofactor recruitment, or activation or repression by disruption of binding sites or conformational DNA changes (PubMed:15329343, PubMed:17721549, PubMed:24326773, PubMed:25787250). Its activity is regulated by transcription factors and cytoplasmic proteins that have been shown to abrogate or completely inhibit YY1-mediated activation or repression (PubMed:15329343, PubMed:17721549, PubMed:24326773, PubMed:25787250). For example, it acts as a repressor in absence of adenovirus E1A protein but as an activator in its presence (PubMed:1655281). Acts synergistically with the SMAD1 and SMAD4 in bone morphogenetic protein (BMP)-mediated cardiac-specific gene expression (PubMed:15329343). Binds to SMAD binding elements (SBEs) (5'-GTCT/AGAC-3') within BMP response element (BMPRE) of cardiac activating regions (PubMed:15329343). May play an important role in development and differentiation. Proposed to recruit the PRC2/EED-EZH2 complex to target genes that are transcriptional repressed (PubMed:11158321). Involved in DNA repair (PubMed:18026119, PubMed:28575647). In vitro, binds to DNA recombination intermediate structures (Holliday junctions). Plays a role in regulating enhancer activation (PubMed:28575647). Recruits the PR-DUB complex to specific gene-regulatory regions (PubMed:20805357)\nProposed core component of the chromatin remodeling INO80 complex which is involved in transcriptional regulation, DNA replication and probably DNA repair; proposed to target the INO80 complex to YY1-responsive elements","source":"project UniProt records20261017/18"},{"partner":"ZMYM3","hgnc":"HGNC:13054","core":true,"core_annotation":{"hgnc":"HGNC:13054","symbol_at_source":"ZMYM3","accession":"Q14202","function":"Histone modification erase cofactor","target":"DNA","pmids":["12493763"],"complexes":"BHC","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":127,"hub_weight":0.5314940034527339,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Required for regulation of cell morphology and cytoskeletal organization","source":"project UniProt records20261017/18"},{"partner":"ZNF711","hgnc":"HGNC:13128","core":true,"core_annotation":{"hgnc":"HGNC:13128","symbol_at_source":"ZNF711","accession":"Q9Y462","function":"Histone modification erase cofactor","target":"histone","pmids":["20346720"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":35,"hub_weight":0.7669649888473704,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Transcription regulator required for brain development (PubMed:20346720). Probably acts as a transcription factor that binds to the promoter of target genes and recruits PHF8 histone demethylase, leading to activated expression of genes involved in neuron development, such as KDM5C (PubMed:20346720, PubMed:31691806). May compete with transcription factor ARX for activation of expression of KDM5C (PubMed:31691806)","source":"project UniProt records20261017/18"},{"partner":"KDM2A","hgnc":"HGNC:13606","core":true,"core_annotation":{"hgnc":"HGNC:13606","symbol_at_source":"KDM2A","accession":"Q9Y2K7","function":"Histone modification erase","target":"histone","pmids":["20417597"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":84,"hub_weight":0.6108472217815262,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus, nucleoplasm; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone demethylase that specifically demethylates 'Lys-36' of histone H3, thereby playing a central role in histone code. Preferentially demethylates dimethylated H3 'Lys-36' residue while it has weak or no activity for mono- and tri-methylated H3 'Lys-36'. May also recognize and bind to some phosphorylated proteins and promote their ubiquitination and degradation. Required to maintain the heterochromatic state. Associates with centromeres and represses transcription of small non-coding RNAs that are encoded by the clusters of satellite repeats at the centromere. Required to sustain centromeric integrity and genomic stability, particularly during mitosis. Regulates circadian gene expression by repressing the transcriptional activator activity of CLOCK-BMAL1 heterodimer and RORA in a catalytically-independent manner (PubMed:26037310)","source":"project UniProt records20261017/18"},{"partner":"KDM2B","hgnc":"HGNC:13610","core":true,"core_annotation":{"hgnc":"HGNC:13610","symbol_at_source":"KDM2B","accession":"Q8NHM5","function":"Histone modification erase","target":"histone","pmids":["17994099"],"complexes":"BCOR","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":158,"hub_weight":0.4902903378454601,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus, nucleolus; Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone demethylase that demethylates 'Lys-4' and 'Lys-36' of histone H3, thereby playing a central role in histone code (PubMed:16362057, PubMed:17994099, PubMed:26237645). Preferentially demethylates trimethylated H3 'Lys-4' and dimethylated H3 'Lys-36' residue while it has weak or no activity for mono- and tri-methylated H3 'Lys-36' (PubMed:16362057, PubMed:17994099, PubMed:26237645). Preferentially binds the transcribed region of ribosomal RNA and represses the transcription of ribosomal RNA genes which inhibits cell growth and proliferation (PubMed:16362057, PubMed:17994099). May also serve as a substrate-recognition component of the SCF (SKP1-CUL1-F-box protein)-type E3 ubiquitin ligase complex (Probable)","source":"project UniProt records20261017/18"},{"partner":"NSD1","hgnc":"HGNC:14234","core":true,"core_annotation":{"hgnc":"HGNC:14234","symbol_at_source":"NSD1","accession":"Q96L73","function":"Histone modification write","target":"histone","pmids":["21196496"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":114,"hub_weight":0.5521576303742327,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone methyltransferase that dimethylates Lys-36 of histone H3 (H3K36me2). Transcriptional intermediary factor capable of both negatively or positively influencing transcription, depending on the cellular context","source":"project UniProt records20261017/18"},{"partner":"BRPF1","hgnc":"HGNC:14255","core":true,"core_annotation":{"hgnc":"HGNC:14255","symbol_at_source":"BRPF1","accession":"P55201","function":"Histone modification read","target":"histone","pmids":["20400950"],"complexes":"MOZ/MORF","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":71,"hub_weight":0.6428243465332251,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Scaffold subunit of various histone acetyltransferase (HAT) complexes, such as the MOZ/MORF and HBO1 complexes, which have a histone H3 acetyltransferase activity (PubMed:16387653, PubMed:24065767, PubMed:27939640). Plays a key role in HBO1 complex by directing KAT7/HBO1 specificity towards histone H3 'Lys-14' acetylation (H3K14ac) (PubMed:24065767). Some HAT complexes preferentially mediate histone H3 'Lys-23' (H3K23ac) acetylation (PubMed:27939640). Positively regulates the transcription of RUNX1 and RUNX2 (PubMed:18794358)","source":"project UniProt records20261017/18"},{"partner":"BRD7","hgnc":"HGNC:14310","core":true,"core_annotation":{"hgnc":"HGNC:14310","symbol_at_source":"BRD7","accession":"Q9NPI1","function":"Histone modification read","target":"histone","pmids":["17498659"],"complexes":"SWI/SNF BRM-BRG1","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":512,"hub_weight":0.2982749931359468,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Acts both as coactivator and as corepressor. May play a role in chromatin remodeling. Activator of the Wnt signaling pathway in a DVL1-dependent manner by negatively regulating the GSK3B phosphotransferase activity. Induces dephosphorylation of GSK3B at 'Tyr-216'. Down-regulates TRIM24-mediated activation of transcriptional activation by AR (By similarity). Transcriptional corepressor that down-regulates the expression of target genes. Binds to target promoters, leading to increased histone H3 acetylation at 'Lys-9' (H3K9ac). Binds to the ESR1 promoter. Recruits BRCA1 and POU2F1 to the ESR1 promoter. Coactivator for TP53-mediated activation of transcription of a set of target genes. Required for TP53-mediated cell-cycle arrest in response to oncogene activation. Promotes acetylation of TP53 at 'Lys-382', and thereby promotes efficient recruitment of TP53 to target promoters. Inhibits cell cycle progression from G1 to S phase","source":"project UniProt records20261017/18"},{"partner":"PRPF31","hgnc":"HGNC:15446","core":true,"core_annotation":{"hgnc":"HGNC:15446","symbol_at_source":"PRPF31","accession":"Q8WWY3","function":"Histone modification write cofactor, Histone modification write cofactor","target":"histone","pmids":[],"complexes":"CHD8, MLL2/3, MLL4/WBP7","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":320,"hub_weight":0.36760731104690386,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Nucleus speckle; Nucleus, Cajal body","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Involved in pre-mRNA splicing as component of the spliceosome (PubMed:11867543, PubMed:20118938, PubMed:28781166). Required for the assembly of the U4/U5/U6 tri-snRNP complex, one of the building blocks of the spliceosome (PubMed:11867543)","source":"project UniProt records20261017/18"},{"partner":"ARID4B","hgnc":"HGNC:15550","core":true,"core_annotation":{"hgnc":"HGNC:15550","symbol_at_source":"ARID4B","accession":"Q4LE39","function":"Histone modification write cofactor","target":"DNA","pmids":["15640446"],"complexes":"mSin3A","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":178,"hub_weight":0.468292905790847,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Acts as a transcriptional repressor (PubMed:12724404). May function in the assembly and/or enzymatic activity of the Sin3A corepressor complex or in mediating interactions between the complex and other regulatory complexes (PubMed:12724404). Plays a role in the regulation of epigenetic modifications at the PWS/AS imprinting center near the SNRPN promoter, where it might function as part of a complex with RB1 and ARID4A. Involved in spermatogenesis, together with ARID4A, where it functions as a transcriptional coactivator for AR (androgen receptor) and enhances expression of genes required for sperm maturation. Regulates expression of the tight junction protein CLDN3 in the testis, which is important for integrity of the blood-testis barrier. Plays a role in myeloid homeostasis where it regulates the histone methylation state of bone marrow cells and expression of various genes involved in hematopoiesis. May function as a leukemia suppressor (By similarity)","source":"project UniProt records20261017/18"},{"partner":"PHIP","hgnc":"HGNC:15673","core":true,"core_annotation":{"hgnc":"HGNC:15673","symbol_at_source":"PHIP","accession":"Q8WWQ0","function":"Histone modification read","target":"histone","pmids":["22464331"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":267,"hub_weight":0.3971507353947688,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Probable regulator of the insulin and insulin-like growth factor signaling pathways. Stimulates cell proliferation through regulation of cyclin transcription and has an anti-apoptotic activity through AKT1 phosphorylation and activation. Plays a role in the regulation of cell morphology and cytoskeletal organization","source":"project UniProt records20261017/18"},{"partner":"KMT2B","hgnc":"HGNC:15840","core":true,"core_annotation":{"hgnc":"HGNC:15840","symbol_at_source":"KMT2B","accession":"Q9UMN6","function":"Histone modification write","target":"histone","pmids":["17707229"],"complexes":"Menin-associated_HMT, MLL2/3, COMPASS-like MLL3,4","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":120,"hub_weight":0.5423261445466404,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone methyltransferase that catalyzes methyl group transfer from S-adenosyl-L-methionine to the epsilon-amino group of 'Lys-4' of histone H3 (H3K4) via a non-processive mechanism. Part of chromatin remodeling machinery predominantly forms H3K4me1 and H3K4me2 methylation marks at active chromatin sites where transcription and DNA repair take place (PubMed:17707229, PubMed:25561738). Likely plays a redundant role with KMT2C in enriching H3K4me1 marks on primed and active enhancer elements (PubMed:24081332). Plays a central role in beta-globin locus transcription regulation by being recruited by NFE2 (PubMed:17707229). Plays an important role in controlling bulk H3K4me during oocyte growth and preimplantation development (By similarity). Required during the transcriptionally active period of oocyte growth for the establishment and/or maintenance of bulk H3K4 trimethylation (H3K4me3), global transcriptional silencing that preceeds resumption of meiosis, oocyte survival and normal zygotic genome activation (By similarity)","source":"project UniProt records20261017/18"},{"partner":"CBX8","hgnc":"HGNC:15962","core":true,"core_annotation":{"hgnc":"HGNC:15962","symbol_at_source":"CBX8","accession":"Q9HC52","function":"Histone modification read","target":"histone","pmids":["21047797"],"complexes":"PRC1","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":231,"hub_weight":0.4218245406095978,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Component of a Polycomb group (PcG) multiprotein PRC1-like complex, a complex class required to maintain the transcriptionally repressive state of many genes, including Hox genes, throughout development. PcG PRC1 complex acts via chromatin remodeling and modification of histones; it mediates monoubiquitination of histone H2A 'Lys-119', rendering chromatin heritably changed in its expressibility","source":"project UniProt records20261017/18"},{"partner":"ANP32E","hgnc":"HGNC:16673","core":true,"core_annotation":{"hgnc":"HGNC:16673","symbol_at_source":"ANP32E","accession":"Q9BTT0","function":"Histone chaperone, Histone modification read","target":"histone","pmids":["24463511"],"complexes":"SWR","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":112,"hub_weight":0.5555555555555556,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Cytoplasm; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone chaperone that specifically mediates the genome-wide removal of histone H2A.Z/H2AZ1 from the nucleosome: removes H2A.Z/H2AZ1 from its normal sites of deposition, especially from enhancer and insulator regions. Not involved in deposition of H2A.Z/H2AZ1 in the nucleosome. May stabilize the evicted H2A.Z/H2AZ1-H2B dimer, thus shifting the equilibrium towards dissociation and the off-chromatin state (PubMed:24463511). Inhibits activity of protein phosphatase 2A (PP2A). Does not inhibit protein phosphatase 1. May play a role in cerebellar development and synaptogenesis","source":"project UniProt records20261017/18"},{"partner":"CDC73","hgnc":"HGNC:16783","core":true,"core_annotation":{"hgnc":"HGNC:16783","symbol_at_source":"CDC73","accession":"Q6P1J9","function":"Histone modification write cofactor","target":"histone","pmids":[],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":304,"hub_weight":0.37582301400141443,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Tumor suppressor probably involved in transcriptional and post-transcriptional control pathways. May be involved in cell cycle progression through the regulation of cyclin D1/PRAD1 expression. Component of the PAF1 complex (PAF1C) which has multiple functions during transcription by RNA polymerase II and is implicated in regulation of development and maintenance of embryonic stem cell pluripotency. PAF1C associates with RNA polymerase II through interaction with POLR2A CTD non-phosphorylated and 'Ser-2'- and 'Ser-5'-phosphorylated forms and is involved in transcriptional elongation, acting both independently and synergistically with TCEA1 and in cooperation with the DSIF complex and HTATSF1. PAF1C is required for transcription of Hox and Wnt target genes. PAF1C is involved in hematopoiesis and stimulates transcriptional activity of KMT2A/MLL1; it promotes leukemogenesis through association with KMT2A/MLL1-rearranged oncoproteins, such as KMT2A/MLL1-MLLT3/AF9 and KMT2A/MLL1-MLLT1/ENL. PAF1C is involved in histone modifications such as ubiquitination of histone H2B and methylation on histone H3 'Lys-4' (H3K4me3). PAF1C recruits the RNF20/40 E3 ubiquitin-protein ligase complex and the E2 enzyme UBE2A or UBE2B to chromatin which mediate monoubiquitination of 'Lys-120' of histone H2B (H2BK120ub1); UB2A/B-mediated H2B ubiquitination is proposed to be coupled to transcription. PAF1C is involved in mRNA 3' end formation probably through association with cleavage and poly(A) factors. In case of infection by influenza A strain H3N2, PAF1C associates with viral NS1 protein, thereby regulating gene transcription. Connects PAF1C with the cleavage and polyadenylation specificity factor (CPSF) complex and the cleavage stimulation factor (CSTF) complex, and with Wnt signaling. Involved in polyadenylation of mRNA precursors","source":"project UniProt records20261017/18"},{"partner":"CTR9","hgnc":"HGNC:16850","core":true,"core_annotation":{"hgnc":"HGNC:16850","symbol_at_source":"CTR9","accession":"Q6PD62","function":"Histone modification cofactor","target":"histone","pmids":["24036311"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":209,"hub_weight":0.4393747751637468,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus speckle","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Component of the PAF1 complex (PAF1C) which has multiple functions during transcription by RNA polymerase II and is implicated in regulation of development and maintenance of embryonic stem cell pluripotency. PAF1C associates with RNA polymerase II through interaction with POLR2A CTD non-phosphorylated and 'Ser-2'- and 'Ser-5'-phosphorylated forms and is involved in transcriptional elongation, acting both independently and synergistically with TCEA1 and in cooperation with the DSIF complex and HTATSF1. PAF1C is required for transcription of Hox and Wnt target genes. PAF1C is involved in hematopoiesis and stimulates transcriptional activity of KMT2A/MLL1; it promotes leukemogenesis through association with KMT2A/MLL1-rearranged oncoproteins, such as KMT2A/MLL1-MLLT3/AF9 and KMT2A/MLL1-MLLT1/ENL. PAF1C is involved in histone modifications such as ubiquitination of histone H2B and methylation on histone H3 'Lys-4' (H3K4me3). PAF1C recruits the RNF20/40 E3 ubiquitin-protein ligase complex and the E2 enzyme UBE2A or UBE2B to chromatin which mediate monoubiquitination of 'Lys-120' of histone H2B (H2BK120ub1); UB2A/B-mediated H2B ubiquitination is proposed to be coupled to transcription. PAF1C is involved in mRNA 3' end formation probably through association with cleavage and poly(A) factors. In case of infection by influenza A strain H3N2, PAF1C associates with viral NS1 protein, thereby regulating gene transcription. Required for mono- and trimethylation on histone H3 'Lys-4' (H3K4me3) and dimethylation on histone H3 'Lys-79' (H3K4me3). Required for Hox gene transcription. Required for the trimethylation of histone H3 'Lys-4' (H3K4me3) on genes involved in stem cell pluripotency; this function is synergistic with CXXC1 indicative for an involvement of the SET1 complex. Involved in transcriptional regulation of IL6-responsive genes and in JAK-STAT pathway; may regulate DNA-association of STAT3 (By similarity)","source":"project UniProt records20261017/18"},{"partner":"SUZ12","hgnc":"HGNC:17101","core":true,"core_annotation":{"hgnc":"HGNC:17101","symbol_at_source":"SUZ12","accession":"Q15022","function":"Histone modification write cofactor, Histone modification write cofactor, Polycomb group (PcG) protein, TF","target":"DNA","pmids":["15385962"],"complexes":"PRC2","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":551,"hub_weight":0.2884348722688805,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Polycomb group (PcG) protein. Component of the PRC2 complex, which methylates 'Lys-9' (H3K9me) and 'Lys-27' (H3K27me) of histone H3, leading to transcriptional repression of the affected target gene (PubMed:15225548, PubMed:15231737, PubMed:15385962, PubMed:16618801, PubMed:17344414, PubMed:18285464, PubMed:28229514, PubMed:29499137, PubMed:31959557). The PRC2 complex may also serve as a recruiting platform for DNA methyltransferases, thereby linking two epigenetic repression systems (PubMed:12351676, PubMed:12435631, PubMed:15099518, PubMed:15225548, PubMed:15385962, PubMed:15684044, PubMed:16431907, PubMed:18086877, PubMed:18285464). Genes repressed by the PRC2 complex include HOXC8, HOXA9, MYT1 and CDKN2A (PubMed:15231737, PubMed:16618801, PubMed:17200670, PubMed:31959557)","source":"project UniProt records20261017/18"},{"partner":"TAF3","hgnc":"HGNC:17303","core":true,"core_annotation":{"hgnc":"HGNC:17303","symbol_at_source":"TAF3","accession":"Q5VWG9","function":"Histone modification read","target":"histone","pmids":["21423274"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":89,"hub_weight":0.5997601439040672,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"The TFIID basal transcription factor complex plays a major role in the initiation of RNA polymerase II (Pol II)-dependent transcription (PubMed:33795473). TFIID recognizes and binds promoters with or without a TATA box via its subunit TBP, a TATA-box-binding protein, and promotes assembly of the pre-initiation complex (PIC) (PubMed:33795473). The TFIID complex consists of TBP and TBP-associated factors (TAFs), including TAF1, TAF2, TAF3, TAF4, TAF5, TAF6, TAF7, TAF8, TAF9, TAF10, TAF11, TAF12 and TAF13 (PubMed:33795473). The TFIID complex structure can be divided into 3 modules TFIID-A, TFIID-B, and TFIID-C (PubMed:33795473). TAF3 forms the TFIID-A module together with TAF5 and TBP (PubMed:33795473). Required in complex with TBPL2 for the differentiation of myoblasts into myocytes (PubMed:11438666). The TAF3-TBPL2 complex replaces TFIID at specific promoters at an early stage in the differentiation process (PubMed:11438666)","source":"project UniProt records20261017/18"},{"partner":"SENP3","hgnc":"HGNC:17862","core":true,"core_annotation":{"hgnc":"HGNC:17862","symbol_at_source":"SENP3","accession":"Q9H4L4","function":"Histone modification erase, Histone modification write cofactor","target":"histone","pmids":[],"complexes":"CHD8, MLL2/3, MLL4/WBP7","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":249,"hub_weight":0.4089304100547653,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus, nucleolus; Nucleus, nucleoplasm; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Protease that releases SUMO2 and SUMO3 monomers from sumoylated substrates, but has only weak activity against SUMO1 conjugates (PubMed:16608850, PubMed:32832608, PubMed:36050397). Deconjugates SUMO2 from MEF2D, which increases its transcriptional activation capability (PubMed:15743823). Deconjugates SUMO2 and SUMO3 from CDCA8 (PubMed:18946085). Redox sensor that, when redistributed into nucleoplasm, can act as an effector to enhance HIF1A transcriptional activity by desumoylating EP300 (PubMed:19680224). Required for rRNA processing through deconjugation of SUMO2 and SUMO3 from nucleophosmin, NPM1 (PubMed:19015314). Plays a role in the regulation of sumoylation status of ZNF148 (PubMed:18259216). Functions as a component of the Five Friends of Methylated CHTOP (5FMC) complex; the 5FMC complex is recruited to ZNF148 by methylated CHTOP, leading to desumoylation of ZNF148 and subsequent transactivation of ZNF148 target genes (PubMed:22872859). Deconjugates SUMO2 from KAT5 (PubMed:32832608). Catalyzes desumoylation of MRE11 (PubMed:36050397)","source":"project UniProt records20261017/18"},{"partner":"ARID2","hgnc":"HGNC:18037","core":true,"core_annotation":{"hgnc":"HGNC:18037","symbol_at_source":"ARID2","accession":"Q68CP9","function":"Chromatin remodeling cofactor","target":"DNA","pmids":["15640446"],"complexes":"PBAF","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":143,"hub_weight":0.5089865985592875,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Involved in transcriptional activation and repression of select genes by chromatin remodeling (alteration of DNA-nucleosome topology). Required for the stability of the SWI/SNF chromatin remodeling complex SWI/SNF-B (PBAF). May be involved in targeting the complex to different genes. May be involved in regulating transcriptional activation of cardiac genes","source":"project UniProt records20261017/18"},{"partner":"RSF1","hgnc":"HGNC:18118","core":true,"core_annotation":{"hgnc":"HGNC:18118","symbol_at_source":"RSF1","accession":"Q96T23","function":"Histone modification read","target":"histone","pmids":["12972596"],"complexes":"RSF","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":124,"hub_weight":0.5360562674188974,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Regulatory subunit of the ATP-dependent RSF-1 and RSF-5 ISWI chromatin-remodeling complexes, which form ordered nucleosome arrays on chromatin and facilitate access to DNA during DNA-templated processes such as DNA replication, transcription, and repair (PubMed:12972596, PubMed:28801535). Binds to core histones together with SMARCA5, and is required for the assembly of regular nucleosome arrays by the RSF-5 ISWI chromatin-remodeling complex (PubMed:12972596). Directly stimulates the ATPase activity of SMARCA1 and SMARCA5 in the RSF-1 and RSF-5 ISWI chromatin-remodeling complexes, respectively (PubMed:28801535). The RSF-1 ISWI chromatin remodeling complex has a lower ATP hydrolysis rate than the RSF-5 ISWI chromatin-remodeling complex (PubMed:28801535). The complexes do not have the ability to slide mononucleosomes to the center of a DNA template (PubMed:28801535). Facilitates transcription of hepatitis B virus (HBV) genes by the pX transcription activator. In case of infection by HBV, together with pX, it represses TNF induced NF-kappa-B transcription activation. Represses transcription when artificially recruited to chromatin by fusion to a heterogeneous DNA binding domain (PubMed:11788598, PubMed:11944984)","source":"project UniProt records20261017/18"},{"partner":"SMARCAD1","hgnc":"HGNC:18398","core":true,"core_annotation":{"hgnc":"HGNC:18398","symbol_at_source":"SMARCAD1","accession":"Q9H4L7","function":"Chromatin remodeling","target":"chromatin","pmids":["22960744"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":202,"hub_weight":0.44543540318737396,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Protein that possesses intrinsic ATP-dependent nucleosome-remodeling activity and is both required for DNA repair and heterochromatin organization (PubMed:22960744, PubMed:21820097). Combines the ATP-dependent ability to exchange histones, with the chaperone-like ATP-independent activity to deposit histones and assemble nucleosomes (PubMed:21820097). Promotes DNA end resection of double-strand breaks (DSBs) following DNA damage: probably acts by weakening histone DNA interactions in nucleosomes flanking DSBs (PubMed:22960744). Required for the restoration of heterochromatin organization after replication (PubMed:21549307). Acts at replication sites to facilitate the maintenance of heterochromatin by directing H3 and H4 histones deacetylation, H3 'Lys-9' trimethylation (H3K9me3) and restoration of silencing (PubMed:21549307)","source":"project UniProt records20261017/18"},{"partner":"SHPRH","hgnc":"HGNC:19336","core":true,"core_annotation":{"hgnc":"HGNC:19336","symbol_at_source":"SHPRH","accession":"Q149N8","function":"Histone modification write cofactor","target":"histone","pmids":["17130289"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":96,"hub_weight":0.5852057359806528,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"","partner_has_nuclear_annotation":false,"partner_location_assessed":false,"function":"E3 ubiquitin-protein ligase involved in DNA repair. Upon genotoxic stress, accepts ubiquitin from the UBE2N-UBE2V2 E2 complex and transfers it to 'Lys-164' of PCNA which had been monoubiquitinated by UBE2A/B-RAD18, promoting the formation of non-canonical poly-ubiquitin chains linked through 'Lys-63'","source":"project UniProt records20261017/18"},{"partner":"SIN3A","hgnc":"HGNC:19353","core":true,"core_annotation":{"hgnc":"HGNC:19353","symbol_at_source":"SIN3A","accession":"Q96ST3","function":"Histone modification erase cofactor, TF","target":"histone, DNA","pmids":["12670868"],"complexes":"SWI/SNF_Brg1(I), SWI/SNF_Brm, mSin3A, mSin3A-like complex","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":329,"hub_weight":0.363216356146074,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Nucleus, nucleolus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Acts as a transcriptional repressor. Corepressor for REST. Interacts with MXI1 to repress MYC responsive genes and antagonize MYC oncogenic activities. Also interacts with MXD1-MAX heterodimers to repress transcription by tethering SIN3A to DNA. Acts cooperatively with OGT to repress transcription in parallel with histone deacetylation. Involved in the control of the circadian rhythms. Required for the transcriptional repression of circadian target genes, such as PER1, mediated by the large PER complex through histone deacetylation. Cooperates with FOXK1 to regulate cell cycle progression probably by repressing cell cycle inhibitor genes expression (By similarity). Required for cortical neuron differentiation and callosal axon elongation (By similarity)","source":"project UniProt records20261017/18"},{"partner":"USP36","hgnc":"HGNC:20062","core":true,"core_annotation":{"hgnc":"HGNC:20062","symbol_at_source":"USP36","accession":"Q9P275","function":"Histone modification write cofactor","target":"histone","pmids":["22622177"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":492,"hub_weight":0.3037283696153935,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus, nucleolus; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Deubiquitinase essential for the regulation of nucleolar structure and function (PubMed:19208757, PubMed:22902402, PubMed:29273634). Required for cell and organism viability (PubMed:19208757, PubMed:22902402, PubMed:29273634). Plays an important role in ribosomal RNA processing and protein synthesis, which is mediated, at least in part, through deubiquitination of DHX33, NPM1 and FBL, regulating their protein stability (PubMed:19208757, PubMed:22902402, PubMed:29273634, PubMed:36912080). Functions as a transcriptional repressor by deubiquiting histone H2B at the promoters of genes critical for cellular differentiation, such as CDKN1A, thereby preventing histone H3 'Lys-4' trimethylation (H3K4) (PubMed:29274341). Specifically deubiquitinates MYC in the nucleolus, leading to prevent MYC degradation by the proteasome: acts by specifically interacting with isoform 3 of FBXW7 (FBW7gamma) in the nucleolus and counteracting ubiquitination of MYC by the SCF(FBW7) complex (PubMed:25775507). In contrast, it does not interact with isoform 1 of FBXW7 (FBW7alpha) in the nucleoplasm (PubMed:25775507). Interacts to and regulates the actions of E3 ubiquitin-protein ligase NEDD4L over substrates such as NTRK1, KCNQ2 and KCNQ3, affecting their expression an functions (PubMed:27445338). Deubiquitinates SOD2, regulates SOD2 protein stability (PubMed:21268071). Deubiquitinase activity is required to control selective autophagy activation by ubiquitinated proteins (PubMed:22622177). Promotes CEP63 stabilization through 'Lys-48'-linked deubiquitination leading to increased stability (PubMed:35989368). Acts as a SUMO ligase to promote EXOSC10 sumoylation critical for the nucleolar RNA exosome function in rRNA processing (PubMed:36912080). Binds to pre-rRNAs (PubMed:36912080)","source":"project UniProt records20261017/18"},{"partner":"CHD7","hgnc":"HGNC:20626","core":true,"core_annotation":{"hgnc":"HGNC:20626","symbol_at_source":"CHD7","accession":"Q9P2D1","function":"Chromatin remodeling","target":"chromatin","pmids":["5201778"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":157,"hub_weight":0.49147318718299043,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Nucleus, nucleolus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"ATP-dependent chromatin-remodeling factor, slides nucleosomes along DNA; nucleosome sliding requires ATP (PubMed:28533432). Probable transcription regulator. May be involved in the in 45S precursor rRNA production","source":"project UniProt records20261017/18"},{"partner":"PHF8","hgnc":"HGNC:20672","core":true,"core_annotation":{"hgnc":"HGNC:20672","symbol_at_source":"PHF8","accession":"Q9UPP1","function":"Histone modification erase","target":"histone","pmids":["21423274"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":163,"hub_weight":0.4845015831115092,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Nucleus, nucleolus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone lysine demethylase with selectivity for mono- and dimethylated residues. It plays an essential role in cell cycle progression and rDNA transcription (PubMed:19843542, PubMed:20531378, PubMed:20548336, PubMed:20622854). Demethylates mono- and dimethylated histone H3 'Lys-9' residue (H3K9Me1 and H3K9Me2) and monomethylated histone H4 'Lys-20' residue (H4K20Me1). Acts as a transcription activator as H3K9Me1, H3K9Me2, H3K27Me2 and H4K20Me1 are epigenetic repressive marks (PubMed:20101266, PubMed:20208542, PubMed:20346720, PubMed:20622853, PubMed:20622854). Displays a very low intrinsic activity toward dimethylated H3 'Lys-27' (H3K27Me2) (PubMed:20346720). May also have weak activity toward dimethylated H3 'Lys-36' (H3K36Me2), however, the relevance of this result remains unsure in vivo (PubMed:19843542, PubMed:20023638, PubMed:20346720). Involved in cell cycle progression by being required to control G1-S transition (PubMed:20622854). Acts as a coactivator of rDNA transcription, by activating polymerase I (pol I) mediated transcription of rRNA genes (PubMed:20531378). Specifically binds trimethylated 'Lys-4' of histone H3 (H3K4me3), affecting histone demethylase specificity: has weak activity toward H3K9Me2 in absence of H3K4me3, while it has high activity toward H3K9me2 when binding H3K4me3 (PubMed:20023638, PubMed:20346720, PubMed:20421419). Positively modulates transcription of histone demethylase KDM5C, acting synergistically with transcription factor ARX; synergy may be related to enrichment of histone H3K4me3 in regulatory elements (PubMed:31691806). Required for brain development, probably by regulating expression of neuron-specific genes (By similarity)","source":"project UniProt records20261017/18"},{"partner":"PHF14","hgnc":"HGNC:22203","core":true,"core_annotation":{"hgnc":"HGNC:22203","symbol_at_source":"PHF14","accession":"O94880","function":"Histone modification read","target":"histone","pmids":["23688586"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":87,"hub_weight":0.604122093330177,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone-binding protein (PubMed:23688586). Binds preferentially to unmodified histone H3 but can also bind to a lesser extent to histone H3 trimethylated at 'Lys-9' (H3K9me3) as well as to histone H3 monomethylated at 'Lys-27' (H3K27ac) and trimethylated at 'Lys-27' (H3K27me3) (By similarity). Represses PDGFRA expression, thus playing a role in regulation of mesenchymal cell proliferation (By similarity). Suppresses the expression of CDKN1A/p21 by reducing the level of trimethylation of histone H3 'Lys-4', leading to enhanced proliferation of germinal center B cells (By similarity)","source":"project UniProt records20261017/18"},{"partner":"L3MBTL3","hgnc":"HGNC:23035","core":true,"core_annotation":{"hgnc":"HGNC:23035","symbol_at_source":"L3MBTL3","accession":"Q96JM7","function":"Histone modification read","target":"histone","pmids":["23292653"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":112,"hub_weight":0.5555555555555556,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Is a negative regulator of Notch target genes expression, required for RBPJ-mediated transcriptional repression (PubMed:29030483). It recruits KDM1A to Notch-responsive elements and promotes KDM1A-mediated H3K4me demethylation (PubMed:29030483). Involved in the regulation of ubiquitin-dependent degradation of a set of methylated non-histone proteins, including SOX2, DNMT1 and E2F1. It acts as an adapter recruiting the CRL4-DCAF5 E3 ubiquitin ligase complex to methylated target proteins (PubMed:29691401, PubMed:30442713). Required for normal maturation of myeloid progenitor cells (By similarity)","source":"project UniProt records20261017/18"},{"partner":"DNTTIP2","hgnc":"HGNC:24013","core":true,"core_annotation":{"hgnc":"HGNC:24013","symbol_at_source":"DNTTIP2","accession":"Q5QJE6","function":"Chromatin remodeling","target":"histone","pmids":["12786946"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":135,"hub_weight":0.5198752449100363,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Nucleus, nucleolus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Regulates the transcriptional activity of DNTT and ESR1. May function as a chromatin remodeling protein (PubMed:12786946, PubMed:15047147). Part of the small subunit (SSU) processome, first precursor of the small eukaryotic ribosomal subunit. During the assembly of the SSU processome in the nucleolus, many ribosome biogenesis factors, an RNA chaperone and ribosomal proteins associate with the nascent pre-rRNA and work in concert to generate RNA folding, modifications, rearrangements and cleavage as well as targeted degradation of pre-ribosomal RNA by the RNA exosome (PubMed:34516797)","source":"project UniProt records20261017/18"},{"partner":"GLYR1","hgnc":"HGNC:24434","core":true,"core_annotation":{"hgnc":"HGNC:24434","symbol_at_source":"GLYR1","accession":"Q49A26","function":"Histone modification read","target":"histone","pmids":["20850016"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":232,"hub_weight":0.42107596053325946,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Cytokine-like nuclear factor with chromatin gene reader activity involved in chromatin modification and regulation of gene expression (PubMed:23260659, PubMed:30970244). Acts as a nucleosome-destabilizing factor that is recruited to genes during transcriptional activation (PubMed:29759984, PubMed:30970244). Recognizes and binds histone H3 without a preference for specific epigenetic markers and also binds DNA (PubMed:20850016, PubMed:30970244). Interacts with KDM1B and promotes its histone demethylase activity by facilitating the capture of H3 tails, they form a multifunctional enzyme complex that modifies transcribed chromatin and facilitates Pol II transcription through nucleosomes (PubMed:23260659, PubMed:29759984, PubMed:30970244). Stimulates the acetylation of 'Lys-56' of nucleosomal histone H3 (H3K56ac) by EP300 (PubMed:29759984). With GATA4, co-binds a defined set of heart development genes and coregulates their expression during cardiomyocyte differentiation (PubMed:35182466). Regulates p38 MAP kinase activity by mediating stress activation of MAPK14/p38alpha and specifically regulating MAPK14 signaling (PubMed:16352664). Indirectly promotes phosphorylation of MAPK14 and activation of ATF2 (PubMed:16352664). The phosphorylation of MAPK14 requires upstream activity of MAP2K4 and MAP2K6 (PubMed:16352664)","source":"project UniProt records20261017/18"},{"partner":"NOC2L","hgnc":"HGNC:24517","core":true,"core_annotation":{"hgnc":"HGNC:24517","symbol_at_source":"NOC2L","accession":"Q9Y3T9","function":"Chromatin remodeling, TF","target":"histone","pmids":["15100215"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":262,"hub_weight":0.40032038451271784,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus, nucleoplasm; Nucleus, nucleolus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Acts as an inhibitor of histone acetyltransferase activity; prevents acetylation of all core histones by the EP300/p300 histone acetyltransferase at p53/TP53-regulated target promoters in a histone deacetylases (HDAC)-independent manner. Acts as a transcription corepressor of p53/TP53- and TP63-mediated transactivation of the p21/CDKN1A promoter. Involved in the regulation of p53/TP53-dependent apoptosis. Associates together with TP63 isoform TA*-gamma to the p21/CDKN1A promoter","source":"project UniProt records20261017/18"},{"partner":"EHMT1","hgnc":"HGNC:24650","core":true,"core_annotation":{"hgnc":"HGNC:24650","symbol_at_source":"EHMT1","accession":"Q9H9B1","function":"Histone modification write","target":"histone","pmids":["18264113"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":169,"hub_weight":0.47781848256749654,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone methyltransferase that specifically mono-, di- and trimethylates 'Lys-9' of histone H3 (H3K9me1, H3K9me2 and H3K9me3, respectively) in euchromatin (PubMed:12004135). H3K9me represents a specific tag for epigenetic transcriptional repression by recruiting HP1 proteins to methylated histones (PubMed:12004135). Also weakly methylates 'Lys-27' of histone H3 (H3K27me) (PubMed:12004135). Also required for DNA methylation, the histone methyltransferase activity is not required for DNA methylation, suggesting that these 2 activities function independently (By similarity). Probably targeted to histone H3 by different DNA-binding proteins like E2F6, MGA, MAX and/or DP1 (PubMed:12004135). During G0 phase, it probably contributes to silencing of MYC- and E2F-responsive genes, suggesting a role in G0/G1 transition in cell cycle (PubMed:12004135). Involved in the differentiation of myoblastic precursors into brown adipose cells: following recruitment to chromatin by PRDM16, mediates formation of H3K9me2 and H3K9me3, inhibiting the expression of white adipose-selective genes (By similarity). Also involved in the differentiation of beige adipocytes from white adipose cells following recruitment by PRDM16 (By similarity). EHMT1 also promotes protein stabilization of PRDM16, by preventing PRDM16 ubiquitination and degradation (By similarity). In addition to the histone methyltransferase activity, also methylates non-histone proteins: mediates dimethylation of 'Lys-373' of p53/TP53 (PubMed:20118233). Represses the expression of mitochondrial function-related genes, perhaps by occupying their promoter regions, working in concert with probable chromatin reader BAZ2B (By similarity)","source":"project UniProt records20261017/18"},{"partner":"H2BC18","hgnc":"HGNC:24700","core":true,"core_annotation":{"hgnc":"HGNC:24700","symbol_at_source":"HIST2H2BF","accession":"Q5QNW6","function":"Histone/protamine","target":"chromatin","pmids":[],"version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":253,"hub_weight":0.40622223185119377,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Core component of nucleosome. Nucleosomes wrap and compact DNA into chromatin, limiting DNA accessibility to the cellular machineries which require DNA as a template. Histones thereby play a central role in transcription regulation, DNA repair, DNA replication and chromosomal stability. DNA accessibility is regulated via a complex set of post-translational modifications of histones, also called histone code, and nucleosome remodeling","source":"project UniProt records20261017/18"},{"partner":"HP1BP3","hgnc":"HGNC:24973","core":true,"core_annotation":{"hgnc":"HGNC:24973","symbol_at_source":"HP1BP3","accession":"Q5SSJ5","function":"Chromatin remodeling","target":"chromatin","pmids":["25100860"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":310,"hub_weight":0.37267799624996495,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Component of heterochromatin that maintains heterochromatin integrity during G1/S progression and regulates the duration of G1 phase to critically influence cell proliferative capacity (PubMed:24830416). Mediates chromatin condensation during hypoxia, leading to increased tumor cell viability, radio-resistance, chemo-resistance and self-renewal (PubMed:25100860)","source":"project UniProt records20261017/18"},{"partner":"PAF1","hgnc":"HGNC:25459","core":true,"core_annotation":{"hgnc":"HGNC:25459","symbol_at_source":"PAF1","accession":"Q8N7H5","function":"Histone modification write cofactor","target":"histone","pmids":["16307923"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":187,"hub_weight":0.45931521217462534,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Component of the PAF1 complex (PAF1C) which has multiple functions during transcription by RNA polymerase II and is implicated in regulation of development and maintenance of embryonic stem cell pluripotency. PAF1C associates with RNA polymerase II through interaction with POLR2A CTD non-phosphorylated and 'Ser-2'- and 'Ser-5'-phosphorylated forms and is involved in transcriptional elongation, acting both independently and synergistically with TCEA1 and in cooperation with the DSIF complex and HTATSF1. PAF1C is required for transcription of Hox and Wnt target genes. PAF1C is involved in hematopoiesis and stimulates transcriptional activity of KMT2A/MLL1; it promotes leukemogenesis through association with KMT2A/MLL1-rearranged oncoproteins, such as KMT2A/MLL1-MLLT3/AF9 and KMT2A/MLL1-MLLT1/ENL. PAF1C is involved in histone modifications such as ubiquitination of histone H2B and methylation on histone H3 'Lys-4' (H3K4me3). PAF1C recruits the RNF20/40 E3 ubiquitin-protein ligase complex and the E2 enzyme UBE2A or UBE2B to chromatin which mediate monoubiquitination of 'Lys-120' of histone H2B (H2BK120ub1); UB2A/B-mediated H2B ubiquitination is proposed to be coupled to transcription. PAF1C is involved in mRNA 3' end formation probably through association with cleavage and poly(A) factors. In case of infection by influenza A strain H3N2, PAF1C associates with viral NS1 protein, thereby regulating gene transcription. Connects PAF1C with the RNF20/40 E3 ubiquitin-protein ligase complex. Involved in polyadenylation of mRNA precursors. Has oncogenic activity in vivo and in vitro","source":"project UniProt records20261017/18"},{"partner":"BCORL1","hgnc":"HGNC:25657","core":true,"core_annotation":{"hgnc":"HGNC:25657","symbol_at_source":"BCORL1","accession":"Q5H9F3","function":"Histone modification erase cofactor","target":"histone","pmids":["23523425","17379597"],"complexes":"BCOR","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":85,"hub_weight":0.6085806194501846,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Transcriptional corepressor. May specifically inhibit gene expression when recruited to promoter regions by sequence-specific DNA-binding proteins such as BCL6. This repression may be mediated at least in part by histone deacetylase activities which can associate with this corepressor","source":"project UniProt records20261017/18"},{"partner":"LAS1L","hgnc":"HGNC:25726","core":true,"core_annotation":{"hgnc":"HGNC:25726","symbol_at_source":"LAS1L","accession":"Q9Y4W2","function":"Histone modification write cofactor, Histone modification write cofactor","target":"histone","pmids":["20442285"],"complexes":"CHD8, MLL2/3, MLL4/WBP7","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":161,"hub_weight":0.4867923835112355,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus, nucleolus; Nucleus, nucleoplasm; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Required for the synthesis of the 60S ribosomal subunit and maturation of the 28S rRNA (PubMed:20647540). Functions as a component of the Five Friends of Methylated CHTOP (5FMC) complex; the 5FMC complex is recruited to ZNF148 by methylated CHTOP, leading to desumoylation of ZNF148 and subsequent transactivation of ZNF148 target genes (PubMed:22872859). Required for the efficient pre-rRNA processing at both ends of internal transcribed spacer 2 (ITS2) (PubMed:22083961)","source":"project UniProt records20261017/18"},{"partner":"TEX10","hgnc":"HGNC:25988","core":true,"core_annotation":{"hgnc":"HGNC:25988","symbol_at_source":"TEX10","accession":"Q9NXF1","function":"Histone modification write cofactor, Histone modification write cofactor","target":"histone","pmids":[],"complexes":"CHD8, MLL2/3, MLL4/WBP7","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":169,"hub_weight":0.47781848256749654,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus, nucleoplasm; Cytoplasm; Nucleus, nucleolus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Functions as a component of the Five Friends of Methylated CHTOP (5FMC) complex; the 5FMC complex is recruited to ZNF148 by methylated CHTOP, leading to desumoylation of ZNF148 and subsequent transactivation of ZNF148 target genes (PubMed:22872859). Component of the PELP1 complex involved in the nucleolar steps of 28S rRNA maturation and the subsequent nucleoplasmic transit of the pre-60S ribosomal subunit (PubMed:21326211)","source":"project UniProt records20261017/18"},{"partner":"MSL1","hgnc":"HGNC:27905","core":true,"core_annotation":{"hgnc":"HGNC:27905","symbol_at_source":"MSL1","accession":"Q68DK7","function":"Histone modification write","target":"histone","pmids":["21726816"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":66,"hub_weight":0.6565321642986127,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Nucleus, nucleoplasm; Nucleus speckle","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Non-catalytic component of the MSL histone acetyltransferase complex, a multiprotein complex that mediates the majority of histone H4 acetylation at 'Lys-16' (H4K16ac), an epigenetic mark that prevents chromatin compaction (PubMed:16227571, PubMed:16543150, PubMed:33837287). The MSL complex is required for chromosome stability and genome integrity by maintaining homeostatic levels of H4K16ac (PubMed:33837287). The MSL complex is also involved in gene dosage by promoting up-regulation of genes expressed by the X chromosome (By similarity). X up-regulation is required to compensate for autosomal biallelic expression (By similarity). The MSL complex also participates in gene dosage compensation by promoting expression of Tsix non-coding RNA (By similarity). Within the MSL complex, acts as a scaffold to tether MSL3 and KAT8 together for enzymatic activity regulation (PubMed:22547026). Greatly enhances MSL2 E3 ubiquitin ligase activity, promoting monoubiquitination of histone H2B at 'Lys-34' (H2BK34Ub) (PubMed:21726816, PubMed:30930284). This modification in turn stimulates histone H3 methylation at 'Lys-4' (H3K4me) and 'Lys-79' (H3K79me) and leads to gene activation, including that of HOXA9 and MEIS1 (PubMed:21726816)","source":"project UniProt records20261017/18"},{"partner":"NIPBL","hgnc":"HGNC:28862","core":true,"core_annotation":{"hgnc":"HGNC:28862","symbol_at_source":"NIPBL","accession":"Q6KC79","function":"Histone modification erase cofactor","target":"#","pmids":["25255084","18854353"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":174,"hub_weight":0.472455591261534,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Plays an important role in the loading of the cohesin complex on to DNA. Forms a heterodimeric complex (also known as cohesin loading complex) with MAU2/SCC4 which mediates the loading of the cohesin complex onto chromatin (PubMed:22628566, PubMed:28914604). Plays a role in cohesin loading at sites of DNA damage. Its recruitment to double-strand breaks (DSBs) sites occurs in a CBX3-, RNF8- and RNF168-dependent manner whereas its recruitment to UV irradiation-induced DNA damage sites occurs in a ATM-, ATR-, RNF8- and RNF168-dependent manner (PubMed:28167679). Along with ZNF609, promotes cortical neuron migration during brain development by regulating the transcription of crucial genes in this process. Preferentially binds promoters containing paused RNA polymerase II. Up-regulates the expression of SEMA3A, NRP1, PLXND1 and GABBR2 genes, among others (By similarity)","source":"project UniProt records20261017/18"},{"partner":"ZNF592","hgnc":"HGNC:28986","core":true,"core_annotation":{"hgnc":"HGNC:28986","symbol_at_source":"ZNF592","accession":"Q92610","function":"Histone modification erase cofactor","target":"histone","pmids":["25123934"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":73,"hub_weight":0.6375767130633383,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"May be involved in transcriptional regulation","source":"project UniProt records20261017/18"},{"partner":"MYSM1","hgnc":"HGNC:29401","core":true,"core_annotation":{"hgnc":"HGNC:29401","symbol_at_source":"MYSM1","accession":"Q5VVJ2","function":"Histone modification erase","target":"histone","pmids":["17707232"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":101,"hub_weight":0.575435337648436,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Metalloprotease with deubiquitinase activity that plays important regulator roles in hematopoietic stem cell function, blood cell production and immune response (PubMed:24062447, PubMed:26220525, PubMed:28115216). Participates in the normal programming of B-cell responses to antigen after the maturation process (By similarity). Within the cytoplasm, plays critical roles in the repression of innate immunity and autoimmunity (PubMed:33086059). Removes 'Lys-63'-linked polyubiquitins from TRAF3 and TRAF6 complexes (By similarity). Attenuates NOD2-mediated inflammation and tissue injury by promoting 'Lys-63'-linked deubiquitination of RIPK2 component (By similarity). Suppresses the CGAS-STING1 signaling pathway by cleaving STING1 'Lys-63'-linked ubiquitin chains (PubMed:33086059). In the nucleus, acts as a hematopoietic transcription regulator derepressing a range of genes essential for normal stem cell differentiation including EBF1 and PAX5 in B-cells, ID2 in NK-cell progenitor or FLT3 in dendritic cell precursors (PubMed:24062447). Deubiquitinates monoubiquitinated histone H2A, a specific tag for epigenetic transcriptional repression, leading to dissociation of histone H1 from the nucleosome (PubMed:17707232)","source":"project UniProt records20261017/18"},{"partner":"MTF2","hgnc":"HGNC:29535","core":true,"core_annotation":{"hgnc":"HGNC:29535","symbol_at_source":"MTF2","accession":"Q9Y483","function":"Polycomb group (PcG) protein","target":"histone","pmids":["21881606"],"complexes":"PRC2","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":82,"hub_weight":0.6154574548966637,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Polycomb group (PcG) protein that specifically binds histone H3 trimethylated at 'Lys-36' (H3K36me3) and recruits the PRC2 complex, thus enhancing PRC2 H3K27me3 methylation activity (PubMed:23142980, PubMed:23228662, PubMed:31959557). Regulates the transcriptional networks during embryonic stem cell self-renewal and differentiation (By similarity). Promotes recruitment of the PRC2 complex to the inactive X chromosome in differentiating XX ES cells and PRC2 recruitment to target genes in undifferentiated ES cells (By similarity). Required to repress Hox genes by enhancing H3K27me3 methylation of the PRC2 complex (By similarity). In some conditions may act as an inhibitor of PRC2 activity: able to activate the CDKN2A gene and promote cellular senescence by suppressing the catalytic activity of the PRC2 complex locally (By similarity). Binds to the metal-regulating-element (MRE) of MT1A gene promoter (By similarity)","source":"project UniProt records20261017/18"},{"partner":"H4C15","hgnc":"HGNC:29607","core":true,"core_annotation":{"hgnc":"HGNC:29607","symbol_at_source":"HIST2H4B","accession":"P62805","function":"Histone/protamine","target":"chromatin","pmids":[],"version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":34,"hub_weight":0.7715167498104596,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Core component of nucleosome. Nucleosomes wrap and compact DNA into chromatin, limiting DNA accessibility to the cellular machineries which require DNA as a template. Histones thereby play a central role in transcription regulation, DNA repair, DNA replication and chromosomal stability. DNA accessibility is regulated via a complex set of post-translational modifications of histones, also called histone code, and nucleosome remodeling","source":"project UniProt records20261017/18"},{"partner":"MPHOSPH8","hgnc":"HGNC:29810","core":true,"core_annotation":{"hgnc":"HGNC:29810","symbol_at_source":"MPHOSPH8","accession":"Q99549","function":"Histone modification read","target":"histone","pmids":["21419134"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":85,"hub_weight":0.6085806194501846,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Heterochromatin component that specifically recognizes and binds methylated 'Lys-9' of histone H3 (H3K9me) and promotes recruitment of proteins that mediate epigenetic repression (PubMed:26022416, PubMed:28581500, PubMed:29211708). As part of the HUSH complex, promotes epigenetic repression of mobile genetic elements, such as retroviruses and transposable elements: the HUSH complex mainly represses LINE-1 (L1) retrotransposons that are still capable of transposition (PubMed:29211708). Silencing events often occur within introns of transcriptionally active genes, and lead to the down-regulation of host gene expression (PubMed:29211708). MPHOSPH8 mediates recruitment of the HUSH complex to H3K9me3 sites: the HUSH complex is recruited to genomic loci rich in H3K9me3 and is required to maintain transcriptional silencing by promoting recruitment of SETDB1, a histone methyltransferase that mediates further deposition of H3K9me3, as well as MORC2, a chromatin remodeler that compacts chromatin (PubMed:26022416, PubMed:28581500). The HUSH complex is also involved in the silencing of unintegrated retroviral DNA by being recruited by ZNF638: some part of the retroviral DNA formed immediately after infection remains unintegrated in the host genome and is transcriptionally repressed (PubMed:30487602). As part of the HUSH2 complex, promotes epigenetic repression of interferon-stimulated genes (PubMed:33144593, PubMed:39013473). Binds H3K9me and promotes DNA methylation by recruiting DNMT3A to target CpG sites; these can be situated within the coding region of the gene (PubMed:20871592). Mediates silencing of E-cadherin (CDH1) and protocadherin genes in the nervous system (PubMed:20871592)","source":"project UniProt records20261017/18"},{"partner":"NAT10","hgnc":"HGNC:29830","core":true,"core_annotation":{"hgnc":"HGNC:29830","symbol_at_source":"NAT10","accession":"Q9H0A0","function":"Histone modification write","target":"histone","pmids":["14592445"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":313,"hub_weight":0.37113480951260275,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus, nucleolus; Midbody","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"RNA cytidine acetyltransferase that catalyzes the formation of N(4)-acetylcytidine (ac4C) modification on mRNAs, 18S rRNA and tRNAs (PubMed:25411247, PubMed:25653167, PubMed:30449621, PubMed:35679869). Catalyzes ac4C modification of a broad range of mRNAs, enhancing mRNA stability and translation (PubMed:30449621, PubMed:35679869). mRNA ac4C modification is frequently present within wobble cytidine sites and promotes translation efficiency (PubMed:30449621). Mediates the formation of ac4C at position 1842 in 18S rRNA (PubMed:25411247). May also catalyze the formation of ac4C at position 1337 in 18S rRNA (By similarity). Required for early nucleolar cleavages of precursor rRNA at sites A0, A1 and A2 during 18S rRNA synthesis (PubMed:25411247, PubMed:25653167). Catalyzes the formation of ac4C in serine and leucine tRNAs (By similarity). Requires the tRNA-binding adapter protein THUMPD1 for full tRNA acetyltransferase activity but not for 18S rRNA acetylation (PubMed:25653167). In addition to RNA acetyltransferase activity, also able to acetylate lysine residues of proteins, such as histones, microtubules, p53/TP53 and MDM2, in vitro (PubMed:14592445, PubMed:17631499, PubMed:19303003, PubMed:26882543, PubMed:27993683, PubMed:30165671). The relevance of the protein lysine acetyltransferase activity is however unsure in vivo (PubMed:30449621). Activates telomerase activity by stimulating the transcription of TERT, and may also regulate telomerase function by affecting the balance of telomerase subunit assembly, disassembly, and localization (PubMed:14592445, PubMed:18082603). Involved in the regulation of centrosome duplication by acetylating CENATAC during mitosis, promoting SASS6 proteasome degradation (PubMed:31722219). Part of the small subunit (SSU) processome, first precursor of the small eukaryotic ribosomal subunit. During the assembly of the SSU processome in the nucleolus, many ribosome biogenesis factors, an RNA chaperone and ribosomal proteins associate with the nascent pre-rRNA and work in concert to generate RNA folding, modifications, rearrangements and cleavage as well as targeted degradation of pre-ribosomal RNA by the RNA exosome (PubMed:34516797)","source":"project UniProt records20261017/18"},{"partner":"GATAD2A","hgnc":"HGNC:29989","core":true,"core_annotation":{"hgnc":"HGNC:29989","symbol_at_source":"GATAD2A","accession":"Q86YP4","function":"Histone modification read","target":"histone","pmids":["16415179"],"complexes":"NuRD","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":214,"hub_weight":0.4351941398892446,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus speckle; Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Transcriptional repressor (PubMed:12183469, PubMed:16415179). Acts as a component of the histone deacetylase NuRD complex which participates in the remodeling of chromatin (PubMed:16428440, PubMed:28977666). Enhances MBD2-mediated repression (PubMed:12183469, PubMed:16415179). Efficient repression requires the presence of GATAD2B (PubMed:16415179)","source":"project UniProt records20261017/18"},{"partner":"PBRM1","hgnc":"HGNC:30064","core":true,"core_annotation":{"hgnc":"HGNC:30064","symbol_at_source":"PBRM1","accession":"Q86U86","function":"Histone modification read","target":"histone","pmids":["22464331"],"complexes":"PBAF, SWI/SNF BRM-BRG1","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":213,"hub_weight":0.4360207201969473,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Involved in transcriptional activation and repression of select genes by chromatin remodeling (alteration of DNA-nucleosome topology). Required for the stability of the SWI/SNF chromatin remodeling complex SWI/SNF-B (PBAF). Acts as a negative regulator of cell proliferation","source":"project UniProt records20261017/18"},{"partner":"LEO1","hgnc":"HGNC:30401","core":true,"core_annotation":{"hgnc":"HGNC:30401","symbol_at_source":"LEO1","accession":"Q8WVC0","function":"Histone modification write cofactor","target":"histone","pmids":["24038468"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":134,"hub_weight":0.5212860351426869,"quality":0.4,"programmes":["pubmed:34079125"],"pmids":["34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Component of the PAF1 complex (PAF1C) which has multiple functions during transcription by RNA polymerase II and is implicated in regulation of development and maintenance of embryonic stem cell pluripotency. PAF1C associates with RNA polymerase II through interaction with POLR2A CTD non-phosphorylated and 'Ser-2'- and 'Ser-5'-phosphorylated forms and is involved in transcriptional elongation, acting both independently and synergistically with TCEA1 and in cooperation with the DSIF complex and HTATSF1. PAF1C is required for transcription of Hox and Wnt target genes. PAF1C is involved in hematopoiesis and stimulates transcriptional activity of KMT2A/MLL1; it promotes leukemogenesis through association with KMT2A/MLL1-rearranged oncoproteins, such as KMT2A/MLL1-MLLT3/AF9 and KMT2A/MLL1-MLLT1/ENL. PAF1C is involved in histone modifications such as ubiquitination of histone H2B and methylation on histone H3 'Lys-4' (H3K4me3). PAF1C recruits the RNF20/40 E3 ubiquitin-protein ligase complex and the E2 enzyme UBE2A or UBE2B to chromatin which mediate monoubiquitination of 'Lys-120' of histone H2B (H2BK120ub1); UB2A/B-mediated H2B ubiquitination is proposed to be coupled to transcription. PAF1C is involved in mRNA 3' end formation probably through association with cleavage and poly(A) factors. In case of infection by influenza A strain H3N2, PAF1C associates with viral NS1 protein, thereby regulating gene transcription. Involved in polyadenylation of mRNA precursors. Connects PAF1C to Wnt signaling","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"LONRF3":{"coreEvidence":[{"partner":"APBB1","hgnc":"HGNC:581","core":true,"core_annotation":{"hgnc":"HGNC:581","symbol_at_source":"APBB1","accession":"O00213","function":"Histone modification","target":"histone","pmids":["21403922"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":178,"hub_weight":0.468292905790847,"quality":0.65,"programmes":["pubmed:24284412"],"pmids":["24284412"],"assays":["capture_association"],"contexts":[],"partner_location":"Cell membrane; Cytoplasm; Nucleus; Cell projection, growth cone; Nucleus speckle","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Transcription coregulator that can have both coactivator and corepressor functions (PubMed:15031292, PubMed:18468999, PubMed:18922798, PubMed:25342469, PubMed:33938178). Adapter protein that forms a transcriptionally active complex with the gamma-secretase-derived amyloid precursor protein (APP) intracellular domain (PubMed:15031292, PubMed:18468999, PubMed:18922798, PubMed:25342469). Plays a central role in the response to DNA damage by translocating to the nucleus and inducing apoptosis (PubMed:15031292, PubMed:18468999, PubMed:18922798, PubMed:25342469). May act by specifically recognizing and binding histone H2AX phosphorylated on 'Tyr-142' (H2AXY142ph) at double-strand breaks (DSBs), recruiting other pro-apoptosis factors such as MAPK8/JNK1 (PubMed:19234442). Required for histone H4 acetylation at double-strand breaks (DSBs) (PubMed:19234442). Its ability to specifically bind modified histones and chromatin modifying enzymes such as KAT5/TIP60, probably explains its transcription activation activity (PubMed:33938178). Functions in association with TSHZ3, SET and HDAC factors as a transcriptional repressor, that inhibits the expression of CASP4 (PubMed:19343227). Associates with chromatin in a region surrounding the CASP4 transcriptional start site(s) (PubMed:19343227). Involved in hippocampal neurite branching and neuromuscular junction formation, as a result plays a role in spatial memory functioning (By similarity). Plays a role in the maintenance of lens transparency (By similarity). May play a role in muscle cell strength (By similarity). Acts as a molecular adapter that functions in neurite outgrowth by activating the RAC1-ARF6 axis upon insulin treatment (PubMed:36250347)","source":"project UniProt records20261017/18"},{"partner":"ZMYND8","hgnc":"HGNC:9397","core":true,"core_annotation":{"hgnc":"HGNC:9397","symbol_at_source":"ZMYND8","accession":"Q9ULU4","function":"Histone modification erase cofactor","target":"histone","pmids":["25123934"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":186,"hub_weight":0.4602873089491617,"quality":0.65,"programmes":["pubmed:31753913"],"pmids":["31753913"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus; Chromosome; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Chromatin reader that recognizes dual histone modifications such as histone H3.1 dimethylated at 'Lys-36' and histone H4 acetylated at 'Lys-16' (H3.1K36me2-H4K16ac) and histone H3 methylated at 'Lys-4' and histone H4 acetylated at 'Lys-14' (H3K4me1-H3K14ac) (PubMed:26655721, PubMed:27477906, PubMed:31965980, PubMed:36064715). May act as a transcriptional corepressor for KDM5D by recognizing the dual histone signature H3K4me1-H3K14ac (PubMed:27477906). May also act as a transcriptional corepressor for KDM5C and EZH2 (PubMed:33323928). Recognizes acetylated histone H4 and recruits the NuRD chromatin remodeling complex to damaged chromatin for transcriptional repression and double-strand break repair by homologous recombination (PubMed:25593309, PubMed:27732854, PubMed:30134174). Also activates transcription elongation by RNA polymerase II through recruiting the P-TEFb complex to target promoters (PubMed:26655721, PubMed:30134174). Localizes to H3.1K36me2-H4K16ac marks at all-trans-retinoic acid (ATRA)-responsive genes and positively regulates their expression (PubMed:26655721). Promotes neuronal differentiation by associating with regulatory regions within the MAPT gene, to enhance transcription of a protein-coding MAPT isoform and suppress the non-coding MAPT213 isoform (PubMed:30134174, PubMed:35916866, PubMed:36064715). Suppresses breast cancer, and prostate cancer cell invasion and metastasis (PubMed:27477906, PubMed:31965980, PubMed:33323928)","source":"project UniProt records20261017/18"},{"partner":"PRDM11","hgnc":"HGNC:13996","core":true,"core_annotation":{"hgnc":"HGNC:13996","symbol_at_source":"PRDM11","accession":"Q9NQV5","function":"Histone modification write","target":"histone","pmids":["23508829"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":18,"hub_weight":0.8574929257125442,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"May be involved in transcription regulation","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"KIAA0408":{"coreEvidence":[{"partner":"PARP2","hgnc":"HGNC:272","core":true,"core_annotation":{"hgnc":"HGNC:272","symbol_at_source":"PARP2","accession":"Q9UGN5","function":"Chromatin remodeling cofactor","target":"#","pmids":["20092359"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":556,"hub_weight":0.28724249481071307,"quality":0.4,"programmes":["pubmed:40057523"],"pmids":["40057523"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Poly-ADP-ribosyltransferase that mediates poly-ADP-ribosylation of proteins and plays a key role in DNA repair (PubMed:10364231, PubMed:25043379, PubMed:27471034, PubMed:30104678, PubMed:32028527, PubMed:32939087, PubMed:34108479, PubMed:34486521, PubMed:34874266). Mediates glutamate, aspartate or serine ADP-ribosylation of proteins: the ADP-D-ribosyl group of NAD(+) is transferred to the acceptor carboxyl group of target residues and further ADP-ribosyl groups are transferred to the 2'-position of the terminal adenosine moiety, building up a polymer with an average chain length of 20-30 units (PubMed:25043379, PubMed:30104678, PubMed:30321391). Serine ADP-ribosylation of proteins constitutes the primary form of ADP-ribosylation of proteins in response to DNA damage (PubMed:32939087). Mediates glutamate and aspartate ADP-ribosylation of target proteins in absence of HPF1 (PubMed:25043379). Following interaction with HPF1, catalyzes serine ADP-ribosylation of target proteins; HPF1 conferring serine specificity by completing the PARP2 active site (PubMed:28190768, PubMed:32028527, PubMed:34108479, PubMed:34486521, PubMed:34874266). PARP2 initiates the repair of double-strand DNA breaks: recognizes and binds DNA breaks within chromatin and recruits HPF1, licensing serine ADP-ribosylation of target proteins, such as histones, thereby promoting decompaction of chromatin and the recruitment of repair factors leading to the reparation of DNA strand breaks (PubMed:10364231, PubMed:32939087, PubMed:34108479). HPF1 initiates serine ADP-ribosylation but restricts the polymerase activity of PARP2 in order to limit the length of poly-ADP-ribose chains (PubMed:34732825, PubMed:34795260). Specifically mediates formation of branched poly-ADP-ribosylation (PubMed:30104678). Branched poly-ADP-ribose chains are specifically recognized by some factors, such as APLF (PubMed:30104678). In addition to proteins, also able to ADP-ribosylate DNA: preferentially acts on 5'-terminal phosphates at DNA strand breaks termini in nicked duplex (PubMed:27471034, PubMed:29361132)","source":"project UniProt records20261017/18"},{"partner":"PHF1","hgnc":"HGNC:8919","core":true,"core_annotation":{"hgnc":"HGNC:8919","symbol_at_source":"PHF1","accession":"O43189","function":"Polycomb group (PcG) protein","target":"#","pmids":["18086877"],"complexes":"PRC2","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":138,"hub_weight":0.5157106231293968,"quality":0.75,"programmes":["CCSB_binary_maps"],"pmids":["32296183"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Polycomb group (PcG) that specifically binds histone H3 trimethylated at 'Lys-36' (H3K36me3) and recruits the PRC2 complex. Involved in DNA damage response and is recruited at double-strand breaks (DSBs). Acts by binding to H3K36me3, a mark for transcriptional activation, and recruiting the PRC2 complex: it is however unclear whether recruitment of the PRC2 complex to H3K36me3 leads to enhance or inhibit H3K27me3 methylation mediated by the PRC2 complex. According to some reports, PRC2 recruitment by PHF1 promotes H3K27me3 and subsequent gene silencing by inducing spreading of PRC2 and H3K27me3 into H3K36me3 loci (PubMed:18285464, PubMed:23273982). According to another report, PHF1 recruits the PRC2 complex at double-strand breaks (DSBs) and inhibits the activity of PRC2 (PubMed:23142980). Regulates p53/TP53 stability and prolonges its turnover: may act by specifically binding to a methylated from of p53/TP53","source":"project UniProt records20261017/18"},{"partner":"SUPT6H","hgnc":"HGNC:11470","core":true,"core_annotation":{"hgnc":"HGNC:11470","symbol_at_source":"SUPT6H","accession":"Q7KZ85","function":"Histone modification erase cofactor","target":"histone","pmids":["23503590"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":188,"hub_weight":0.45834924851410563,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone H3-H4 chaperone that plays a key role in the regulation of transcription elongation and mRNA processing. Enhances the transcription elongation by RNA polymerase II (RNAPII) and is also required for the efficient activation of transcriptional elongation by the HIV-1 nuclear transcriptional activator, Tat. Besides chaperoning histones in transcription, acts to transport and splice mRNA by forming a complex with IWS1 and the C-terminal domain (CTD) of the RNAPII subunit RPB1 (POLR2A). The SUPT6H:IWS1:CTD complex recruits mRNA export factors (ALYREF/THOC4, EXOSC10) as well as histone modifying enzymes (such as SETD2), to ensure proper mRNA splicing, efficient mRNA export and elongation-coupled H3K36 methylation, a signature chromatin mark of active transcription. SUPT6H via its association with SETD1A, regulates both class-switch recombination and somatic hypermutation through formation of H3K4me3 epigenetic marks on activation-induced cytidine deaminase (AICDA) target loci. Promotes the activation of the myogenic gene program by entailing erasure of the repressive H3K27me3 epigenetic mark through stabilization of the chromatin interaction of the H3K27 demethylase KDM6A","source":"project UniProt records20261017/18"},{"partner":"TLE1","hgnc":"HGNC:11837","core":true,"core_annotation":{"hgnc":"HGNC:11837","symbol_at_source":"TLE1","accession":"Q04724","function":"Chromatin remodeling, Histone modification cofactor","target":"histone","pmids":["9334241","17041588"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":342,"hub_weight":0.35714285714285715,"quality":0.75,"programmes":["pubmed:21900206"],"pmids":["21900206"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Transcriptional corepressor that binds to a number of transcription factors. Inhibits NF-kappa-B-regulated gene expression. Inhibits the transcriptional activation mediated by FOXA2, and by CTNNB1 and TCF family members in Wnt signaling. Enhances FOXG1/BF-1- and HES1-mediated transcriptional repression (By similarity). The effects of full-length TLE family members may be modulated by association with dominant-negative AES. Unusual function as coactivator for ESRRG","source":"project UniProt records20261017/18"},{"partner":"PRMT6","hgnc":"HGNC:18241","core":true,"core_annotation":{"hgnc":"HGNC:18241","symbol_at_source":"PRMT6","accession":"Q96LA8","function":"Histone modification write","target":"histone","pmids":["18079182"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":111,"hub_weight":0.5572782125753528,"quality":0.75,"programmes":["pubmed:23455924"],"pmids":["23455924"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Arginine methyltransferase that can catalyze the formation of both omega-N monomethylarginine (MMA) and asymmetrical dimethylarginine (aDMA), with a strong preference for the formation of aDMA (PubMed:17898714, PubMed:18077460, PubMed:18079182, PubMed:19405910, PubMed:30420520). Preferentially methylates arginyl residues present in a glycine and arginine-rich domain and displays preference for monomethylated substrates (PubMed:17898714, PubMed:18077460, PubMed:18079182, PubMed:19405910). Specifically mediates the asymmetric dimethylation of histone H3 'Arg-2' to form H3R2me2a (PubMed:17898714, PubMed:18077460, PubMed:18079182). H3R2me2a represents a specific tag for epigenetic transcriptional repression and is mutually exclusive with methylation on histone H3 'Lys-4' (H3K4me2 and H3K4me3) (PubMed:17898714, PubMed:18077460). Acts as a transcriptional repressor of various genes such as HOXA2, THBS1 and TP53 (PubMed:19509293). Repression of TP53 blocks cellular senescence (By similarity). Also methylates histone H2A and H4 'Arg-3' (H2AR3me and H4R3me, respectively). Acts as a regulator of DNA base excision during DNA repair by mediating the methylation of DNA polymerase beta (POLB), leading to the stimulation of its polymerase activity by enhancing DNA binding and processivity (PubMed:16600869). Methylates HMGA1 (PubMed:16157300, PubMed:16159886). Regulates alternative splicing events. Acts as a transcriptional coactivator of a number of steroid hormone receptors including ESR1, ESR2, PGR and NR3C1. Promotes fasting-induced transcriptional activation of the gluconeogenic program through methylation of the CRTC2 transcription coactivator (By similarity). May play a role in innate immunity against HIV-1 in case of infection by methylating and impairing the function of various HIV-1 proteins such as Tat, Rev and Nucleocapsid protein p7 (NC) (PubMed:17267505). Methylates GPS2, protecting GPS2 from ubiquitination and degradation (By similarity). Methylates SIRT7, inhibiting SIRT7 histone deacetylase activity and promoting mitochondria biogenesis (PubMed:30420520)","source":"project UniProt records20261017/18"},{"partner":"SETD2","hgnc":"HGNC:18420","core":true,"core_annotation":{"hgnc":"HGNC:18420","symbol_at_source":"SETD2","accession":"Q9BYW2","function":"Histone modification write","target":"histone","pmids":["16118227"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":113,"hub_weight":0.5538487756217113,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone methyltransferase that specifically trimethylates 'Lys-36' of histone H3 (H3K36me3) using dimethylated 'Lys-36' (H3K36me2) as substrate (PubMed:16118227, PubMed:19141475, PubMed:21526191, PubMed:21792193, PubMed:23043551, PubMed:27474439). It is capable of trimethylating unmethylated H3K36 (H3K36me0) in vitro (PubMed:19332550). Represents the main enzyme generating H3K36me3, a specific tag for epigenetic transcriptional activation (By similarity). Plays a role in chromatin structure modulation during elongation by coordinating recruitment of the FACT complex and by interacting with hyperphosphorylated POLR2A (PubMed:23325844). Acts as a key regulator of DNA mismatch repair in G1 and early S phase by generating H3K36me3, a mark required to recruit MSH6 subunit of the MutS alpha complex: early recruitment of the MutS alpha complex to chromatin to be replicated allows a quick identification of mismatch DNA to initiate the mismatch repair reaction (PubMed:23622243). Required for DNA double-strand break repair in response to DNA damage: acts by mediating formation of H3K36me3, promoting recruitment of RAD51 and DNA repair via homologous recombination (HR) (PubMed:24843002). Acts as a tumor suppressor (PubMed:24509477). H3K36me3 also plays an essential role in the maintenance of a heterochromatic state, by recruiting DNA methyltransferase DNMT3A (PubMed:27317772). H3K36me3 is also enhanced in intron-containing genes, suggesting that SETD2 recruitment is enhanced by splicing and that splicing is coupled to recruitment of elongating RNA polymerase (PubMed:21792193). Required during angiogenesis (By similarity). Required for endoderm development by promoting embryonic stem cell differentiation toward endoderm: acts by mediating formation of H3K36me3 in distal promoter regions of FGFR3, leading to regulate transcription initiation of FGFR3 (By similarity). In addition to histones, also mediates methylation of other proteins, such as tubulins and STAT1 (PubMed:27518565, PubMed:28753426). Trimethylates 'Lys-40' of alpha-tubulins such as TUBA1B (alpha-TubK40me3); alpha-TubK40me3 is required for normal mitosis and cytokinesis and may be a specific tag in cytoskeletal remodeling (PubMed:27518565). Involved in interferon-alpha-induced antiviral defense by mediating both monomethylation of STAT1 at 'Lys-525' and catalyzing H3K36me3 on promoters of some interferon-stimulated genes (ISGs) to activate gene transcription (PubMed:28753426)\n(Microbial infection) Recruited to the promoters of adenovirus 12 E1A gene in case of infection, possibly leading to regulate its expression","source":"project UniProt records20261017/18"},{"partner":"KDM1A","hgnc":"HGNC:29079","core":true,"core_annotation":{"hgnc":"HGNC:29079","symbol_at_source":"KDM1A","accession":"O60341","function":"Histone modification erase","target":"histone","pmids":["16223729"],"complexes":"NuRD, BHC, SCL","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":641,"hub_weight":0.26899609689495085,"quality":0.75,"programmes":["pubmed:23455924"],"pmids":["23455924"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone demethylase that can demethylate both 'Lys-4' (H3K4me) and 'Lys-9' (H3K9me) of histone H3, thereby acting as a coactivator or a corepressor, depending on the context (PubMed:15620353, PubMed:15811342, PubMed:16079794, PubMed:16079795, PubMed:16140033, PubMed:16223729, PubMed:27292636). Acts by oxidizing the substrate by FAD to generate the corresponding imine that is subsequently hydrolyzed (PubMed:15620353, PubMed:15811342, PubMed:16079794, PubMed:21300290, PubMed:26214369). Acts as a corepressor by mediating demethylation of H3K4me, a specific tag for epigenetic transcriptional activation. Demethylates both mono- (H3K4me1) and di-methylated (H3K4me2) (PubMed:15620353, PubMed:20389281, PubMed:21300290, PubMed:23721412). May play a role in the repression of neuronal genes. Alone, it is unable to demethylate H3K4me on nucleosomes and requires the presence of RCOR1/CoREST to achieve such activity (PubMed:16079794, PubMed:16140033, PubMed:16885027, PubMed:21300290, PubMed:23721412). Also acts as a coactivator of androgen receptor (AR)-dependent transcription, by being recruited to AR target genes and mediating demethylation of H3K9me, a specific tag for epigenetic transcriptional repression. The presence of PRKCB in AR-containing complexes, which mediates phosphorylation of 'Thr-6' of histone H3 (H3T6ph), a specific tag that prevents demethylation H3K4me, prevents H3K4me demethylase activity of KDM1A (PubMed:16079795). Demethylates di-methylated 'Lys-370' of p53/TP53 which prevents interaction of p53/TP53 with TP53BP1 and represses p53/TP53-mediated transcriptional activation. Demethylates and stabilizes the DNA methylase DNMT1 (PubMed:29691401). Demethylates methylated 'Lys-42' and methylated 'Lys-117' of SOX2 (PubMed:29358331). Required for gastrulation during embryogenesis. Component of a RCOR/GFI/KDM1A/HDAC complex that suppresses, via histone deacetylase (HDAC) recruitment, a number of genes implicated in multilineage blood cell development (PubMed:16079794, PubMed:16140033). Facilitates epithelial-to-mesenchymal transition by acting as an effector of SNAI1-mediated transcription repression of epithelial markers E-cadherin/CDH1, CDN7 and KRT8 (PubMed:20562920, PubMed:27292636). Required for the maintenance of the silenced state of the SNAI1 target genes E-cadherin/CDH1 and CDN7 (PubMed:20389281). Required for the repression of GIPR expression (PubMed:34655521, PubMed:34906447)\nNeuron-specific histone demethylase that demethylates mono- and dimethylated 'Lys-20' of histone H4 (H4K20me1 and H4K20me2), a chromatin repressive mark (PubMed:26214369). This demethylation is crucial for the initiation and elongation of neuronal activity-regulated genes, required for spatial learning and memory (By similarity). Mediates H3K9me2 demethylation through cooperation with the supervillin protein (SVIL), and this H3K9 demethylase activity is essential for regulating gene expression during neuronal differentiation (PubMed:25684206)\nNeuron-specific histone demethylase that demethylates mono- and dimethylated 'Lys-20' of histone H4 (H4K20me1 and H4K20me2), a chromatin repressive mark (PubMed:26214369). This demethylation is crucial for the initiation and elongation of neuronal activity-regulated genes, required for spatial learning and memory (By similarity). Mediates H3K9me2 demethylation through cooperation with the supervillin protein (SVIL), and this H3K9 demethylase activity is essential for regulating gene expression during neuronal differentiation (PubMed:25684206)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"TIGD2":{"coreEvidence":[{"partner":"PARP3","hgnc":"HGNC:273","core":true,"core_annotation":{"hgnc":"HGNC:273","symbol_at_source":"PARP3","accession":"Q9Y6F1","function":"Polycomb group (PcG) protein","target":"#","pmids":["16924674"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":209,"hub_weight":0.4393747751637468,"quality":0.4,"programmes":["pubmed:40057523"],"pmids":["40057523"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome, centriole","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Mono-ADP-ribosyltransferase that mediates mono-ADP-ribosylation of target proteins and plays a key role in the response to DNA damage (PubMed:16924674, PubMed:19354255, PubMed:20064938, PubMed:21211721, PubMed:21270334, PubMed:23742272, PubMed:24598253, PubMed:25043379, PubMed:28447610). Mediates mono-ADP-ribosylation of glutamate, aspartate or lysine residues on target proteins (PubMed:20064938, PubMed:25043379). In contrast to PARP1 and PARP2, it is not able to mediate poly-ADP-ribosylation (PubMed:25043379). Involved in DNA repair by mediating mono-ADP-ribosylation of a limited number of acceptor proteins involved in chromatin architecture and in DNA metabolism, such as histone H2B, XRCC5 and XRCC6 (PubMed:16924674, PubMed:24598253). ADP-ribosylation follows DNA damage and appears as an obligatory step in a detection/signaling pathway leading to the reparation of DNA strand breaks (PubMed:16924674, PubMed:21211721, PubMed:21270334). Involved in single-strand break repair by catalyzing mono-ADP-ribosylation of histone H2B on 'Glu-2' (H2BE2ADPr) of nucleosomes containing nicked DNA (PubMed:27530147). Cooperates with the XRCC5-XRCC6 (Ku80-Ku70) heterodimer to limit end-resection thereby promoting accurate NHEJ (PubMed:24598253). Suppresses G-quadruplex (G4) structures in response to DNA damage (PubMed:28447610). Associates with a number of DNA repair factors and is involved in the response to exogenous and endogenous DNA strand breaks (PubMed:16924674, PubMed:21211721, PubMed:21270334). Together with APLF, promotes the retention of the LIG4-XRCC4 complex on chromatin and accelerate DNA ligation during non-homologous end-joining (NHEJ) (PubMed:21211721). May link the DNA damage surveillance network to the mitotic fidelity checkpoint (PubMed:16924674). Acts as a negative regulator of immunoglobulin class switch recombination, probably by controlling the level of AICDA /AID on the chromatin (By similarity). In addition to proteins, also able to ADP-ribosylate DNA: mediates DNA mono-ADP-ribosylation of DNA strand break termini via covalent addition of a single ADP-ribose moiety to a 5'- or 3'-terminal phosphate residues in DNA containing multiple strand breaks (PubMed:29361132, PubMed:29520010)","source":"project UniProt records20261017/18"},{"partner":"EP300","hgnc":"HGNC:3373","core":true,"core_annotation":{"hgnc":"HGNC:3373","symbol_at_source":"EP300","accession":"Q09472","function":"Histone modification write","target":"histone","pmids":["17065153"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":1188,"hub_weight":0.2009669677645352,"quality":0.65,"programmes":["pubmed:41611887"],"pmids":["41611887"],"assays":["capture_association"],"contexts":[],"partner_location":"Cytoplasm; Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Functions as a histone acetyltransferase and regulates transcription via chromatin remodeling (PubMed:23415232, PubMed:23934153, PubMed:40240600, PubMed:8945521). Acetylates all four core histones in nucleosomes (PubMed:23415232, PubMed:23934153, PubMed:8945521). Histone acetylation gives an epigenetic tag for transcriptional activation (PubMed:23415232, PubMed:23934153, PubMed:8945521). Mediates acetylation of histone H3 at 'Lys-122' (H3K122ac), a modification that localizes at the surface of the histone octamer and stimulates transcription, possibly by promoting nucleosome instability (PubMed:23415232). Mediates acetylation of histone H3 at 'Lys-18' and 'Lys-27' (H3K18ac and H3K27ac, respectively) (PubMed:21131905, PubMed:23911289). Also able to acetylate histone lysine residues that are already monomethylated on the same side chain to form N6-acetyl-N6-methyllysine (Kacme), an epigenetic mark of active chromatin associated with increased transcriptional initiation (PubMed:37731000). Catalyzes formation of histone H4 acetyl-methylated at 'Lys-5' and 'Lys-12' (H4K5acme and H4K12acme, respectively) (PubMed:37731000). In response to DNA damage, catalyzes acetylation of histone H1 at 'Lys-75' (H1K75ac) following histone H1 deamidation by CTPS1, increasing chromatin accessibility to facilitate the recruitment of DNA repair proteins (PubMed:40240600). Also functions as acetyltransferase for non-histone targets, such as ALX1, HDAC1, PRDM16, PRMT1, SIRT2, STAT3, ZNF76 or GLUL (PubMed:12929931, PubMed:15653507, PubMed:16285960, PubMed:16337145, PubMed:16762839, PubMed:18722353, PubMed:18782771, PubMed:26990986). Acetylates 'Lys-131' of ALX1 and acts as its coactivator (PubMed:12929931). Acetylates SIRT2 and is proposed to indirectly increase the transcriptional activity of p53/TP53 through acetylation and subsequent attenuation of SIRT2 deacetylase function (PubMed:18722353). Following DNA damage, forms a stress-responsive p53/TP53 coactivator complex with JMY which mediates p53/TP53 acetylation, thereby increasing p53/TP53-dependent transcription and apoptosis (PubMed:11511361, PubMed:15448695). Promotes chromatin acetylation in heat shock responsive HSP genes during the heat shock response (HSR), thereby stimulating HSR transcription (PubMed:18451878). Acetylates HDAC1 leading to its inactivation and modulation of transcription (PubMed:16762839). Acetylates 'Lys-247' of EGR2 (By similarity). Acts as a TFAP2A-mediated transcriptional coactivator in presence of CITED2 (PubMed:12586840). Plays a role as a coactivator of NEUROD1-dependent transcription of the secretin and p21 genes and controls terminal differentiation of cells in the intestinal epithelium. Promotes cardiac myocyte enlargement (PubMed:14752053). Can also mediate transcriptional repression. Acetylates FOXO1 and enhances its transcriptional activity (PubMed:15890677). Acetylates STAT3 at different sites, promoting both STAT3 dimerization and activation and recruitment to chromatin (PubMed:15653507, PubMed:16285960, PubMed:18782771). Acetylates BCL6 which disrupts its ability to recruit histone deacetylases and hinders its transcriptional repressor activity (PubMed:12402037). Participates in CLOCK or NPAS2-regulated rhythmic gene transcription; exhibits a circadian association with CLOCK or NPAS2, correlating with increase in PER1/2 mRNA and histone H3 acetylation on the PER1/2 promoter (PubMed:14645221). Acetylates MTA1 at 'Lys-626' which is essential for its transcriptional coactivator activity (PubMed:16617102). Acetylates XBP1 isoform 2; acetylation increases protein stability of XBP1 isoform 2 and enhances its transcriptional activity (PubMed:20955178). Acetylates PCNA; acetylation promotes removal of chromatin-bound PCNA and its degradation during nucleotide excision repair (NER) (PubMed:24939902). Acetylates MEF2D (PubMed:21030595). Acetylates and stabilizes ZBTB7B protein by antagonizing ubiquitin conjugation and degradation, this mechanism may be involved in CD4/CD8 lineage differentiation (PubMed:20810990). Acetylates GABPB1, impairing GABPB1 heterotetramerization and activity (By similarity). Acetylates PCK1 and promotes PCK1 anaplerotic activity (PubMed:30193097). Acetylates RXRA and RXRG (PubMed:17761950). Acetylates isoform M2 of PKM (PKM2), promoting its homodimerization and conversion into a protein kinase (PubMed:24120661). Acetylates RPTOR in response to leucine, leading to activation of the mTORC1 complex (PubMed:30197302, PubMed:32561715). Acetylates RICTOR, leading to activation of the mTORC2 complex (PubMed:22084251). Mediates cAMP-gene regulation by binding specifically to phosphorylated CREBBP (PubMed:8917528). In addition to protein acetyltransferase, can use different acyl-CoA substrates, such as (2E)-butenoyl-CoA (crotonyl-CoA), butanoyl-CoA (butyryl-CoA), 2-hydroxyisobutanoyl-CoA (2-hydroxyisobutyryl-CoA), lactoyl-CoA, propanoyl-CoA (propionyl-CoA) or isonicotinyl-CoA, and is able to mediate protein crotonylation, butyrylation, 2-hydroxyisobutyrylation, lactylation, propionylation or isonicotinylation, respectively (PubMed:17267393, PubMed:25818647, PubMed:29775581, PubMed:31645732, PubMed:34545082). Acts as a histone crotonyltransferase; crotonylation marks active promoters and enhancers and confers resistance to transcriptional repressors (PubMed:25818647). Histone crotonyltransferase activity is dependent on the concentration of (2E)-butenoyl-CoA (crotonyl-CoA) substrate and such activity is weak when (2E)-butenoyl-CoA (crotonyl-CoA) concentration is low (PubMed:25818647). Also acts as a histone butyryltransferase; butyrylation marks active promoters (PubMed:17267393). Catalyzes histone lactylation in macrophages by using lactoyl-CoA directly derived from endogenous or exogenous lactate, leading to stimulates gene transcription (PubMed:31645732). Acts as a protein-lysine 2-hydroxyisobutyryltransferase; regulates glycolysis by mediating 2-hydroxyisobutyrylation of glycolytic enzymes (PubMed:29775581). Functions as a transcriptional coactivator for SMAD4 in the TGF-beta signaling pathway (PubMed:25514493)\n(Microbial infection) In case of HIV-1 infection, it is recruited by the viral protein Tat. Regulates Tat's transactivating activity and may help inducing chromatin remodeling of proviral genes. Binds to and may be involved in the transforming capacity of the adenovirus E1A protein","source":"project UniProt records20261017/18"},{"partner":"H4C1","hgnc":"HGNC:4781","core":true,"core_annotation":{"hgnc":"HGNC:4781","symbol_at_source":"HIST1H4A","accession":"P62805","function":"Histone/protamine","target":"chromatin","pmids":[],"version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":1538,"hub_weight":0.17744336024691904,"quality":0.65,"programmes":["pubmed:30804502"],"pmids":["30804502"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Core component of nucleosome. Nucleosomes wrap and compact DNA into chromatin, limiting DNA accessibility to the cellular machineries which require DNA as a template. Histones thereby play a central role in transcription regulation, DNA repair, DNA replication and chromosomal stability. DNA accessibility is regulated via a complex set of post-translational modifications of histones, also called histone code, and nucleosome remodeling","source":"project UniProt records20261017/18"},{"partner":"SMARCA4","hgnc":"HGNC:11100","core":true,"core_annotation":{"hgnc":"HGNC:11100","symbol_at_source":"SMARCA4","accession":"P51532","function":"Histone modification read, TF","target":"histone","pmids":["17582821"],"complexes":"BAF, nBAF, npBAF, PBAF, SWI/SNF_Brg1(I), SWI/SNF_Brg1(II), SWI/SNF_Brm, SWI/SNF-like_EPAFa, WINAC, SWI/SNF-like EPAFB, bBAF, SWI/SNF BRM-BRG1, CREST-BRG1","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":753,"hub_weight":0.24953256425297482,"quality":0.65,"programmes":["pubmed:41611887"],"pmids":["41611887"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"ATPase involved in transcriptional activation and repression of select genes by chromatin remodeling (alteration of DNA-nucleosome topology). Component of SWI/SNF chromatin remodeling complexes that carry out key enzymatic activities, changing chromatin structure by altering DNA-histone contacts within a nucleosome in an ATP-dependent manner (PubMed:15075294, PubMed:29374058, PubMed:30339381, PubMed:32459350). Component of the CREST-BRG1 complex, a multiprotein complex that regulates promoter activation by orchestrating the calcium-dependent release of a repressor complex and the recruitment of an activator complex. In resting neurons, transcription of the c-FOS promoter is inhibited by SMARCA4-dependent recruitment of a phospho-RB1-HDAC repressor complex. Upon calcium influx, RB1 is dephosphorylated by calcineurin, which leads to release of the repressor complex. At the same time, there is increased recruitment of CREBBP to the promoter by a CREST-dependent mechanism, which leads to transcriptional activation. The CREST-BRG1 complex also binds to the NR2B promoter, and activity-dependent induction of NR2B expression involves the release of HDAC1 and recruitment of CREBBP (By similarity). Belongs to the neural progenitors-specific chromatin remodeling complex (npBAF complex) and the neuron-specific chromatin remodeling complex (nBAF complex). During neural development, a switch from a stem/progenitor to a postmitotic chromatin remodeling mechanism occurs as neurons exit the cell cycle and become committed to their adult state. The transition from proliferating neural stem/progenitor cells to postmitotic neurons requires a switch in subunit composition of the npBAF and nBAF complexes. As neural progenitors exit mitosis and differentiate into neurons, npBAF complexes which contain ACTL6A/BAF53A and PHF10/BAF45A, are exchanged for homologous alternative ACTL6B/BAF53B and DPF1/BAF45B or DPF3/BAF45C subunits in neuron-specific complexes (nBAF). The npBAF complex is essential for the self-renewal/proliferative capacity of the multipotent neural stem cells. The nBAF complex along with CREST plays a role regulating the activity of genes essential for dendrite growth. SMARCA4/BAF190A may promote neural stem cell self-renewal/proliferation by enhancing Notch-dependent proliferative signals, while concurrently making the neural stem cell insensitive to SHH-dependent differentiating cues (By similarity). Acts as a corepressor of ZEB1 to regulate E-cadherin transcription and is required for induction of epithelial-mesenchymal transition (EMT) by ZEB1 (PubMed:20418909). Binds via DLX1 to enhancers located in the intergenic region between DLX5 and DLX6 and this binding is stabilized by the long non-coding RNA (lncRNA) Evf2 (By similarity). Binds to RNA in a promiscuous manner (By similarity). In brown adipose tissue, involved in the regulation of thermogenic genes expression (By similarity)","source":"project UniProt records20261017/18"},{"partner":"SMARCB1","hgnc":"HGNC:11103","core":true,"core_annotation":{"hgnc":"HGNC:11103","symbol_at_source":"SMARCB1","accession":"Q12824","function":"Histone modification read","target":"histone","pmids":["21423274"],"complexes":"BAF, nBAF, npBAF, PBAF, SWI/SNF_Brg1(I), SWI/SNF_Brg1(II), SWI/SNF_Brm, SWI/SNF-like_EPAFa, WINAC, SWI/SNF-like EPAFB, bBAF, SWI/SNF BRM-BRG1","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":713,"hub_weight":0.2559898425245689,"quality":0.65,"programmes":["pubmed:41611887"],"pmids":["41611887"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Core component of the BAF (hSWI/SNF) complex. This ATP-dependent chromatin-remodeling complex plays important roles in cell proliferation and differentiation, in cellular antiviral activities and inhibition of tumor formation. The BAF complex is able to create a stable, altered form of chromatin that constrains fewer negative supercoils than normal. This change in supercoiling would be due to the conversion of up to one-half of the nucleosomes on polynucleosomal arrays into asymmetric structures, termed altosomes, each composed of 2 histones octamers. Stimulates in vitro the remodeling activity of SMARCA4/BRG1/BAF190A. Involved in activation of CSF1 promoter. Belongs to the neural progenitors-specific chromatin remodeling complex (npBAF complex) and the neuron-specific chromatin remodeling complex (nBAF complex). During neural development a switch from a stem/progenitor to a postmitotic chromatin remodeling mechanism occurs as neurons exit the cell cycle and become committed to their adult state. The transition from proliferating neural stem/progenitor cells to postmitotic neurons requires a switch in subunit composition of the npBAF and nBAF complexes. As neural progenitors exit mitosis and differentiate into neurons, npBAF complexes which contain ACTL6A/BAF53A and PHF10/BAF45A, are exchanged for homologous alternative ACTL6B/BAF53B and DPF1/BAF45B or DPF3/BAF45C subunits in neuron-specific complexes (nBAF). The npBAF complex is essential for the self-renewal/proliferative capacity of the multipotent neural stem cells. The nBAF complex along with CREST plays a role regulating the activity of genes essential for dendrite growth (By similarity). Plays a key role in cell-cycle control and causes cell cycle arrest in G0/G1","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"MSANTD3":{"coreEvidence":[{"partner":"BUB1","hgnc":"HGNC:1148","core":true,"core_annotation":{"hgnc":"HGNC:1148","symbol_at_source":"BUB1","accession":"O43683","function":"Histone modification write","target":"histone","pmids":["20929775"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":105,"hub_weight":0.5679618342470648,"quality":0.75,"programmes":["pubmed:24412244"],"pmids":["24412244"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus; Chromosome, centromere, kinetochore","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Serine/threonine-protein kinase that performs 2 crucial functions during mitosis: it is essential for spindle-assembly checkpoint signaling and for correct chromosome alignment. Has a key role in the assembly of checkpoint proteins at the kinetochore, being required for the subsequent localization of CENPF, BUB1B, CENPE and MAD2L1. Required for the kinetochore localization of PLK1. Required for centromeric enrichment of AUKRB in prometaphase. Plays an important role in defining SGO1 localization and thereby affects sister chromatid cohesion. Promotes the centromeric localization of TOP2A (PubMed:35044816). Acts as a substrate for anaphase-promoting complex or cyclosome (APC/C) in complex with its activator CDH1 (APC/C-Cdh1). Necessary for ensuring proper chromosome segregation and binding to BUB3 is essential for this function. Can regulate chromosome segregation in a kinetochore-independent manner. Can phosphorylate BUB3. The BUB1-BUB3 complex plays a role in the inhibition of APC/C when spindle-assembly checkpoint is activated and inhibits the ubiquitin ligase activity of APC/C by phosphorylating its activator CDC20. This complex can also phosphorylate MAD1L1. Kinase activity is essential for inhibition of APC/CCDC20 and for chromosome alignment but does not play a major role in the spindle-assembly checkpoint activity. Mediates cell death in response to chromosome missegregation and acts to suppress spontaneous tumorigenesis","source":"project UniProt records20261017/18"},{"partner":"H3-3A","hgnc":"HGNC:4764","core":true,"core_annotation":{"hgnc":"HGNC:4764","symbol_at_source":"H3F3A","accession":"P84243","function":"Histone/protamine","target":"chromatin","pmids":[],"version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":888,"hub_weight":0.23087854826980506,"quality":0.65,"programmes":["pubmed:29044188"],"pmids":["29044188"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Variant histone H3 which replaces conventional H3 in a wide range of nucleosomes in active genes. Constitutes the predominant form of histone H3 in non-dividing cells and is incorporated into chromatin independently of DNA synthesis. Deposited at sites of nucleosomal displacement throughout transcribed genes, suggesting that it represents an epigenetic imprint of transcriptionally active chromatin. Nucleosomes wrap and compact DNA into chromatin, limiting DNA accessibility to the cellular machineries which require DNA as a template. Histones thereby play a central role in transcription regulation, DNA repair, DNA replication and chromosomal stability. DNA accessibility is regulated via a complex set of post-translational modifications of histones, also called histone code, and nucleosome remodeling","source":"project UniProt records20261017/18"},{"partner":"H4C1","hgnc":"HGNC:4781","core":true,"core_annotation":{"hgnc":"HGNC:4781","symbol_at_source":"HIST1H4A","accession":"P62805","function":"Histone/protamine","target":"chromatin","pmids":[],"version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":1538,"hub_weight":0.17744336024691904,"quality":0.65,"programmes":["pubmed:30804502"],"pmids":["30804502"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Core component of nucleosome. Nucleosomes wrap and compact DNA into chromatin, limiting DNA accessibility to the cellular machineries which require DNA as a template. Histones thereby play a central role in transcription regulation, DNA repair, DNA replication and chromosomal stability. DNA accessibility is regulated via a complex set of post-translational modifications of histones, also called histone code, and nucleosome remodeling","source":"project UniProt records20261017/18"},{"partner":"SUV39H1","hgnc":"HGNC:11479","core":true,"core_annotation":{"hgnc":"HGNC:11479","symbol_at_source":"SUV39H1","accession":"O43463","function":"Histone modification write, Histone modification write","target":"histone","pmids":["10949293"],"complexes":"eNoSc","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":191,"hub_weight":0.45548751867427695,"quality":0.75,"programmes":["pubmed:23455924"],"pmids":["23455924"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus; Chromosome; Nucleus lamina; Nucleus, nucleoplasm; Chromosome, centromere; Cytoplasmic vesicle, phagosome lumen; Cell membrane","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone methyltransferase that specifically mediates trimethylation of 'Lys-9' of histone H3 (H3K9me3) using monomethylated H3 'Lys-9' (H3K9me1) as substrate (PubMed:10949293, PubMed:11242053, PubMed:18004385, PubMed:40440427). Also weakly methylates histone H1 (in vitro) (PubMed:10949293). H3 'Lys-9' trimethylation represents a specific tag for epigenetic transcriptional repression by recruiting HP1 (CBX1, CBX3 and/or CBX5) proteins to methylated histones (PubMed:10949293, PubMed:11242053, PubMed:18004385). Mainly functions in heterochromatin regions, thereby playing a central role in the establishment of constitutive heterochromatin at pericentric and telomere regions (By similarity). H3 'Lys-9' trimethylation is also required to direct DNA methylation at pericentric repeats (PubMed:41094145). SUV39H1 is targeted to histone H3 via its interaction with RB1 and is involved in many processes, such as repression of MYOD1-stimulated differentiation, regulation of the control switch for exiting the cell cycle and entering differentiation, repression by the PML-RARA fusion protein, BMP-induced repression, repression of switch recombination to IgA and regulation of telomere length (PubMed:11484059, PubMed:14765126, PubMed:16449642, PubMed:16818776, PubMed:16858404, PubMed:30111536). Involved in the maintenance of H3K9me3 mark following DNA replication, when histone marks are diluted: HP1 recognizes the preexisting H3K9me3 mark and serves as a platform to recruit SUV39H1 to modify the adjacent newly incorporated histones (PubMed:10949293, PubMed:11242053, PubMed:40440427). Component of the eNoSC (energy-dependent nucleolar silencing) complex, a complex that mediates silencing of rDNA in response to intracellular energy status and acts by recruiting histone-modifying enzymes (PubMed:18485871). The eNoSC complex is able to sense the energy status of cell: upon glucose starvation, elevation of NAD(+)/NADP(+) ratio activates SIRT1, leading to histone H3 deacetylation followed by dimethylation of H3 at 'Lys-9' (H3K9me2) by SUV39H1 and the formation of silent chromatin in the rDNA locus (PubMed:18485871). Recruited by the large PER complex to the E-box elements of the circadian target genes such as PER2 itself or PER1, contributes to the conversion of local chromatin to a heterochromatin-like repressive state through H3 'Lys-9' trimethylation (By similarity)\n(Microbial infection) Plays a role in defense against mycobacterial infections. Methylates M.tuberculosis HupB on 'Lys-140', probably methylates HupB of M.bovis also. Methylation has an inhibitory effect on mycobacterial growth in the host. Macrophages expressing about 60% SUV39H1 are slightly more susceptible to M.bovis or M.tuberculosis infection. Chaetocin (an inhibitor of this enzyme) increases macrophage survival of M.tuberculosis. This protein inhibits biofilm formation by M.tuberculosis via 'Lys-140' trimethylation","source":"project UniProt records20261017/18"},{"partner":"TP53BP1","hgnc":"HGNC:11999","core":true,"core_annotation":{"hgnc":"HGNC:11999","symbol_at_source":"TP53BP1","accession":"Q12888","function":"Histone modification read","target":"histone","pmids":["15525939"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":457,"hub_weight":0.3140371465106639,"quality":0.4,"programmes":["pubmed:29656893"],"pmids":["29656893"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome; Chromosome, centromere, kinetochore","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Double-strand break (DSB) repair protein involved in response to DNA damage, telomere dynamics and class-switch recombination (CSR) during antibody genesis (PubMed:12364621, PubMed:17190600, PubMed:21144835, PubMed:22553214, PubMed:23333306, PubMed:27153538, PubMed:28241136, PubMed:31135337, PubMed:37696958). Plays a key role in the repair of double-strand DNA breaks (DSBs) in response to DNA damage by promoting non-homologous end joining (NHEJ)-mediated repair of DSBs and specifically counteracting the function of the homologous recombination (HR) repair protein BRCA1 (PubMed:22553214, PubMed:23333306, PubMed:23727112, PubMed:27153538, PubMed:31135337). In response to DSBs, phosphorylation by ATM promotes interaction with RIF1 and dissociation from NUDT16L1/TIRR, leading to recruitment to DSBs sites (PubMed:28241136). Recruited to DSBs sites by recognizing and binding histone H2A monoubiquitinated at 'Lys-15' (H2AK15Ub) and histone H4 dimethylated at 'Lys-20' (H4K20me2), two histone marks that are present at DSBs sites (PubMed:17190600, PubMed:23760478, PubMed:27153538, PubMed:28241136). Required for immunoglobulin class-switch recombination (CSR) during antibody genesis, a process that involves the generation of DNA DSBs (PubMed:23345425). Participates in the repair and the orientation of the broken DNA ends during CSR (By similarity). In contrast, it is not required for classic NHEJ and V(D)J recombination (By similarity). Promotes NHEJ of dysfunctional telomeres via interaction with PAXIP1 (PubMed:23727112)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"THAP8":{"coreEvidence":[{"partner":"SETDB1","hgnc":"HGNC:10761","core":true,"core_annotation":{"hgnc":"HGNC:10761","symbol_at_source":"SETDB1","accession":"Q15047","function":"Histone modification write","target":"histone","pmids":["11959841"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":180,"hub_weight":0.4662524041201569,"quality":0.75,"programmes":["pubmed:16169070"],"pmids":["16169070"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus; Cytoplasm; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone methyltransferase that specifically trimethylates 'Lys-9' of histone H3 (H3K9me3) (PubMed:11959841, PubMed:12869583, PubMed:14536086, PubMed:27237050, PubMed:39096901). H3 'Lys-9' trimethylation represents a specific tag for epigenetic transcriptional repression by recruiting HP1 (CBX1, CBX3 and/or CBX5) proteins to methylated histones (PubMed:11959841, PubMed:12869583, PubMed:14536086, PubMed:27237050, PubMed:39096901). Mainly functions in euchromatin regions, thereby playing a central role in the silencing of euchromatic genes (PubMed:12869583, PubMed:14536086, PubMed:27237050, PubMed:39096901). H3 'Lys-9' trimethylation is coordinated with DNA methylation (PubMed:12869583, PubMed:14536086, PubMed:27237050, PubMed:39096901). Forms a complex with MBD1 and ATF7IP that represses transcription and couples DNA methylation and histone 'Lys-9' trimethylation (PubMed:14536086). Its activity is dependent on MBD1 and is heritably maintained through DNA replication by being recruited by CAF-1 (PubMed:14536086). SETDB1 is targeted to histone H3 by TRIM28/TIF1B, a factor recruited by KRAB zinc-finger proteins (PubMed:24623306). Required for HUSH-mediated heterochromatin formation and gene silencing (PubMed:27732843). Probably forms a corepressor complex required for activated KRAS-mediated promoter hypermethylation and transcriptional silencing of tumor suppressor genes (TSGs) or other tumor-related genes in colorectal cancer (CRC) cells (PubMed:24623306). Required to maintain a transcriptionally repressive state of genes in undifferentiated embryonic stem cells (ESCs) (PubMed:24623306). In ESCs, in collaboration with TRIM28, is also required for H3K9me3 and silencing of endogenous and introduced retroviruses in a DNA-methylation independent-pathway (PubMed:37938770). Associates at promoter regions of tumor suppressor genes (TSGs) leading to their gene silencing (PubMed:24623306). The SETDB1-TRIM28-ZNF274 complex may play a role in recruiting ATRX to the 3'-exons of zinc-finger coding genes with atypical chromatin signatures to establish or maintain/protect H3K9me3 at these transcriptionally active regions (PubMed:27029610). Also catalyzes mono- and dimethylation of 'Lys-9' of free histone H3 (H3K9me1 and H3K9me2) during translation in the cytoplasm, which is then transported to the nucleus and incorporated into nucleosomes (PubMed:26405197)\nLacks all domains required for histone methyltransferase activity","source":"project UniProt records20261017/18"},{"partner":"TP53","hgnc":"HGNC:11998","core":true,"core_annotation":{"hgnc":"HGNC:11998","symbol_at_source":"TP53","accession":"P04637","function":"Histone modification write cofactor, TF","target":"histone","pmids":["23870121"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":1691,"hub_weight":0.16946718543287687,"quality":0.75,"programmes":["pubmed:16169070"],"pmids":["16169070"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Cytoplasm; Nucleus; Nucleus, PML body; Endoplasmic reticulum; Mitochondrion matrix; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Nucleus; Cytoplasm; Nucleus; Cytoplasm; Nucleus; Cytoplasm; Nucleus; Cytoplasm; Nucleus; Cytoplasm; Nucleus; Cytoplasm; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Multifunctional transcription factor that induces cell cycle arrest, DNA repair or apoptosis upon binding to its target DNA sequence (PubMed:11025664, PubMed:12524540, PubMed:12810724, PubMed:15186775, PubMed:15340061, PubMed:17317671, PubMed:17349958, PubMed:19556538, PubMed:20673990, PubMed:20959462, PubMed:22726440, PubMed:24051492, PubMed:24652652, PubMed:35618207, PubMed:36634798, PubMed:38653238, PubMed:9840937). Acts as a tumor suppressor in many tumor types; induces growth arrest or apoptosis depending on the physiological circumstances and cell type (PubMed:11025664, PubMed:12524540, PubMed:12810724, PubMed:15186775, PubMed:15340061, PubMed:17189187, PubMed:17317671, PubMed:17349958, PubMed:19556538, PubMed:20673990, PubMed:20959462, PubMed:22726440, PubMed:24051492, PubMed:24652652, PubMed:38653238, PubMed:9840937). Negatively regulates cell division by controlling expression of a set of genes required for this process (PubMed:11025664, PubMed:12524540, PubMed:12810724, PubMed:15186775, PubMed:15340061, PubMed:17317671, PubMed:17349958, PubMed:19556538, PubMed:20673990, PubMed:20959462, PubMed:22726440, PubMed:24051492, PubMed:24652652, PubMed:9840937). One of the activated genes is an inhibitor of cyclin-dependent kinases. Apoptosis induction seems to be mediated either by stimulation of BAX and FAS antigen expression, or by repression of Bcl-2 expression (PubMed:12524540, PubMed:17189187). Its pro-apoptotic activity is activated via its interaction with PPP1R13B/ASPP1 or TP53BP2/ASPP2 (PubMed:12524540). However, this activity is inhibited when the interaction with PPP1R13B/ASPP1 or TP53BP2/ASPP2 is displaced by PPP1R13L/iASPP (PubMed:12524540). In cooperation with mitochondrial PPIF is involved in activating oxidative stress-induced necrosis; the function is largely independent of transcription. Induces the transcription of long intergenic non-coding RNA p21 (lincRNA-p21) and lincRNA-Mkln1. LincRNA-p21 participates in TP53-dependent transcriptional repression leading to apoptosis and seems to have an effect on cell-cycle regulation. Implicated in Notch signaling cross-over. Prevents CDK7 kinase activity when associated to CAK complex in response to DNA damage, thus stopping cell cycle progression. Isoform 2 enhances the transactivation activity of isoform 1 from some but not all TP53-inducible promoters. Isoform 4 suppresses transactivation activity and impairs growth suppression mediated by isoform 1. Isoform 7 inhibits isoform 1-mediated apoptosis. Regulates the circadian clock by repressing CLOCK-BMAL1-mediated transcriptional activation of PER2 (PubMed:24051492)","source":"project UniProt records20261017/18"},{"partner":"PRMT7","hgnc":"HGNC:25557","core":true,"core_annotation":{"hgnc":"HGNC:25557","symbol_at_source":"PRMT7","accession":"Q9NVM4","function":"Histone modification write","target":"histone","pmids":["15494416"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":35,"hub_weight":0.7669649888473704,"quality":0.65,"programmes":["BioPlex"],"pmids":["26186194","28514442","33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Cytoplasm, cytosol; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Arginine methyltransferase that can both catalyze the formation of omega-N monomethylarginine (MMA) and symmetrical dimethylarginine (sDMA), with a preference for the formation of MMA. Specifically mediates the symmetrical dimethylation of arginine residues in the small nuclear ribonucleoproteins Sm D1 (SNRPD1) and Sm D3 (SNRPD3); such methylation being required for the assembly and biogenesis of snRNP core particles. Specifically mediates the symmetric dimethylation of histone H4 'Arg-3' to form H4R3me2s. Plays a role in gene imprinting by being recruited by CTCFL at the H19 imprinted control region (ICR) and methylating histone H4 to form H4R3me2s, possibly leading to recruit DNA methyltransferases at these sites. May also play a role in embryonic stem cell (ESC) pluripotency. Also able to mediate the arginine methylation of histone H2A and myelin basic protein (MBP) in vitro; the relevance of such results is however unclear in vivo","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"CIMIP6":{"coreEvidence":[{"partner":"BABAM2","hgnc":"HGNC:1106","core":true,"core_annotation":{"hgnc":"HGNC:1106","symbol_at_source":"BRE","accession":"Q9NXR7","function":"Histone modification write cofactor","target":"histone","pmids":["14636569"],"complexes":"BRISC, BRCC, BRCA1-A","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":74,"hub_weight":0.6350006350009525,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Cytoplasm; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Component of the BRCA1-A complex, a complex that specifically recognizes 'Lys-63'-linked ubiquitinated histones H2A and H2AX at DNA lesions sites, leading to target the BRCA1-BARD1 heterodimer to sites of DNA damage at double-strand breaks (DSBs). The BRCA1-A complex also possesses deubiquitinase activity that specifically removes 'Lys-63'-linked ubiquitin on histones H2A and H2AX (PubMed:17525341, PubMed:19261746, PubMed:19261748, PubMed:19261749). In the BRCA1-A complex, it acts as an adapter that bridges the interaction between BABAM1/NBA1 and the rest of the complex, thereby being required for the complex integrity and modulating the E3 ubiquitin ligase activity of the BRCA1-BARD1 heterodimer (PubMed:19261748, PubMed:21282113). Component of the BRISC complex, a multiprotein complex that specifically cleaves 'Lys-63'-linked ubiquitin in various substrates (PubMed:19214193, PubMed:24075985, PubMed:25283148, PubMed:26195665). Within the BRISC complex, acts as an adapter that bridges the interaction between BABAM1/NBA1 and the rest of the complex, thereby being required for the complex integrity (PubMed:21282113). The BRISC complex is required for normal mitotic spindle assembly and microtubule attachment to kinetochores via its role in deubiquitinating NUMA1 (PubMed:26195665). The BRISC complex plays a role in interferon signaling via its role in the deubiquitination of the interferon receptor IFNAR1; deubiquitination increases IFNAR1 activity by enhancing its stability and cell surface expression (PubMed:24075985). Down-regulates the response to bacterial lipopolysaccharide (LPS) via its role in IFNAR1 deubiquitination (PubMed:24075985). May play a role in homeostasis or cellular differentiation in cells of neural, epithelial and germline origins. May also act as a death receptor-associated anti-apoptotic protein, which inhibits the mitochondrial apoptotic pathway. May regulate TNF signaling through its interactions with TNFRSF1A; however these effects may be indirect (PubMed:15465831)","source":"project UniProt records20261017/18"},{"partner":"NEK9","hgnc":"HGNC:18591","core":true,"core_annotation":{"hgnc":"HGNC:18591","symbol_at_source":"NEK9","accession":"Q8TD19","function":"Histone modification write","target":"histone","pmids":["14660563"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":98,"hub_weight":0.5812381937190964,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HCT116 colon carcinoma cell\", \"human-hct116\"]","dataset_cell:HCT116"],"partner_location":"Cytoplasm; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Pleiotropic regulator of mitotic progression, participating in the control of spindle dynamics and chromosome separation (PubMed:12101123, PubMed:12840024, PubMed:14660563, PubMed:19941817). Phosphorylates different histones, myelin basic protein, beta-casein, and BICD2 (PubMed:11864968). Phosphorylates histone H3 on serine and threonine residues and beta-casein on serine residues (PubMed:11864968). Important for G1/S transition and S phase progression (PubMed:12840024, PubMed:14660563, PubMed:19941817). Phosphorylates NEK6 and NEK7 and stimulates their activity by releasing the autoinhibitory functions of Tyr-108 and Tyr-97 respectively (PubMed:12840024, PubMed:14660563, PubMed:19941817, PubMed:26522158)","source":"project UniProt records20261017/18"},{"partner":"BRCC3","hgnc":"HGNC:24185","core":true,"core_annotation":{"hgnc":"HGNC:24185","symbol_at_source":"BRCC3","accession":"P46736","function":"Histone modification erase","target":"histone","pmids":["19202061"],"complexes":"BRISC, BRCA1-A","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":108,"hub_weight":0.562543950463012,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HCT116 colon carcinoma cell\", \"human-hct116\"]","dataset_cell:HCT116"],"partner_location":"Nucleus; Cytoplasm; Cytoplasm, cytoskeleton, spindle pole","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Metalloprotease that specifically cleaves 'Lys-63'-linked polyubiquitin chains (PubMed:19214193, PubMed:20656690, PubMed:24075985, PubMed:26344097). Does not have activity toward 'Lys-48'-linked polyubiquitin chains (PubMed:19214193, PubMed:20656690, PubMed:24075985, PubMed:26344097). Component of the BRCA1-A complex, a complex that specifically recognizes 'Lys-63'-linked ubiquitinated histones H2A and H2AX at DNA lesions sites, leading to target the BRCA1-BARD1 heterodimer to sites of DNA damage at double-strand breaks (DSBs) (PubMed:14636569, PubMed:16707425, PubMed:17525341, PubMed:19202061, PubMed:19261746, PubMed:19261748, PubMed:19261749). In the BRCA1-A complex, it specifically removes 'Lys-63'-linked ubiquitin on histones H2A and H2AX, antagonizing the RNF8-dependent ubiquitination at double-strand breaks (DSBs) (PubMed:20656690). Catalytic subunit of the BRISC complex, a multiprotein complex that specifically cleaves 'Lys-63'-linked ubiquitin in various substrates (PubMed:20656690, PubMed:24075985, PubMed:26195665, PubMed:26344097). Mediates the specific 'Lys-63'-specific deubiquitination associated with the COP9 signalosome complex (CSN), via the interaction of the BRISC complex with the CSN complex (PubMed:19214193). The BRISC complex is required for normal mitotic spindle assembly and microtubule attachment to kinetochores via its role in deubiquitinating NUMA1 (PubMed:26195665). Plays a role in interferon signaling via its role in the deubiquitination of the interferon receptor IFNAR1; deubiquitination increases IFNAR1 activity by enhancing its stability and cell surface expression (PubMed:24075985, PubMed:26344097). Acts as a regulator of the NLRP3 inflammasome by mediating deubiquitination of NLRP3, leading to NLRP3 inflammasome assembly (By similarity). Down-regulates the response to bacterial lipopolysaccharide (LPS) via its role in IFNAR1 deubiquitination (PubMed:24075985). Deubiquitinates HDAC1 and PWWP2B leading to their stabilization (By similarity)","source":"project UniProt records20261017/18"},{"partner":"BABAM1","hgnc":"HGNC:25008","core":true,"core_annotation":{"hgnc":"HGNC:25008","symbol_at_source":"BABAM1","accession":"Q9NWV8","function":"Histone modification erase cofactor","target":"histone","pmids":["19261746"],"complexes":"BRISC, BRCA1-A","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":69,"hub_weight":0.6482037235521644,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HCT116 colon carcinoma cell\", \"human-hct116\"]","IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HCT116","dataset_cell:HEK293T"],"partner_location":"Cytoplasm; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Component of the BRCA1-A complex, a complex that specifically recognizes 'Lys-63'-linked ubiquitinated histones H2A and H2AX at DNA lesions sites, leading to target the BRCA1-BARD1 heterodimer to sites of DNA damage at double-strand breaks (DSBs). The BRCA1-A complex also possesses deubiquitinase activity that specifically removes 'Lys-63'-linked ubiquitin on histones H2A and H2AX. In the BRCA1-A complex, it is required for the complex integrity and its localization at DSBs. Component of the BRISC complex, a multiprotein complex that specifically cleaves 'Lys-63'-linked ubiquitin in various substrates (PubMed:24075985, PubMed:26195665). In these 2 complexes, it is probably required to maintain the stability of BABAM2 and help the 'Lys-63'-linked deubiquitinase activity mediated by BRCC3/BRCC36 component. The BRISC complex is required for normal mitotic spindle assembly and microtubule attachment to kinetochores via its role in deubiquitinating NUMA1 (PubMed:26195665). Plays a role in interferon signaling via its role in the deubiquitination of the interferon receptor IFNAR1; deubiquitination increases IFNAR1 activity by enhancing its stability and cell surface expression (PubMed:24075985). Down-regulates the response to bacterial lipopolysaccharide (LPS) via its role in IFNAR1 deubiquitination (PubMed:24075985)","source":"project UniProt records20261017/18"},{"partner":"ABRAXAS2","hgnc":"HGNC:28975","core":true,"core_annotation":{"hgnc":"HGNC:28975","symbol_at_source":"FAM175B","accession":"Q15018","function":"Histone modification erase cofactor","target":"histone","pmids":["20656690"],"complexes":"BRISC","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":92,"hub_weight":0.5933908290969266,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HCT116 colon carcinoma cell\", \"human-hct116\"]","IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HCT116","dataset_cell:HEK293T"],"partner_location":"Cytoplasm; Nucleus; Cytoplasm, cytoskeleton, spindle pole; Cytoplasm, cytoskeleton","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Component of the BRISC complex, a multiprotein complex that specifically cleaves 'Lys-63'-linked polyubiquitin, leaving the last ubiquitin chain attached to its substrates (PubMed:19214193, PubMed:20032457, PubMed:20656690, PubMed:24075985). May act as a central scaffold protein that assembles the various components of the BRISC complex and retains them in the cytoplasm (PubMed:20656690). Plays a role in regulating the onset of apoptosis via its role in modulating 'Lys-63'-linked ubiquitination of target proteins (By similarity). Required for normal mitotic spindle assembly and microtubule attachment to kinetochores via its role in deubiquitinating NUMA1 (PubMed:26195665). Plays a role in interferon signaling via its role in the deubiquitination of the interferon receptor IFNAR1; deubiquitination increases IFNAR1 activities by enhancing its stability and cell surface expression (PubMed:24075985, PubMed:26344097). Down-regulates the response to bacterial lipopolysaccharide (LPS) via its role in IFNAR1 deubiquitination (PubMed:24075985). Required for normal induction of p53/TP53 in response to DNA damage (PubMed:25283148). Independent of the BRISC complex, promotes interaction between USP7 and p53/TP53, and thereby promotes deubiquitination of p53/TP53, preventing its degradation and resulting in increased p53/TP53-mediated transcription regulation and p53/TP53-dependent apoptosis in response to DNA damage (PubMed:25283148)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"MAB21L3":{"coreEvidence":[{"partner":"PHC2","hgnc":"HGNC:3183","core":true,"core_annotation":{"hgnc":"HGNC:3183","symbol_at_source":"PHC2","accession":"Q8IXK0","function":"Polycomb group (PcG) protein","target":"#","pmids":["16024804"],"complexes":"PRC1","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":150,"hub_weight":0.5,"quality":0.75,"programmes":["CCSB_binary_maps"],"pmids":["25416956"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Component of a Polycomb group (PcG) multiprotein PRC1-like complex, a complex class required to maintain the transcriptionally repressive state of many genes, including Hox genes, throughout development. PcG PRC1 complex acts via chromatin remodeling and modification of histones; it mediates monoubiquitination of histone H2A 'Lys-119', rendering chromatin heritably changed in its expressibility","source":"project UniProt records20261017/18"},{"partner":"SIRT1","hgnc":"HGNC:14929","core":true,"core_annotation":{"hgnc":"HGNC:14929","symbol_at_source":"SIRT1","accession":"Q96EB6","function":"Histone modification erase, Histone modification write cofactor","target":"histone","pmids":["15469825"],"complexes":"eNoSc","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":398,"hub_weight":0.33407655239053047,"quality":0.65,"programmes":["pubmed:40205054"],"pmids":["40205054"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens U2OS osteosarcoma cell\", \"human-u2os\"]"],"partner_location":"Nucleus, PML body; Cytoplasm; Nucleus; Nucleus, nucleoplasm; Cytoplasm; Mitochondrion","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"NAD-dependent protein deacetylase that links transcriptional regulation directly to intracellular energetics and participates in the coordination of several separated cellular functions such as cell cycle, response to DNA damage, metabolism, apoptosis and autophagy (PubMed:11672523, PubMed:12006491, PubMed:14976264, PubMed:14980222, PubMed:15126506, PubMed:15152190, PubMed:15205477, PubMed:15469825, PubMed:15692560, PubMed:16079181, PubMed:16166628, PubMed:16892051, PubMed:16998810, PubMed:17283066, PubMed:17290224, PubMed:17334224, PubMed:17505061, PubMed:17612497, PubMed:17620057, PubMed:17936707, PubMed:18203716, PubMed:18296641, PubMed:18662546, PubMed:18687677, PubMed:19188449, PubMed:19220062, PubMed:19364925, PubMed:19690166, PubMed:19934257, PubMed:20097625, PubMed:20100829, PubMed:20203304, PubMed:20375098, PubMed:20620956, PubMed:20670893, PubMed:20817729, PubMed:20955178, PubMed:21149730, PubMed:21245319, PubMed:21471201, PubMed:21504832, PubMed:21555002, PubMed:21698133, PubMed:21701047, PubMed:21775285, PubMed:21807113, PubMed:21841822, PubMed:21890893, PubMed:21947282, PubMed:22274616, PubMed:22918831, PubMed:24415752, PubMed:24824780, PubMed:29681526, PubMed:29765047, PubMed:30409912). Can modulate chromatin function through deacetylation of histones and can promote alterations in the methylation of histones and DNA, leading to transcriptional repression (PubMed:15469825). Deacetylates a broad range of transcription factors and coregulators, thereby regulating target gene expression positively and negatively (PubMed:14976264, PubMed:14980222, PubMed:15152190). Serves as a sensor of the cytosolic ratio of NAD(+)/NADH which is altered by glucose deprivation and metabolic changes associated with caloric restriction (PubMed:15205477). Is essential in skeletal muscle cell differentiation and in response to low nutrients mediates the inhibitory effect on skeletal myoblast differentiation which also involves 5'-AMP-activated protein kinase (AMPK) and nicotinamide phosphoribosyltransferase (NAMPT) (By similarity). Component of the eNoSC (energy-dependent nucleolar silencing) complex, a complex that mediates silencing of rDNA in response to intracellular energy status and acts by recruiting histone-modifying enzymes (PubMed:18485871). The eNoSC complex is able to sense the energy status of cell: upon glucose starvation, elevation of NAD(+)/NADP(+) ratio activates SIRT1, leading to histone H3 deacetylation followed by dimethylation of H3 at 'Lys-9' (H3K9me2) by SUV39H1 and the formation of silent chromatin in the rDNA locus (PubMed:18485871, PubMed:21504832). Deacetylates 'Lys-266' of SUV39H1, leading to its activation (PubMed:21504832). Inhibits skeletal muscle differentiation by deacetylating PCAF and MYOD1 (PubMed:19188449). Deacetylates H2A and 'Lys-26' of H1-4 (PubMed:15469825). Deacetylates 'Lys-16' of histone H4 (in vitro). Involved in NR0B2/SHP corepression function through chromatin remodeling: Recruited to LRH1 target gene promoters by NR0B2/SHP thereby stimulating histone H3 and H4 deacetylation leading to transcriptional repression (PubMed:20375098). Proposed to contribute to genomic integrity via positive regulation of telomere length; however, reports on localization to pericentromeric heterochromatin are conflicting (By similarity). Proposed to play a role in constitutive heterochromatin (CH) formation and/or maintenance through regulation of the available pool of nuclear SUV39H1 (PubMed:15469825, PubMed:18004385). Upon oxidative/metabolic stress decreases SUV39H1 degradation by inhibiting SUV39H1 polyubiquitination by MDM2 (PubMed:18004385, PubMed:21504832). This increase in SUV39H1 levels enhances SUV39H1 turnover in CH, which in turn seems to accelerate renewal of the heterochromatin which correlates with greater genomic integrity during stress response (PubMed:18004385, PubMed:21504832). Deacetylates 'Lys-382' of p53/TP53 and impairs its ability to induce transcription-dependent proapoptotic program and modulate cell senescence (PubMed:11672523, PubMed:12006491, PubMed:22542455). Deacetylates TAF1B and thereby represses rDNA transcription by the RNA polymerase I (By similarity). Deacetylates MYC, promotes the association of MYC with MAX and decreases MYC stability leading to compromised transformational capability (PubMed:19364925, PubMed:21807113). Deacetylates FOXO3 in response to oxidative stress thereby increasing its ability to induce cell cycle arrest and resistance to oxidative stress but inhibiting FOXO3-mediated induction of apoptosis transcriptional activity; also leading to FOXO3 ubiquitination and protesomal degradation (PubMed:14976264, PubMed:14980222, PubMed:21841822). Appears to have a similar effect on MLLT7/FOXO4 in regulation of transcriptional activity and apoptosis (PubMed:15126506). Deacetylates DNMT1; thereby impairs DNMT1 methyltransferase-independent transcription repressor activity, modulates DNMT1 cell cycle regulatory function and DNMT1-mediated gene silencing (PubMed:21947282). Deacetylates RELA/NF-kappa-B p65 thereby inhibiting its transactivating potential and augments apoptosis in response to TNF (PubMed:15152190). Deacetylates HIF1A, KAT5/TIP60, RB1 and HIC1 (PubMed:17283066, PubMed:17620057, PubMed:20100829, PubMed:20620956). Deacetylates FOXO1 resulting in its nuclear retention and enhancement of its transcriptional activity leading to increased gluconeogenesis in liver (PubMed:15692560). Inhibits E2F1 transcriptional activity and apoptotic function, possibly by deacetylation (PubMed:16892051). Involved in HES1- and HEY2-mediated transcriptional repression (PubMed:12535671). In cooperation with MYCN seems to be involved in transcriptional repression of DUSP6/MAPK3 leading to MYCN stabilization by phosphorylation at 'Ser-62' (PubMed:21698133). Deacetylates MEF2D (PubMed:16166628). Required for antagonist-mediated transcription suppression of AR-dependent genes which may be linked to local deacetylation of histone H3 (PubMed:17505061). Represses HNF1A-mediated transcription (By similarity). Required for the repression of ESRRG by CREBZF (PubMed:19690166). Deacetylates NR1H3 and NR1H2 and deacetylation of NR1H3 at 'Lys-434' positively regulates transcription of NR1H3:RXR target genes, promotes NR1H3 proteasomal degradation and results in cholesterol efflux; a promoter clearing mechanism after reach round of transcription is proposed (PubMed:17936707). Involved in lipid metabolism: deacetylates LPIN1, thereby inhibiting diacylglycerol synthesis (PubMed:20817729, PubMed:29765047). Implicated in regulation of adipogenesis and fat mobilization in white adipocytes by repression of PPARG which probably involves association with NCOR1 and SMRT/NCOR2 (By similarity). Deacetylates p300/EP300 and PRMT1 (By similarity). Deacetylates ACSS2 leading to its activation, and HMGCS1 deacetylation (PubMed:21701047). Involved in liver and muscle metabolism. Through deacetylation and activation of PPARGC1A is required to activate fatty acid oxidation in skeletal muscle under low-glucose conditions and is involved in glucose homeostasis (PubMed:23142079). Involved in regulation of PPARA and fatty acid beta-oxidation in liver. Involved in positive regulation of insulin secretion in pancreatic beta cells in response to glucose; the function seems to imply transcriptional repression of UCP2. Proposed to deacetylate IRS2 thereby facilitating its insulin-induced tyrosine phosphorylation. Deacetylates SREBF1 isoform SREBP-1C thereby decreasing its stability and transactivation in lipogenic gene expression (PubMed:17290224, PubMed:20817729). Involved in DNA damage response by repressing genes which are involved in DNA repair, such as XPC and TP73, deacetylating XRCC6/Ku70, and facilitating recruitment of additional factors to sites of damaged DNA, such as SIRT1-deacetylated NBN can recruit ATM to initiate DNA repair and SIRT1-deacetylated XPA interacts with RPA2 (PubMed:15205477, PubMed:16998810, PubMed:17334224, PubMed:17612497, PubMed:20670893, PubMed:21149730). Also involved in DNA repair of DNA double-strand breaks by homologous recombination and specifically single-strand annealing independently of XRCC6/Ku70 and NBN (PubMed:15205477, PubMed:17334224, PubMed:20097625). Promotes DNA double-strand breaks by mediating deacetylation of SIRT6 (PubMed:32538779). Transcriptional suppression of XPC probably involves an E2F4:RBL2 suppressor complex and protein kinase B (AKT) signaling. Transcriptional suppression of TP73 probably involves E2F4 and PCAF. Deacetylates WRN thereby regulating its helicase and exonuclease activities and regulates WRN nuclear translocation in response to DNA damage (PubMed:18203716). Deacetylates APEX1 at 'Lys-6' and 'Lys-7' and stimulates cellular AP endonuclease activity by promoting the association of APEX1 to XRCC1 (PubMed:19934257). Catalyzes deacetylation of ERCC4/XPF, thereby impairing interaction with ERCC1 and nucleotide excision repair (NER) (PubMed:32034146). Increases p53/TP53-mediated transcription-independent apoptosis by blocking nuclear translocation of cytoplasmic p53/TP53 and probably redirecting it to mitochondria. Deacetylates XRCC6/Ku70 at 'Lys-539' and 'Lys-542' causing it to sequester BAX away from mitochondria thereby inhibiting stress-induced apoptosis. Is involved in autophagy, presumably by deacetylating ATG5, ATG7 and MAP1LC3B/ATG8 (PubMed:18296641). Deacetylates AKT1 which leads to enhanced binding of AKT1 and PDK1 to PIP3 and promotes their activation (PubMed:21775285). Acts as a regulator of AMPK activity in response to calorie restriction: deacetylates the ATP6V1E1 subunit of the V-ATPase complex following activation by TULP3, leading to (1) V-ATPase complex inhibition on lysosomes and (2) AMPK activation via the AXIN1-STK11/LKB1 axis (By similarity). Proposed to play role in regulation of STK11/LBK1-dependent AMPK signaling pathways implicated in cellular senescence which seems to involve the regulation of the acetylation status of STK11/LBK1. Can deacetylate STK11/LBK1 and thereby increase its activity, cytoplasmic localization and association with STRAD; however, the relevance of such activity in normal cells is unclear (PubMed:18687677, PubMed:20203304). In endothelial cells is shown to inhibit STK11/LBK1 activity and to promote its degradation. Deacetylates SMAD7 at 'Lys-64' and 'Lys-70' thereby promoting its degradation. Deacetylates CIITA and augments its MHC class II transactivation and contributes to its stability (PubMed:21890893). Deacetylates MECOM/EVI1 (PubMed:21555002). Deacetylates PML at 'Lys-487' and this deacetylation promotes PML control of PER2 nuclear localization (PubMed:22274616). During the neurogenic transition, represses selective NOTCH1-target genes through histone deacetylation in a BCL6-dependent manner and leading to neuronal differentiation. Regulates the circadian expression of several core clock genes, including BMAL1, RORC, PER2 and CRY1 and plays a critical role in maintaining a controlled rhythmicity in histone acetylation, thereby contributing to circadian chromatin remodeling (PubMed:18662546). Deacetylates BMAL1 and histones at the circadian gene promoters in order to facilitate repression by inhibitory components of the circadian oscillator (By similarity). Deacetylates PER2, facilitating its ubiquitination and degradation by the proteasome (By similarity). Protects cardiomyocytes against palmitate-induced apoptosis (By similarity). Deacetylates XBP1 isoform 2; deacetylation decreases protein stability of XBP1 isoform 2 and inhibits its transcriptional activity (PubMed:20955178). Deacetylates PCK1 and directs its activity toward phosphoenolpyruvate production promoting gluconeogenesis (PubMed:30193097). Involved in the CCAR2-mediated regulation of PCK1 and NR1D1 (PubMed:24415752). Deacetylates CTNB1 at 'Lys-49' (PubMed:24824780). In POMC (pro-opiomelanocortin) neurons, required for leptin-induced activation of PI3K signaling (By similarity). Deacetylates SOX9; promoting SOX9 nuclear localization and transactivation activity (By similarity). Involved in the regulation of centrosome duplication: deacetylates CENATAC in G1 phase, allowing for SASS6 accumulation on the centrosome and subsequent procentriole assembly (PubMed:31722219). Deacetylates NDC80/HEC1 (PubMed:30409912). In addition to protein deacetylase activity, also acts as a protein-lysine deacylase by mediating protein delactylation, depropionylation and decrotonylation (PubMed:28497810, PubMed:38512451). Mediates depropionylation of Osterix (SP7) (By similarity). Catalyzes decrotonylation of histones; it however does not represent a major histone decrotonylase (PubMed:28497810). Mediates protein delactylation of TEAD1 and YAP1 (PubMed:38512451)\nDeacetylates 'Lys-382' of p53/TP53, however with lower activity than isoform 1. In combination, the two isoforms exert an additive effect. Isoform 2 regulates p53/TP53 expression and cellular stress response and is in turn repressed by p53/TP53 presenting a SIRT1 isoform-dependent auto-regulatory loop\nCatalytically inactive 75SirT1 may be involved in regulation of apoptosis. May be involved in protecting chondrocytes from apoptotic death by associating with cytochrome C and interfering with apoptosome assembly\n(Microbial infection) In case of HIV-1 infection, interacts with and deacetylates the viral Tat protein. The viral Tat protein inhibits SIRT1 deacetylation activity toward RELA/NF-kappa-B p65, thereby potentiates its transcriptional activity and SIRT1 is proposed to contribute to T-cell hyperactivation during infection","source":"project UniProt records20261017/18"},{"partner":"CHD8","hgnc":"HGNC:20153","core":true,"core_annotation":{"hgnc":"HGNC:20153","symbol_at_source":"CHD8","accession":"Q9HCK8","function":"Chromatin remodeling","target":"chromatin","pmids":["18378692"],"complexes":"CHD8, MLL2/3, MLL4/WBP7","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":375,"hub_weight":0.3429971702850177,"quality":0.65,"programmes":["pubmed:40205054"],"pmids":["40205054"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens U2OS osteosarcoma cell\", \"human-u2os\"]"],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"ATP-dependent chromatin-remodeling factor, it slides nucleosomes along DNA; nucleosome sliding requires ATP (PubMed:28533432). Acts as a transcription repressor by remodeling chromatin structure and recruiting histone H1 to target genes. Suppresses p53/TP53-mediated apoptosis by recruiting histone H1 and preventing p53/TP53 transactivation activity. Acts as a negative regulator of Wnt signaling pathway by regulating beta-catenin (CTNNB1) activity. Negatively regulates CTNNB1-targeted gene expression by being recruited specifically to the promoter regions of several CTNNB1 responsive genes. Involved in both enhancer blocking and epigenetic remodeling at chromatin boundary via its interaction with CTCF. Acts as a suppressor of STAT3 activity by suppressing the LIF-induced STAT3 transcriptional activity. Also acts as a transcription activator via its interaction with ZNF143 by participating in efficient U6 RNA polymerase III transcription. Regulates alternative splicing of a core group of genes involved in neuronal differentiation, cell cycle and DNA repair. Enables H3K36me3-coupled transcription elongation and co-transcriptional RNA processing likely via interaction with HNRNPL","source":"project UniProt records20261017/18"},{"partner":"CHD7","hgnc":"HGNC:20626","core":true,"core_annotation":{"hgnc":"HGNC:20626","symbol_at_source":"CHD7","accession":"Q9P2D1","function":"Chromatin remodeling","target":"chromatin","pmids":["5201778"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":157,"hub_weight":0.49147318718299043,"quality":0.65,"programmes":["pubmed:40205054"],"pmids":["40205054"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens U2OS osteosarcoma cell\", \"human-u2os\"]"],"partner_location":"Nucleus; Nucleus, nucleolus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"ATP-dependent chromatin-remodeling factor, slides nucleosomes along DNA; nucleosome sliding requires ATP (PubMed:28533432). Probable transcription regulator. May be involved in the in 45S precursor rRNA production","source":"project UniProt records20261017/18"},{"partner":"CHD9","hgnc":"HGNC:25701","core":true,"core_annotation":{"hgnc":"HGNC:25701","symbol_at_source":"CHD9","accession":"Q3L8U1","function":"Chromatin remodeling","target":"DNA","pmids":["16554032"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":64,"hub_weight":0.6622661785325219,"quality":0.65,"programmes":["pubmed:40205054"],"pmids":["40205054"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens U2OS osteosarcoma cell\", \"human-u2os\"]"],"partner_location":"Cytoplasm; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Probable ATP-dependent chromatin-remodeling factor. Acts as a transcriptional coactivator for PPARA and possibly other nuclear receptors. Has DNA-dependent ATPase activity and binds to A/T-rich DNA. Associates with A/T-rich regulatory regions in promoters of genes that participate in the differentiation of progenitors during osteogenesis (By similarity)","source":"project UniProt records20261017/18"},{"partner":"INO80E","hgnc":"HGNC:26905","core":true,"core_annotation":{"hgnc":"HGNC:26905","symbol_at_source":"INO80E","accession":"Q8NBZ0","function":"Chromatin remodeling cofactor","target":"chromatin","pmids":["21303910"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":88,"hub_weight":0.601929265428846,"quality":0.75,"programmes":["CCSB_binary_maps"],"pmids":["32296183"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Putative regulatory component of the chromatin remodeling INO80 complex which is involved in transcriptional regulation, DNA replication and probably DNA repair","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"PRR3":{"coreEvidence":[{"partner":"UHRF1","hgnc":"HGNC:12556","core":true,"core_annotation":{"hgnc":"HGNC:12556","symbol_at_source":"UHRF1","accession":"Q96T88","function":"Histone modification read, Histone modification write cofactor","target":"histone, DNA","pmids":["17967883"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":194,"hub_weight":0.45267873021259264,"quality":0.65,"programmes":["pubmed:40205054"],"pmids":["40205054"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens U2OS osteosarcoma cell\", \"human-u2os\"]"],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"E3 ubiquitin-protein ligase that acts as a key epigenetic regulator by bridging DNA methylation and chromatin modification (PubMed:10646863, PubMed:15009091, PubMed:19056828, PubMed:23022729, PubMed:24013172, PubMed:27595565, PubMed:30104358, PubMed:30392929, PubMed:30392931, PubMed:39607687). Plays a key role in DNA methylation inheritance by promoting recruitment of DNMT1 to hemimethylated DNA and ensure faithful propagation of the DNA methylation patterns through DNA replication (PubMed:23022729, PubMed:24013172, PubMed:27595565, PubMed:30104358, PubMed:30392929, PubMed:30392931, PubMed:39607687). Acts both as a histone reader and writer: specifically recognizes and binds (1) hemimethylated DNA at replication forks and (2) histone H3 trimethylated at 'Lys-9' and unmethylated at 'Arg-2' (H3K9me3 and H3R2me0, respectively), thereby activating its E3 ubiquitin-protein ligase activity (PubMed:15361834, PubMed:17673620, PubMed:17967883, PubMed:18772889, PubMed:21745816, PubMed:21777816, PubMed:22100450, PubMed:22837395, PubMed:23022729, PubMed:27595565, PubMed:30104358). UHRF1 then mediates histone H3 'Lys-18' monoubiquitination (H3K18ub), a docking site for DNMT1, leading to DNMT1 recruitment and replication-coupled DNA methylation maintenance (PubMed:27595565). Also mediates histone H3 'Lys-14' and 'Lys-23' ubiquitination (H3K14ub and H3K23ub) at lower level (PubMed:24013172, PubMed:27595565). Histone ubiquitin ligase activity also stimulates the methyltransferase activity of SUV39H1 and/or SUV39H2, promoting accumulation of H3K9me3 histone mark to reinformce heterochromatin state (PubMed:39631394). Enriched in pericentric heterochromatin where it recruits different chromatin modifiers required for this chromatin replication. Also localizes to euchromatic regions where it negatively regulates transcription possibly by impacting DNA methylation and histone modifications (PubMed:21777816). Plays a role in DNA repair by cooperating with UHRF2 to ensure recruitment of FANCD2 to interstrand cross-links (ICLs) leading to FANCD2 activation (PubMed:30335751). Also ubiquitinates non-histone proteins, such as histone H3, KIF11 and PML (PubMed:22945642, PubMed:37728657). Acts as a critical player of proper spindle architecture by catalyzing the 'Lys-63'-linked ubiquitination of KIF11, thereby controlling KIF11 localization on the spindle (PubMed:37728657)","source":"project UniProt records20261017/18"},{"partner":"BRPF3","hgnc":"HGNC:14256","core":true,"core_annotation":{"hgnc":"HGNC:14256","symbol_at_source":"BRPF3","accession":"Q9ULD4","function":"Histone modification write cofactor","target":"histone","pmids":["18794358"],"complexes":"MOZ/MORF","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":131,"hub_weight":0.5255883312276367,"quality":0.65,"programmes":["pubmed:31753913"],"pmids":["31753913"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Scaffold subunit of various histone acetyltransferase (HAT) complexes, such as the MOZ/MORF and HBO1 complexes, which have a histone H3 acetyltransferase activity (PubMed:16387653, PubMed:26620551, PubMed:26677226). Plays a role in DNA replication initiation by directing KAT7/HBO1 specificity towards histone H3 'Lys-14' acetylation (H3K14ac), thereby facilitating the activation of replication origins (PubMed:26620551). Component of the MOZ/MORF complex which has a histone H3 acetyltransferase activity (PubMed:16387653)","source":"project UniProt records20261017/18"},{"partner":"MACROH2A2","hgnc":"HGNC:14453","core":true,"core_annotation":{"hgnc":"HGNC:14453","symbol_at_source":"H2AFY2","accession":"Q9P0M6","function":"Histone/protamine","target":"chromatin","pmids":[],"version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":229,"hub_weight":0.42333375666730166,"quality":0.65,"programmes":["pubmed:40205054"],"pmids":["40205054"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens U2OS osteosarcoma cell\", \"human-u2os\"]"],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Variant histone H2A which replaces conventional H2A in a subset of nucleosomes where it represses transcription. Nucleosomes wrap and compact DNA into chromatin, limiting DNA accessibility to the cellular machineries which require DNA as a template. Histones thereby play a central role in transcription regulation, DNA repair, DNA replication and chromosomal stability. DNA accessibility is regulated via a complex set of post-translational modifications of histones, also called histone code, and nucleosome remodeling. May be involved in stable X chromosome inactivation","source":"project UniProt records20261017/18"},{"partner":"APOBEC3B","hgnc":"HGNC:17352","core":true,"core_annotation":{"hgnc":"HGNC:17352","symbol_at_source":"APOBEC3B","accession":"Q9UH17","function":"DNA modification, RNA modification","target":"DNA, RNA","pmids":["22001110"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":67,"hub_weight":0.6537204504606134,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HCT116 colon carcinoma cell\", \"human-hct116\"]","dataset_cell:HCT116"],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"DNA deaminase (cytidine deaminase) which acts as an inhibitor of retrovirus replication and retrotransposon mobility via deaminase-dependent and -independent mechanisms. After the penetration of retroviral nucleocapsids into target cells of infection and the initiation of reverse transcription, it can induce the conversion of cytosine to uracil in the minus-sense single-strand viral DNA, leading to G-to-A hypermutations in the subsequent plus-strand viral DNA. The resultant detrimental levels of mutations in the proviral genome, along with a deamination-independent mechanism that works prior to the proviral integration, together exert efficient antiretroviral effects in infected target cells. Selectively targets single-stranded DNA and does not deaminate double-stranded DNA or single- or double-stranded RNA. Exhibits antiviral activity against simian immunodeficiency virus (SIV), hepatitis B virus (HBV) and human T-cell leukemia virus type 1 (HTLV-1) and may inhibit the mobility of LTR and non-LTR retrotransposons","source":"project UniProt records20261017/18"},{"partner":"APOBEC3C","hgnc":"HGNC:17353","core":true,"core_annotation":{"hgnc":"HGNC:17353","symbol_at_source":"APOBEC3C","accession":"Q9NRW3","function":"DNA modification, RNA modification","target":"DNA, RNA","pmids":["22001110"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":171,"hub_weight":0.4756514941544941,"quality":0.75,"programmes":["CCSB_binary_maps","pubmed:34133714"],"pmids":["32296183","34133714"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"DNA deaminase (cytidine deaminase) which acts as an inhibitor of retrovirus replication and retrotransposon mobility via deaminase-dependent and -independent mechanisms. After the penetration of retroviral nucleocapsids into target cells of infection and the initiation of reverse transcription, it can induce the conversion of cytosine to uracil in the minus-sense single-strand viral DNA, leading to G-to-A hypermutations in the subsequent plus-strand viral DNA. The resultant detrimental levels of mutations in the proviral genome, along with a deamination-independent mechanism that works prior to the proviral integration, together exert efficient antiretroviral effects in infected target cells. Selectively targets single-stranded DNA and does not deaminate double-stranded DNA or single- or double-stranded RNA. Exhibits antiviral activity against simian immunodeficiency virus (SIV), hepatitis B virus (HBV), herpes simplex virus 1 (HHV-1) and Epstein-Barr virus (EBV) and may inhibit the mobility of LTR and non-LTR retrotransposons. May also play a role in the epigenetic regulation of gene expression through the process of active DNA demethylation","source":"project UniProt records20261017/18"},{"partner":"APOBEC3F","hgnc":"HGNC:17356","core":true,"core_annotation":{"hgnc":"HGNC:17356","symbol_at_source":"APOBEC3F","accession":"Q8IUX4","function":"DNA modification, RNA modification","target":"DNA, RNA","pmids":["22001110"],"complexes":"APOB_mRNA_editosome","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":61,"hub_weight":0.6711560552140243,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HCT116 colon carcinoma cell\", \"human-hct116\"]","IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HCT116","dataset_cell:HEK293T"],"partner_location":"Cytoplasm; Cytoplasm, P-body","partner_has_nuclear_annotation":false,"partner_location_assessed":true,"function":"DNA deaminase (cytidine deaminase) which acts as an inhibitor of retrovirus replication and retrotransposon mobility via deaminase-dependent and -independent mechanisms (PubMed:15141007, PubMed:17121840, PubMed:20062055, PubMed:22915799, PubMed:34774569). Exhibits antiviral activity against viruse such as HIV-1 or HIV-2 (PubMed:15141007, PubMed:15152192, PubMed:17121840, PubMed:20219927, PubMed:21835787, PubMed:22807680, PubMed:23001005, PubMed:23097438, PubMed:23152537, PubMed:34774569). After the penetration of retroviral nucleocapsids into target cells of infection and the initiation of reverse transcription, it can induce the conversion of cytosine to uracil in the minus-sense single-strand viral DNA, leading to G-to-A hypermutations in the subsequent plus-strand viral DNA (PubMed:15141007). The resultant detrimental levels of mutations in the proviral genome, along with a deamination-independent mechanism that works prior to the proviral integration, together exert efficient antiretroviral effects in infected target cells (PubMed:15141007). Selectively targets single-stranded DNA and does not deaminate double-stranded DNA or single- or double-stranded RNA (PubMed:15141007). Exhibits antiviral activity also against hepatitis B virus (HBV), equine infectious anemia virus (EIAV), xenotropic MuLV-related virus (XMRV) and simian foamy virus (SFV) and may inhibit the mobility of LTR and non-LTR retrotransposons (PubMed:16378963, PubMed:16527742, PubMed:19458006, PubMed:20062055, PubMed:20335265). May also play a role in the epigenetic regulation of gene expression through the process of active DNA demethylation (PubMed:21496894)","source":"project UniProt records20261017/18"},{"partner":"ASF1A","hgnc":"HGNC:20995","core":true,"core_annotation":{"hgnc":"HGNC:20995","symbol_at_source":"ASF1A","accession":"Q9Y294","function":"Histone chaperone","target":"histone","pmids":["10759893"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":234,"hub_weight":0.4195906791483445,"quality":0.75,"programmes":["CCSB_binary_maps"],"pmids":["25416956","32296183"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone chaperone that facilitates histone deposition and histone exchange and removal during nucleosome assembly and disassembly (PubMed:10759893, PubMed:11897662, PubMed:12842904, PubMed:14718166, PubMed:15664198, PubMed:16151251, PubMed:21454524). Cooperates with chromatin assembly factor 1 (CAF-1) to promote replication-dependent chromatin assembly and with HIRA to promote replication-independent chromatin assembly (PubMed:11897662, PubMed:14718166, PubMed:15664198). Promotes homologous recombination-mediated repair of double-strand breaks (DSBs) at stalled or collapsed replication forks: acts by mediating histone replacement at DSBs, leading to recruitment of the MMS22L-TONSL complex and subsequent loading of RAD51 (PubMed:29478807). Also involved in the nuclear import of the histone H3-H4 dimer together with importin-4 (IPO4): specifically recognizes and binds newly synthesized histones with the monomethylation of H3 'Lys-9' and acetylation at 'Lys-14' (H3K9me1K14ac) marks, and diacetylation at 'Lys-5' and 'Lys-12' of H4 (H4K5K12ac) marks in the cytosol (PubMed:21454524, PubMed:29408485). Required for the formation of senescence-associated heterochromatin foci (SAHF) and efficient senescence-associated cell cycle exit (PubMed:15621527)","source":"project UniProt records20261017/18"},{"partner":"LRWD1","hgnc":"HGNC:21769","core":true,"core_annotation":{"hgnc":"HGNC:21769","symbol_at_source":"LRWD1","accession":"Q9UFC0","function":"Chromatin remodeling","target":"histone, DNA","pmids":["20932478"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":105,"hub_weight":0.5679618342470648,"quality":0.65,"programmes":["pubmed:26496610"],"pmids":["26496610"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus; Chromosome, centromere; Chromosome, telomere; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Chromosome, centromere, kinetochore","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Required for G1/S transition. Recruits and stabilizes the origin recognition complex (ORC) onto chromatin during G1 to establish pre-replication complex (preRC) and to heterochromatic sites in post-replicated cells. Binds a combination of DNA and histone methylation repressive marks on heterochromatin. Binds histone H3 and H4 trimethylation marks H3K9me3, H3K27me3 and H4K20me3 in a cooperative manner with DNA methylation. Required for silencing of major satellite repeats. May be important ORC2, ORC3 and ORC4 stability","source":"project UniProt records20261017/18"},{"partner":"HP1BP3","hgnc":"HGNC:24973","core":true,"core_annotation":{"hgnc":"HGNC:24973","symbol_at_source":"HP1BP3","accession":"Q5SSJ5","function":"Chromatin remodeling","target":"chromatin","pmids":["25100860"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":310,"hub_weight":0.37267799624996495,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Component of heterochromatin that maintains heterochromatin integrity during G1/S progression and regulates the duration of G1 phase to critically influence cell proliferative capacity (PubMed:24830416). Mediates chromatin condensation during hypoxia, leading to increased tumor cell viability, radio-resistance, chemo-resistance and self-renewal (PubMed:25100860)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"FLYWCH2":{"coreEvidence":[{"partner":"DDB2","hgnc":"HGNC:2718","core":true,"core_annotation":{"hgnc":"HGNC:2718","symbol_at_source":"DDB2","accession":"Q92466","function":"Histone modification write cofactor","target":"histone","pmids":["16678110"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":211,"hub_weight":0.43768810953240855,"quality":0.4,"programmes":["pubmed:41932313"],"pmids":["41932313"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Protein, which is both involved in DNA repair and protein ubiquitination, as part of the UV-DDB complex and DCX (DDB1-CUL4-X-box) complexes, respectively (PubMed:10882109, PubMed:11278856, PubMed:11705987, PubMed:12732143, PubMed:15882621, PubMed:16473935, PubMed:18593899, PubMed:32789493, PubMed:9892649). Core component of the UV-DDB complex (UV-damaged DNA-binding protein complex), a complex that recognizes UV-induced DNA damage and recruit proteins of the nucleotide excision repair pathway (the NER pathway) to initiate DNA repair (PubMed:10882109, PubMed:11278856, PubMed:11705987, PubMed:12944386, PubMed:14751237, PubMed:16260596, PubMed:32789493). The UV-DDB complex preferentially binds to cyclobutane pyrimidine dimers (CPD), 6-4 photoproducts (6-4 PP), apurinic sites and short mismatches (PubMed:10882109, PubMed:11278856, PubMed:11705987, PubMed:12944386, PubMed:16260596). Also functions as the substrate recognition module for the DCX (DDB2-CUL4-X-box) E3 ubiquitin-protein ligase complex DDB2-CUL4-ROC1 (also known as CUL4-DDB-ROC1 and CUL4-DDB-RBX1) (PubMed:12732143, PubMed:15882621, PubMed:16473935, PubMed:18593899, PubMed:26572825). The DDB2-CUL4-ROC1 complex may ubiquitinate histone H2A, histone H3 and histone H4 at sites of UV-induced DNA damage (PubMed:16473935, PubMed:16678110). The ubiquitination of histones may facilitate their removal from the nucleosome and promote subsequent DNA repair (PubMed:16473935, PubMed:16678110). The DDB2-CUL4-ROC1 complex also ubiquitinates XPC, which may enhance DNA-binding by XPC and promote NER (PubMed:15882621). The DDB2-CUL4-ROC1 complex also ubiquitinates KAT7/HBO1 in response to DNA damage, leading to its degradation: recognizes KAT7/HBO1 following phosphorylation by ATR (PubMed:26572825)\nInhibits UV-damaged DNA repair\nInhibits UV-damaged DNA repair","source":"project UniProt records20261017/18"},{"partner":"EED","hgnc":"HGNC:3188","core":true,"core_annotation":{"hgnc":"HGNC:3188","symbol_at_source":"EED","accession":"O75530","function":"Polycomb group (PcG) protein","target":"#","pmids":["9584199"],"complexes":"PRC2","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":587,"hub_weight":0.2801659073402629,"quality":0.4,"programmes":["pubmed:41932313"],"pmids":["41932313"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Polycomb group (PcG) protein. Component of the PRC2/EED-EZH2 complex, which methylates 'Lys-9' and 'Lys-27' of histone H3, leading to transcriptional repression of the affected target gene. Also recognizes 'Lys-26' trimethylated histone H1 with the effect of inhibiting PRC2 complex methyltransferase activity on nucleosomal histone H3 'Lys-27', whereas H3 'Lys-27' recognition has the opposite effect, enabling the propagation of this repressive mark. The PRC2/EED-EZH2 complex may also serve as a recruiting platform for DNA methyltransferases, thereby linking two epigenetic repression systems. Genes repressed by the PRC2/EED-EZH2 complex include HOXC8, HOXA9, MYT1 and CDKN2A","source":"project UniProt records20261017/18"},{"partner":"H2BC8","hgnc":"HGNC:4746","core":true,"core_annotation":{"hgnc":"HGNC:4746","symbol_at_source":"HIST1H2BG","accession":"P62807","function":"Histone/protamine","target":"chromatin","pmids":[],"version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":546,"hub_weight":0.28964222318174615,"quality":0.4,"programmes":["pubmed:25281560","pubmed:34079125"],"pmids":["25281560","34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Core component of nucleosome. Nucleosomes wrap and compact DNA into chromatin, limiting DNA accessibility to the cellular machineries which require DNA as a template. Histones thereby play a central role in transcription regulation, DNA repair, DNA replication and chromosomal stability. DNA accessibility is regulated via a complex set of post-translational modifications of histones, also called histone code, and nucleosome remodeling\nHas broad antibacterial activity. May contribute to the formation of the functional antimicrobial barrier of the colonic epithelium, and to the bactericidal activity of amniotic fluid","source":"project UniProt records20261017/18"},{"partner":"H3C1","hgnc":"HGNC:4766","core":true,"core_annotation":{"hgnc":"HGNC:4766","symbol_at_source":"HIST1H3A","accession":"P68431","function":"Histone/protamine","target":"chromatin","pmids":[],"version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":827,"hub_weight":0.23877299420036402,"quality":0.4,"programmes":["pubmed:25281560"],"pmids":["25281560"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Core component of nucleosome. Nucleosomes wrap and compact DNA into chromatin, limiting DNA accessibility to the cellular machineries which require DNA as a template. Histones thereby play a central role in transcription regulation, DNA repair, DNA replication and chromosomal stability. DNA accessibility is regulated via a complex set of post-translational modifications of histones, also called histone code, and nucleosome remodeling","source":"project UniProt records20261017/18"},{"partner":"HSPA1A","hgnc":"HGNC:5232","core":true,"core_annotation":{"hgnc":"HGNC:5232","symbol_at_source":"HSPA1A","accession":"P0DMV8","function":"Histone modification write cofactor","target":"Protein","pmids":["16809764","2123078"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":1105,"hub_weight":0.20806259464411975,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["dataset_cell:HEK293T"],"partner_location":"Cytoplasm; Nucleus; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Secreted","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Molecular chaperone implicated in a wide variety of cellular processes, including protection of the proteome from stress, folding and transport of newly synthesized polypeptides, activation of proteolysis of misfolded proteins and the formation and dissociation of protein complexes. Plays a pivotal role in the protein quality control system, ensuring the correct folding of proteins, the re-folding of misfolded proteins and controlling the targeting of proteins for subsequent degradation. This is achieved through cycles of ATP binding, ATP hydrolysis and ADP release, mediated by co-chaperones. The co-chaperones have been shown to not only regulate different steps of the ATPase cycle, but they also have an individual specificity such that one co-chaperone may promote folding of a substrate while another may promote degradation. The affinity for polypeptides is regulated by its nucleotide bound state. In the ATP-bound form, it has a low affinity for substrate proteins. However, upon hydrolysis of the ATP to ADP, it undergoes a conformational change that increases its affinity for substrate proteins. It goes through repeated cycles of ATP hydrolysis and nucleotide exchange, which permits cycles of substrate binding and release. The co-chaperones are of three types: J-domain co-chaperones such as HSP40s (stimulate ATPase hydrolysis by HSP70), the nucleotide exchange factors (NEF) such as BAG1/2/3 (facilitate conversion of HSP70 from the ADP-bound to the ATP-bound state thereby promoting substrate release), and the TPR domain chaperones such as HOPX and STUB1 (PubMed:24012426, PubMed:24318877, PubMed:26865365). Maintains protein homeostasis during cellular stress through two opposing mechanisms: protein refolding and degradation. Its acetylation/deacetylation state determines whether it functions in protein refolding or protein degradation by controlling the competitive binding of co-chaperones HOPX and STUB1. During the early stress response, the acetylated form binds to HOPX which assists in chaperone-mediated protein refolding, thereafter, it is deacetylated and binds to ubiquitin ligase STUB1 that promotes ubiquitin-mediated protein degradation (PubMed:27708256). Regulates centrosome integrity during mitosis, and is required for the maintenance of a functional mitotic centrosome that supports the assembly of a bipolar mitotic spindle (PubMed:27137183). Enhances STUB1-mediated SMAD3 ubiquitination and degradation and facilitates STUB1-mediated inhibition of TGF-beta signaling (PubMed:24613385). Essential for STUB1-mediated ubiquitination and degradation of FOXP3 in regulatory T-cells (Treg) during inflammation (PubMed:23973223). Required as a co-chaperone for optimal STUB1/CHIP ubiquitination of NFATC3 (By similarity). Negatively regulates heat shock-induced HSF1 transcriptional activity during the attenuation and recovery phase period of the heat shock response (PubMed:9499401). Involved in the clearance of misfolded PRDM1/Blimp-1 proteins. Sequesters them in the cytoplasm and promotes their association with SYNV1/HRD1, leading to proteasomal degradation (PubMed:28842558)\n(Microbial infection) In case of rotavirus A infection, serves as a post-attachment receptor for the virus to facilitate entry into the cell","source":"project UniProt records20261017/18"},{"partner":"RBBP4","hgnc":"HGNC:9887","core":true,"core_annotation":{"hgnc":"HGNC:9887","symbol_at_source":"RBBP4","accession":"Q09028","function":"Histone chaperone","target":"histone","pmids":["8858152"],"complexes":"NuRF, SWI/SNF_Brg1(I), SWI/SNF_Brg1(II), SWI/SNF_Brm, NuRD, mSin3A, core HDAC, mSin3A-like complex, PRC2, CAF-1","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":718,"hub_weight":0.2551551815399144,"quality":0.4,"programmes":["pubmed:41932313"],"pmids":["41932313"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome, telomere","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Core histone-binding subunit that may target chromatin assembly factors, chromatin remodeling factors and histone deacetylases to their histone substrates in a manner that is regulated by nucleosomal DNA (PubMed:10866654). Component of the chromatin assembly factor 1 (CAF-1) complex, which is required for chromatin assembly following DNA replication and DNA repair (PubMed:8858152). Component of the core histone deacetylase (HDAC) complex, which promotes histone deacetylation and consequent transcriptional repression (PubMed:9150135). Component of the nucleosome remodeling and histone deacetylase complex (the NuRD complex), which promotes transcriptional repression by histone deacetylation and nucleosome remodeling (PubMed:16428440, PubMed:28977666, PubMed:39460621). Component of the PRC2 complex, which promotes repression of homeotic genes during development (PubMed:29499137, PubMed:31959557). Component of the NURF (nucleosome remodeling factor) complex (PubMed:14609955, PubMed:15310751)","source":"project UniProt records20261017/18"},{"partner":"RBBP5","hgnc":"HGNC:9888","core":true,"core_annotation":{"hgnc":"HGNC:9888","symbol_at_source":"RBBP5","accession":"Q15291","function":"Histone modification write cofactor","target":"histone","pmids":["19556245"],"complexes":"COMPASS, Menin-associated_HMT, MLL-HCF, CHD8, MLL2/3, COMPASS-like MLL1,2, MLL4/WBP7, COMPASS-like MLL3,4","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":385,"hub_weight":0.3390317518104052,"quality":0.4,"programmes":["pubmed:41932313"],"pmids":["41932313"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"In embryonic stem (ES) cells, plays a crucial role in the differentiation potential, particularly along the neural lineage, regulating gene induction and H3 'Lys-4' methylation at key developmental loci, including that mediated by retinoic acid (By similarity). Does not affect ES cell self-renewal (By similarity). Component or associated component of some histone methyltransferase complexes which regulates transcription through recruitment of those complexes to gene promoters (PubMed:19131338). As part of the MLL1/MLL complex, involved in mono-, di- and trimethylation at 'Lys-4' of histone H3 (PubMed:19556245). Histone H3 'Lys-4' methylation represents a specific tag for epigenetic transcriptional activation (PubMed:19556245). In association with ASH2L and WDR5, stimulates the histone methyltransferase activities of KMT2A, KMT2B, KMT2C, KMT2D, SETD1A and SETD1B (PubMed:21220120, PubMed:22266653)","source":"project UniProt records20261017/18"},{"partner":"RBBP7","hgnc":"HGNC:9890","core":true,"core_annotation":{"hgnc":"HGNC:9890","symbol_at_source":"RBBP7","accession":"Q16576","function":"Histone chaperone","target":"histone","pmids":["18571423"],"complexes":"NuRF, NuRD, mSin3A, core HDAC, mSin3A-like complex, PRC2","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":637,"hub_weight":0.2697780639425129,"quality":0.4,"programmes":["pubmed:41932313"],"pmids":["41932313"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Core histone-binding subunit that may target chromatin remodeling factors, histone acetyltransferases and histone deacetylases to their histone substrates in a manner that is regulated by nucleosomal DNA. Component of several complexes which regulate chromatin metabolism. These include the type B histone acetyltransferase (HAT) complex, which is required for chromatin assembly following DNA replication; the core histone deacetylase (HDAC) complex, which promotes histone deacetylation and consequent transcriptional repression; the nucleosome remodeling and histone deacetylase complex (the NuRD complex), which promotes transcriptional repression by histone deacetylation and nucleosome remodeling; and the PRC2/EED-EZH2 complex, which promotes repression of homeotic genes during development; and the NURF (nucleosome remodeling factor) complex","source":"project UniProt records20261017/18"},{"partner":"UBE2H","hgnc":"HGNC:12484","core":true,"core_annotation":{"hgnc":"HGNC:12484","symbol_at_source":"UBE2H","accession":"P62256","function":"Histone modification write","target":"histone","pmids":["8132613"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":1345,"hub_weight":0.18932061141568826,"quality":0.65,"programmes":["pubmed:38113892"],"pmids":["38113892"],"assays":["capture_association"],"contexts":[],"partner_location":"","partner_has_nuclear_annotation":false,"partner_location_assessed":false,"function":"Accepts ubiquitin from the E1 complex and catalyzes its covalent attachment to other proteins (PubMed:17588522, PubMed:20061386, PubMed:8132613). E2 ubiquitin conjugating enzyme that transfers ubiquitin to MAEA, a core component of the CTLH E3 ubiquitin-protein ligase complex (PubMed:29911972). In vitro catalyzes 'Lys-11'- and 'Lys-48'-linked polyubiquitination (PubMed:20061386). Capable, in vitro, to ubiquitinate histone H2A (PubMed:8132613)","source":"project UniProt records20261017/18"},{"partner":"WDR5","hgnc":"HGNC:12757","core":true,"core_annotation":{"hgnc":"HGNC:12757","symbol_at_source":"WDR5","accession":"P61964","function":"Histone modification read","target":"histone","pmids":["16946699"],"complexes":"ATAC, NSL, RING2-L3MBTL2, COMPASS, Menin-associated_HMT, MLL-HCF, CHD8, MLL2/3, COMPASS-like MLL1,2, MLL4/WBP7, COMPASS-like MLL3,4","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":1007,"hub_weight":0.21749411414517786,"quality":0.4,"programmes":["pubmed:41932313"],"pmids":["41932313"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Contributes to histone modification (PubMed:16600877, PubMed:16829960, PubMed:19103755, PubMed:19131338, PubMed:19556245, PubMed:20018852). May position the N-terminus of histone H3 for efficient trimethylation at 'Lys-4' (PubMed:16829960). As part of the MLL1/MLL complex it is involved in methylation and dimethylation at 'Lys-4' of histone H3 (PubMed:19556245). H3 'Lys-4' methylation represents a specific tag for epigenetic transcriptional activation (PubMed:18840606). As part of the NSL complex it may be involved in acetylation of nucleosomal histone H4 on several lysine residues (PubMed:19103755, PubMed:20018852). May regulate osteoblasts differentiation (By similarity). In association with RBBP5 and ASH2L, stimulates the histone methyltransferase activities of KMT2A, KMT2B, KMT2C, KMT2D, SETD1A and SETD1B (PubMed:21220120, PubMed:22266653)","source":"project UniProt records20261017/18"},{"partner":"HDAC7","hgnc":"HGNC:14067","core":true,"core_annotation":{"hgnc":"HGNC:14067","symbol_at_source":"HDAC7","accession":"Q8WUI4","function":"Histone modification erase","target":"histone","pmids":["18285338"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":143,"hub_weight":0.5089865985592875,"quality":0.65,"programmes":["BioPlex"],"pmids":["26186194","28514442","33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Responsible for the deacetylation of lysine residues on the N-terminal part of the core histones (H2A, H2B, H3 and H4) (By similarity). Histone deacetylation gives a tag for epigenetic repression and plays an important role in transcriptional regulation, cell cycle progression and developmental events (By similarity). Histone deacetylases act via the formation of large multiprotein complexes (By similarity). Involved in muscle maturation by repressing transcription of myocyte enhancer factors such as MEF2A, MEF2B and MEF2C (By similarity). During muscle differentiation, it shuttles into the cytoplasm, allowing the expression of myocyte enhancer factors (By similarity). May be involved in Epstein-Barr virus (EBV) latency, possibly by repressing the viral BZLF1 gene (PubMed:12239305). Positively regulates the transcriptional repressor activity of FOXP3 (PubMed:17360565). Serves as a corepressor of RARA, causing its deacetylation and inhibition of RARE DNA element binding (PubMed:28167758). In association with RARA, plays a role in the repression of microRNA-10a and thereby in the inflammatory response (PubMed:28167758). Also acetylates non-histone proteins, such as ALKBH5 (PubMed:37369679)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"ZSWIM9":{"coreEvidence":[{"partner":"BMI1","hgnc":"HGNC:1066","core":true,"core_annotation":{"hgnc":"HGNC:1066","symbol_at_source":"BMI1","accession":"P35226","function":"Polycomb group (PcG) protein","target":"#","pmids":["15386022"],"complexes":"PRC1","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":900,"hub_weight":0.22941573387056177,"quality":0.65,"programmes":["pubmed:34316702"],"pmids":["34316702"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens LN-428 glioblastoma cell\", \"human-ln_428\"]"],"partner_location":"Nucleus; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Component of a Polycomb group (PcG) multiprotein PRC1-like complex, a complex class required to maintain the transcriptionally repressive state of many genes, including Hox genes, throughout development. PcG PRC1 complex acts via chromatin remodeling and modification of histones; it mediates monoubiquitination of histone H2A 'Lys-119', rendering chromatin heritably changed in its expressibility (PubMed:15386022, PubMed:16359901, PubMed:16714294, PubMed:21772249, PubMed:25355358, PubMed:26151332, PubMed:27827373). The complex composed of RNF2, UB2D3 and BMI1 binds nucleosomes, and has activity only with nucleosomal histone H2A (PubMed:21772249, PubMed:25355358). In the PRC1-like complex, regulates the E3 ubiquitin-protein ligase activity of RNF2/RING2 (PubMed:15386022, PubMed:21772249, PubMed:26151332)","source":"project UniProt records20261017/18"},{"partner":"CBX1","hgnc":"HGNC:1551","core":true,"core_annotation":{"hgnc":"HGNC:1551","symbol_at_source":"CBX1","accession":"P83916","function":"Histone modification read","target":"histone","pmids":["21047797"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":289,"hub_weight":0.3840476863212843,"quality":0.65,"programmes":["pubmed:24981860","pubmed:27705803"],"pmids":["24981860","27705803"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293 embryonic kidney cell\", \"human-293\"]"],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Component of heterochromatin, which recognizes and binds histone H3 tails methylated at 'Lys-9', leading to epigenetic repression (PubMed:41094145). Also recognizes and binds histone H1.4 methylated at 'Lys-26' (H1.4K26me) (PubMed:16127177). Excluded from chromatin when histone H1.4 is Simultaneously methylated at Lys-26 (H1.4K26me) and phosphorylated at Ser-27 (H1.4S27Ph) (PubMed:16127177). Interaction with lamin B receptor (LBR) can contribute to the association of the heterochromatin with the inner nuclear membrane (By similarity)","source":"project UniProt records20261017/18"},{"partner":"CBX3","hgnc":"HGNC:1553","core":true,"core_annotation":{"hgnc":"HGNC:1553","symbol_at_source":"CBX3","accession":"Q13185","function":"Histone modification read","target":"histone","pmids":["21047797"],"complexes":"RING2-L3MBTL2, L3MBTL1","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":629,"hub_weight":0.2713626770646286,"quality":0.65,"programmes":["BioPlex","pubmed:27705803"],"pmids":["27705803","33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293 embryonic kidney cell\", \"human-293\"]","IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Component of heterochromatin, which recognizes and binds histone H3 tails methylated at 'Lys-9', leading to epigenetic repression (PubMed:11242053). Also recognizes and binds histone H1.4 methylated at 'Lys-26' (H1.4K26me) (PubMed:16127177). Excluded from chromatin when histone H1.4 is Simultaneously methylated at Lys-26 (H1.4K26me) and phosphorylated at Ser-27 (H1.4S27Ph) (PubMed:16127177). Involved in the formation of functional kinetochore through interaction with MIS12 complex proteins (PubMed:15502821). Contributes to the conversion of local chromatin to a heterochromatin-like repressive state through H3 'Lys-9' trimethylation, mediates the recruitment of the methyltransferases SUV39H1 and/or SUV39H2 by the PER complex to the E-box elements of the circadian target genes such as PER2 itself or PER1 (By similarity). Mediates the recruitment of NIPBL to sites of DNA damage at double-strand breaks (DSBs) (PubMed:28167679)","source":"project UniProt records20261017/18"},{"partner":"ZMYM2","hgnc":"HGNC:12989","core":true,"core_annotation":{"hgnc":"HGNC:12989","symbol_at_source":"ZMYM2","accession":"Q9UBW7","function":"Histone modification erase cofactor, TF","target":"DNA","pmids":["12493763"],"complexes":"BHC, LSD-CoREST","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":243,"hub_weight":0.4130961923860138,"quality":0.4,"programmes":["pubmed:32891193"],"pmids":["32891193"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Involved in the negative regulation of transcription","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"EFCAB12":{"coreEvidence":[{"partner":"H1-2","hgnc":"HGNC:4716","core":true,"core_annotation":{"hgnc":"HGNC:4716","symbol_at_source":"HIST1H1C","accession":"P16403","function":"Histone/protamine","target":"chromatin","pmids":[],"version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":535,"hub_weight":0.2923526731023431,"quality":0.65,"programmes":["pubmed:30021884","pubmed:35575683"],"pmids":["30021884","35575683"],"assays":["crosslink"],"contexts":[],"partner_location":"Nucleus; Nucleus, nucleolus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone H1 protein binds to linker DNA between nucleosomes forming the macromolecular structure known as the chromatin fiber (PubMed:26581166, PubMed:38530350). Histone H1-2 is required for the condensation of nucleosome chains into higher-order structured fibers (PubMed:38530350). Compared to other histone H1 variants, H1-2 plays an essential role in nucleosome condensation: its absence leads to global chromatin decompaction, which is not observed when depleting other histone H1 variants (PubMed:38530350). Histone H1-2 also acts as a histone reader: specifically recognizes and binds histone H3 trimethylated at 'lys-27' (H3K27me3) (PubMed:26581166). Histones H1 also promote formation of the H3K27me3 mark by the PRC2/EED-EZH2 complex, possibly by facilitating restoration of H3K27me3 post-replication (PubMed:37429872, PubMed:40516528). Together with histone H1-3, histone H1-2 acts as a regulator of splicing, most specifically exon skipping and intron retention events: histone H1-2 has a high affinity for exons and regulates splicing by affecting RNA polymerase II (RNAPII) elongation (PubMed:37922872). Also acts as a regulator of individual gene transcription through chromatin remodeling, nucleosome spacing and DNA methylation (PubMed:38530350)","source":"project UniProt records20261017/18"},{"partner":"H1-4","hgnc":"HGNC:4718","core":true,"core_annotation":{"hgnc":"HGNC:4718","symbol_at_source":"HIST1H1E","accession":"P10412","function":"Histone/protamine","target":"chromatin","pmids":[],"version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":559,"hub_weight":0.2865341275306264,"quality":0.65,"programmes":["pubmed:35575683"],"pmids":["35575683"],"assays":["crosslink"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone H1 protein binds to linker DNA between nucleosomes forming the macromolecular structure known as the chromatin fiber (PubMed:35581345, PubMed:40240600). Histones H1 are necessary for the condensation of nucleosome chains into higher-order structured fibers and promote formation of the H3K27me3 mark by the PRC2/EED-EZH2 complex (PubMed:35581345, PubMed:40240600, PubMed:40516528). Ability to associate with nucleosomes and compact chromatin depends on linker DNA length and trajectory (PubMed:35581345). Also acts as a regulator of individual gene transcription through chromatin remodeling, nucleosome spacing and DNA methylation (PubMed:40240600)","source":"project UniProt records20261017/18"},{"partner":"H1-5","hgnc":"HGNC:4719","core":true,"core_annotation":{"hgnc":"HGNC:4719","symbol_at_source":"HIST1H1B","accession":"P16401","function":"Histone/protamine","target":"chromatin","pmids":[],"version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":330,"hub_weight":0.3627381250550058,"quality":0.65,"programmes":["pubmed:35575683"],"pmids":["35575683"],"assays":["crosslink"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone H1 protein binds to linker DNA between nucleosomes forming the macromolecular structure known as the chromatin fiber (By similarity). Histones H1 are necessary for the condensation of nucleosome chains into higher-order structured fibers and promote formation of the H3K27me3 mark by the PRC2/EED-EZH2 complex (PubMed:40516528). Also acts as a regulator of individual gene transcription through chromatin remodeling, nucleosome spacing and DNA methylation (By similarity)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"R3HDM2":{"coreEvidence":[{"partner":"PARP1","hgnc":"HGNC:270","core":true,"core_annotation":{"hgnc":"HGNC:270","symbol_at_source":"PARP1","accession":"P09874","function":"Chromatin remodeling","target":"histone","pmids":["20926656","17177976","17396150"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":1585,"hub_weight":0.17487435419566724,"quality":0.4,"programmes":["pubmed:40057523"],"pmids":["40057523"],"assays":["proximity_label"],"contexts":[],"partner_location":"Chromosome; Nucleus; Nucleus, nucleolus; Cytoplasm, cytosol; Chromosome; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Poly-ADP-ribosyltransferase that mediates poly-ADP-ribosylation of proteins and plays a key role in DNA repair (PubMed:17177976, PubMed:18055453, PubMed:18172500, PubMed:19344625, PubMed:19661379, PubMed:20388712, PubMed:21680843, PubMed:22582261, PubMed:23230272, PubMed:25043379, PubMed:26344098, PubMed:26626479, PubMed:26626480, PubMed:30104678, PubMed:31796734, PubMed:32028527, PubMed:32241924, PubMed:32358582, PubMed:33186521, PubMed:34465625, PubMed:34737271). Mediates glutamate, aspartate, serine, histidine or tyrosine ADP-ribosylation of proteins: the ADP-D-ribosyl group of NAD(+) is transferred to the acceptor carboxyl group of target residues and further ADP-ribosyl groups are transferred to the 2'-position of the terminal adenosine moiety, building up a polymer with an average chain length of 20-30 units (PubMed:19764761, PubMed:25043379, PubMed:28190768, PubMed:29954836, PubMed:35393539, PubMed:7852410, PubMed:9315851). Serine ADP-ribosylation of proteins constitutes the primary form of ADP-ribosylation of proteins in response to DNA damage (PubMed:33186521, PubMed:34874266, PubMed:41062835). Specificity for the different amino acids is conferred by interacting factors, such as HPF1 and NMNAT1 (PubMed:28190768, PubMed:29954836, PubMed:32028527, PubMed:33186521, PubMed:33589610, PubMed:34625544, PubMed:34874266). Following interaction with HPF1, catalyzes serine ADP-ribosylation of target proteins; HPF1 confers serine specificity by completing the PARP1 active site (PubMed:28190768, PubMed:29954836, PubMed:32028527, PubMed:33186521, PubMed:33589610, PubMed:34625544, PubMed:34874266). Also catalyzes tyrosine ADP-ribosylation of target proteins following interaction with HPF1 (PubMed:29954836, PubMed:30257210). Following interaction with NMNAT1, catalyzes glutamate and aspartate ADP-ribosylation of target proteins; NMNAT1 confers glutamate and aspartate specificity (By similarity). PARP1 initiates the repair of DNA breaks: recognizes and binds DNA breaks within chromatin and recruits HPF1, licensing serine ADP-ribosylation of target proteins, such as histones (H2BS6ADPr and H3S10ADPr), thereby promoting decompaction of chromatin and the recruitment of repair factors leading to the reparation of DNA strand breaks (PubMed:17177976, PubMed:18172500, PubMed:19344625, PubMed:19661379, PubMed:23230272, PubMed:27067600, PubMed:34465625, PubMed:34874266). HPF1 initiates serine ADP-ribosylation but restricts the polymerase activity of PARP1 in order to limit the length of poly-ADP-ribose chains (PubMed:33683197, PubMed:34732825, PubMed:34795260). In addition to base excision repair (BER) pathway, also involved in double-strand breaks (DSBs) repair: together with TIMELESS, accumulates at DNA damage sites and promotes homologous recombination repair by mediating poly-ADP-ribosylation (PubMed:26344098, PubMed:30356214). Mediates the poly-ADP-ribosylation of a number of proteins, including itself, APLF, CHFR, RPA1 and NFAT5 (PubMed:17396150, PubMed:19764761, PubMed:24906880, PubMed:34049076). In addition to proteins, also able to ADP-ribosylate DNA: catalyzes ADP-ribosylation of DNA strand break termini containing terminal phosphates and a 2'-OH group in single- and double-stranded DNA, respectively (PubMed:27471034). Required for PARP9 and DTX3L recruitment to DNA damage sites (PubMed:23230272). PARP1-dependent PARP9-DTX3L-mediated ubiquitination promotes the rapid and specific recruitment of 53BP1/TP53BP1, UIMC1/RAP80, and BRCA1 to DNA damage sites (PubMed:23230272). PARP1-mediated DNA repair in neurons plays a role in sleep: senses DNA damage in neurons and promotes sleep, facilitating efficient DNA repair (By similarity). In addition to DNA repair, also involved in other processes, such as transcription regulation, programmed cell death, membrane repair, adipogenesis and innate immunity (PubMed:15607977, PubMed:17177976, PubMed:19344625, PubMed:27256882, PubMed:32315358, PubMed:32844745, PubMed:35124853, PubMed:35393539, PubMed:35460603). Acts as a repressor of transcription: binds to nucleosomes and modulates chromatin structure in a manner similar to histone H1, thereby altering RNA polymerase II (PubMed:15607977, PubMed:22464733). Acts both as a positive and negative regulator of transcription elongation, depending on the context (PubMed:27256882, PubMed:35393539). Acts as a positive regulator of transcription elongation by mediating poly-ADP-ribosylation of NELFE, preventing RNA-binding activity of NELFE and relieving transcription pausing (PubMed:27256882). Acts as a negative regulator of transcription elongation in response to DNA damage by catalyzing poly-ADP-ribosylation of CCNT1, disrupting the phase separation activity of CCNT1 and subsequent activation of CDK9 (PubMed:35393539). Involved in replication fork progression following interaction with CARM1: mediates poly-ADP-ribosylation at replication forks, slowing fork progression (PubMed:33412112). Poly-ADP-ribose chains generated by PARP1 also play a role in poly-ADP-ribose-dependent cell death, a process named parthanatos (By similarity). Also acts as a negative regulator of the cGAS-STING pathway (PubMed:32315358, PubMed:32844745, PubMed:35460603). Acts by mediating poly-ADP-ribosylation of CGAS: PARP1 translocates into the cytosol following phosphorylation by PRKDC and catalyzes poly-ADP-ribosylation and inactivation of CGAS (PubMed:35460603). Acts as a negative regulator of adipogenesis: catalyzes poly-ADP-ribosylation of histone H2B on 'Glu-35' (H2BE35ADPr) following interaction with NMNAT1, inhibiting phosphorylation of H2B at 'Ser-36' (H2BS36ph), thereby blocking expression of pro-adipogenetic genes (By similarity). Involved in the synthesis of ATP in the nucleus, together with NMNAT1, PARG and NUDT5 (PubMed:27257257). Nuclear ATP generation is required for extensive chromatin remodeling events that are energy-consuming (PubMed:27257257). Plays a role in sister chromatid cohesion by mediating ADP-ribosylation of RSMC during S phase which promotes the interaction between RSMC and CDCA5/sororin, leading to enhanced interaction of CDCA5/sororin with the cohesin complex and promotion of sister chromatid cohesion (PubMed:41261216)\nPromotes AIFM1-mediated apoptosis (PubMed:33168626). This form, which translocates into the cytoplasm following cleavage by caspase-3 (CASP3) and caspase-7 (CASP7) in response to apoptosis, is auto-poly-ADP-ribosylated and serves as a poly-ADP-ribose carrier to induce AIFM1-mediated apoptosis (PubMed:33168626)\nThis cleavage form irreversibly binds to DNA breaks and interferes with DNA repair, promoting DNA damage-induced apoptosis","source":"project UniProt records20261017/18"},{"partner":"EYA4","hgnc":"HGNC:3522","core":true,"core_annotation":{"hgnc":"HGNC:3522","symbol_at_source":"EYA4","accession":"O95677","function":"Histone modification erase","target":"histone","pmids":[],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":212,"hub_weight":0.436852028330519,"quality":0.4,"programmes":["pubmed:38360978"],"pmids":["38360978"],"assays":["proximity_label"],"contexts":[],"partner_location":"Cytoplasm; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Tyrosine phosphatase that specifically dephosphorylates 'Tyr-142' of histone H2AX (H2AXY142ph). 'Tyr-142' phosphorylation of histone H2AX plays a central role in DNA repair and acts as a mark that distinguishes between apoptotic and repair responses to genotoxic stress. Promotes efficient DNA repair by dephosphorylating H2AX, promoting the recruitment of DNA repair complexes containing MDC1. Its function as histone phosphatase probably explains its role in transcription regulation during organogenesis. May be involved in development of the eye (By similarity)","source":"project UniProt records20261017/18"},{"partner":"YWHAB","hgnc":"HGNC:12849","core":true,"core_annotation":{"hgnc":"HGNC:12849","symbol_at_source":"YWHAB","accession":"P31946","function":"Histone modification erase cofactor","target":"histone","pmids":["10869435"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":704,"hub_weight":0.2575131013123024,"quality":0.65,"programmes":["BioPlex","pubmed:24255178","pubmed:35271311"],"pmids":["24255178","33961781","35271311"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293 embryonic kidney cell\", \"human-293\"]","IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Cytoplasm; Melanosome; Vacuole membrane","partner_has_nuclear_annotation":false,"partner_location_assessed":true,"function":"Adapter protein implicated in the regulation of a large spectrum of both general and specialized signaling pathways. Binds to a large number of partners, usually by recognition of a phosphoserine or phosphothreonine motif. Binding generally results in the modulation of the activity of the binding partner. Negative regulator of osteogenesis. Blocks the nuclear translocation of the phosphorylated form (by AKT1) of SRPK2 and antagonizes its stimulatory effect on cyclin D1 expression resulting in blockage of neuronal apoptosis elicited by SRPK2. Negative regulator of signaling cascades that mediate activation of MAP kinases via AKAP13","source":"project UniProt records20261017/18"},{"partner":"YWHAE","hgnc":"HGNC:12851","core":true,"core_annotation":{"hgnc":"HGNC:12851","symbol_at_source":"YWHAE","accession":"P62258","function":"Histone modification erase cofactor","target":"histone","pmids":["10869435"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":833,"hub_weight":0.23796037813647444,"quality":0.65,"programmes":["pubmed:35271311"],"pmids":["35271311"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]"],"partner_location":"Nucleus; Cytoplasm; Melanosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Adapter protein implicated in the regulation of a large spectrum of both general and specialized signaling pathways (PubMed:21189250). Binds to a large number of partners, usually by recognition of a phosphoserine or phosphothreonine motif (PubMed:35343654). Binding generally results in the modulation of the activity of the binding partner (By similarity). Positively regulates phosphorylated protein HSF1 nuclear export to the cytoplasm (PubMed:12917326). Plays a positive role in the antiviral signaling pathway upstream of TBK1 via interaction with RIGI (PubMed:37555661). Mechanistically, directs RIGI redistribution from the cytosol to mitochondrial associated membranes where it mediates MAVS-dependent innate immune signaling during viral infection (PubMed:22607805). Plays a role in proliferation inhibition and cell cycle arrest by exporting HNRNPC from the nucleus to the cytoplasm to be degraded by ubiquitination (PubMed:37599448)","source":"project UniProt records20261017/18"},{"partner":"YWHAZ","hgnc":"HGNC:12855","core":true,"core_annotation":{"hgnc":"HGNC:12855","symbol_at_source":"YWHAZ","accession":"P63104","function":"Histone modification read","target":"histone","pmids":["16246723"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":960,"hub_weight":0.2224970797449924,"quality":0.65,"programmes":["pubmed:35271311"],"pmids":["35271311"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]"],"partner_location":"Cytoplasm; Melanosome","partner_has_nuclear_annotation":false,"partner_location_assessed":true,"function":"Adapter protein implicated in the regulation of a large spectrum of both general and specialized signaling pathways (PubMed:14578935, PubMed:15071501, PubMed:15644438, PubMed:16376338, PubMed:16959763, PubMed:31024343, PubMed:9360956). Binds to a large number of partners, usually by recognition of a phosphoserine or phosphothreonine motif (PubMed:35662396). Binding generally results in the modulation of the activity of the binding partner (PubMed:35662396). Promotes cytosolic retention and inactivation of TFEB transcription factor by binding to phosphorylated TFEB (PubMed:35662396). Induces ARHGEF7 activity on RAC1 as well as lamellipodia and membrane ruffle formation (PubMed:16959763). In neurons, regulates spine maturation through the modulation of ARHGEF7 activity (By similarity)","source":"project UniProt records20261017/18"},{"partner":"TDRD3","hgnc":"HGNC:20612","core":true,"core_annotation":{"hgnc":"HGNC:20612","symbol_at_source":"TDRD3","accession":"Q9H7E2","function":"Histone modification read","target":"histone","pmids":["21172665"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":158,"hub_weight":0.4902903378454601,"quality":0.4,"programmes":["pubmed:29395067"],"pmids":["29395067"],"assays":["proximity_label"],"contexts":[],"partner_location":"Cytoplasm; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Scaffolding protein that specifically recognizes and binds dimethylarginine-containing proteins (PubMed:15955813). Plays a role in the regulation of translation of target mRNAs by binding Arg/Gly-rich motifs (GAR) in dimethylarginine-containing proteins. In nucleus, acts as a coactivator: recognizes and binds asymmetric dimethylation on the core histone tails associated with transcriptional activation (H3R17me2a and H4R3me2a) and recruits proteins at these arginine-methylated loci (PubMed:21172665). In cytoplasm, acts as an antiviral factor that participates in the assembly of stress granules together with G3BP1 (PubMed:35085371)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"JRKL":{"coreEvidence":[{"partner":"EP300","hgnc":"HGNC:3373","core":true,"core_annotation":{"hgnc":"HGNC:3373","symbol_at_source":"EP300","accession":"Q09472","function":"Histone modification write","target":"histone","pmids":["17065153"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":1188,"hub_weight":0.2009669677645352,"quality":0.65,"programmes":["pubmed:41611887"],"pmids":["41611887"],"assays":["capture_association"],"contexts":[],"partner_location":"Cytoplasm; Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Functions as a histone acetyltransferase and regulates transcription via chromatin remodeling (PubMed:23415232, PubMed:23934153, PubMed:40240600, PubMed:8945521). Acetylates all four core histones in nucleosomes (PubMed:23415232, PubMed:23934153, PubMed:8945521). Histone acetylation gives an epigenetic tag for transcriptional activation (PubMed:23415232, PubMed:23934153, PubMed:8945521). Mediates acetylation of histone H3 at 'Lys-122' (H3K122ac), a modification that localizes at the surface of the histone octamer and stimulates transcription, possibly by promoting nucleosome instability (PubMed:23415232). Mediates acetylation of histone H3 at 'Lys-18' and 'Lys-27' (H3K18ac and H3K27ac, respectively) (PubMed:21131905, PubMed:23911289). Also able to acetylate histone lysine residues that are already monomethylated on the same side chain to form N6-acetyl-N6-methyllysine (Kacme), an epigenetic mark of active chromatin associated with increased transcriptional initiation (PubMed:37731000). Catalyzes formation of histone H4 acetyl-methylated at 'Lys-5' and 'Lys-12' (H4K5acme and H4K12acme, respectively) (PubMed:37731000). In response to DNA damage, catalyzes acetylation of histone H1 at 'Lys-75' (H1K75ac) following histone H1 deamidation by CTPS1, increasing chromatin accessibility to facilitate the recruitment of DNA repair proteins (PubMed:40240600). Also functions as acetyltransferase for non-histone targets, such as ALX1, HDAC1, PRDM16, PRMT1, SIRT2, STAT3, ZNF76 or GLUL (PubMed:12929931, PubMed:15653507, PubMed:16285960, PubMed:16337145, PubMed:16762839, PubMed:18722353, PubMed:18782771, PubMed:26990986). Acetylates 'Lys-131' of ALX1 and acts as its coactivator (PubMed:12929931). Acetylates SIRT2 and is proposed to indirectly increase the transcriptional activity of p53/TP53 through acetylation and subsequent attenuation of SIRT2 deacetylase function (PubMed:18722353). Following DNA damage, forms a stress-responsive p53/TP53 coactivator complex with JMY which mediates p53/TP53 acetylation, thereby increasing p53/TP53-dependent transcription and apoptosis (PubMed:11511361, PubMed:15448695). Promotes chromatin acetylation in heat shock responsive HSP genes during the heat shock response (HSR), thereby stimulating HSR transcription (PubMed:18451878). Acetylates HDAC1 leading to its inactivation and modulation of transcription (PubMed:16762839). Acetylates 'Lys-247' of EGR2 (By similarity). Acts as a TFAP2A-mediated transcriptional coactivator in presence of CITED2 (PubMed:12586840). Plays a role as a coactivator of NEUROD1-dependent transcription of the secretin and p21 genes and controls terminal differentiation of cells in the intestinal epithelium. Promotes cardiac myocyte enlargement (PubMed:14752053). Can also mediate transcriptional repression. Acetylates FOXO1 and enhances its transcriptional activity (PubMed:15890677). Acetylates STAT3 at different sites, promoting both STAT3 dimerization and activation and recruitment to chromatin (PubMed:15653507, PubMed:16285960, PubMed:18782771). Acetylates BCL6 which disrupts its ability to recruit histone deacetylases and hinders its transcriptional repressor activity (PubMed:12402037). Participates in CLOCK or NPAS2-regulated rhythmic gene transcription; exhibits a circadian association with CLOCK or NPAS2, correlating with increase in PER1/2 mRNA and histone H3 acetylation on the PER1/2 promoter (PubMed:14645221). Acetylates MTA1 at 'Lys-626' which is essential for its transcriptional coactivator activity (PubMed:16617102). Acetylates XBP1 isoform 2; acetylation increases protein stability of XBP1 isoform 2 and enhances its transcriptional activity (PubMed:20955178). Acetylates PCNA; acetylation promotes removal of chromatin-bound PCNA and its degradation during nucleotide excision repair (NER) (PubMed:24939902). Acetylates MEF2D (PubMed:21030595). Acetylates and stabilizes ZBTB7B protein by antagonizing ubiquitin conjugation and degradation, this mechanism may be involved in CD4/CD8 lineage differentiation (PubMed:20810990). Acetylates GABPB1, impairing GABPB1 heterotetramerization and activity (By similarity). Acetylates PCK1 and promotes PCK1 anaplerotic activity (PubMed:30193097). Acetylates RXRA and RXRG (PubMed:17761950). Acetylates isoform M2 of PKM (PKM2), promoting its homodimerization and conversion into a protein kinase (PubMed:24120661). Acetylates RPTOR in response to leucine, leading to activation of the mTORC1 complex (PubMed:30197302, PubMed:32561715). Acetylates RICTOR, leading to activation of the mTORC2 complex (PubMed:22084251). Mediates cAMP-gene regulation by binding specifically to phosphorylated CREBBP (PubMed:8917528). In addition to protein acetyltransferase, can use different acyl-CoA substrates, such as (2E)-butenoyl-CoA (crotonyl-CoA), butanoyl-CoA (butyryl-CoA), 2-hydroxyisobutanoyl-CoA (2-hydroxyisobutyryl-CoA), lactoyl-CoA, propanoyl-CoA (propionyl-CoA) or isonicotinyl-CoA, and is able to mediate protein crotonylation, butyrylation, 2-hydroxyisobutyrylation, lactylation, propionylation or isonicotinylation, respectively (PubMed:17267393, PubMed:25818647, PubMed:29775581, PubMed:31645732, PubMed:34545082). Acts as a histone crotonyltransferase; crotonylation marks active promoters and enhancers and confers resistance to transcriptional repressors (PubMed:25818647). Histone crotonyltransferase activity is dependent on the concentration of (2E)-butenoyl-CoA (crotonyl-CoA) substrate and such activity is weak when (2E)-butenoyl-CoA (crotonyl-CoA) concentration is low (PubMed:25818647). Also acts as a histone butyryltransferase; butyrylation marks active promoters (PubMed:17267393). Catalyzes histone lactylation in macrophages by using lactoyl-CoA directly derived from endogenous or exogenous lactate, leading to stimulates gene transcription (PubMed:31645732). Acts as a protein-lysine 2-hydroxyisobutyryltransferase; regulates glycolysis by mediating 2-hydroxyisobutyrylation of glycolytic enzymes (PubMed:29775581). Functions as a transcriptional coactivator for SMAD4 in the TGF-beta signaling pathway (PubMed:25514493)\n(Microbial infection) In case of HIV-1 infection, it is recruited by the viral protein Tat. Regulates Tat's transactivating activity and may help inducing chromatin remodeling of proviral genes. Binds to and may be involved in the transforming capacity of the adenovirus E1A protein","source":"project UniProt records20261017/18"},{"partner":"H4C1","hgnc":"HGNC:4781","core":true,"core_annotation":{"hgnc":"HGNC:4781","symbol_at_source":"HIST1H4A","accession":"P62805","function":"Histone/protamine","target":"chromatin","pmids":[],"version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":1538,"hub_weight":0.17744336024691904,"quality":0.65,"programmes":["pubmed:30804502"],"pmids":["30804502"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Core component of nucleosome. Nucleosomes wrap and compact DNA into chromatin, limiting DNA accessibility to the cellular machineries which require DNA as a template. Histones thereby play a central role in transcription regulation, DNA repair, DNA replication and chromosomal stability. DNA accessibility is regulated via a complex set of post-translational modifications of histones, also called histone code, and nucleosome remodeling","source":"project UniProt records20261017/18"},{"partner":"SMARCA4","hgnc":"HGNC:11100","core":true,"core_annotation":{"hgnc":"HGNC:11100","symbol_at_source":"SMARCA4","accession":"P51532","function":"Histone modification read, TF","target":"histone","pmids":["17582821"],"complexes":"BAF, nBAF, npBAF, PBAF, SWI/SNF_Brg1(I), SWI/SNF_Brg1(II), SWI/SNF_Brm, SWI/SNF-like_EPAFa, WINAC, SWI/SNF-like EPAFB, bBAF, SWI/SNF BRM-BRG1, CREST-BRG1","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":753,"hub_weight":0.24953256425297482,"quality":0.65,"programmes":["pubmed:41611887"],"pmids":["41611887"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"ATPase involved in transcriptional activation and repression of select genes by chromatin remodeling (alteration of DNA-nucleosome topology). Component of SWI/SNF chromatin remodeling complexes that carry out key enzymatic activities, changing chromatin structure by altering DNA-histone contacts within a nucleosome in an ATP-dependent manner (PubMed:15075294, PubMed:29374058, PubMed:30339381, PubMed:32459350). Component of the CREST-BRG1 complex, a multiprotein complex that regulates promoter activation by orchestrating the calcium-dependent release of a repressor complex and the recruitment of an activator complex. In resting neurons, transcription of the c-FOS promoter is inhibited by SMARCA4-dependent recruitment of a phospho-RB1-HDAC repressor complex. Upon calcium influx, RB1 is dephosphorylated by calcineurin, which leads to release of the repressor complex. At the same time, there is increased recruitment of CREBBP to the promoter by a CREST-dependent mechanism, which leads to transcriptional activation. The CREST-BRG1 complex also binds to the NR2B promoter, and activity-dependent induction of NR2B expression involves the release of HDAC1 and recruitment of CREBBP (By similarity). Belongs to the neural progenitors-specific chromatin remodeling complex (npBAF complex) and the neuron-specific chromatin remodeling complex (nBAF complex). During neural development, a switch from a stem/progenitor to a postmitotic chromatin remodeling mechanism occurs as neurons exit the cell cycle and become committed to their adult state. The transition from proliferating neural stem/progenitor cells to postmitotic neurons requires a switch in subunit composition of the npBAF and nBAF complexes. As neural progenitors exit mitosis and differentiate into neurons, npBAF complexes which contain ACTL6A/BAF53A and PHF10/BAF45A, are exchanged for homologous alternative ACTL6B/BAF53B and DPF1/BAF45B or DPF3/BAF45C subunits in neuron-specific complexes (nBAF). The npBAF complex is essential for the self-renewal/proliferative capacity of the multipotent neural stem cells. The nBAF complex along with CREST plays a role regulating the activity of genes essential for dendrite growth. SMARCA4/BAF190A may promote neural stem cell self-renewal/proliferation by enhancing Notch-dependent proliferative signals, while concurrently making the neural stem cell insensitive to SHH-dependent differentiating cues (By similarity). Acts as a corepressor of ZEB1 to regulate E-cadherin transcription and is required for induction of epithelial-mesenchymal transition (EMT) by ZEB1 (PubMed:20418909). Binds via DLX1 to enhancers located in the intergenic region between DLX5 and DLX6 and this binding is stabilized by the long non-coding RNA (lncRNA) Evf2 (By similarity). Binds to RNA in a promiscuous manner (By similarity). In brown adipose tissue, involved in the regulation of thermogenic genes expression (By similarity)","source":"project UniProt records20261017/18"},{"partner":"SMARCB1","hgnc":"HGNC:11103","core":true,"core_annotation":{"hgnc":"HGNC:11103","symbol_at_source":"SMARCB1","accession":"Q12824","function":"Histone modification read","target":"histone","pmids":["21423274"],"complexes":"BAF, nBAF, npBAF, PBAF, SWI/SNF_Brg1(I), SWI/SNF_Brg1(II), SWI/SNF_Brm, SWI/SNF-like_EPAFa, WINAC, SWI/SNF-like EPAFB, bBAF, SWI/SNF BRM-BRG1","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":713,"hub_weight":0.2559898425245689,"quality":0.65,"programmes":["pubmed:41611887"],"pmids":["41611887"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Core component of the BAF (hSWI/SNF) complex. This ATP-dependent chromatin-remodeling complex plays important roles in cell proliferation and differentiation, in cellular antiviral activities and inhibition of tumor formation. The BAF complex is able to create a stable, altered form of chromatin that constrains fewer negative supercoils than normal. This change in supercoiling would be due to the conversion of up to one-half of the nucleosomes on polynucleosomal arrays into asymmetric structures, termed altosomes, each composed of 2 histones octamers. Stimulates in vitro the remodeling activity of SMARCA4/BRG1/BAF190A. Involved in activation of CSF1 promoter. Belongs to the neural progenitors-specific chromatin remodeling complex (npBAF complex) and the neuron-specific chromatin remodeling complex (nBAF complex). During neural development a switch from a stem/progenitor to a postmitotic chromatin remodeling mechanism occurs as neurons exit the cell cycle and become committed to their adult state. The transition from proliferating neural stem/progenitor cells to postmitotic neurons requires a switch in subunit composition of the npBAF and nBAF complexes. As neural progenitors exit mitosis and differentiate into neurons, npBAF complexes which contain ACTL6A/BAF53A and PHF10/BAF45A, are exchanged for homologous alternative ACTL6B/BAF53B and DPF1/BAF45B or DPF3/BAF45C subunits in neuron-specific complexes (nBAF). The npBAF complex is essential for the self-renewal/proliferative capacity of the multipotent neural stem cells. The nBAF complex along with CREST plays a role regulating the activity of genes essential for dendrite growth (By similarity). Plays a key role in cell-cycle control and causes cell cycle arrest in G0/G1","source":"project UniProt records20261017/18"},{"partner":"WDR5","hgnc":"HGNC:12757","core":true,"core_annotation":{"hgnc":"HGNC:12757","symbol_at_source":"WDR5","accession":"P61964","function":"Histone modification read","target":"histone","pmids":["16946699"],"complexes":"ATAC, NSL, RING2-L3MBTL2, COMPASS, Menin-associated_HMT, MLL-HCF, CHD8, MLL2/3, COMPASS-like MLL1,2, MLL4/WBP7, COMPASS-like MLL3,4","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":1007,"hub_weight":0.21749411414517786,"quality":0.4,"programmes":["pubmed:41932313"],"pmids":["41932313"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Contributes to histone modification (PubMed:16600877, PubMed:16829960, PubMed:19103755, PubMed:19131338, PubMed:19556245, PubMed:20018852). May position the N-terminus of histone H3 for efficient trimethylation at 'Lys-4' (PubMed:16829960). As part of the MLL1/MLL complex it is involved in methylation and dimethylation at 'Lys-4' of histone H3 (PubMed:19556245). H3 'Lys-4' methylation represents a specific tag for epigenetic transcriptional activation (PubMed:18840606). As part of the NSL complex it may be involved in acetylation of nucleosomal histone H4 on several lysine residues (PubMed:19103755, PubMed:20018852). May regulate osteoblasts differentiation (By similarity). In association with RBBP5 and ASH2L, stimulates the histone methyltransferase activities of KMT2A, KMT2B, KMT2C, KMT2D, SETD1A and SETD1B (PubMed:21220120, PubMed:22266653)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]}};
